Question.create({"id"=>63913, "text"=>"Pertaining to your data inventory (above), what data formats and file types will you use? You are encouraged to avoid proprietary file types whenever possible.", "default_value"=>nil, "number"=>2, "section_id"=>20739, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59724, "question_id"=>63913, "org_id"=>15, "text"=>"tabular data (continuous or otherwise) .csv, .txt, .xlsx; modelled data/outputs as netCDF; geospatial data as shapefiles (.shp), grids (.tif); video / audio / photography stored as open-source formats, .jpg; text documents saved as .txt, .doc, .pdf", "type"=>"example_answer", "versionable_id"=>nil})
Annotation.create({"id"=>59725, "question_id"=>63913, "org_id"=>15, "text"=>"<p>Description of the files types that will hold the information described in the previous question.&nbsp;</p>", "type"=>"guidance", "versionable_id"=>nil})
