Annotation.create({"id"=>59848, "question_id"=>64026, "org_id"=>16, "text"=>"<p><span class=\"Heading7Char\">Agreements may include stipulations for data sharing, data transfer, or other agreements between researchers and Universities.</span><span lang=\"EN-US\">&nbsp; For more information, contact the Memorial University Information Access &amp; Privacy Office (<a href=\"https://www.mun.ca/iap/\" target=\"_blank\" rel=\"noopener\">https://www.mun.ca/iap/</a>). Please specify the agreements.&nbsp;</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64027, "text"=>"Does your study include human information or other sensitive data?  ", "default_value"=>nil, "number"=>2, "section_id"=>20777, "question_format_id"=>5, "option_comment_display"=>false, "modifiable"=>false, "versionable_id"=>nil})
