Annotation.create({"id"=>59849, "question_id"=>64027, "org_id"=>16, "text"=>"<p>If no, you may move onto the next section.&nbsp;</p>\r\n<p>If yes, please complete all questions below.&nbsp;</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64028, "text"=>"How will sensitive data be managed securely during the active research project life cycle?  Will non-disclosure agreements be required for researchers or participants?", "default_value"=>nil, "number"=>3, "section_id"=>20777, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59850, "question_id"=>64028, "org_id"=>16, "text"=>"<p><span lang=\"EN-US\">Note: you may need to consult with University research data policy and ethics professionals to fully answer this question.&nbsp; As well, you may need to consult with University IT services to identify protocols for storing, working with, and sharing sensitive information securely.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64029, "text"=>"If any data are to be released publicly, what steps will be taken to ensure anonymization and/or data cleaning?", "default_value"=>nil, "number"=>4, "section_id"=>20777, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59851, "question_id"=>64029, "org_id"=>16, "text"=>"<p><span lang=\"EN-US\">For guidance, please refer to the Memorial University Guide on Research Ethics (<a href=\"https://guides.library.mun.ca/c.php?g=502039&amp;p=5059458\" target=\"_blank\" rel=\"noopener\">https://guides.library.mun.ca/c.php?g=502039&amp;p=5059458</a>)</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>20778, "title"=>"Preservation and FAIR Data Sharing", "description"=>nil, "number"=>7, "phase_id"=>3226, "modifiable"=>false, "versionable_id"=>nil})
Question.create({"id"=>64030, "text"=>"Which datasets from this project will be shared publicly?", "default_value"=>nil, "number"=>1, "section_id"=>20778, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59852, "question_id"=>64030, "org_id"=>16, "text"=>"<p><span lang=\"EN-US\">We encourage you to share as much of your data as possible, helping to support FAIR data sharing principles (Findable, Accessible, Interoperable, and Reusable; see e.g., Wilkinson, et al., 2016, DOI: <a href=\"https://www.nature.com/articles/sdata201618\" target=\"_blank\" rel=\"noopener\">10.1038/sdata.2016.18</a>). &nbsp;</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64031, "text"=>"When will data from this project be shared?", "default_value"=>nil, "number"=>2, "section_id"=>20778, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59853, "question_id"=>64031, "org_id"=>16, "text"=>"<p><span lang=\"EN-US\">When answering this question, be mindful of the OFI Data Management Principles and Policy, as well as your own research group&rsquo;s goals.&nbsp;</span></p>", "type"=>"guidance", "versionable_id"=>nil})
