Phase.create({"id"=>3228, "title"=>"York U Data Management Questions", "description"=>nil, "number"=>1, "template_id"=>3240, "modifiable"=>false, "versionable_id"=>nil})
Section.create({"id"=>20786, "title"=>"Project Information", "description"=>"<p><span style=\"font-weight: 400;\">This section is to provide an overview of the research project.</span></p>", "number"=>1, "phase_id"=>3228, "modifiable"=>false, "versionable_id"=>nil})
Question.create({"id"=>64057, "text"=>"1.1 Name of project or sub-project and project number (if applicable).\r\n", "default_value"=>nil, "number"=>1, "section_id"=>20786, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Question.create({"id"=>64058, "text"=>"1.2  Please provide an outline description of the research project and the intended products of the research.", "default_value"=>nil, "number"=>2, "section_id"=>20786, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59877, "question_id"=>64058, "org_id"=>45, "text"=>"<p>Scope of project or sub-project. Describe the types of data and products that will be generated in the research, such as images of astronomical objects, spectra, data tables, time series, theoretical formalisms, computational strategies, software, and curriculum materials.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64059, "text"=>"1.3  Please provide details of the project timelines.", "default_value"=>nil, "number"=>3, "section_id"=>20786, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59878, "question_id"=>64059, "org_id"=>45, "text"=>"<p>Start date, end date, and duration of major tasks of the project.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64060, "text"=>"1.4 Principal Investigator(s)", "default_value"=>nil, "number"=>4, "section_id"=>20786, "question_format_id"=>2, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59879, "question_id"=>64060, "org_id"=>45, "text"=>"<p>Name(s) and affiliation(s) of Principal Investigator(s).</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64061, "text"=>"1.5 Identify collaborating Agencies/Organizations.", "default_value"=>nil, "number"=>5, "section_id"=>20786, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59880, "question_id"=>64061, "org_id"=>45, "text"=>"<p>List any collaborating agencies and organizations, if applicable.</p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>20787, "title"=>"Data Collection", "description"=>"<p><span style=\"font-weight: 400;\">This section addresses data collection issues such as data types, file formats, naming conventions, and data organisation &ndash; factors that will improve the usability of your data and contribute to the success of your project.</span></p>", "number"=>2, "phase_id"=>3228, "modifiable"=>false, "versionable_id"=>nil})
Question.create({"id"=>64062, "text"=>"2.1 What types of data will you collect, create, link to, acquire and/or record?", "default_value"=>nil, "number"=>1, "section_id"=>20787, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59881, "question_id"=>64062, "org_id"=>45, "text"=>"<p>Examples: numeric, images, audio, video, text, tabular data, modeling data, spatial data, instrumentation data.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64063, "text"=>"2.2 What file formats will your data be collected in? Will these formats allow for data re-use, sharing and long-term access to the data?", "default_value"=>nil, "number"=>2, "section_id"=>20787, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59882, "question_id"=>64063, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Use open (non-proprietary) file formats whenever possible. Proprietary file formats that require specialized software or hardware are not recommended but may be necessary for certain types of data collection or analysis. Using open file formats or industry-standard formats, especially those widely used by a given community, is preferred whenever possible. Changes to file formats should be documented and original files saved with preservation-friendly versions.</span><span style=\"font-weight: 400;\"><br /></span><span style=\"font-weight: 400;\"><br /></span><span style=\"font-weight: 400;\">Read more about </span><a href=\"http://www.dcc.ac.uk/resources/curation-reference-manual/completed-chapters/file-formats\" target=\"_blank\"><span style=\"font-weight: 400;\">file formats</span></a><span style=\"font-weight: 400;\"> and a list of </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/recommended-formats\" target=\"_blank\"><span style=\"font-weight: 400;\">recommended formats</span></a><span style=\"font-weight: 400;\"> from UK Data Archive.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64064, "text"=>"2.3 How much data do you anticipate collecting? Include an estimate of how much storage space you will require (in megabytes, gigabytes, terabytes). This estimate should also take into account storage space required for file versioning, backups, and the growth rate over time.", "default_value"=>nil, "number"=>3, "section_id"=>20787, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59883, "question_id"=>64064, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">The type of data you collect will impact your storage requirements. Textual and tabular data files are usually very small (a few megabytes) unless you have a lot of data. Video files are usually very large (hundreds of megabytes up to several gigabytes). If you have a large amount of data (gigabytes or terabytes), it will be more challenging to share and transfer it. You may need to consider networked storage options or more sophisticated backup methods.</span></p>\r\n<p><span style=\"font-weight: 400;\">If your data will be changing frequently, please estimate how much extra storage will be required to store multiple versions. If you are collecting data over a long period of time (e.g. several months or years), please describe your plan for adding additional storage to accommodate the growth of your data.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64065, "text"=>"2.4 Are there are any existing data that you can re-use? If so, please explain how you will obtain that data and integrate it into your research project.", "default_value"=>nil, "number"=>4, "section_id"=>20787, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59884, "question_id"=>64065, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Considering answering the following questions: Where did the existing dataset(s) come from? Is that data published or publicly available? Will the project use contracted datasets (data from external sources?) &nbsp;If yes, will you be able to store a local copy of the contracted data?</span></p>\r\n<p><span style=\"font-weight: 400;\">Contact York University Libraries&rsquo; </span><a href=\"http://scottlibrary.apps01.yorku.ca/machform/view.php?id=31546\" target=\"_blank\"><span style=\"font-weight: 400;\">Open Scholarship Department</span></a><span style=\"font-weight: 400;\"> for help with finding existing data.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64066, "text"=>"2.5 What conventions and procedures will you use to structure, name and version-control your files to help you and others better understand how your data are organized?", "default_value"=>nil, "number"=>5, "section_id"=>20787, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59885, "question_id"=>64066, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Logical file structures, informative naming conventions, and clear indications of file versions, all contribute to better use of your data during and after your research project. These practices will help ensure that you and your research team are using the appropriate version of your data, and minimize confusion regarding copies on different computers and/or on different media.</span></p>\r\n<p><span style=\"font-weight: 400;\">Read more about </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/organising\" target=\"_blank\"><span style=\"font-weight: 400;\">file organizing</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/versioning\" target=\"_blank\"><span style=\"font-weight: 400;\">version control</span></a><span style=\"font-weight: 400;\"> from UK Data Archive.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>20788, "title"=>"Documentation and Metadata", "description"=>"<p><span style=\"font-weight: 400;\">Because data are rarely self-explanatory, all research data should be accompanied by metadata (information that describes the data according to community best practices). &nbsp;Metadata standards vary across disciplines, but generally state who created the data and when, how the data were created, their quality, accuracy, and precision, as well as other features necessary to facilitate data discovery, understanding and reuse. Any restrictions on use of the data must be explained in the metadata, along with information on how to obtain approved access to the data, where possible.</span></p>", "number"=>3, "phase_id"=>3228, "modifiable"=>false, "versionable_id"=>nil})
Question.create({"id"=>64067, "text"=>"3.1 What documentation will be needed for the data to be read and interpreted correctly in the future? This includes study-level documentation, data-level description, and any other contextual information required to make the data usable by other researchers.", "default_value"=>nil, "number"=>1, "section_id"=>20788, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59886, "question_id"=>64067, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Your documentation may include study-level information about:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">who created/collected the data</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">when it was created</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">any relevant study documents</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">conditions of use</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">contextual details about data collection methods and procedural documentation about how data files are stored, structured, and modified.</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">A complete description of the data files may include:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">naming and labelling conventions</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">explanations of codes and variables</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">any information or files require to reproduce derived data.</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">More information about data documentation is available at the </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/document.aspx\" target=\"_blank\" rel=\"noopener\"><span style=\"font-weight: 400;\">UK Data Archive</span></a></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64068, "text"=>"3.2 How will you make sure that documentation is created or captured consistently throughout your project?", "default_value"=>nil, "number"=>2, "section_id"=>20788, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59887, "question_id"=>64068, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Consider how you will capture this information and where it will be recorded, ideally in advance of data collection and analysis, to ensure accuracy, consistency, and completeness of the documentation. &nbsp;Often, resources you've already created can contribute to this (e.g. publications, websites, progress reports, etc.). It is useful to consult regularly with members of the research team to capture potential changes in data collection/processing that need to be reflected in the documentation. &nbsp;Individual roles and workflows should include gathering data documentation as a key element.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64069, "text"=>"3.3 If you are using a metadata standard and/or tools to document and describe your data, please list here.", "default_value"=>nil, "number"=>3, "section_id"=>20788, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59888, "question_id"=>64069, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Metadata is a description of the contents and context of data files. Using a metadata standard (a set of required fields to fill out) helps ensure that your documentation is consistent, structured, and machine-readable, which is essential for depositing data in repositories and making it easily discoverable by search engines.</span></p>\r\n<p><span style=\"font-weight: 400;\">There are general and discipline-specific </span><a href=\"http://www.dcc.ac.uk/resources/metadata-standards\" target=\"_blank\"><span style=\"font-weight: 400;\">metadata standards and tools</span></a><span style=\"font-weight: 400;\"> for research data. </span></p>\r\n<p><span style=\"font-weight: 400;\">For assistance with choosing and using a metadata standard, please contact York University Libraries at yul_rdm@yorku.ca</span><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>20789, "title"=>"Storage and Backup", "description"=>"<p><span style=\"font-weight: 400;\">Planning how research data will be stored and backed up throughout and beyond a research project is critical in ensuring data security and integrity. Appropriate storage and backup not only helps protect research data from catastrophic losses (due to hardware and software failures, viruses, hackers, natural disasters, human error, etc.), but also facilitates appropriate access by current and future researchers.</span></p>", "number"=>4, "phase_id"=>3228, "modifiable"=>false, "versionable_id"=>nil})
Question.create({"id"=>64070, "text"=>"4.1 What are the anticipated storage requirements for your project, in terms of storage space (in megabytes, gigabytes, terabytes, etc.) and the length of time you will be storing it? \r\n\r\nIf applicable, where are hardcopy notebooks and physical samples going to be physically stored?", "default_value"=>nil, "number"=>1, "section_id"=>20789, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59889, "question_id"=>64070, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Storage-space estimates should take into account requirements for file versioning, backups, and growth over time. They should also take into account whether the data will be preserved for a set number of years, or whether it needs to be preserved in perpetuity.</span></p>\r\n<p><span style=\"font-weight: 400;\">If you are collecting data over a long period (e.g. several months or years), your data storage and backup strategy should accommodate data growth. Similarly, a long-term storage plan is necessary if you intend to retain your data after the research project.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64071, "text"=>"4.2 How and where will your data be stored and backed up during your research project?", "default_value"=>nil, "number"=>2, "section_id"=>20789, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59890, "question_id"=>64071, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">The risk of losing data due to human error, natural disasters, or other mishaps can be mitigated by following the 3-2-1 backup rule:</span><span style=\"font-weight: 400;\"><br /></span><span style=\"font-weight: 400;\">1. Have at least three copies of your data.</span><span style=\"font-weight: 400;\"><br /></span><span style=\"font-weight: 400;\">2. Store the copies on two different media.</span><span style=\"font-weight: 400;\"><br /></span><span style=\"font-weight: 400;\">3. Keep one backup copy offsite</span><span style=\"font-weight: 400;\"><br /></span><span style=\"font-weight: 400;\">Data may be stored using optical or magnetic media, which can be removable (e.g. DVD and USB drives), fixed (e.g. desktop or laptop hard drives), or networked (e.g. networked drives or cloud-based servers). Each storage method has benefits and drawbacks that should be considered when determining the most appropriate solution.</span></p>\r\n<p><span style=\"font-weight: 400;\">Using software which automatically backs up your data and keeps it synchronized with a master copy is recommended. Copies of data should ideally be stored in separate physical locations to mitigate physical risks, e.g. fire. More about data storage from </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store\" target=\"_blank\"><span style=\"font-weight: 400;\">UK Data Archive</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">For York University researchers, UIT provides </span><a href=\"https://staff.computing.yorku.ca/support-services/server-data-storage/\" target=\"_blank\"><span style=\"font-weight: 400;\">secure storage solutions</span></a><span style=\"font-weight: 400;\"> that meet and exceed the 3-2-1 backup rule. Each file saved to UIT storage is copied three times, resulting in four separate copies. These copies reside in two separate data centres on campus, with the fourth copy stored at the University of Guelph. Find more information about </span><a href=\"https://staff.computing.yorku.ca/support-services/server-data-storage/\" target=\"_blank\"><span style=\"font-weight: 400;\">Server Data Storage offered by UIT</span></a><span style=\"font-weight: 400;\">. </span><span style=\"font-weight: 400;\">It is important that a conversation is had with UIT prior to submitting your grant as there may be costs associated with data storage that will need to be represented in your budget.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64072, "text"=>"4.3 How will the research team and other collaborators access, modify, and contribute data throughout the project?\r\n\r\nIf applicable, how will you ensure that sensitive data is stored securely and only accessible to the research team and other collaborators throughout the project?", "default_value"=>nil, "number"=>3, "section_id"=>20789, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59891, "question_id"=>64072, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">An ideal solution is one that facilitates co-operation and ensures data security. The security measures you choose to implement will depend on the sensitivity of the data being stored. Data can be protected by limiting physical access to hard drives and file servers on which it is stored, by storing data on computers that do not have external network access (i.e. access to the Internet), through password protection, and by encrypting data files. Sharing sensitive data via email and cloud storage services such as Dropbox is not recommended, since the security of these services cannot be trusted. </span><span style=\"font-weight: 400;\">&nbsp;Check out the York University&rsquo;s </span><a href=\"https://research.info.yorku.ca/data-security-guideline-research-involving-human-participants/\" target=\"_blank\"><span style=\"font-weight: 400;\">Data Security Guideline for Research Involving Human Participants</span></a></p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>20790, "title"=>"Preservation", "description"=>"<p><span style=\"font-weight: 400;\">Data preservation will depend on potential reuse value, whether there are obligations to either retain or destroy data, and the resources required to properly curate the data and ensure that it remains usable in the future. In some circumstances, it may be desirable to preserve all versions of the data (e.g. raw, processed, analyzed, final), but in others, it may be preferable to keep only selected or final data (e.g. transcripts instead of audio interviews).</span></p>", "number"=>5, "phase_id"=>3228, "modifiable"=>false, "versionable_id"=>nil})
Question.create({"id"=>64073, "text"=>"5.1 Which data are selected for preservation and access? ", "default_value"=>nil, "number"=>1, "section_id"=>20790, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59892, "question_id"=>64073, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Which data are selected for preservation and access will depend on potential reuse value, whether there are obligations to either retain or destroy data, and the resources required to properly curate the data and ensure that it remains usable in the future. In some circumstances, it may be feasible to preserve all versions of the data (e.g. raw, processed, analyzed, final), but in others, it may be preferable to only keep only selected data (e.g. transcripts instead of audio interviews).</span></p>\r\n<p><span style=\"font-weight: 400;\">It is important that the cost of longer term storage for larger data sets be considered and factored into the grant budget. See Section 4.2: </span><em><span style=\"font-weight: 400;\">How and where will your data be stored and backed up during your research project?</span></em></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64074, "text"=>"5.2 Where will you deposit your data for long-term preservation and access at the end of your research project? Is there specific software needed in order to use or interpret your research data collection?", "default_value"=>nil, "number"=>2, "section_id"=>20790, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59893, "question_id"=>64074, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Please describe how you will identify a data repository or data center for your data.</span></p>\r\n<p><a href=\"https://www.library.yorku.ca/web/open/rdm/depositdata/\" target=\"_blank\"><span style=\"font-weight: 400;\">Scholars Portal Dataverse</span></a><span style=\"font-weight: 400;\"> is available to York researchers and can serve preservation needs where file sizes are less than 2 GB. Scholars Portal Dataverse allows researchers to restrict access to datasets in compliance with research ethics guidelines.</span></p>\r\n<p><span style=\"font-weight: 400;\">Another option is the </span><a href=\"https://www.frdr.ca/repo/\" target=\"_blank\"><span style=\"font-weight: 400;\">Federated Research Data Repository (FRDR)</span></a><span style=\"font-weight: 400;\"> which also allows for data deposit. FRDR allows researchers to set an embargo period for their data.</span></p>\r\n<p><span style=\"font-weight: 400;\">Larger projects will need to </span><a href=\"http://staff.computing.yorku.ca/support-services/server-data-storage/#squelch-taas-toggle-shortcode-content-0\" target=\"_blank\"><span style=\"font-weight: 400;\">contact UIT</span></a><span style=\"font-weight: 400;\"> to discuss the ongoing cost of long-term preservation. It is prudent that these costs be written into the grant budget.</span></p>\r\n<p><span style=\"font-weight: 400;\">For other data deposit options, including discipline specific repositories, see the </span><a href=\"http://www.re3data.org/\" target=\"_blank\"><span style=\"font-weight: 400;\">re3data.org</span></a><span style=\"font-weight: 400;\"> directory.</span></p>\r\n<p><span style=\"font-weight: 400;\">There are many ways in which you can release your software. These include: a binary executable that can be run directly; bundled in an installer program; an archive (.zip or .tar.gz) of binary executables or libraries, or as Python or R packages; an archive of source code; via a download link on a web site; via e-mail from you; via access to a source code repository hosted at your institution or on a third-party site such as GitHub (<a href=\"http://github.com\" target=\"_blank\">http://github.com</a></span><span style=\"font-weight: 400;\">), GitLab (<a href=\"http://www.gitlab.com\" target=\"_blank\">http://www.gitlab.com</a></span><span style=\"font-weight: 400;\">), BitBucket (</span><a href=\"http://bitbucket.org\" target=\"_blank\"><span style=\"font-weight: 400;\">http://bitbucket.org</span></a><span style=\"font-weight: 400;\"><a href=\"http://bitbucket.org\" target=\"_blank\">)</a>, LaunchPad (<a href=\"https://launchpad.net\" target=\"_blank\">https://launchpad.net</a></span><span style=\"font-weight: 400;\">) or Assembla (</span><a href=\"https://www.assembla.com\" target=\"_blank\"><span style=\"font-weight: 400;\">https://www.assembla.com</span></a><span style=\"font-weight: 400;\">). (The Software Sustainability Institute. (2016). Checklist for a Software Management Plan. v0.1. doi: </span><a href=\"https://doi.org/10.5281/zenodo.1422657\" target=\"_blank\"><span style=\"font-weight: 400;\">10.5281/zenodo.1422657</span></a><span style=\"font-weight: 400;\">. Available online: https://www.software.ac.uk/software-management-plans.)</span></p>\r\n<p><span style=\"font-weight: 400;\">If you need assistance locating a suitable data repository or archive, please contact York University Libraries at yul_rdm@yorku.ca</span><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64075, "text"=>"5.3 Indicate how you will ensure your data is preservation ready. Consider preservation-friendly file formats, ensuring file integrity, anonymization and de-identification, inclusion of supporting documentation.", "default_value"=>nil, "number"=>3, "section_id"=>20790, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59894, "question_id"=>64075, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">It is likely that you will have multiple versions of your data (raw, processed, analyzed, final), and your data may be stored in different file formats depending on how they were collected and analyzed. Some data formats are optimal for long-term preservation of data. The UK Data Archive provides a list of </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/recommended-formats\" target=\"_blank\" rel=\"noopener\"><span style=\"font-weight: 400;\">recommended formats</span></a><span style=\"font-weight: 400;\"> for various types of data. </span></p>\r\n<p><span style=\"font-weight: 400;\">Digital information may be lost while converting files from one format to another (e.g. converting an image from a non-compressed &lsquo;lossless&rsquo; TIFF file to a compressed &lsquo;lossy&rsquo; JPG file), so changes to file formats should be clearly documented.</span></p>\r\n<p><span style=\"font-weight: 400;\">Identify what steps are needed after your project is completed in order to ensure the data you are choosing to preserve or share is anonymous, error-free, and converted to recommended formats with a minimal risk of data loss. Read more about </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical/anonymisation.aspx\" target=\"_blank\" rel=\"noopener\"><span style=\"font-weight: 400;\">anonymization</span></a><span style=\"font-weight: 400;\"> on the UK Data Archive Website.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>20791, "title"=>"Sharing and Reuse", "description"=>"<p><span style=\"font-weight: 400;\">Most Canadian research funding agencies now have policies requiring research data to be shared upon publication of the research results or within a reasonable period of time. While data sharing contributes to the visibility and impact of research, it has to be balanced with the legitimate desire of researchers to maximise their research outputs before releasing their data. Equally important is the need to protect the privacy of respondents and to properly handle sensitive data.</span></p>", "number"=>6, "phase_id"=>3228, "modifiable"=>false, "versionable_id"=>nil})
Question.create({"id"=>64076, "text"=>"6.1 What data will you be sharing and in what form? (e.g. raw, processed, analyzed, final). ", "default_value"=>nil, "number"=>1, "section_id"=>20791, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59895, "question_id"=>64076, "org_id"=>45, "text"=>"<p><strong>Raw data</strong><span style=\"font-weight: 400;\"> are the data directly obtained from the instrument, simulation or survey.</span></p>\r\n<p><strong>Processed data</strong><span style=\"font-weight: 400;\"> result from some manipulation of the raw data in order to eliminate errors or outliers, to prepare the data for analysis, to derive new variables, or to de-identify the human participants.</span></p>\r\n<p><strong>Analyzed data</strong><span style=\"font-weight: 400;\"> are the the results of qualitative, statistical, or mathematical analysis of the processed data. They can be presented as graphs, charts or statistical tables.</span></p>\r\n<p><strong>Final data</strong><span style=\"font-weight: 400;\"> are processed data that have, if needed, been converted into a preservation-friendly format.</span></p>\r\n<p><span style=\"font-weight: 400;\">Consider which data may need to be shared in order to meet institutional or funding requirements, and which data may be restricted because of confidentiality/privacy/intellectual property considerations.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64077, "text"=>"6.2 If the way you store and share data during your research project differs from how you will preserve your data long-term, include a brief description of any resources needed to share your data (equipment, systems, expertise, etc.).", "default_value"=>nil, "number"=>2, "section_id"=>20791, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59896, "question_id"=>64077, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">It&rsquo;s possible that the data repository you've selected provides long-term preservation but does not meet your needs in terms of short- or medium-term data sharing and access. For instance, you may need exploration and analysis tools that the long-term archive does not provide. &nbsp;In addition, the long-term archive may not provide flexible authenticated-access options. Also consider if the repository supports metadata standards commonly used by researchers in your field.</span></p>\r\n<p><span style=\"font-weight: 400;\">In some instances, you may want to use another (or additional) repository or platform to share your dataset. </span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64078, "text"=>"6.3 How will you be sharing your data? (e.g. institutional repository, a specialized data archive, informal/on-request \r\nsharing). Include a brief description of any resources needed to share your data (equipment, systems, expertise, etc.).", "default_value"=>nil, "number"=>3, "section_id"=>20791, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59897, "question_id"=>64078, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Where you share your data depends on the complexity and size of your data. Smaller, low-risk datasets can be shared via institutional or disciplinary repositories. Larger datasets or datasets with more stringent security requirements cannot be easily transferred over the Internet. Read more about sharing data at the </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/plan/how-share.aspx\" target=\"_blank\" rel=\"noopener\"><span style=\"font-weight: 400;\">UK Data Archive</span></a><span style=\"font-weight: 400;\">. </span></p>\r\n<p><span style=\"font-weight: 400;\">See section 5.2: </span><em><span style=\"font-weight: 400;\">Where will you deposit your data for long-term preservation and access at the end of your research project?</span></em><span style=\"font-weight: 400;\"> This section suggests repositories that allow for both sharing and preservation</span><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">For help, please contact York University Libraries at yul_rdm@yorku.ca</span><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64079, "text"=>"6.4 Please describe whether there will be any restrictions placed on your data when they are made available and who may access them. If data are not openly available, describe the process for gaining access.", "default_value"=>nil, "number"=>4, "section_id"=>20791, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59898, "question_id"=>64079, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">It may be necessary or desirable to restrict access to your data for a limited time or to a limited number of people, for:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">ethical reasons (privacy and confidentiality)</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">economic reasons (patents and commercialization)</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">intellectual property reasons (e.g. ownership of the original dataset on which yours is based)</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">or to comply with a journal publishing policy.</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Strategies to mitigate these issues may include:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical/anonymisation.aspx\" target=\"_blank\"><span style=\"font-weight: 400;\">anonymising or aggregating data</span></a></li>\r\n<li style=\"font-weight: 400;\"><a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical/consent-data-sharing\" target=\"_blank\"><span style=\"font-weight: 400;\">gaining participant consent for data sharing</span></a></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">gaining permissions to share adapted or modified data</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">and agreeing to a limited embargo period.</span></li>\r\n</ul>\r\n<p><a href=\"https://dataverse.scholarsportal.info/\" target=\"_blank\"><span style=\"font-weight: 400;\">Scholars Portal Dataverse</span></a><span style=\"font-weight: 400;\"> is available to York researchers and can serve preservation needs where file sizes are less than 2 GB. Scholars Portal Dataverse allows researchers to restrict access to datasets in compliance with research ethics guidelines.</span></p>\r\n<p><span style=\"font-weight: 400;\">For help, please contact York University Libraries at yul_rdm@yorku.ca</span><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64080, "text"=>"6.5 Have you considered what type of end-user license to include with your data?", "default_value"=>nil, "number"=>5, "section_id"=>20791, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59899, "question_id"=>64080, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Licenses determine what uses can be made of your data. Funding agencies and/or data repositories may have end-user license requirements in place; if not, they may still be able to guide you in the development of a license. Once created, please consider including a copy of your end-user license with your Data Management Plan. Note that only the intellectual property rights holder(s) can issue a license, so it is crucial to clarify who owns those rights.</span></p>\r\n<p><span style=\"font-weight: 400;\">There are several types of standard licenses available to researchers, such as the </span><a href=\"http://creativecommons.org/choose/\" target=\"_blank\"><span style=\"font-weight: 400;\">Creative Commons licenses</span></a><span style=\"font-weight: 400;\"> and the </span><a href=\"http://opendatacommons.org/licenses/\" target=\"_blank\"><span style=\"font-weight: 400;\">Open Data Commons licenses</span></a><span style=\"font-weight: 400;\">. In fact, for most datasets it is easier to use a standard license rather than to devise a custom-made one. Note that even if you choose to make your data part of the public domain, it is preferable to make this explicit by using a license such as Creative Commons' CC0.</span></p>\r\n<p><span style=\"font-weight: 400;\">Read more about </span><a href=\"https://www.library.yorku.ca/web/open/overview/data-licensing/\" target=\"_blank\"><span style=\"font-weight: 400;\">data licensing</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">For help, please contact York University Libraries at yul_rdm@yorku.ca</span><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64081, "text"=>"6.6 What steps will be taken to help the research community know that your data exists?", "default_value"=>nil, "number"=>6, "section_id"=>20791, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59900, "question_id"=>64081, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Possibilities include: data registries, repositories, indexes, word-of-mouth, publications.</span></p>\r\n<p><span style=\"font-weight: 400;\">How will the data be accessed (Web service, ftp, etc.)? If possible, choose a repository that will assign a persistent identifier (such as a DOI) to your dataset. This will ensure a stable access to the dataset and make it retrievable by various discovery tools.</span></p>\r\n<p><span style=\"font-weight: 400;\">One of the best ways to refer other researchers to your deposited datasets is to cite them the same way you cite other types of publications (articles, books, proceedings). The Digital Curation Centre provides a detailed </span><a href=\"http://www.dcc.ac.uk/resources/how-guides/cite-datasets\" target=\"_blank\"><span style=\"font-weight: 400;\">guide</span></a><span style=\"font-weight: 400;\"> on data citation, as does the </span><a href=\"https://www.datacite.org/\" target=\"_blank\"><span style=\"font-weight: 400;\">DataCite</span></a><span style=\"font-weight: 400;\"> website. Note that some data repositories also create links from datasets to their associated papers, thus increasing the visibility of the publications.</span></p>\r\n<p><a href=\"https://dataverse.scholarsportal.info/\" target=\"_blank\"><span style=\"font-weight: 400;\">Scholars Portal Dataverse</span></a><span style=\"font-weight: 400;\"> and the </span><a href=\"https://www.frdr.ca/repo/\" target=\"_blank\"><span style=\"font-weight: 400;\">Federated Research Data Repository (FRDR)</span></a><span style=\"font-weight: 400;\"> are available to York researchers and can assign a persistent identifier (DOI) for your dataset.</span></p>\r\n<p><span style=\"font-weight: 400;\">For assistance in making your dataset visible and easily accessible, please contact York University Libraries at yul_rdm@yorku.ca</span><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>20792, "title"=>"Responsibilities and Resources", "description"=>"<p><span style=\"font-weight: 400;\">Data management focuses on the 'what' and 'how' of operationally supporting data across the research lifecycle. &nbsp;Data stewardship focuses on 'who' is responsible for ensuring that data management happens. A large project, for example, will involve multiple data stewards. The Principal Investigator should identify at the beginning of a project all of the people who will have responsibilities for data management tasks during and after the project.</span></p>", "number"=>7, "phase_id"=>3228, "modifiable"=>false, "versionable_id"=>nil})
Question.create({"id"=>64082, "text"=>"7.1 Identify who will be responsible for managing this project's data during and after the project and the major data management tasks for which they will be responsible.", "default_value"=>nil, "number"=>1, "section_id"=>20792, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59901, "question_id"=>64082, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Your data management plan has identified important data activities in your project. Identify who will be responsible -- individuals or organizations -- for carrying out these parts of your data management plan. This could also include the time frame associated with these staff responsibilities and any training needed to prepare staff for these duties.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64083, "text"=>"7.2 How will responsibilities for managing data activities be handled if substantive changes happen in the personnel overseeing the project's data, including a change of Principal Investigator?", "default_value"=>nil, "number"=>2, "section_id"=>20792, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59902, "question_id"=>64083, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Indicate a succession strategy for these data in the event that one or more people responsible for the data leaves (e.g. a graduate student leaving after graduation). Describe the process to be followed in the event that the Principal Investigator leaves the project. In some instances, a co-investigator or the department or division overseeing this research will assume responsibility.</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64084, "text"=>"7.3 What resources will you require to implement your data management plan? What do you estimate the overall cost for data management to be?\r\n\r\nWhat additional resources will you require to implement your data management plan?", "default_value"=>nil, "number"=>3, "section_id"=>20792, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59903, "question_id"=>64084, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">This estimate should incorporate data management costs incurred during the project as well as those required for the longer-term support for the data after the project is finished. Items to consider in the latter category of expenses include the costs of curating and providing long-term access to the data. Some funding agencies state explicitly the support that they will provide to meet the </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/plan/costing\" target=\"_blank\"><span style=\"font-weight: 400;\">cost of preparing data for deposit</span></a><span style=\"font-weight: 400;\">. This might include technical aspects of data management, training requirements, file storage &amp; backup, and contributions of non-project staff. </span></p>\r\n<p><span style=\"font-weight: 400;\">More information about estimating cost for data management is available through the UK Data Archive via their </span><a href=\"https://data-archive.ac.uk/media/247429/costingtool.pdf\" target=\"_blank\"><span style=\"font-weight: 400;\">Data Management Costing Tool</span></a><span style=\"font-weight: 400;\">. This information should be incorporated into any grant applications for your project. </span></p>\r\n<p>&nbsp;</p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>20793, "title"=>"Ethics and Legal Compliance", "description"=>"<p><span style=\"font-weight: 400;\">Researchers and their teams need to be aware of the policies and processes, both ethical and legal, to which their research data management must comply. Protection of respondent privacy is of paramount importance and informs many data management practices. &nbsp;In their data management plan, researchers must state how they will prepare, store, share, and archive the data in a way that ensures participant information is protected, throughout the research lifecycle, from disclosure, harmful use, or inappropriate linkages with other personal data.</span><span style=\"font-weight: 400;\"><br /></span><span style=\"font-weight: 400;\">It's recognized that there may be cases where certain data and metadata cannot be made public for various policy or legal reasons, however, the default position should be that all research data and metadata are public.</span></p>", "number"=>8, "phase_id"=>3228, "modifiable"=>false, "versionable_id"=>nil})
Question.create({"id"=>64085, "text"=>"8.1 If your research project includes sensitive data, how will you ensure that it is securely managed and accessible only to approved members of the project?", "default_value"=>nil, "number"=>1, "section_id"=>20793, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59904, "question_id"=>64085, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Consider where, how, and to whom sensitive data with acknowledged long-term value should be made available, and how long it should be archived. These decisions should align with </span><a href=\"http://research.info.yorku.ca/research-ethics/\" target=\"_blank\"><span style=\"font-weight: 400;\">Research Ethics Board</span></a><span style=\"font-weight: 400;\"> requirements. The methods used to share data will be dependent on a number of factors such as the type, size, complexity and degree of sensitivity of data. </span></p>\r\n<p><span style=\"font-weight: 400;\">If researchers seek to share openly de-identified data emerging from their research, it is crucial that consent be secured from participants during the informed consent process. Contact the </span><a href=\"http://research.info.yorku.ca/research-ethics/\" target=\"_blank\"><span style=\"font-weight: 400;\">Office of Research Ethics</span></a><span style=\"font-weight: 400;\"> for further details. Further details can be found on </span><a href=\"https://yulink-new.yorku.ca/group/yulink/research-ethics\" target=\"_blank\"><span style=\"font-weight: 400;\">YULink</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">Restrictions can be imposed by limiting physical access to storage devices, by placing data on computers that do not have external network access (i.e. access to the Internet), through password protection, and by encrypting files. Sensitive data should never be shared via email or cloud storage services such as Dropbox.</span></p>\r\n<p><span style=\"font-weight: 400;\">Outline problems anticipated in sharing data, along with causes and possible measures to mitigate these. Problems may include confidentiality, lack of consent agreements, or concerns about Intellectual Property Rights, among others. In some instances, an embargo period may be justified; these may be defined by a funding agency's policy on research data. (Reused from: DCC. (2013). Checklist for a Data Management Plan. v.4.0. Edinburgh: Digital Curation Centre)</span></p>\r\n<p><span style=\"font-weight: 400;\">Check out the York University&rsquo;s </span><a href=\"https://research.info.yorku.ca/data-security-guideline-research-involving-human-participants/\" target=\"_blank\"><span style=\"font-weight: 400;\">Data Security Guideline for Research Involving Human Participants</span></a><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64086, "text"=>"8.2 If applicable, what strategies will you undertake to address secondary uses of sensitive data?", "default_value"=>nil, "number"=>2, "section_id"=>20793, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59905, "question_id"=>64086, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Obtaining the appropriate consent from research participants is an important step in assuring</span> <a href=\"http://research.info.yorku.ca/research-ethics/\" target=\"_blank\" rel=\"noopener\"><span style=\"font-weight: 400;\">Research Ethics Boards</span></a><span style=\"font-weight: 400;\"> that the data may be shared with researchers outside your project. The consent statement may identify certain conditions clarifying the uses of the data by other researchers. For example, it may stipulate that the data will only be shared for non-profit research purposes or that the data will not be linked with personally identified data from other sources.</span></p>\r\n<p><span style=\"font-weight: 400;\">Read more about data security: </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\" target=\"_blank\" rel=\"noopener\"><span style=\"font-weight: 400;\">UK Data Archive</span></a></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>64087, "text"=>"8.3 How will you manage legal, ethical, and intellectual property issues?", "default_value"=>nil, "number"=>3, "section_id"=>20793, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>false, "versionable_id"=>nil})
Annotation.create({"id"=>59906, "question_id"=>64087, "org_id"=>45, "text"=>"<p><span style=\"font-weight: 400;\">Compliance with privacy legislation and laws that may impose content restrictions in the data should be discussed with your </span><a href=\"http://ipo.info.yorku.ca/\" target=\"_blank\"><span style=\"font-weight: 400;\">institution's privacy officer</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"http://research.info.yorku.ca/research-services/\" target=\"_blank\"><span style=\"font-weight: 400;\">research services office</span></a><span style=\"font-weight: 400;\">. </span><a href=\"http://research.info.yorku.ca/research-ethics/\" target=\"_blank\"><span style=\"font-weight: 400;\">Research Ethics Boards</span></a><span style=\"font-weight: 400;\"> are central to the research process.</span></p>\r\n<p><span style=\"font-weight: 400;\">Include here a description concerning ownership, licensing, and intellectual property rights of the data. Terms of reuse must be clearly stated, in line with the relevant legal and ethical requirements where applicable (e.g., subject consent, permissions, restrictions, etc.).</span></p>", "type"=>"guidance", "versionable_id"=>nil})
Template.create!({"id"=>3402, "title"=>"Portage Template", "description"=>"This is the generic DMP template for Portage.", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>1088, "visibility"=>0, "customization_of"=>nil, "family_id"=>12, "archived"=>true, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3389, "title"=>"Portage Data Management Questions", "description"=>nil, "number"=>1, "template_id"=>3402, "modifiable"=>true, "versionable_id"=>nil})
Section.create({"id"=>21847, "title"=>"Data Collection", "description"=>"This section addresses data collection issues such as data types, file formats, naming conventions, and data organisation – factors that will improve the usability of your data and contribute to the success of your project.", "number"=>1, "phase_id"=>3389, "modifiable"=>true, "versionable_id"=>nil})
Question.create({"id"=>67252, "text"=>"What types of data will you collect, create, link to, acquire and/or record?", "default_value"=>nil, "number"=>1, "section_id"=>21847, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63037, "question_id"=>67252, "org_id"=>8, "text"=>"<p>Examples: numeric, images, audio, video, text, tabular data, modeling data, spatial data, instrumentation data.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67253, "text"=>"What file formats will your data be collected in? Will these formats allow for data re-use, sharing and long-term access to the data?", "default_value"=>nil, "number"=>2, "section_id"=>21847, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63038, "question_id"=>67253, "org_id"=>8, "text"=>"<p>Proprietary file formats requiring specialized software or hardware to use are not recommended, but may be necessary for certain data collection or analysis methods. Using open file formats or industry-standard formats (e.g. those widely used by a given community) is preferred whenever possible.</p>\r\n<p>Read more about file formats: <a href=\"http://researchdata.library.ubc.ca/plan/format-your-data/\" target=\"_blank\" rel=\"noopener\">UBC Library</a> or <a href=\"https://www.ukdataservice.ac.uk/manage-data/format/file-formats.aspx\" target=\"_blank\" rel=\"noopener\">UK Data Service</a>.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67254, "text"=>"What conventions and procedures will you use to structure, name and version-control your files to help you and others better understand how your data are organized?", "default_value"=>nil, "number"=>3, "section_id"=>21847, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63039, "question_id"=>67254, "org_id"=>8, "text"=>"<p>It is important to keep track of different copies or versions of files, files held in different formats or locations, and information cross-referenced between files. This process is called 'version control'.</p>\r\n<p>Logical file structures, informative naming conventions, and clear indications of file versions, all contribute to better use of your data during and after your research project. &nbsp;These practices will help ensure that you and your research team are using the appropriate version of your data, and minimize confusion regarding copies on different computers and/or on different media.</p>\r\n<p>Read more about file naming and version control: <a href=\"http://researchdata.library.ubc.ca/plan/organize-your-data/\" target=\"_blank\" rel=\"noopener\">UBC Library</a> or <a href=\"https://www.ukdataservice.ac.uk/manage-data/format/versioning.aspx\" target=\"_blank\" rel=\"noopener\">UK Data Service</a>.</p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>21848, "title"=>"Documentation and Metadata", "description"=>"Because data are rarely self-explanatory, all research data should be accompanied by metadata (information that describes the data according to community best practices).  Metadata standards vary across disciplines, but generally state who created the data and when, how the data were created, their quality, accuracy, and precision, as well as other features necessary to facilitate data discovery, understanding and reuse. </br>Any restrictions on use of the data must be explained in the metadata, along with information on how to obtain approved access to the data, where possible.", "number"=>2, "phase_id"=>3389, "modifiable"=>true, "versionable_id"=>nil})
Question.create({"id"=>67255, "text"=>"What documentation will be needed for the data to be read and interpreted correctly in the future?", "default_value"=>nil, "number"=>1, "section_id"=>21848, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63040, "question_id"=>67255, "org_id"=>8, "text"=>"<p>Typically, good documentation includes information about the study, data-level descriptions, and any other contextual information required to make the data usable by other researchers.  Other elements you should document, as applicable, include: research methodology used, variable definitions, vocabularies, classification systems, units of measurement, assumptions made, format and file type of the data, a description of the data capture and collection methods, explanation of data coding and analysis performed (including syntax files), and details of who has worked on the project and performed each task, etc.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67256, "text"=>"How will you make sure that documentation is created or captured consistently throughout your project?", "default_value"=>nil, "number"=>2, "section_id"=>21848, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63041, "question_id"=>67256, "org_id"=>8, "text"=>"<p>Consider how you will capture this information and where it will be recorded, ideally in advance of data collection and analysis, to ensure accuracy, consistency, and completeness of the documentation.  Often, resources you've already created can contribute to this (e.g. publications, websites, progress reports, etc.).  It is useful to consult regularly with members of the research team to capture potential changes in data collection/processing that need to be reflected in the documentation.  Individual roles and workflows should include gathering data documentation as a key element.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67257, "text"=>"If you are using a metadata standard and/or tools to document and describe your data, please list here.", "default_value"=>nil, "number"=>3, "section_id"=>21848, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63042, "question_id"=>67257, "org_id"=>8, "text"=>"<p>There are many general and domain-specific metadata standards.  Dataset documentation should be provided in one of these standard, machine readable, openly-accessible formats to enable the effective exchange of information between users and systems.  These standards are often based on language-independent data formats such as XML, RDF, and JSON. There are many metadata standards based on these formats, including discipline-specific standards.</p> <p>Read more about metadata standards:  <a href=\"http://dcc.ac.uk/resources/metadata-standards\" target=\"_blank\">UK Digital Curation Centre's Disciplinary Metadata</a>. </p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>21849, "title"=>"Storage and Backup", "description"=>"Planning how research data will be stored and backed up throughout and beyond a research project is critical in ensuring data security and integrity. Appropriate storage and backup not only helps protect research data from catastrophic losses (due to hardware and software failures, viruses, hackers, natural disasters, human error, etc.), but also facilitates appropriate access by current and future researchers.", "number"=>3, "phase_id"=>3389, "modifiable"=>true, "versionable_id"=>nil})
Question.create({"id"=>67258, "text"=>"What are the anticipated storage requirements for your project, in terms of storage space (in megabytes, gigabytes, terabytes, etc.) and the length of time you will be storing it?", "default_value"=>nil, "number"=>1, "section_id"=>21849, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63043, "question_id"=>67258, "org_id"=>8, "text"=>"<p>Storage-space estimates should take into account requirements for file versioning, backups, and growth over time.  </p> <p>If you are collecting data over a long period (e.g. several months or years), your data storage and backup strategy should accommodate data growth. Similarly, a long-term storage plan is necessary if you intend to retain your data after the research project.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67259, "text"=>"How and where will your data be stored and backed up during your research project?", "default_value"=>nil, "number"=>2, "section_id"=>21849, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63044, "question_id"=>67259, "org_id"=>8, "text"=>"<p>The risk of losing data due to human error, natural disasters, or other mishaps can be mitigated by following the&nbsp;<a href=\"http://dataabinitio.com/?p=501\" target=\"_blank\" rel=\"noopener\">3-2-1 backup rule</a>:</p>\r\n<ul>\r\n<li>Have at least three copies of your data.</li>\r\n<li>Store the copies on two different media.</li>\r\n<li>Keep one backup copy offsite</li>\r\n</ul>\r\n<p>Data may be stored using optical or magnetic media, which can be removable (e.g. DVD and USB drives), fixed (e.g. desktop or laptop hard drives), or networked (e.g. networked drives or cloud-based servers). Each storage method has benefits and drawbacks that should be considered when determining the most appropriate solution.</p>\r\n<p>Further information on storage and backup practices is available from the <a href=\"https://www.sheffield.ac.uk/library/rdm/storage\" target=\"_blank\" rel=\"noopener\">University of Sheffield Library</a> and the <a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\" target=\"_blank\" rel=\"noopener\">UK Data Service</a>.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67260, "text"=>"How will the research team and other collaborators access, modify, and contribute data throughout the project?", "default_value"=>nil, "number"=>3, "section_id"=>21849, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63045, "question_id"=>67260, "org_id"=>8, "text"=>"<p>An ideal solution is one that facilitates co-operation and ensures data security, yet is able to be adopted by users with minimal training. Transmitting data between locations or within research teams can be challenging for data management infrastructure. Relying on email for data transfer is not a robust or secure solution. Third-party commercial file sharing services (such as Google Drive and Dropbox) facilitate file exchange, but they are not necessarily permanent or secure, and are often located outside Canada. Please contact your Library to develop the best solution for your research project.</p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>21850, "title"=>"Preservation", "description"=>"Data preservation will depend on potential reuse value, whether there are obligations to either retain or destroy data, and the resources required to properly curate the data and ensure that it remains usable in the future. In some circumstances, it may be desirable to preserve all versions of the data (e.g. raw, processed, analyzed, final), but in others, it may be preferable to keep only selected or final data (e.g. transcripts instead of audio interviews).", "number"=>4, "phase_id"=>3389, "modifiable"=>true, "versionable_id"=>nil})
Question.create({"id"=>67261, "text"=>"Where will you deposit your data for long-term preservation and access at the end of your research project?", "default_value"=>nil, "number"=>1, "section_id"=>21850, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63046, "question_id"=>67261, "org_id"=>8, "text"=>"<p>The issue of data retention should be considered early in the research lifecycle.  Data-retention decisions can be driven by external policies (e.g. funding agencies, journal publishers), or by an understanding of the enduring value of a given set of data.  The need to preserve data in the short-term (i.e. for peer-verification purposes) or long-term (for data of lasting value), will influence the choice of data repository or archive.  A helpful analogy is to think of creating a 'living will' for the data, that is, a plan describing how future researchers will have continued access to the data.</p><p>If you need assistance locating a suitable data repository or archive, please contact your Library.</p><p><a href=\"http://www.re3data.org/\" target=\"_blank\">re3data.org</a> is a directory of potential open data repositories. Verify whether or not the data repository will provide a statement agreeing to the terms of deposit outlined in your Data Management Plan.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67262, "text"=>"Indicate how you will ensure your data is preservation ready. Consider preservation-friendly file formats, ensuring file integrity, anonymization and de-identification, inclusion of supporting documentation.", "default_value"=>nil, "number"=>2, "section_id"=>21850, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63047, "question_id"=>67262, "org_id"=>8, "text"=>"<p>Some data formats are optimal for long-term preservation of data. For example, non-proprietary file formats, such as text ('.txt') and comma-separated ('.csv'), are considered preservation-friendly. The UK Data Service provides a useful table of file formats for various types of data. Keep in mind that preservation-friendly files converted from one format to another may lose information (e.g. converting from an uncompressed TIFF file to a compressed JPG file), so changes to file formats should be documented.</p>\r\n<p>Identify steps required following project completion in order to ensure the data you are choosing to preserve or share is anonymous, error-free, and converted to recommended formats with a minimal risk of data loss.</p>\r\n<p>Read more about anonymization: <a href=\"https://researchdata.library.ubc.ca/share/anonymize-and-de-identify/\" target=\"_blank\" rel=\"noopener\">UBC Library</a> or <a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical/anonymisation.aspx\" target=\"_blank\" rel=\"noopener\">UK Data Service</a>.</p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>21851, "title"=>"Sharing and Reuse", "description"=>"Most Canadian research funding agencies now have policies requiring research data to be shared upon publication of the research results or within a reasonable period of time. While data sharing contributes to the visibility and impact of research, it has to be balanced with the legitimate desire of researchers to maximise their research outputs before releasing their data. Equally important is the need to protect the privacy of respondents and to properly handle sensitive data.", "number"=>5, "phase_id"=>3389, "modifiable"=>true, "versionable_id"=>nil})
Question.create({"id"=>67263, "text"=>"What data will you be sharing and in what form? (e.g. raw, processed, analyzed, final).", "default_value"=>nil, "number"=>1, "section_id"=>21851, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63048, "question_id"=>67263, "org_id"=>8, "text"=>"<p><b>Raw data</b> are the data directly obtained from the instrument, simulation or survey.</p><p><b>Processed data</b> result from some manipulation of the raw data in order to eliminate errors or outliers, to prepare the data for analysis, to derive new variables, or to de-identify the human participants. </p><p><b>Analyzed data</b> are the the results of qualitative, statistical, or mathematical analysis of the processed data. They can be presented as graphs, charts or statistical tables.</p><p><b>Final data</b> are processed data that have, if needed, been converted into a preservation-friendly format.</p><p>Consider which data may need to be shared in order to meet institutional or funding requirements, and which data may be restricted because of confidentiality/privacy/intellectual property considerations.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67264, "text"=>"Have you considered what type of end-user license to include with your data?", "default_value"=>nil, "number"=>2, "section_id"=>21851, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63049, "question_id"=>67264, "org_id"=>8, "text"=>"<p>Licenses determine what uses can be made of your data. Funding agencies and/or data repositories may have end-user license requirements in place; if not, they may still be able to guide you in the development of a license. Once created, please consider including a copy of your end-user license with your Data Management Plan.  Note that only the intellectual property rights holder(s) can issue a license, so it is crucial to clarify who owns those rights. </p><p>There are several types of standard licenses available to researchers, such as the <a href=\"http://creativecommons.org/choose/\" target=\"_blank\">Creative Commons licenses</a> and the <a href=\"http://opendatacommons.org/licenses/\" target=\"_blank\">Open Data Commons licenses</a>. In fact, for most datasets it is easier to use a standard license rather than to devise a custom-made one. Note that even if you choose to make your data part of the public domain, it is preferable to make this explicit by using a license such as Creative Commons'  CC0. </p> <p>Read more about data licensing: <a href=\"http://www.dcc.ac.uk/resources/how-guides/license-research-data\" target=\"_blank\">UK Digital Curation Centre</a>. </p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67265, "text"=>"What steps will be taken to help the research community know that your data exists?", "default_value"=>nil, "number"=>3, "section_id"=>21851, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63050, "question_id"=>67265, "org_id"=>8, "text"=>"<p>Possibilities include: data registries, repositories, indexes, word-of-mouth, publications.</p><p>How will the data be accessed (Web service, ftp, etc.)? If possible, choose a repository that will assign a persistent identifier (such as a DOI) to your dataset. This will ensure a stable access to the dataset and make it retrievable by various discovery tools.</p><p>One of the best ways to refer other researchers to your deposited datasets is to cite them the same way you cite other types of publications (articles, books, proceedings). The Digital Curation Centre provides a detailed <a href=\"http://www.dcc.ac.uk/resources/how-guides/cite-datasets\" target=\"_blank\">guide</a> on data citation.Note that some data repositories also create links from datasets to their associated papers, thus increasing the visibility of the publications.</p><p>Contact your Library for assistance in making your dataset visible and easily accessible. </p><p>Reused from NIH. (2009). <a href=\"https://grants.nih.gov/grants/sharing_key_elements_data_sharing_plan.pdf\" target=\"_blank\">Key Elements to Consider in Preparing a Data Sharing Plan Under NIH Extramural Support</a>. National Institutes of Health.</p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>21852, "title"=>"Responsibilities and Resources", "description"=>"Data management focuses on the 'what' and 'how' of operationally supporting data across the research lifecycle.  Data stewardship focuses on 'who' is responsible for ensuring that data management happens. A large project, for example, will involve multiple data stewards. The Principal Investigator should identify at the beginning of a project all of the people who will have responsibilities for data management tasks during and after the project.", "number"=>6, "phase_id"=>3389, "modifiable"=>true, "versionable_id"=>nil})
Question.create({"id"=>67266, "text"=>"Identify who will be responsible for managing this project's data during and after the project and the major data management tasks for which they will be responsible.", "default_value"=>nil, "number"=>1, "section_id"=>21852, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63051, "question_id"=>67266, "org_id"=>8, "text"=>"<p>Your data management plan has identified important data activities in your project. Identify who will be responsible -- individuals or organizations -- for carrying out these parts of your data management plan. This could also include the timeframe associated with these staff responsibilities and any training needed to prepare staff for these duties.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67267, "text"=>"How will responsibilities for managing data activities be handled if substantive changes happen in the personnel overseeing the project's data, including a change of Principal Investigator?", "default_value"=>nil, "number"=>2, "section_id"=>21852, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63052, "question_id"=>67267, "org_id"=>8, "text"=>"<p>Indicate a succession strategy for these data in the event that one or more people responsible for the data leaves (e.g. a graduate student leaving after graduation). Describe the process to be followed in the event that the Principal Investigator leaves the project. In some instances, a co-investigator or the department or division overseeing this research will assume responsibility.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67268, "text"=>"What resources will you require to implement your data management plan? What do you estimate the overall cost for data management to be?", "default_value"=>nil, "number"=>3, "section_id"=>21852, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63053, "question_id"=>67268, "org_id"=>8, "text"=>"<p>This estimate should incorporate data management costs incurred during the project as well as those required for the longer-term support for the data after the project is finished. Items to consider in the latter category of expenses include the costs of curating and providing long-term access to the data. Some funding agencies state explicitly the support that they will provide to meet the cost of preparing data for deposit. This might include technical aspects of data management, training requirements, file storage & backup, and contributions of non-project staff.</p>", "type"=>"guidance", "versionable_id"=>nil})
Section.create({"id"=>21853, "title"=>"Ethics and Legal Compliance", "description"=>"Researchers and their teams need to be aware of the policies and processes, both ethical and legal, to which their research data management must comply. Protection of respondent privacy is of paramount importance and informs many data management practices.  In their data management plan, researchers must state how they will prepare, store, share, and archive the data in a way that ensures participant information is protected, throughout the research lifecycle, from disclosure, harmful use, or inappropriate linkages with other personal data.</br>It's recognized that there may be cases where certain data and metadata cannot be made public for various policy or legal reasons, however, the default position should be that all research data and metadata are public.", "number"=>7, "phase_id"=>3389, "modifiable"=>true, "versionable_id"=>nil})
Question.create({"id"=>67269, "text"=>"If your research project includes sensitive data, how will you ensure that it is securely managed and accessible only to approved members of the project?", "default_value"=>nil, "number"=>1, "section_id"=>21853, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63054, "question_id"=>67269, "org_id"=>8, "text"=>"<p>Consider where, how, and to whom sensitive data with acknowledged long-term value should be made available, and how long it should be archived. These decisions should align with Research Ethics Board requirements. The methods used to share data will be dependent on a number of factors such as the type, size, complexity and degree of sensitivity of data. Outline problems anticipated in sharing data, along with causes and possible measures to mitigate these. Problems may include confidentiality, lack of consent agreements, or concerns about Intellectual Property Rights, among others. In some instances, an embargo period may be justified; these may be defined by a funding agency's policy on research data. </p><p>Reused from: DCC. (2013). <a href=\"http://www.dcc.ac.uk/resources/data-management-plans\" target=\"_blank\">Checklist for a Data Management Plan</a>. v.4.0. Edinburgh: Digital Curation Centre</p><p>Restrictions can be imposed by limiting physical access to storage devices, by placing data on computers that do not have external network access (i.e. access to the Internet), through password protection, and by encrypting files.  Sensitive data should never be shared via email or cloud storage services such as Dropbox.</p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67270, "text"=>"If applicable, what strategies will you undertake to address secondary uses of sensitive data?", "default_value"=>nil, "number"=>2, "section_id"=>21853, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63055, "question_id"=>67270, "org_id"=>8, "text"=>"<p>Obtaining the appropriate consent from research participants is an important step in assuring Research Ethics Boards that the data may be shared with researchers outside your project. The consent statement may identify certain conditions clarifying the uses of the data by other researchers. For example, it may stipulate that the data will only be shared for non-profit research purposes or that the data will not be linked with personally identified data from other sources.</p>\r\n<p>Read more about data security: <a href=\"https://www.ukdataservice.ac.uk/manage-data/store/security.aspx\" target=\"_blank\" rel=\"noopener\">UK Data Service</a></p>", "type"=>"guidance", "versionable_id"=>nil})
Question.create({"id"=>67271, "text"=>"How will you manage legal, ethical, and intellectual property issues?", "default_value"=>nil, "number"=>3, "section_id"=>21853, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>nil})
Annotation.create({"id"=>63056, "question_id"=>67271, "org_id"=>8, "text"=>"<p>Compliance with privacy legislation and laws that may impose content restrictions in the data should be discussed with your institution's privacy officer or research services office. Research Ethics Boards are central to the research process.</p><p>Include here a description concerning ownership, licensing, and intellectual property rights of the data. Terms of reuse must be clearly stated, in line with the relevant legal and ethical requirements where applicable (e.g., subject consent, permissions, restrictions, etc.).</p>", "type"=>"guidance", "versionable_id"=>nil})
Template.create!({"id"=>3468, "title"=>"Alliance CRDCN Template for Research Data Centres and External Analysis", "description"=>"<p><span style=\"font-weight: 400;\">The </span><a href=\"https://crdcn.org/\"><span style=\"font-weight: 400;\">Canadian Research Data Centre Network</span></a><span style=\"font-weight: 400;\"> (CRDCN) template summarizes the data management that is conducted by Statistics Canada and the CRDCN on behalf of researchers. While there are some advantages to working inside the RDC for data management, there is also a substantial drawback: RDC data can never be deposited in a repository in accordance with the recommended best practices for research data management. Because of this, researchers should be mindful of other options to engage in best practices. In addition to ensuring that the RDC project folder is well documented, and consistent with the research output, researchers should curate a supporting data deposit at a recognized repository in their discipline or within the </span><a href=\"https://www.frdr-dfdr.ca/repo/\"><span style=\"font-weight: 400;\">Federated Research Data Repository</span></a><span style=\"font-weight: 400;\"> (FRDR) containing metadata, syntax (code that produces a statistical output), and any other supporting material for the research project.</span></p>\n<p><span style=\"font-weight: 400;\">This template is for researchers who are doing RDC work using Statistics Canada data </span><em><span style=\"font-weight: 400;\">and</span></em><span style=\"font-weight: 400;\"> research data that they have either brought into the RDC &ldquo;supplemental data&rdquo; or are analyzing in parallel to their work in the RDC (such as mixed-methods) or public use statistics that compliment the RDC work (hereafter: </span><em><span style=\"font-weight: 400;\">external data</span></em><span style=\"font-weight: 400;\">). Researchers should be aware that any data brought into the RDC will be stored alongside the rest of their project material subject to the information management protocols from Statistics Canada. This is a free, relatively straightforward, process and researchers can obtain more information by talking to their RDC analyst.</span></p>\n<p><span style=\"font-weight: 400;\">If your work is being conducted in the RDC using only data provided through the RDC program then the RDC-only template should be completed and not this template.&nbsp; </span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>0, "visibility"=>1, "customization_of"=>nil, "family_id"=>589022318, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3447, "title"=>"CRDCN Template for Research Data Centres and External Analysis", "description"=>"<p><span style=\"font-weight: 400;\">This template is for researchers who are doing RDC work using Statistics Canada data </span><em><span style=\"font-weight: 400;\">and</span></em><span style=\"font-weight: 400;\"> research data that they have either brought into the RDC &ldquo;supplemental data&rdquo; or are analyzing in parallel to their work in the RDC (such as mixed-methods) or public use statistics that compliment the RDC work (hereafter: </span><em><span style=\"font-weight: 400;\">external data</span></em><span style=\"font-weight: 400;\">). Researchers should be aware that any data brought into the RDC will be stored alongside the rest of their project material subject to the information management protocols from Statistics Canada. This is a free, relatively straightforward, process and researchers can obtain more information by talking to their RDC analyst.</span></p>\r\n<p><span style=\"font-weight: 400;\">If your work is being conducted in the RDC using only data provided through the RDC program then the RDC-only template should be completed and not this template.&nbsp;</span></p>", "number"=>1, "template_id"=>3468, "modifiable"=>true, "versionable_id"=>"38c1bf2b-d79f-4b4f-a17c-243ebcfb8d70"})
Section.create({"id"=>22156, "title"=>"Data Collection", "description"=>"<p><span style=\"font-weight: 400;\">All research conducted in the Research Data Centres (hereafter RDC) is secondary in nature. There is no data collection involved in this portion of the project. These data are owned and maintained by Statistics Canada with storage and access provided by the Canadian Research Data Centres Network.</span></p>\r\n<p><span style=\"font-weight: 400;\">Raw data in the RDC are stored in multiple formats including, but not limited to: .SAS (SAS), .dta (STATA), and .shp (shapefiles) as appropriate. The availability of StatTransfer&trade; software within the RDCs and continued management by Statistics Canada will ensure that the data will be accessible indefinitely should the file formats currently in use become obsolete. Researchers can bring data into the RDCs (these will be called &ldquo;supplemental data&rdquo;). When they do, they are stored alongside all of the other research products related to that contract from the RDC and archived.</span></p>", "number"=>1, "phase_id"=>3447, "modifiable"=>true, "versionable_id"=>"b7c814fa-6a12-431f-a2ee-f25427f33d50"})
Question.create({"id"=>68226, "text"=>"<span style=\"font-weight: 400;\">Which RDC datasets will be used in the research?</span>", "default_value"=>nil, "number"=>1, "section_id"=>22156, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5e8e3db7-ae2c-4ff1-8d06-350e747e2966"})
Annotation.create({"id"=>63970, "question_id"=>68226, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">The record number is available on Statistics Canada's website which can be accessed directly, or through our website: </span><a href=\"http://crdcn.org/data\"><span style=\"font-weight: 400;\">crdcn.org/data</span></a><span style=\"font-weight: 400;\">. E.g. Aboriginal People's Survey 2017 Record number:3250 </span><a href=\"https://www23.statcan.gc.ca/imdb/p2SV.pl?Function=getSurvey&amp;SDDS=3250\"><span style=\"font-weight: 400;\">https://www23.statcan.gc.ca/imdb/p2SV.pl?Function=getSurvey&amp;SDDS=3250</span></a>", "type"=>"guidance", "versionable_id"=>"60b5c385-21ed-4767-bc85-38d8194b117a"})
Annotation.create({"id"=>63969, "question_id"=>68226, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">The data source(s) for this project is/are the &lt;&lt;INSERT NAME OF SURVEYS/ADMINISTRATIVE RECORDS APPROVED&gt;&gt;. The current version(s) is/are: &lt;&lt;Record number&gt;&gt;.</span>", "type"=>"example_answer", "versionable_id"=>"13c3c192-3412-4c8f-be2d-0b4a4547f720"})
Question.create({"id"=>68227, "text"=>"<span style=\"font-weight: 400;\">Please describe the collection process for the supplemental or external data that will be part of your project.</span>", "default_value"=>nil, "number"=>2, "section_id"=>22156, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4fefb338-b22b-483f-a97a-9ab401e4cffa"})
Annotation.create({"id"=>63971, "question_id"=>68227, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">External or Supplemental data are the data used for your research project that are not provided to you by Statistics Canada through the Research Data Centre program.</span>", "type"=>"guidance", "versionable_id"=>"cb3ea37c-1ba7-49d3-bc04-12c29bc32572"})
Question.create({"id"=>68228, "text"=>"<span style=\"font-weight: 400;\">What file formats will the supplementary data be collected and processed in? Will these formats permit sharing and long-term access to the data? How will you structure, name and version these files in a way easily understood by others?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22156, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4f865ea2-ba44-430c-ae1f-7a06a573254e"})
Section.create({"id"=>22157, "title"=>"Documentation and Metadata", "description"=>"<p><span style=\"font-weight: 400;\">Documentation provided by Statistics Canada in the RDC will be available to any potential future users of these data. This documentation is freely available to those with approved projects, and contains information about the sample selection process, a copy of the questionnaire, and a codebook. Researchers should also think about how the metadata for their external data can be provided to other researchers. Best practices require that there be coordination between the internal and external data management. How to best manage this will depend on the nature of the external data.</span></p>", "number"=>2, "phase_id"=>3447, "modifiable"=>true, "versionable_id"=>"e44a959d-0ccf-4df8-9c7c-0ca1220b9897"})
Question.create({"id"=>68229, "text"=>"<span style=\"font-weight: 400;\">What will you do to ensure that your research data contributions (syntax, output etc&hellip;) in your RDC project folder and (if applicable) your external analysis are properly documented, organized and accessible? </span>", "default_value"=>nil, "number"=>1, "section_id"=>22157, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"393f4f26-9ded-4970-a40f-dd0582abcce2"})
Annotation.create({"id"=>63972, "question_id"=>68229, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Resources are available on the CRDCN website to help. A recommendation from CRDCN on how to document your research contributions can be found here. For ideas on how to properly curate reproducible research, you can go here: </span><a href=\"https://labordynamicsinstitute.github.io/replication-tutorial-2019/#/\"><span style=\"font-weight: 400;\">https://labordynamicsinstitute.github.io/replication-tutorial-2019/#/</span></a>", "type"=>"guidance", "versionable_id"=>"5e961b84-0bfb-4617-972e-ada51886618f"})
Question.create({"id"=>68230, "text"=>"<span style=\"font-weight: 400;\">How will you make sure that the syntax archived in your project folder (and if applicable that created for your external analysis) is created consistently throughout your project?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22157, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c5522829-80db-4256-895b-e0aed7c949dc"})
Annotation.create({"id"=>63973, "question_id"=>68230, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Syntax: Any code used by the researcher to transform the raw data into the research results. This most commonly includes, but is not limited to, .do (Stata) files, .sas (SAS) files, and .r (R) R code.</span>", "type"=>"guidance", "versionable_id"=>"9d85a2d1-ce6a-453a-a918-2719036b3120"})
Question.create({"id"=>68231, "text"=>"<p><span style=\"font-weight: 400;\">Please provide the information about the availability of the metadata for your project here (both the RDC data and your external data). Some metadata for RDC datasets is available by contacting the RDC analyst.</span></p>\r\n<p><span style=\"font-weight: 400;\">How will you ensure that the external/supplemental data are easily understood and correctly documented (including metadata)?</span></p>", "default_value"=>nil, "number"=>3, "section_id"=>22157, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"49aebbed-2df2-4ff5-b422-b8712eda81ac"})
Annotation.create({"id"=>64797, "question_id"=>68231, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">For a good starter resource on metadata see: </span><a href=\"https://www.go-fair.org/fair-principles/f2-data-described-rich-metadata/\"><span style=\"font-weight: 400;\">https://www.go-fair.org/fair-principles/f2-data-described-rich-metadata/</span></a><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>"a027328b-ef33-487a-803c-787bdceb5761"})
Section.create({"id"=>22158, "title"=>"Storage and Backup", "description"=>"<p><span style=\"font-weight: 400;\">Data storage is managed by the CRDCN in partnership with Statistics Canada&nbsp;on Servers located across the network. The current policy of the CRDCN is to store project data (syntax, releases, and anything else stored in the project folder) for ten years. These data are backed up on site and accessible through a highly secured network from any of the other RDC locations. Raw data related to the research project are stored in perpetuity by Statistics Canada.</span></p>\r\n<p><span style=\"font-weight: 400;\">For external research data, storage and backup are solely the responsibility of the researcher. Please consider the following questions as they relate to external data. These questions should also be considered for supplemental data if you plan to do parallel storage and backup of these data.</span></p>", "number"=>3, "phase_id"=>3447, "modifiable"=>true, "versionable_id"=>"bab48833-12a2-41ce-a894-2fb9ffcd10cb"})
Question.create({"id"=>68233, "text"=>"<span style=\"font-weight: 400;\">What are the anticipated storage requirements for your project, in terms of storage space (in megabytes, gigabytes, terabytes, etc.) and the length of time you will be storing it?</span>", "default_value"=>nil, "number"=>1, "section_id"=>22158, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"298d9027-c3ae-4d1e-ad9f-e123b1b16e91"})
Annotation.create({"id"=>63975, "question_id"=>68233, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Because of the structure of the agreements under which supplemental data are brought into the RDC we highly recommend a parallel storage and backup to simplify sharing of these research data. Note that \"data\" here refers not only to the raw data, but to any and all data generated in the course of conducting the research.</span>", "type"=>"guidance", "versionable_id"=>"9f42eb2a-32b0-44de-b0e2-18ee142564b8"})
Question.create({"id"=>68234, "text"=>"<span style=\"font-weight: 400;\">How and where will your data be stored and backed up during your research project?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22158, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c27fb1c7-5aea-4aa5-95a8-e2923e13ebb5"})
Question.create({"id"=>68235, "text"=>"<span style=\"font-weight: 400;\">How will the research team and other collaborators access, modify, and contribute data throughout the project?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22158, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5c22f887-3840-458d-b257-97cb4cb05943"})
Section.create({"id"=>22159, "title"=>"Preservation", "description"=>"<p><span style=\"font-weight: 400;\">The work conducted in the RDC for this project is kept based on the Contract ID provided by the RDC program which can be used by anyone on the project team to retrieve the code and supporting documents for a period of 10 years as described above in &ldquo;Storage and Backup&rdquo;. Raw data that is the property of Statistics Canada, i.e. RDC data, is permanently stored by Statistics Canada, but can never be released to the researcher. Researchers can also preserve all user-generated RDC research data that meets the criteria for release through a vetting request via a repository such as FRDR (though it is again emphasized that the raw RDC data cannot be shared). Best practices for reproducible work require indefinite preservation of research data (so in the case of RDC research, this means metadata, syntax, methodology). In addition to this preservation for the RDC work, the external data (and related syntax, metadata and methodology) should be preserved also.</span></p>", "number"=>4, "phase_id"=>3447, "modifiable"=>true, "versionable_id"=>"e5e2f2a2-cd86-4b9d-bc9b-3ddf367651b0"})
Question.create({"id"=>68236, "text"=>"<span style=\"font-weight: 400;\">Will you deposit your syntax and other research data in a repository to preserve your files? Please describe your intended preservation of all research data here, noting how you will deal with any privacy concerns related to your supplemental/external data:</span>", "default_value"=>nil, "number"=>1, "section_id"=>22159, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"cfee1432-8c3a-432e-8053-a9e159f4193f"})
Section.create({"id"=>22160, "title"=>"Sharing and Reuse", "description"=>"<p><span style=\"font-weight: 400;\">Because the Statistics Canada Microdata files are collected under assurances of confidentiality and are owned and controlled by Statistics Canada, they cannot be shared by any member of the research team.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Access to the data in the RDCs is governed by the CRDCN's Access and Fee-for-service policy in </span><a href=\"https://crdcn.org/sites/default/files/uploads/crdcn_affs_policy.pdf\"><span style=\"font-weight: 400;\">English</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://crdcn.org/sites/default/files/uploads/crdcn_affs_policy_fr.pdf\"><span style=\"font-weight: 400;\">French</span></a><span style=\"font-weight: 400;\">. The policy provides free access to university-based researchers who are network members and provides access to others on a cost-recovery basis.</span></p>\r\n<p><span style=\"font-weight: 400;\">The CRDCN and Statistics Canada promote their data holdings through social media and their respective websites. In addition, CRDCN data are required to be cited in any and all publications with the record number so that readers are able to find the data. In addition, all publications using RDC data should include the RDC contract ID so that potential users can find information on the original contract. This information is available on the CRDCN website (<a href=\"https://crdcn.org/publications\">crdcn.org/publications</a>).</span></p>\r\n<p><span style=\"font-weight: 400;\">For your supplemental/external data, please answer the following questions aimed to satisfy the </span><a href=\"https://www.go-fair.org/fair-principles/\"><span style=\"font-weight: 400;\">FAIR principles</span></a><span style=\"font-weight: 400;\">.</span></p>", "number"=>5, "phase_id"=>3447, "modifiable"=>true, "versionable_id"=>"61c36983-c088-40e1-8243-5862cdcd5b34"})
Question.create({"id"=>68237, "text"=>"<p><span style=\"font-weight: 400;\">Outside of the data sharing/reuse that happens automatically within your project folder, what data will you be sharing, where, and in what form (e.g. raw, processed, analyzed, final)?</span></p>", "default_value"=>nil, "number"=>1, "section_id"=>22160, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e815c7f0-44d5-4643-abfe-28a1ee2f3d45"})
Annotation.create({"id"=>63976, "question_id"=>68237, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Consider also what file-format you will use. Will this file format be useable in the future? Is it proprietary?</span></p>", "type"=>"guidance", "versionable_id"=>"c6e5702a-a3f1-42ec-b573-054f1301bb0a"})
Question.create({"id"=>68238, "text"=>"<span style=\"font-weight: 400;\">What type of end-user license will these shared data fall under?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22160, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"6f2363bc-f5e4-46e3-812e-19094e6151e6"})
Question.create({"id"=>68239, "text"=>"<span style=\"font-weight: 400;\">What steps will you take to help the research community know that these data exist?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22160, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"b9510552-1840-45ea-b0f6-0b5090149ee4"})
Section.create({"id"=>22161, "title"=>"Responsibilities and Resources", "description"=>"<p><span style=\"font-weight: 400;\">The CRDCN and Statistics Canada will maintain the research data even if the researcher leaves their organization.</span></p>\r\n<p><span style=\"font-weight: 400;\">CRDCN enjoys the support of CIHR, SSHRC and CFI as well as receiving funds from the partner universities. There is no charge to the users of the RDCs for the data management conducted under the auspices of CRDCN and Statistics Canada as described within this DMP.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">CRDCN does not employ consistency checking to ensure that the code provided alongside requests for research results to be released from the secure facility truly creates the output as requested. The responsibility for ensuring that the code and documents describing their use work as intended and are clear to other users who might access them lies with the researchers in the RDC. The CRDCN has a mechanism to ensure that the code is saved alongside all of the research output used to support the conclusions of any published works.</span></p>\r\n<p><span style=\"font-weight: 400;\">Researchers should consider how to manage their external research data and should think about who on the project team will have responsibility for managing the research data and what resources might be required to do so. Where possible, the research data from within the RDC should be managed in a way that is coordinated with the external research data management.<br /><br />In addition to the data management employed by Statistics Canada, it is possible for researchers to have research output that does not contain confidential data, including tables, syntax and other information, released from the RDC where it could be curated in a repository of the researcher&rsquo;s choosing as described in the Preservation section. If you plan to do any supplemental storage or curation of your research data (either the user-generated research data from the RDC or the external/supplemental data), please comment on where the responsibility for curation and maintenance of this archive resides.<br /></span></p>", "number"=>6, "phase_id"=>3447, "modifiable"=>true, "versionable_id"=>"e9e714af-304e-49b3-8293-daaaad6ec2fe"})
Question.create({"id"=>68240, "text"=>"<span style=\"font-weight: 400;\">For the supplemental/external data, i</span><span style=\"font-weight: 400;\">dentify who will be responsible for managing this project's data during and after the project and the major data management tasks for which they will be responsible.</span>", "default_value"=>nil, "number"=>1, "section_id"=>22161, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"bc0435f8-9c12-4a3e-a025-13b9eef7cdca"})
Question.create({"id"=>68241, "text"=>"<span style=\"font-weight: 400;\">For the supplemental/external data, how will responsibilities for managing data activities be handled if substantive changes happen in the personnel overseeing the project's data, including a change of Principal Investigator?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22161, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c81fb3b8-4d69-426f-9f88-29a442fa2d60"})
Question.create({"id"=>68242, "text"=>"<span style=\"font-weight: 400;\">For the supplemental/external data, what resources will you require to implement your data management plan for all your research Data (i.e. RDC data and external/supplemental)? What do you estimate the overall cost for data management to be?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22161, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f519e62b-ec5c-4c44-a1dd-5f4428059f66"})
Annotation.create({"id"=>63977, "question_id"=>68242, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">A tool provided by OpenAIRE can help researchers estimate the cost of research data management: </span><a href=\"https://www.openaire.eu/how-to-comply-to-h2020-mandates-rdm-costs\"><span style=\"font-weight: 400;\">https://www.openaire.eu/how-to-comply-to-h2020-mandates-rdm-costs</span></a>.", "type"=>"guidance", "versionable_id"=>"a5c68fcc-5415-42fc-aae9-703997539803"})
Section.create({"id"=>22162, "title"=>"Ethics and Legal Compliance", "description"=>"<p><span style=\"font-weight: 400;\">Any users of the RDC must be 'deemed employees' of Statistics Canada. To become a deemed employee, the Treasury Board mandates a security clearance process including a criminal background check, credit check and fingerprinting. Approval for access to data requires a peer-review process of a research proposal and an institutional review at Statistics Canada. In cases where a researcher&rsquo;s scholarly work has been assessed through the tenure review process, they are considered peer-review pre-approved and only the institutional review is required.</span></p>\r\n<p><span style=\"font-weight: 400;\">Once a researcher is granted access to the RDC they must take an </span><em><span style=\"font-weight: 400;\">Oath of Secrecy</span></em><span style=\"font-weight: 400;\"> &ndash; promising never to disclose confidential data. Criminal penalties can apply under the Statistics Act for violations of this oath.</span></p>\r\n<p><span style=\"font-weight: 400;\">Intellectual property for work done within the RDC becomes property of Statistics Canada including code used to manipulate data. The collection and dissemination of, and access to, confidential microdata is conducted under the </span><em><span style=\"font-weight: 400;\">Statistics Act</span></em><span style=\"font-weight: 400;\"> and complies with all legal requirements. The confidential microdata for this project cannot be shared, posted, or copied. Access to the data is available exclusively through Statistics Canada and the RDC program. More information on how to access data is available here in </span><a href=\"https://crdcn.org/research\"><span style=\"font-weight: 400;\">English</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://crdcn.org/fr/recherche\"><span style=\"font-weight: 400;\">French</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\"><br /></span><span style=\"font-weight: 400;\">In general, research ethics clearance is not required for research conducted in the RDC. A statement from the CRDCN on the topic is available here in <a href=\"https://crdcn.org/sites/default/files/uploads/ethics_review_recommendations_en.pdf\">English</a> or <a href=\"https://crdcn.org/sites/default/files/uploads/ethics_review_recommendations_fr.pdf\">French</a>.</span></p>\r\n<p><span style=\"font-weight: 400;\">Please respond to the following ethical compliance questions as they relate to your external/supplemental data. If your project underwent research-ethics review at your institution, you can summarize the submission instead of answering these questions.</span></p>", "number"=>7, "phase_id"=>3447, "modifiable"=>true, "versionable_id"=>"ffe16fbd-5bec-4e45-82b2-41a3125317bd"})
Question.create({"id"=>68243, "text"=>"<span style=\"font-weight: 400;\">If your research project includes sensitive data, how will you ensure that it is securely managed and accessible only to approved members of the project?</span>", "default_value"=>nil, "number"=>1, "section_id"=>22162, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"12d7687b-75c4-4f11-a53b-67191c7dfd08"})
Annotation.create({"id"=>63978, "question_id"=>68243, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Consider where, how, and to whom sensitive data with acknowledged long-term value should be made available, and how long it should be archived. Decisions should align with Research Ethics Board requirements. Methods used to share data will be dependent on the type, size, complexity and degree of sensitivity of data. Outline problems anticipated in sharing data, along with causes and possible measures to mitigate these. Problems may include confidentiality, lack of consent agreements, or concerns about Intellectual Property Rights, among others.</span></p>\r\n<span style=\"font-weight: 400;\">Reused from: Digital Curation Centre. (2013). </span><a href=\"http://www.dcc.ac.uk/resources/data-management-plans\"><span style=\"font-weight: 400;\">Checklist for a Data Management Plan</span></a><span style=\"font-weight: 400;\">. v.4.0. Restrictions can be imposed by limiting physical access to storage devices, placing data on computers with no access to the Internet, through password protection, and by encrypting files. Sensitive data should never be shared via email or cloud storage services such as Dropbox</span>", "type"=>"guidance", "versionable_id"=>"074345d9-7583-4b48-8715-3e7b84e49fa2"})
Question.create({"id"=>68244, "text"=>"<span style=\"font-weight: 400;\">If applicable, what strategies will you undertake to address secondary uses of sensitive data?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22162, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d039b13f-5848-4eee-bcbc-db5617955749"})
Annotation.create({"id"=>63979, "question_id"=>68244, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Obtaining the appropriate consent from research participants is an important step in assuring Research Ethics Boards that the data may be shared with researchers outside your project. The consent statement may identify certain conditions clarifying the uses of the data by other researchers. For example, it may stipulate that the data will only be shared for non-profit research purposes or that the data will not be linked with personally identified data from other sources. Read more about data security: </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\"><span style=\"font-weight: 400;\">UK Data Archive</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"4032634d-d68b-412b-a2e4-2860c83a6133"})
Question.create({"id"=>68245, "text"=>"<span style=\"font-weight: 400;\">How will you manage legal, ethical, and intellectual property issues?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22162, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a5053e60-2d76-4dde-93a7-ebfa2e25571f"})
Annotation.create({"id"=>63980, "question_id"=>68245, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Compliance with privacy legislation and laws that may impose content restrictions in the data should be discussed with your institution's privacy officer or research services office. Research Ethics Boards are central to the research process.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Include here a description concerning ownership, licensing, and intellectual property rights of the data. Terms of reuse must be clearly stated, in line with the relevant legal and ethical requirements where applicable (e.g., subject consent, permissions, restrictions, etc.).</span></p>", "type"=>"guidance", "versionable_id"=>"96137b9c-f898-46c4-a681-1488723fbe9e"})
Question.create({"id"=>68246, "text"=>"<span style=\"font-weight: 400;\">If you feel there are any other legal or ethical requirements for your project please describe them here:</span>", "default_value"=>nil, "number"=>4, "section_id"=>22162, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a87a16ca-2602-46e2-8709-54488f65a909"})
Template.create!({"id"=>3925, "title"=>"Alliance Simplified Template (Funding Application Stage)", "description"=>"<p><span style=\"font-weight: 400;\">This data management plan (DMP) template was collaboratively developed by the Digital Research Alliance of Canada Data Management Planning Expert Group (DMPEG). The template has been designed specifically to support researchers in meeting DMP requirements at the funding opportunity application stage.&nbsp;</span></p>\n<p><span style=\"font-weight: 400;\">Given the purpose of this DMP template, it includes questions and guidance that are deemed most relevant at the funding opportunity stage. It is recognized that a more detailed DMP may be required to optimally support research projects moving forward and across the research data lifecycle.</span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>0, "visibility"=>1, "customization_of"=>nil, "family_id"=>586916378, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3994, "title"=>"DMP", "description"=>nil, "number"=>1, "template_id"=>3925, "modifiable"=>true, "versionable_id"=>"28fd208d-b280-4676-aa6c-a6962c644d0c"})
Section.create({"id"=>25130, "title"=>"Introductory Guidance", "description"=>"<p><span style=\"font-weight: 400;\">Before beginning to develop your data management plan (DMP) you should always consider as applicable:</span></p>\r\n<p><em><strong>Policies &amp; requirements:</strong></em></p>\r\n<p><span style=\"font-weight: 400;\">Ensure that you are familiar with, and that your proposed research data management practices abide by, any relevant and applicable policies and requirements, including funder and organizational requirements, ethical&nbsp; requirements (such as TCPS2), and publisher or journal policies.</span></p>\r\n<p><em><strong>Guiding Principles:</strong></em></p>\r\n<p><span style=\"font-weight: 400;\">Consider how your data management practices will appropriately support the tenets of open science, including </span><a href=\"https://www.go-fair.org/fair-principles/\"><span style=\"font-weight: 400;\">FAIR</span></a><span style=\"font-weight: 400;\">, a set of guiding principles focused towards making data findable, accessible, interoperable, and reusable. Information and resources relating to the FAIR principles can be found at the GOFAIR website at: </span><a href=\"https://www.go-fair.org/fair-principles/\"><span style=\"font-weight: 400;\">https://www.go-fair.org/fair-principles/</span></a></p>\r\n<p><em><strong>Indigenous data governance:</strong></em></p>\r\n<p><span style=\"font-weight: 400;\">If your research engages with or involves Indigenous communities in any way, be aware of and consider your obligations under policy and ethical guidelines, including best practices and requirements for conducting Indigenous research as outlined by Tri-Agency frameworks and, as applicable, institutional policies. Ideally, a data management plan should be co-developed with the Indigenous communities that your research involves.</span></p>\r\n<p><span style=\"font-weight: 400;\">Some notable guiding principles and resources that you may find useful to refer to include:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://www.gida-global.org/care\"><span style=\"font-weight: 400;\">CARE</span></a><span style=\"font-weight: 400;\">, an overarching set of principles highlighting the need for research involving Indigenous communities to have collective benefit, while the communities themselves have the authority to control their data, with the goal of conducting responsible and ethical research</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://fnigc.ca/ocap-training/\"><span style=\"font-weight: 400;\">OCAP</span></a><span style=\"font-weight: 400;\">, a set of principles set forth by the </span><a href=\"https://fnigc.ca/\"><span style=\"font-weight: 400;\">First Nations Information Governance Centre (FNIGC)</span></a><span style=\"font-weight: 400;\"> which asserts the need for First Nations communities to have ownership, control, access, and possession of data involving them.&nbsp;</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Other community specific resources may be available as they relate to your research. Connecting with Indigenous communities and consulting&nbsp; resources early will help to ensure your project incorporates&nbsp; best practices relating to Indigenous data sovereignty from the start.</span></p>\r\n<p><em><strong>Responsibilities &amp; resources:</strong></em></p>\r\n<p><span style=\"font-weight: 400;\">Consider who will be responsible for various aspects of research data management, including such things as data collection and/or acquisition, analysis, storage and security, and long-term data stewardship. Depending upon your project&rsquo;s needs, responsibilities may be assigned to specific individuals or be shared, including by the principal investigator, co-investigators, research staff, trainees, another individual, or an organization.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">You should also consider what resources may be required in order to meet your project&rsquo;s data management needs, including if dedicated positions or outsourcing of tasks is required, and how these costs will be met. Building data management support into your research budget will help to ensure that your project&rsquo;s needs are met.</span></p>", "number"=>1, "phase_id"=>3994, "modifiable"=>true, "versionable_id"=>"6f7ffd61-861e-4bf6-b84e-a96c6b7b838e"})
Question.create({"id"=>77335, "text"=>"Introductory Guidance", "default_value"=>nil, "number"=>1, "section_id"=>25130, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>nil, "versionable_id"=>"e4bd4260-dade-4de7-846f-d3748e516391"})
Section.create({"id"=>25129, "title"=>"Plan Questions", "description"=>nil, "number"=>2, "phase_id"=>3994, "modifiable"=>true, "versionable_id"=>"88726c69-91eb-43ad-81b9-1d424e1719d2"})
Question.create({"id"=>77314, "text"=>"<p><em><span style=\"font-weight: 400;\">What considerations will you take into account with respect to ethical, legal, or commercial issues?</span></em></p>\r\n<br />\r\n<p><span style=\"font-weight: 400;\">Describe any applicable ethical, legal, or commercial considerations related to your project and data. This includes research involving Indigenous communities and knowledges, human subjects, legal and commercial considerations/agreements, partnerships or data with a high level of risk associated with it</span></p>", "default_value"=>nil, "number"=>1, "section_id"=>25129, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>nil, "versionable_id"=>"00565e3b-d412-4b5d-8f04-2025a1f30b39"})
Annotation.create({"id"=>73466, "question_id"=>77314, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Consider how you will manage data throughout the lifecycle of the project, including how you will safeguard information, protect potentially sensitive data, support potential long-term data stewardship, and meet requirements, including those set forth by funders, research ethics boards, or other obligations, as applicable. If needed, contact key areas at your institution or organization for guidance and to find out what resources and support are available.</span></p>\r\n<p><span style=\"font-weight: 400;\">Some notable key considerations include:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">How will you support long-term data stewardship, including data deposit and appropriate sharing? Note - research involving human participants will very often&nbsp; require both informed consent and ethics approval with respect to data sharing.</span></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">How will data deemed as being sensitive be effectively safeguarded and protected across the lifecycle of your research project?</span></li>\r\n</ul>\r\n<br /><span style=\"font-weight: 400;\">Depending upon the nature of your project, you may want to consider how parts will be shared through knowledge translation/mobilization or through </span><a href=\"https://www.wipo.int/technology-transfer/en/\"><span style=\"font-weight: 400;\">technology transfer</span></a><span style=\"font-weight: 400;\"> if you develop new technology. </span>", "type"=>"guidance", "versionable_id"=>"dc2c2e27-63b3-4836-b43b-814243fe8f87"})
Question.create({"id"=>77315, "text"=>"<p><em><span style=\"font-weight: 400;\">What data will you collect or otherwise bring into your project under this plan?</span></em></p>\r\n<p><span style=\"font-weight: 400;\">Describe the data that will be collected, generated, and/or acquired.</span></p>", "default_value"=>nil, "number"=>2, "section_id"=>25129, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>nil, "versionable_id"=>"27f4c238-2a87-4e34-b70c-6fad12ebcd29"})
Annotation.create({"id"=>73467, "question_id"=>77315, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Research data refers to any information that is collected, observed, generated, or acquired to validate your research findings.</span></p>\r\n<p><span style=\"font-weight: 400;\">Notable examples of research data may include data files, questionnaires, transcripts, samples, physical collections, software, models, algorithms, lab notebook, codebooks, methodologies, workflows, and other materials to be produced during the course of the project.</span></p>\r\n<p><span style=\"font-weight: 400;\">&nbsp;When describing your data be sure to:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Describe the data types (e.g., image data, textual data, numerical data, audiovisual, etc)&nbsp;</span></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Briefly explain how the data will be collected or generated - if already existing data will be acquired, describe the source of the data (e.g., citations, URL, persistent identifiers linked to the data, acquisition requests) and specify what data will be used.</span></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Indicate if your data is, or may possibly be, considered as sensitive (e.g., health, administrative and/or clinical records, participant interviews, involving sensitive topics, etc).</span></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Indicate if your data involves Indigenous communities and/or knowledges and information.</span></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Describe if your data are in proprietary vs. non-proprietary formats</span></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">As best able, provide an estimate of the size of the data, taking into account multiple versions of data needed (e.g., raw, master, analytic). This will additionally help when considering storage data storage needs for the project.</span></li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"c0268130-d6af-41f6-a733-4c01a6d10302"})
Question.create({"id"=>77316, "text"=>"<p><em><span style=\"font-weight: 400;\">How will you document data for future re-use or validation?</span></em></p>\r\n<p><span style=\"font-weight: 400;\">Describe how you will document your data to ensure that it is easily read and interpreted correctly throughout the research process.</span></p>\r\n<p><span style=\"font-weight: 400;\">If applicable, specify any data and/or metadata standards that are being used to support your research project.</span></p>", "default_value"=>nil, "number"=>3, "section_id"=>25129, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>nil, "versionable_id"=>"e97d421b-0c16-4585-8a85-d2dc9aabcaa3"})
Annotation.create({"id"=>73468, "question_id"=>77316, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Structured documentation allows for your research and data to be understood, reproduced, and, potentially, reused by others. Notable examples of data documentation may include such things as data dictionaries, codebooks, readme files, lab and/or field notes, code and syntax, user guides, etc.&nbsp;</span></p>\r\n<p><a href=\"https://www.dcc.ac.uk/guidance/standards/metadata\"><span style=\"font-weight: 400;\">Metadata standards</span></a><span style=\"font-weight: 400;\"> provide a set list of descriptive fields (similar to a vocabulary) for providing relevant contextual information to describe data. Most metadata standards use open and machine-readable formats (e.g., JSON; XML), which facilitates opportunities for interoperability, including future exchange and reuse of metadata between systems and software used for analysis, as well as for supporting data sharing and indexing in a repository or database for search and discovery purposes.</span></p>\r\n<p><span style=\"font-weight: 400;\">Consider at the funding application stage how you will ensure that your data is efficiently documented and captured through out your project (e.g. scripting, tool-generated, user-documented), including by whom, can help to identify needs, including staffing resources and expertise, that may possibly be built into your application and supported through grant funds.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">As needed, connect with local expertise at your institution or organization, including the Library, for assistance when considering your project&rsquo;s metadata needs, including identifying if there are existing metadata standards that can be used.</span></p>", "type"=>"guidance", "versionable_id"=>"1476d037-33b2-45be-ba51-17784619a914"})
Question.create({"id"=>77317, "text"=>"<p><em><span style=\"font-weight: 400;\">How will data be stored, accessed and worked with?</span></em></p>\r\n<p><span style=\"font-weight: 400;\">Describe both where and how data will be stored, accessed, and worked with during the </span><span style=\"font-weight: 400;\">active phases</span><span style=\"font-weight: 400;\"> of your research including as applicable:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">all versions of data (e.g., raw, master, analytic)</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">All activities (e.g., data collection, processing, analysis, dissemination)</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">All software and platforms&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Who requires access, including security measures (e.g., Investigators, research staff, collaborators, partners)</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">How data will be backed up to prevent data loss</span></li>\r\n</ul>", "default_value"=>nil, "number"=>4, "section_id"=>25129, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>nil, "versionable_id"=>"1208d3d5-2019-43aa-98f4-19ba93af33c2"})
Annotation.create({"id"=>73469, "question_id"=>77317, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Consider and identify both </span><em><span style=\"font-weight: 400;\">where</span></em><span style=\"font-weight: 400;\"> and </span><em><span style=\"font-weight: 400;\">how</span></em><span style=\"font-weight: 400;\"> data will be stored, accessed, and worked with across the active phases of your research. Projects involving multiple people (e.g., co-investigators, research staff, trainees, partners) need to consider who requires access, as well as how they will work with data.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">If you are working with sensitive data, you will require secure storage. Contact your institution&rsquo;s IT services to discuss options. If you are working with data from human participants, you will need to follow any directions from your local research ethics board.</span></p>\r\n<p><span style=\"font-weight: 400;\">Many server and cloud based environments, such as the Digital Research Alliance of Canada&rsquo;s freely available </span><a href=\"https://alliancecan.ca/en/services/advanced-research-computing/accessing-resources/rapid-access-service\"><span style=\"font-weight: 400;\">Rapid Access Service</span></a><span style=\"font-weight: 400;\">, can support projects&rsquo; active data storage and access needs, including for geographically dispersed teams, greatly reducing the need for data transferring and storing data on personal computers and mobile devices.</span></p>\r\n<p><span style=\"font-weight: 400;\">Notable things to consider and describe as able at the funding application stage include:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Where and how all versions of data will be stored and worked with</span><span style=\"font-weight: 400;\"> - this includes data that are unprocessed and identifiable (raw data), those that are processed and de-identified (master data), as well as analytic files.</span></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Who needs access and to what versions of data</span><span style=\"font-weight: 400;\"> - Consider if, for instance, co-investigators, trainees, and/or research staff may require access to data. Should your project move forward, in some instances, individuals may require ethics approval in order to access raw or sensitive data.</span></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">How people will access and work with data </span><span style=\"font-weight: 400;\">-&nbsp; will you utilize a server or cloud based environment and, if so, will all team members be able to access&nbsp;</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">If for any reason data are being worked with or stored on personal computers or mobile devices, describe how you will ensure that data are backed up to prevent data loss, including if to an external hard drive, a server, and/or a cloud solution. You may also want to contact your institution's data library or IT divisions to ensure you are compliant with local policies.</span></p>", "type"=>"guidance", "versionable_id"=>"faa2bda8-4997-4f85-b01a-21f516c9a145"})
Question.create({"id"=>77318, "text"=>"<p><em><span style=\"font-weight: 400;\">How will data be managed, discoverable, and accessible for the long term?</span></em></p>\r\n<p><span style=\"font-weight: 400;\">Describe plans for long-term management of your data </span><span style=\"font-weight: 400;\">after the active phases</span><span style=\"font-weight: 400;\"> of your research have concluded including data deposit and sharing.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Consider and describe as applicable plans for:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">all versions of data deposited (raw, master, analytic, published)</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">All activities (e.g., curation, preservation, ethical compliance, publishing etc.)</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">All software and platforms (e.g., data repositories)</span></li>\r\n</ul>", "default_value"=>nil, "number"=>5, "section_id"=>25129, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>nil, "versionable_id"=>"89fb12fe-c40c-468f-a53f-a094c11851eb"})
Annotation.create({"id"=>73470, "question_id"=>77318, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Describe the steps you will take to ensure your data will remain, as appropriate, discoverable and accessible over time while considering:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Any obligations from funders, publishers, or your own institution&rsquo;s policies</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">If any data will be destroyed and, if so, under what conditions.&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">If any data are sensitive and if ethics approval and/or de-identification is required prior to sharing</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">If any software is needed for continued access to the data, as well as if code, scripts, or metadata are required to interpret the data</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Will you deposit any versions of your data into a digital research data repository for open discovery, appropriate access, and potential reuse by others?&nbsp;</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">If yes, provide details including, as best able, where you will deposit your data</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">If no, include an explanation as to why your data will not be deposited.&nbsp;</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">When planning to deposit data, consider repositories that assign a persistent identifier as these support both its discovery and citability. Two free-to-use generalist (not discipline specific) data repositories in Canada are:&nbsp;</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://borealisdata.ca/\"><span style=\"font-weight: 400;\">Borealis</span></a><span style=\"font-weight: 400;\">, the Canadian Dataverse Repository: Check the Borealis website to see if your institution supports the delivery of this repository service and to learn more about it and its key features.</span></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://www.frdr-dfdr.ca/repo/\"><span style=\"font-weight: 400;\">Federated Research Data Repository (FRDR)</span></a><span style=\"font-weight: 400;\">: Hosted by the Digital Research Alliance of CanadaFRDR, is a national repository service and data discovery platform that can additionally support very large data deposits.</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Some repositories and institutions may provide support for curation activities. Curators can work with you to help ensure your data are appropriately formatted and documented, which contributes to its long term value.</span></p>\r\n<p><span style=\"font-weight: 400;\">Connect with local expertise at your institution or organization, including the Library, for assistance when considering your project&rsquo;s long-term management and deposit needs, including if there are resources, expertise, and/or repository solutions that can be leveraged.</span></p>", "type"=>"guidance", "versionable_id"=>"378acb1e-0a0b-4eff-9c6b-772ba931de45"})
Template.create!({"id"=>3848, "title"=>"Alliance Template for Mixed Methods (Surveys & Qualitative Research)", "description"=>"<p>This mixed methods data management plan template was developed for use within the Portage DMP Assistant and is meant to assist researchers conducting mixed methods research (e.g., surveys and qualitative interviews/focus groups) in developing high quality data management plans to support their research. The template consists of a number of categories, questions, and customized guidance that relate directly to mixed methods research.</p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>1, "visibility"=>1, "customization_of"=>nil, "family_id"=>1388567390, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3896, "title"=>"Alliance Template for Mixed Methods (Surveys & Qualitative Research)", "description"=>"<p>This mixed methods data management plan template was developed for use within the Portage DMP Assistant and is meant to assist researchers conducting mixed methods research (e.g., surveys and qualitative interviews/focus groups) in developing high quality data management plans to support their research. The template consists of a number of categories, questions, and customized guidance that relate directly to mixed methods research.</p>", "number"=>1, "template_id"=>3848, "modifiable"=>true, "versionable_id"=>"1945d993-f3da-4a84-ad7f-ae2560946956"})
Section.create({"id"=>24611, "title"=>"Research Data Management Policies", "description"=>nil, "number"=>1, "phase_id"=>3896, "modifiable"=>true, "versionable_id"=>"1ba88e26-2fb2-404b-ae31-bf9365303b26"})
Question.create({"id"=>75834, "text"=>"<span style=\"font-weight: 400;\">Are there any research data management policies in place that outline requirements and/or best practice guidance regarding the management of your data? If so, provide details and, if helpful, URL links to these policies. </span>", "default_value"=>nil, "number"=>1, "section_id"=>24611, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d7813b8c-de39-4081-bdb6-1c716019aaa2"})
Annotation.create({"id"=>71825, "question_id"=>75834, "org_id"=>8, "text"=>"Examples of research data management policies that may be in place include those set forth by funders, post secondary institutions, legislation, and communities.<br />\r\n<p><span style=\"font-weight: 400;\">Examples of these might include:&nbsp;</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://www.ic.gc.ca/eic/site/063.nsf/eng/h_83F7624E.html\"><span style=\"font-weight: 400;\">Tri-Agency Statement of Principles on Digital Data Management</span></a></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://fnigc.ca/ocap-training/\"><span style=\"font-weight: 400;\">First Nations Information Governance Centre Principles of OCAP</span></a></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://ethics.gc.ca/eng/policy-politique_tcps2-eptc2_2018.html\"><span style=\"font-weight: 400;\">Tri-Council Policy Statement: Ethical Conduct for Research Involving Humans (TCPS-2)</span></a></li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"8bb14b2c-58e2-42bc-921e-bb846d4e0d0f"})
Section.create({"id"=>24612, "title"=>"Data Collection", "description"=>nil, "number"=>2, "phase_id"=>3896, "modifiable"=>true, "versionable_id"=>"a20071a4-ac12-4bd5-b79b-0d2a56da4db4"})
Question.create({"id"=>75835, "text"=>"Describe the type(s) of data that you will collect, including all survey, interview and/or focus group data. If there are any additional types of data that will be collected or generated describe these as well.", "default_value"=>nil, "number"=>1, "section_id"=>24612, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"470a0399-29c5-4956-9ea1-d61f4cb5c217"})
Annotation.create({"id"=>71826, "question_id"=>75835, "org_id"=>8, "text"=>"Having a clear understanding of all the data that you will collect or use within your project will help with planning for their management. <br /><br />Include a general description of each type of data related to your project, including the formats that they will be collected in, such as audio or video files for qualitative interviews and focus groups and survey collection software or file types.<br /><br />As well, provide any additional details that may be helpful, such as the estimated length (number of survey variables/length of interviews) and quantity (number of participants to be interviewed) both of surveys and interviews.", "type"=>"guidance", "versionable_id"=>"4e8fbb6e-4e80-42f5-b59e-70468bec3cf8"})
Question.create({"id"=>75836, "text"=>"Are there any existing data that you can re-use and that will provide insight or answer any of your research questions? If so, please explain how you will obtain these data and integrate them into your research project.", "default_value"=>nil, "number"=>2, "section_id"=>24612, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d0eb4305-f128-4b1f-b903-e2364ae9e44b"})
Annotation.create({"id"=>71827, "question_id"=>75836, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">There are many potential sources of existing data, including research data repositories, research registries, and government agencies.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Examples of these include:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><a href=\"https://www.statcan.gc.ca/eng/dli/dli-products\"><span style=\"font-weight: 400;\">Statistics Canada Public Use Microdata Files</span></a><span style=\"font-weight: 400;\"> available through the </span><a href=\"https://www.statcan.gc.ca/eng/dli/dli\">Data Liberation Initiative (DLI)</a></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">The Canadian based </span><a href=\"https://www.frdr-dfdr.ca/repo/\"><span style=\"font-weight: 400;\">Federated Research Data Repository (FRDR</span></a><span style=\"font-weight: 400;\">)</span></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Research data repositories, such as those listed at </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">re3data.org</span></a></li>\r\n</ul>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><a href=\"https://docs.google.com/presentation/d/1hVG2jufMaYysIXxw2DDuK5Ia0yzvLMaLx23GTH7Dz4U/edit#slide=id.p4\"><span style=\"font-weight: 400;\">Data repositories that house qualitative research data</span></a></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">You may also wish to contact the Library at your institution for assistance in searching for any existing data that may be useful to your research.</span></p>", "type"=>"guidance", "versionable_id"=>"df281d4e-d26f-4387-8bf3-e7e0f5102804"})
Question.create({"id"=>75837, "text"=>"<p><span style=\"font-weight: 400;\">It is important to identify and understand as early as possible the methods which you will employ in collecting your data to ensure that they will support your needs, including supporting the secure collection of sensitive data if applicable.</span></p>\r\n<p><span style=\"font-weight: 400;\">Describe the method(s) that you will use to collect your data.</span></p>", "default_value"=>nil, "number"=>3, "section_id"=>24612, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"19698dfb-f98a-448a-a6ae-5d567f645954"})
Annotation.create({"id"=>71828, "question_id"=>75837, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Include a description of any methods that you will use to collect data, including electronic platforms or paper based methods. For electronic methods be sure to include descriptions of any privacy policies as well as where and how data will be stored while within the platform.<br /><br /></span><span style=\"font-weight: 400;\">For an example of a detailed mixed methods description, see this Portage DMP Exemplar in either </span><a href=\"https://zenodo.org/records/4019563\"><span style=\"font-weight: 400;\">English</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://zenodo.org/records/4019569\"><span style=\"font-weight: 400;\">French</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">There are many electronic survey data collection platforms to choose from (e.g., </span><a href=\"https://www.qualtrics.com/lp/survey-platform-2/?utm_source=google&amp;utm_medium=ppc&amp;utm_campaign=US-RC-Online-Surveys&amp;utm_keyword=%2Bsurvey%20%2Bplatforms&amp;MatchType=b&amp;adid=351559586523&amp;utm_content=351559586523&amp;adgroupid=40727763998&amp;campaignid=755265584&amp;AdGroup=%7BAdGroup%7D&amp;BidMatchType=%7BBidMatchType%7D&amp;Target=&amp;targetid=kwd-303502943024&amp;Device=c&amp;devicemodel=&amp;loc_phsyical_ms=9001389&amp;Placement=&amp;querystring=%7Bquerystring%7D&amp;network=g&amp;adposition=&amp;GCLID=EAIaIQobChMIgKjd-eaQ6gIVeT2tBh3HtwZCEAAYASAAEgK8rPD_BwE&amp;gclid=EAIaIQobChMIgKjd-eaQ6gIVeT2tBh3HtwZCEAAYASAAEgK8rPD_BwE&amp;utm_expid=.tPmKzGJRSWWAk6oPbSwaWw.1&amp;utm_referrer=https%3A%2F%2Fwww.google.com%2F\"><span style=\"font-weight: 400;\">Qualtrics</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://www.project-redcap.org/\"><span style=\"font-weight: 400;\">REDCap</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://www.hostedincanadasurveys.ca/\"><span style=\"font-weight: 400;\">Hosted in Canada Surveys</span></a><span style=\"font-weight: 400;\">). Understanding </span><em><span style=\"font-weight: 400;\">how </span></em><span style=\"font-weight: 400;\">and </span><em><span style=\"font-weight: 400;\">where</span></em><span style=\"font-weight: 400;\"> your survey data will be collected and stored is an essential component of managing your data and ensuring that you are adhering to any security requirements imposed by funders or research ethics boards.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">Additionally, it is important to clearly understand any security and privacy policies that are in place for any given electronic platform that you will use for collecting your data&nbsp; - examples of such privacy policies include those provided by </span><a href=\"https://www.qualtrics.com/privacy-statement/\"><span style=\"font-weight: 400;\">Qualtrics</span></a><span style=\"font-weight: 400;\"> (survey) and </span><a href=\"https://zoom.us/privacy\"><span style=\"font-weight: 400;\">Zoom</span></a><span style=\"font-weight: 400;\"> (interviews).</span>", "type"=>"guidance", "versionable_id"=>"24d57dcf-daa6-41df-9a97-ebe986a8384d"})
Question.create({"id"=>75838, "text"=>"If interview and/or focus group audio recordings will be transcribed, describe how this will securely occur, including if it will be performed internally to the research team or externally (outsourced), and/or if any software and/or electronic platforms or services will be used for transcribing.", "default_value"=>nil, "number"=>4, "section_id"=>24612, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"2e2e88c4-9d2d-46b8-a6f1-e19e73b21c7f"})
Annotation.create({"id"=>71829, "question_id"=>75838, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">To support transcribing activities within your research project, it is recommended that you implement a transcribing protocol which clearly outlines such things as formatting instructions, a summary of contextual metadata to include, participant and interviewer anonymization, and file naming conventions.</span></p>\r\n<p><span style=\"font-weight: 400;\">When outsourcing transcribing services, and especially when collecting sensitive data, it is important to have a confidentiality agreement in place with transcribers, including a protocol for their deleting any copies of data once it has been transcribed, transferred, and approved. Additionally, you will need to ensure that methods for transferring and storing data align with any applicable funder or institutional requirements.</span></p>", "type"=>"guidance", "versionable_id"=>"03868e74-8529-4e23-b989-06339bec0238"})
Question.create({"id"=>75839, "text"=>"Describe how your data will be securely transferred, including from data collection devices/platforms and, if applicable, to/from transcriptionists.", "default_value"=>nil, "number"=>5, "section_id"=>24612, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"35b72d9a-ed47-421b-a0f7-876e6e7d596c"})
Annotation.create({"id"=>71830, "question_id"=>75839, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Transferring of data is a critical stage of the data collection process, and especially so when managing sensitive information. Data transfers may occur:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">from the field (real world settings)</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">from data providers</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">between researchers</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">between researchers &amp; stakeholders</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">It is best practice to identify data transfer methods that you will use </span><em><span style=\"font-weight: 400;\">before </span></em><span style=\"font-weight: 400;\">your research begins.</span></p>\r\n<p><span style=\"font-weight: 400;\">Some risks associated with the transferring of data include loss of data, unintended copies of data files, and data being provided to unintended recipients. You should avoid transferring data using unsecured methods, such as email. Typical approved methods for transferring data include </span><a href=\"https://en.wikipedia.org/wiki/SSH_File_Transfer_Protocol\"><span style=\"font-weight: 400;\">secure File Transfer Protocol (SFTP)</span></a><span style=\"font-weight: 400;\">, secure extranets, or other methods approved by your institution.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Talk to your local IT support to identify secure data transferring methods available to you.</span></p>", "type"=>"guidance", "versionable_id"=>"16853699-6a73-491a-9166-e0a6f0aa2b8d"})
Question.create({"id"=>75840, "text"=>"Describe all of the file formats that your data will exist in, including for the various versions of both survey and qualitative interview/focus group data. Will these formats allow for data re-use, sharing and long-term access to the data?", "default_value"=>nil, "number"=>6, "section_id"=>24612, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"179d529c-2e26-447c-9dc2-afc8f047b6d2"})
Annotation.create({"id"=>71831, "question_id"=>75840, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Ensuring that your data files exist in non-proprietary formats helps to ensure that they are able to be easily accessed and reused by others in the future.</span></p>\r\n<p><span style=\"font-weight: 400;\">Examples of non-proprietary file formats include:</span></p>\r\n<p><span style=\"font-weight: 400;\">Surveys: </span><a href=\"https://en.wikipedia.org/wiki/Comma-separated_values\"><span style=\"font-weight: 400;\">CSV</span></a><span style=\"font-weight: 400;\">; </span><a href=\"https://en.wikipedia.org/wiki/HTML\"><span style=\"font-weight: 400;\">HTML</span></a><span style=\"font-weight: 400;\">;</span><a href=\"https://en.wikipedia.org/wiki/Unicode#UTF\"><span style=\"font-weight: 400;\"> Unicode Transformation Formats</span></a><span style=\"font-weight: 400;\">&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Qualitative interviews:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Audio files&rarr; </span><a href=\"https://en.wikipedia.org/wiki/MP3\"><span style=\"font-weight: 400;\">MP3</span></a><span style=\"font-weight: 400;\">; </span><a href=\"https://en.wikipedia.org/wiki/FLAC\"><span style=\"font-weight: 400;\">FLAC</span></a><span style=\"font-weight: 400;\">; </span><a href=\"https://en.wikipedia.org/wiki/Ogg\"><span style=\"font-weight: 400;\">Ogg</span></a></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Video files&rarr; </span><a href=\"https://en.wikipedia.org/wiki/MPEG-4_Part_14\"><span style=\"font-weight: 400;\">MP4</span></a><span style=\"font-weight: 400;\">; </span><a href=\"https://en.wikipedia.org/wiki/Matroska\"><span style=\"font-weight: 400;\">.mkv</span></a></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Transcriptions&rarr; </span><a href=\"https://en.wikipedia.org/wiki/Plain_text\"><span style=\"font-weight: 400;\">Plain Text</span></a><span style=\"font-weight: 400;\">, such as </span><a href=\"https://en.wikipedia.org/wiki/ASCII\"><span style=\"font-weight: 400;\">ASCII</span></a><span style=\"font-weight: 400;\">; </span><a href=\"https://en.wikipedia.org/wiki/Comma-separated_values\"><span style=\"font-weight: 400;\">CSV</span></a><span style=\"font-weight: 400;\">; </span><a href=\"https://en.wikipedia.org/wiki/HTML\"><span style=\"font-weight: 400;\">HTML</span></a></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">For more information and resources pertaining to file formats you may wish to visit:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><a href=\"https://library-archives.canada.ca/eng/services/government-canada/information-disposition/guidelines-information-management/Pages/guidelines-file-formats-enduring-value.aspx\"><span style=\"font-weight: 400;\">Library &amp; Archives Canada</span></a></li>\r\n<li style=\"font-weight: 400;\"><a href=\"https://datacurationnetwork.org/resources/data-curation-primers/\"><span style=\"font-weight: 400;\">Data Curation Network</span></a></li>\r\n<li style=\"font-weight: 400;\"><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/file-formats.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a></li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"25fe9cc9-dc6d-45e2-8438-608d9c18d05d"})
Section.create({"id"=>24613, "title"=>"Documentation and Metadata", "description"=>nil, "number"=>3, "phase_id"=>3896, "modifiable"=>true, "versionable_id"=>"3668a338-2423-4ba9-965b-6d5e6714b5e5"})
Question.create({"id"=>75841, "text"=>"Describe any documentation and metadata that will be used in order to ensure that data are able to be read and understood both during the active phases of the project and in the future.", "default_value"=>nil, "number"=>1, "section_id"=>24613, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"fa5cfab9-b4d8-4634-8ccc-41b3e0be865e"})
Annotation.create({"id"=>71832, "question_id"=>75841, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Include a description of the survey codebook(s) (data dictionary), as well as how it will be developed and generated. You should also include a description of the interview data that will be collected, including any important contextual information and metadata associated with file formats.</span></p>\r\n<p><span style=\"font-weight: 400;\">Your documentation may include study-level information about:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">who created/collected the data</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">when it was created</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">any relevant study documents</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">conditions of use</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">contextual details about data collection methods and procedural documentation about how data files are stored, structured, and modified.</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">A complete description of the data files may include:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">naming and labelling conventions</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">explanations of codes and variables</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">any information or files required to reproduce derived data.</span></li>\r\n</ul>\r\n<span style=\"font-weight: 400;\">More information about both general and discipline specific data documentation is available at </span><a href=\"https://www.dcc.ac.uk/guidance/standards/metadata\"><span style=\"font-weight: 400;\">https://www.dcc.ac.uk/guidance/standards/metadata</span></a>", "type"=>"guidance", "versionable_id"=>"ef25c2ca-c36c-4323-bac6-dc4ebc6ab5df"})
Question.create({"id"=>75842, "text"=>"Describe the file naming conventions that will be used in order to support quality assurance and version-control of your files and to help others understand how your data are organized.", "default_value"=>nil, "number"=>2, "section_id"=>24613, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7957299f-24cd-4724-a1ef-c9dd2b23d602"})
Annotation.create({"id"=>71833, "question_id"=>75842, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">For guidance on file naming conventions please see the <a href=\"https://www.ed.ac.uk/records-management/guidance/records/practical-guidance/naming-conventions\">University of Edinburgh</a>.</span>", "type"=>"guidance", "versionable_id"=>"1d5d2a16-edc6-4464-ba88-24f5886cbfb0"})
Question.create({"id"=>75843, "text"=>"<span style=\"font-weight: 400;\">Describe how you will ensure that documentation and metadata are created, captured and, if necessary, updated consistently throughout the research project.</span>", "default_value"=>nil, "number"=>3, "section_id"=>24613, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"da239179-2e5a-4527-8724-2444e4ff448c"})
Annotation.create({"id"=>71834, "question_id"=>75843, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">High quality documentation and metadata help to ensure accuracy, consistency, and completeness of your data. It is considered best practice to develop and implement protocols that clearly communicate processes for capturing important information throughout your research project. </span><span style=\"font-weight: 400;\">Example topics that these protocols might cover include file naming conventions, file versioning, folder structure, and both descriptive and structural metadata.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">Researchers and research staff should ideally have the opportunity to contribute to the content of metadata protocols, and it </span><span style=\"font-weight: 400;\">is additionally useful to consult regularly with members of the research team to capture any potential changes in data collection/processing that need to be reflected in the documentation.</span>", "type"=>"guidance", "versionable_id"=>"04a6d14c-6b94-4411-a056-79b0f3e48df1"})
Question.create({"id"=>75844, "text"=>"<span style=\"font-weight: 400;\">Describe any metadata standard(s) and/or tools that you will use to support the describing and documenting of your data. </span>", "default_value"=>nil, "number"=>4, "section_id"=>24613, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"90abab15-6c40-461e-836c-f2ec3c4ee70d"})
Annotation.create({"id"=>71835, "question_id"=>75844, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Metadata are descriptions of the contents and context of data files. Using a metadata standard (a set of required fields to fill out) helps to ensure that your documentation is consistent, structured, and machine-readable, which is essential for depositing data in repositories and making it easily discoverable by search engines.</span></p>\r\n<p><span style=\"font-weight: 400;\">There are both general and </span><a href=\"https://le.unimelb.edu.au/supporting-teaching-learning-assessment/video-for-learning-resources/discipline-specific-skills\"><span style=\"font-weight: 400;\">discipline-specific</span></a><span style=\"font-weight: 400;\"> metadata standards and tools for research data.</span></p>\r\n<p><span style=\"font-weight: 400;\">One of the most widely used metadata standards for surveys is </span><a href=\"https://ddialliance.org\"><span style=\"font-weight: 400;\">DDI</span></a><span style=\"font-weight: 400;\"> (Data Documentation Initiative), a free standard that can document and manage different stages in the research data lifecycle including data collection, processing, distribution, discovery and archiving.</span></p>\r\n<span style=\"font-weight: 400;\">For assistance with choosing a metadata standard, support may be available at your institution&rsquo;s Library or contact </span><a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a><span style=\"font-weight: 400;\">. </span>", "type"=>"guidance", "versionable_id"=>"16b8495f-fa11-4bbf-9d37-97ca0927c19f"})
Section.create({"id"=>24614, "title"=>"Storage, Access, and Backup", "description"=>nil, "number"=>4, "phase_id"=>3896, "modifiable"=>true, "versionable_id"=>"ea7414ef-f59f-4451-9c4e-764e2a71c011"})
Question.create({"id"=>75845, "text"=>"<span style=\"font-weight: 400;\">Describe where, how, and for how long data will be securely stored during the </span><em><span style=\"font-weight: 400;\">active phases</span></em><span style=\"font-weight: 400;\"> of the research project. If any data are to be collected through the use of electronic platforms, account for their usage within your data storage description. Include a description of any policies and procedures that will be in place to ensure that data are regularly backed-up.</span>", "default_value"=>nil, "number"=>1, "section_id"=>24614, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"41eb366d-7823-4c6e-bb2b-06e42d241177"})
Annotation.create({"id"=>71836, "question_id"=>75845, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Data storage is a critical component of managing your research data, and secure methods should always be used, especially when managing sensitive data. Storing data on USB sticks, laptops, computers, and/or external hard drives without a regular backup procedure in place is not considered to be best practice due to their being a risk both for data breaches (e.g., loss, theft) as well as corruption and hardware failure. Likewise, having only one copy, or multiple copies of data stored in the same physical location does little to mitigate risk.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Many universities offer networked file storage which is automatically backed up. Contact your local (e.g., faculty or organization) and/or central IT services to find out what secure data storage services and resources they are able to offer to support your research project.</span></p>\r\n<span style=\"font-weight: 400;\">Additionally, you may wish to consider investigating Computer Canada's </span><a href=\"https://alliancecan.ca/en/services/advanced-research-computing/accessing-resources/rapid-access-service\"><span style=\"font-weight: 400;\">Rapid Access Service </span></a><span style=\"font-weight: 400;\">which provides Principal Investigators at Canadian post-secondary institutions with a modest amount of storage and cloud resources at no cost.</span>", "type"=>"guidance", "versionable_id"=>"80f84426-053e-4eaa-a487-6c14df9cffd3"})
Question.create({"id"=>75846, "text"=>"<span style=\"font-weight: 400;\">Describe how members of the research team will securely access and work with data during the active phases of the research project. </span>", "default_value"=>nil, "number"=>2, "section_id"=>24614, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c99fcc78-5f83-4a35-8e71-559a830ca258"})
Annotation.create({"id"=>71837, "question_id"=>75846, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">It is important to determine at the early stages of your research project how members of the research team will appropriately access and work with data. If researchers will be working with data using their local computers (work or personal) then it is important to ensure that data are securely transferred (see previous question on data transferring), computers may need to be encrypted, and that all processes meet any requirements imposed by funders, institutions, and research ethics offices.</span></p>\r\n<p><span style=\"font-weight: 400;\">When possible, it can be very advantageous to use a cloud-based environment so that researchers can remotely access and work with data, reducing the need for data transferring and associated risks, as well as unnecessary copies of data existing.</span></p>\r\n<span style=\"font-weight: 400;\">One such cloud environment that is freely available to Canadian researchers is Compute Canada&rsquo;s </span><a href=\"https://alliancecan.ca/en/services/advanced-research-computing/accessing-resources/rapid-access-service\"><span style=\"font-weight: 400;\">Rapid Access Service</span></a><span style=\"font-weight: 400;\">. </span>", "type"=>"guidance", "versionable_id"=>"e0a62b2e-a967-4949-a1ab-8cdb114fd8b6"})
Question.create({"id"=>75847, "text"=>"<span style=\"font-weight: 400;\">Describe how much storage space you will require during the active phases of the research project, being sure to take into account file versioning and </span><span style=\"font-weight: 400;\">data growth.</span>", "default_value"=>nil, "number"=>3, "section_id"=>24614, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5bac0951-f3e7-4382-9940-85fca7ec0451"})
Annotation.create({"id"=>71838, "question_id"=>75847, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Think about all of the data that will be generated, including their various versions, and estimate how much space (e.g., megabytes, gigabytes, terabytes) will be required to store them.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">The type of data you collect, along with the length of time that you require active storage, will impact the resources that you require. Textual and tabular data files are usually very small (a few megabytes) unless you have a lot of data. Video files are usually very large (hundreds of megabytes up to several gigabytes). If you have a large amount of data (gigabytes or terabytes), it will be more challenging to share and transfer it. You may need to consider networked storage options or more sophisticated backup methods.</span></p>\r\n<span style=\"font-weight: 400;\">You may wish to contact your local IT services to discuss what data storage options are available to you, or consider the use of </span><a href=\"https://alliancecan.ca/en/services/advanced-research-computing/accessing-resources/rapid-access-service\"><span style=\"font-weight: 400;\">Compute Canada&rsquo;s Rapid Access Service</span></a><span style=\"font-weight: 400;\">.&nbsp; </span>", "type"=>"guidance", "versionable_id"=>"a9286834-e40f-42fc-82bd-fae318e769ec"})
Section.create({"id"=>24615, "title"=>"Preservation", "description"=>nil, "number"=>5, "phase_id"=>3896, "modifiable"=>true, "versionable_id"=>"1179dbd6-85c4-446c-b98f-cc3ff59218df"})
Question.create({"id"=>75848, "text"=>"<span style=\"font-weight: 400;\">Describe how you will ensure that your data is preservation ready, including the file format(s) that they will be preserved in and. </span><span style=\"font-weight: 400;\">Explain how you will prevent data from being lost while processing and converting files.</span>", "default_value"=>nil, "number"=>1, "section_id"=>24615, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"77778f54-3fd8-4c3c-b760-d076df1e8572"})
Annotation.create({"id"=>71839, "question_id"=>75848, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Proprietary data formats are not optimal for long-term preservation of data as they typically require specialized licensed software to open them. Such software may have costs associated with its use, or may not even be available to others wanting to re-use your data in the future.</span></p>\r\n<p><span style=\"font-weight: 400;\">Non-proprietary file formats, such as comma-separated values (</span><a href=\"https://en.wikipedia.org/wiki/Comma-separated_values\"><span style=\"font-weight: 400;\">.csv</span></a><span style=\"font-weight: 400;\">), text (</span><a href=\"https://en.wikipedia.org/wiki/Text_file\"><span style=\"font-weight: 400;\">.txt</span></a><span style=\"font-weight: 400;\">) and </span><span style=\"font-weight: 400;\">free lossless audio codec (<a href=\"https://en.wikipedia.org/wiki/FLAC\">.flac</a>)</span><span style=\"font-weight: 400;\">, are considered preservation-friendly. The </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/recommended-formats.aspx\"><span style=\"font-weight: 400;\">UK Data Archive</span></a><span style=\"font-weight: 400;\"> provides a useful table of file formats for various types of data. Keep in mind that preservation-friendly files converted from one format to another may lose information (e.g. converting from an uncompressed TIFF file to a compressed JPG file), so changes to file formats should be documented.</span></p>\r\n<p><span style=\"font-weight: 400;\">Identify the steps required to ensure the data you are choosing to preserve is error-free, and converted to recommended formats with a minimal risk of data loss following project completion. Some strategies to remove identifiers in images, audio, and video (e.g. blurring faces, changing voices) also remove information of value to other researchers.</span></p>\r\n<p><span style=\"font-weight: 400;\">See this Portage DMP Exemplar in </span><a href=\"https://zenodo.org/records/4019563\"><span style=\"font-weight: 400;\">English</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://zenodo.org/records/4019569\"><span style=\"font-weight: 400;\">French</span></a><span style=\"font-weight: 400;\"> for more help describing preservation-readiness.</span></p>", "type"=>"guidance", "versionable_id"=>"9115aaf5-c4df-4a57-b015-f42279613b11"})
Question.create({"id"=>75849, "text"=>"<span style=\"font-weight: 400;\">Describe where you will preserve your data for long-term preservation, including any research data repositories that you may be considering to use. If there are any costs associated with the preservation of your data, include those details.</span>", "default_value"=>nil, "number"=>2, "section_id"=>24615, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"19931f19-0a34-4b0a-ab2e-2099f73dde39"})
Annotation.create({"id"=>71840, "question_id"=>75849, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">A research data repository is a technology-based platform that allows for research data to be:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Deposited &amp; described</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Stored &amp; archived</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Shared &amp; published</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Discovered &amp; reused</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">There are different types of repositories including:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Proprietary (paid for services)</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Open source (free to use)</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Discipline specific</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">A key feature of a trusted research data repository is the assignment of a digital object identifier (DOI) to your data - a </span><em><span style=\"font-weight: 400;\">unique persistent identifier</span></em><span style=\"font-weight: 400;\"> assigned by a registration agency to identify digital content and provide a persistent link to its location, enabling for long-term discovery.</span></p>\r\n<p><span style=\"font-weight: 400;\">Dataverse is one of the most popular research data repository platforms in Canada for supporting the deposition of survey data and qualitative text files. Key features of Dataverse include the assignment of a DOI, the ability to make your data both open or restricted access, built in data citations, file versioning, and the ability to create customized terms of use pertaining to your data. Contact your local university Library to find out if there is a Dataverse instance available for you to use.</span></p>\r\n<a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">Re3data.org</span></a> <span style=\"font-weight: 400;\">is an online registry of data repositories, which can be searched according to subject, content type and country. Find a list of </span><a href=\"https://www.re3data.org/search?query=&amp;countries[]=CAN\"><span style=\"font-weight: 400;\">Canadian research data repositories</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"a7ccc151-2cc1-41f8-ab9f-5a50de976016"})
Section.create({"id"=>24616, "title"=>"Sharing and Reuse", "description"=>nil, "number"=>6, "phase_id"=>3896, "modifiable"=>true, "versionable_id"=>"b96d6436-88b5-4712-acbc-46aea71d2b11"})
Question.create({"id"=>75850, "text"=>"<span style=\"font-weight: 400;\">Describe what data you will be sharing, including which version(s) (e.g., raw, processed, analyzed) and in what format(s). </span>", "default_value"=>nil, "number"=>1, "section_id"=>24616, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"ac7aa17d-2879-4476-a005-49c731b79a3a"})
Annotation.create({"id"=>71841, "question_id"=>75850, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Consider which data you are planning to share or that you may need to share in order to meet funding or institutional requirements. As well, think about which data may possibly be restricted for reasons relating to confidentiality and/or privacy. If you are planning to share either/both survey and qualitative interviews data that require de-identification, explain how any necessary direct and indirect identifiers will be removed.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Examples of file versions are:</span></p>\r\n<ul>\r\n<li><strong>Raw</strong><span style=\"font-weight: 400;\">: </span><span style=\"font-weight: 400;\">Original data that has been collected and not yet processed or analysed. For surveys this will be the original survey data, and for qualitative interviews this will most often be the original audio data as well as raw transcriptions which are verbatim copies of the audio files.</span></li>\r\n<li><strong>Processed:</strong><span style=\"font-weight: 400;\"> Data that have undergone some type of processing, typically for data integrity and quality assurance purposes. For survey data, this may involve such things as deletion of cases and derivation of variables. For qualitative interview data, this may involve such things as formatting, and de-identification and anonymization activities.</span></li>\r\n<li><strong>Analyzed: </strong><span style=\"font-weight: 400;\">Data that are already processed and have been used for analytic purposes. Both for surveys and qualitative interviews, analyzed data can exist in different forms including in analytic software formats (e.g. SPSS, R, Nvivo), as well as in text, tables, graphs, etc.</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Remember, research involving human participants typically requires participant consent to allow for the sharing of data. Along with your data, you should ideally include samples of the study information letter and participant consent form, as well as information relating to your approved institutional ethics application.</span></p>", "type"=>"guidance", "versionable_id"=>"26e2108a-9ddb-4a74-899f-49e78a57f9a0"})
Question.create({"id"=>75851, "text"=>"<span style=\"font-weight: 400;\">Describe whether there will be any restrictions placed on your data when they are made available and who may access them. If data are not openly available, describe the process for gaining access</span><span style=\"font-weight: 400;\">.</span>", "default_value"=>nil, "number"=>2, "section_id"=>24616, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"00f34952-f8ca-4118-a28b-7c39f537e422"})
Annotation.create({"id"=>71842, "question_id"=>75851, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">It may be necessary or desirable to restrict access to your data for a limited time or to a limited number of people, for:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">ethical reasons (privacy and confidentiality)&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">economic reasons (patents and commercialization)</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">intellectual property reasons (e.g. ownership of the original dataset on which yours is based)&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">or to comply with a journal publishing policy.&nbsp;</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Strategies to mitigate these issues may include:&nbsp;</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">anonymising or aggregating data (see additional information at the </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical/anonymisation.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\"> or the </span><a href=\"https://doi.org/10.5281/zenodo.4270551\"><span style=\"font-weight: 400;\">Portage Network</span></a><span style=\"font-weight: 400;\">)</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">gaining participant consent for data sharing</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">gaining permissions to share adapted or modified data</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">and agreeing to a limited embargo period.</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">If applicable, consider creating a Terms of Use document to accompany your data. </span></p>", "type"=>"guidance", "versionable_id"=>"31708182-4210-4727-8542-3ec0637e1de0"})
Question.create({"id"=>75852, "text"=>"<span style=\"font-weight: 400;\">What type of end-user license will you include with your data? </span>", "default_value"=>nil, "number"=>3, "section_id"=>24616, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"217cb252-6a2e-46af-b806-9828d6832667"})
Annotation.create({"id"=>71843, "question_id"=>75852, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Licenses determine what uses can be made of your data. Funding agencies and/or data repositories may have end-user license requirements in place; if not, they may still be able to guide you in the development of a license. Once created, it is considered as best practice to include a copy of your end-user license with your Data Management Plan. Note that only the intellectual property rights holder(s) can issue a license, so it is crucial to clarify who owns those rights.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">There are several types of standard licenses available to researchers, such as the </span><a href=\"http://creativecommons.org/choose/\"><span style=\"font-weight: 400;\">Creative Commons licenses</span></a><span style=\"font-weight: 400;\"> and the </span><a href=\"http://opendatacommons.org/licenses/\"><span style=\"font-weight: 400;\">Open Data Commons licenses</span></a><span style=\"font-weight: 400;\">. In fact, for most datasets it is easier to use a standard license rather than to devise a custom-made one. Note that even if you choose to make your data part of the public domain, it is preferable to make this explicit by using a license such as Creative Commons' CC0.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">Read more about data licensing: </span><a href=\"http://www.dcc.ac.uk/resources/how-guides/license-research-data\"><span style=\"font-weight: 400;\">UK Digital Curation Centre</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"fc85f4b9-edea-41b1-afca-a0bd6efc83c1"})
Section.create({"id"=>24617, "title"=>"Responsibilities and Resources", "description"=>nil, "number"=>7, "phase_id"=>3896, "modifiable"=>true, "versionable_id"=>"a067b6f5-d528-4f7d-ada4-34588781bf6a"})
Question.create({"id"=>75853, "text"=>"<span style=\"font-weight: 400;\">Who will be responsible for data management during the project (i.e., during collection, processing, analysis, documentation)? Identify staff and organizational roles and their responsibilities for carrying out the data management plan (DMP), including time allocations and training requirements.</span>", "default_value"=>nil, "number"=>1, "section_id"=>24617, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0ab8dd8c-ea45-4ff0-9fac-e08ebb00df96"})
Annotation.create({"id"=>71844, "question_id"=>75853, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Research data management is a shared responsibility that can involve many research team members including the Principal Investigator, co-investigators, collaborators, trainees, and research staff. Some projects warrant having a dedicated research data manager position. Think about your project and its needs, including the time and expertise that may be required to manage the data and if any training will be required to prepare members of the research team for these duties.</span></p>\r\n<p><span style=\"font-weight: 400;\">Larger and more complex research projects may additionally wish to have a research data management committee in place which can be responsible for data governance, including the development of policies and procedures relating to research data management. This is a useful way to tap into the collective expertise of the research team, and to establish robust policies and protocols that will serve to guide data management throughout your project.</span></p>", "type"=>"guidance", "versionable_id"=>"6bc7f573-1078-4691-aa91-46ed96d7dadd"})
Question.create({"id"=>75854, "text"=>"<span style=\"font-weight: 400;\">How will responsibilities for managing data activities be handled if substantive changes happen in the personnel overseeing the project's data, including a change of Principal Investigator?</span>", "default_value"=>nil, "number"=>2, "section_id"=>24617, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7d9c66a3-4c8d-4f40-a49f-e9fa6046b306"})
Annotation.create({"id"=>71845, "question_id"=>75854, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">It is important to think ahead and be prepared for potential PI and/or research team members changes should they occur. </span><span style=\"font-weight: 400;\">Developing data governance policies that clearly indicate a succession strategy for the project&rsquo;s data will help greatly in ensuring that the data continue to be effectively and appropriately managed. Such policies should clearly describe the process to be followed in the event that the Principal Investigator leaves the project. In some instances, a co-investigator or the department or division overseeing this research will assume responsibility. </span>", "type"=>"guidance", "versionable_id"=>"89f6bbf1-132f-4714-8d2c-ee8389ae059a"})
Question.create({"id"=>75855, "text"=>"<span style=\"font-weight: 400;\">What resources will you require to implement your data management plan? What do you estimate the overall cost for data management to be?</span>", "default_value"=>nil, "number"=>3, "section_id"=>24617, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"b7a61fd1-69e9-4eb1-acc8-931bce6ebc22"})
Annotation.create({"id"=>71846, "question_id"=>75855, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Estimate as early as possible the resources and costs associated with the management of your project&rsquo;s data. This estimate should incorporate costs incurred both during the active phases of the project as well as those potentially required for support of the data once the project is finished, including preparing the data for deposit and long-term preservation.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Many funding agencies will provide support for research data management, so these estimates may be included within your proposed project budget. Items that may be pertinent to mixed methods research include such things as a dedicated research data management position (even if it is part-time), support for the use of a digital survey data collection platform, computers/laptops, digital voice recorders, specialized software, transcription of qualitative interviews, data storage, data deposition, and data preservation.</span></p>", "type"=>"guidance", "versionable_id"=>"34cde2f8-eb55-4b26-919d-11f6555f245f"})
Section.create({"id"=>24618, "title"=>"Ethics and Legal Compliance", "description"=>nil, "number"=>8, "phase_id"=>3896, "modifiable"=>true, "versionable_id"=>"e37d254e-227c-4f42-ae95-32bcae7522c7"})
Question.create({"id"=>75856, "text"=>"<span style=\"font-weight: 400;\">If applicable, what strategies will you undertake to address secondary uses of data, </span><span style=\"font-weight: 400;\">and especially those which are sensitive in nature</span><span style=\"font-weight: 400;\">?</span>", "default_value"=>nil, "number"=>1, "section_id"=>24618, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"6f198c9f-c105-4fc2-ad3a-56321b3c24ae"})
Annotation.create({"id"=>71847, "question_id"=>75856, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Obtaining the appropriate consent from research participants is an important step in assuring Research Ethics Boards that the data may be shared with researchers outside your project. The consent statement may identify certain conditions clarifying the uses of the data by other researchers, as well as what version(s) of the data may be shared and re-used. For example, it may stipulate that the data will only be shared for non-profit research purposes, that the data will not be linked with personally identified data from other sources, and that only de-identified and/or aggregated data may be reused. In the case of qualitative interviews, this may include only the de-identified transcriptions of interviews and/or analytic files containing de-identified contextual information.</span></p>\r\n<p><span style=\"font-weight: 400;\">Sensitive data in particular should always receive special attention and be clearly identified and documented within your DMP as to how they will be managed throughout your project including data collection, transferring, storage, access, and both potential sharing, and reuse</span><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">Your data management plan and deposited data should both include an identifier or link to your approved research ethics application form as well as an example of any participant consent forms.</span></p>", "type"=>"guidance", "versionable_id"=>"8d4d38a5-18a5-47a0-8f45-3b03d95a2bb8"})
Question.create({"id"=>75857, "text"=>"<span style=\"font-weight: 400;\">How will you manage legal, ethical, and intellectual property issues?</span>", "default_value"=>nil, "number"=>2, "section_id"=>24618, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f75005bd-d41b-4b04-9e5e-24528d91acb3"})
Annotation.create({"id"=>71848, "question_id"=>75857, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Compliance with privacy legislation and laws that may impose content restrictions in the data should be discussed with your institution's privacy officer, research services office, and/or research ethics office.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Include here a description concerning ownership, licensing, and intellectual property rights of the data. Terms of reuse must be clearly stated, in line with the relevant legal and ethical requirements where applicable (e.g., subject consent, permissions, restrictions, etc.).</span></p>", "type"=>"guidance", "versionable_id"=>"0ad12d56-0eb3-465a-b9c2-dc59edc6191c"})
Template.create!({"id"=>3873, "title"=>"Alliance Template for Open Science Workflows", "description"=>"<p><span style=\"font-weight: 400;\">This template guides the writing of a research data management plan (DMP) with an open science/open scholarship workflow, which uses mixed social sciences research methods, producing quantitative as well as qualitative datasets. The questions emphasize data sharing and reuse throughout the project, not only at the final stage of publication. This DMP template will be most useful to researchers who are working in a multi-institutional partnership and who have already completed a funding application and an ethics review protocol.&nbsp; The DMP is a living document:</span> <span style=\"font-weight: 400;\">don&rsquo;t forget to revisit your DMP throughout the research project to update or review your responses.</span></p>\n<p><span style=\"font-weight: 400;\">Not all of these questions will apply to all research projects. We encourage you to respond to as many as possible but ultimately, you and your team have to decide which questions and answers apply to your workflow. </span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>2, "visibility"=>1, "customization_of"=>nil, "family_id"=>43432169, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3931, "title"=>"Alliance Template for Open Science Workflows", "description"=>"<p><span style=\"font-weight: 400;\">This template guides the writing of a research data management plan (DMP) with an open science/open scholarship workflow, which uses mixed social sciences research methods, producing quantitative as well as qualitative datasets. The questions emphasize data sharing and reuse throughout the project, not only at the final stage of publication. This DMP template will be most useful to researchers who are working in a multi-institutional partnership and who have already completed a funding application and an ethics review protocol.&nbsp; The DMP is a living document:</span> <span style=\"font-weight: 400;\">don&rsquo;t forget to revisit your DMP throughout the research project to update or review your responses.</span></p>\r\n<p><span style=\"font-weight: 400;\">Not all of these questions will apply to all research projects. We encourage you to respond to as many as possible but ultimately, you and your team have to decide which questions and answers apply to your workflow. </span></p>", "number"=>1, "template_id"=>3873, "modifiable"=>true, "versionable_id"=>"e6951813-58f1-4b51-918d-5b29a744541d"})
Section.create({"id"=>24790, "title"=>"Responsibilities and Resources", "description"=>nil, "number"=>1, "phase_id"=>3931, "modifiable"=>true, "versionable_id"=>"1e26e580-841e-4e88-b4f2-5678e833eb25"})
Question.create({"id"=>76417, "text"=>"Who will be responsible for data management? Will the Principal Investigator (PI) hold all responsibility during and beyond the project, or will this be divided among a team or partner organizations?", "default_value"=>nil, "number"=>1, "section_id"=>24790, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"87268b11-ca08-4ae3-9697-5744ca26fa3c"})
Annotation.create({"id"=>72479, "question_id"=>76417, "org_id"=>8, "text"=>"<p><strong>Assign responsibilities: </strong><span style=\"font-weight: 400;\">Once completed, your data management plan will outline important data activities in your project. Identify who will be responsible -- individuals or organizations -- for carrying out these parts of your data management plan. This could also include the time frame associated with these staff responsibilities and any training needed to prepare staff for these duties.</span></p>", "type"=>"guidance", "versionable_id"=>"b03f2ff9-d7fd-4aa2-866b-360022d6b0ec"})
Question.create({"id"=>76418, "text"=>"In the event that the PI leaves the project, who will replace them? Who will take temporary responsibility until a new PI takes over?", "default_value"=>nil, "number"=>2, "section_id"=>24790, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"15553fae-6358-45c9-8cfd-83eb58a75810"})
Annotation.create({"id"=>72480, "question_id"=>76418, "org_id"=>8, "text"=>"<p><strong>Succession planning: </strong><span style=\"font-weight: 400;\">The PI is usually in charge of maintaining data accessibility standards for the team. Consider who will field questions about accessing information or granting access to the data in&nbsp; the event the PI leaves the project. Usually the Co-PI takes over the responsibilities.</span></p>\r\n<p><span style=\"font-weight: 400;\">Indicate a succession strategy for these data in the event that one or more people responsible for the data leaves (e.g. a graduate student leaving after graduation). Describe the process to be followed in the event that the Principal Investigator leaves the project. In some instances, a co-investigator or the department or division overseeing this research will assume responsibility.</span></p>", "type"=>"guidance", "versionable_id"=>"f9d4e86d-aa97-48c9-9cbe-b8258e28564f"})
Question.create({"id"=>76419, "text"=>"List all expected resources for data management required to complete your project. What hardware, software and human resources will you need? What is your estimated budget?", "default_value"=>nil, "number"=>3, "section_id"=>24790, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0d803857-de44-4cf2-89cc-cc9c3042880d"})
Annotation.create({"id"=>72481, "question_id"=>76419, "org_id"=>8, "text"=>"<strong>Budgeting: </strong><span style=\"font-weight: 400;\">Common purchases are hard drives, cloud storage or software access. </span><a href=\"https://www.tudelft.nl/en/library/research-data-management/r/plan/data-management-costs\"><span style=\"font-weight: 400;\">TU Delft&rsquo;s Data Management Costing Tool</span></a><span style=\"font-weight: 400;\"> is helpful to determine the share of human labor (FTE) that should be allocated for research data management.</span>", "type"=>"guidance", "versionable_id"=>"ebf2728e-23ab-4044-893c-e2eb6c26c8fc"})
Section.create({"id"=>24791, "title"=>"Data Collection", "description"=>nil, "number"=>2, "phase_id"=>3931, "modifiable"=>true, "versionable_id"=>"be274f01-2b3b-4e22-9bdc-b66f5c5acab3"})
Question.create({"id"=>76420, "text"=>"What types of data will you collect, create, link to, acquire and/or record?", "default_value"=>nil, "number"=>1, "section_id"=>24791, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"dad52b46-dbd1-41e6-8781-fc37ffb9ca72"})
Annotation.create({"id"=>72482, "question_id"=>76420, "org_id"=>8, "text"=>"<p><strong>Data types:&nbsp;</strong><span style=\"font-weight: 400;\">Your research data may include digital resources, software code, audio files, image files, video, numeric, text, tabular data, modeling data, spatial data, instrumentation data.</span></p>", "type"=>"guidance", "versionable_id"=>"1a5210a5-50a1-4eb5-874e-ceaecf97e10f"})
Question.create({"id"=>76421, "text"=>"<span style=\"font-weight: 400;\">Answer the following regarding file formats:</span><br />\r\n<ol style=\"list-style-type: upper-alpha;\">\r\n<li><span style=\"font-weight: 400;\">What file formats do you expect to collect (e.g. .doc, .csv, .jpg, .mov)?</span></li>\r\n<li><span style=\"font-weight: 400;\">Are these file formats easy to share with other researchers from different disciplines? </span></li>\r\n<li><span style=\"font-weight: 400;\">In the event that one of your chosen file formats becomes obsolete (or is no longer supported) how will you ensure access to the research data? </span></li>\r\n<li><span style=\"font-weight: 400;\">Does your data need to be copied to a new media or cloud platform, or converted to a different file format when you store or publish your datasets?</span></li>\r\n</ol>", "default_value"=>nil, "number"=>2, "section_id"=>24791, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"badccb96-a80a-48f7-b9a0-16aa6415dabb"})
Annotation.create({"id"=>72483, "question_id"=>76421, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Proprietary file formats requiring specialized software or hardware to use are not recommended, but may be necessary for certain data collection or analysis methods. Using open file formats or industry-standard formats (e.g. those widely used by a given community) is preferred whenever possible. Read more about file formats: </span><a href=\"https://library-archives.canada.ca/eng/services/government-canada/information-disposition/guidelines-information-management/Pages/guidelines-file-formats-enduring-value.aspx\"><span style=\"font-weight: 400;\">Library and Archives Canada,</span></a><span style=\"font-weight: 400;\">&nbsp; </span><a href=\"https://researchdata.library.ubc.ca/plan/format-your-data/\"><span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format.aspx\"><span style=\"font-weight: 400;\">UK Data Archive</span></a><span style=\"font-weight: 400;\">. </span>", "type"=>"guidance", "versionable_id"=>"375ed213-37ee-4a2b-a9f4-0e96984cbee0"})
Question.create({"id"=>76422, "text"=>"Answer the following regarding naming conventions:<br />\r\n<ol style=\"list-style-type: upper-alpha;\">\r\n<li><span style=\"font-weight: 400;\">How will you structure, name and version-control your files to help someone outside your research team understand how your data are organized?</span></li>\r\n<li><span style=\"font-weight: 400;\">Describe your ideal workflow for file sharing between research team members step-by-step. </span></li>\r\n<li><span style=\"font-weight: 400;\">What tools or strategies will you use to document your workflow as it evolves during the course of the project?</span></li>\r\n</ol>", "default_value"=>nil, "number"=>3, "section_id"=>24791, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"948d7f59-bc93-4545-9479-cd657c31f6c9"})
Annotation.create({"id"=>72484, "question_id"=>76422, "org_id"=>8, "text"=>"<strong>File naming and versioning: </strong>It is important to keep track of different copies or versions of files, files held in different formats or locations, and information cross-referenced between files. This process is called 'version control'. Logical file structures, informative naming conventions, and clear indications of file versions, all contribute to better use of your data during and after your research project. These practices will help ensure that you and your research team are using the appropriate version of your data, and minimize confusion regarding copies on different computers and/or on different media. Read more about file naming and version control from <a href=\"https://researchdata.library.ubc.ca/plan/organize-your-data/\">UBC Library</a> or the <a href=\"https://www.ukdataservice.ac.uk/manage-data/format/organising.aspx\">UK Data Service</a>.<br /><br />Remember that this workflow can be adapted, and the DMP updated throughout the project.<br /><br />Using a <a href=\"https://authors.library.caltech.edu/103626/1/FileNamingConventionWorksheet_Caltech.pdf\">file naming convention worksheet</a> can be very useful. Make sure the convention only uses alphanumeric characters, dashes and underscores. In general, file names should be 32 characters or less and contain the date and the version number (e.g.: &ldquo;P1-MUS023_2020-02-29_051_raw.tif&rdquo; and &ldquo;P1-MUS023_2020-02-29_051_clean_v1.tif&rdquo;). <br /><br /><strong>Document workflows: </strong>Have you thought about how you will capture, save and share your workflow and project milestones with your team? You can create an onboarding document to ensure that all team members adopt the same workflows or use workflow management tools like <a href=\"https://osf.io/\">OSF</a> or <a href=\"https://github.com/\">GitHub</a>.", "type"=>"guidance", "versionable_id"=>"8733d208-dda2-42c0-a251-15ddf102c92c"})
Section.create({"id"=>24792, "title"=>"Documentation and Metadata", "description"=>nil, "number"=>3, "phase_id"=>3931, "modifiable"=>true, "versionable_id"=>"775b7fdb-83d0-492f-aa50-7c4922aaf08e"})
Question.create({"id"=>76423, "text"=>"What support material and documentation (e.g. ReadMe) will your team members and future researchers need in order to navigate and reuse your data without ambiguity?", "default_value"=>nil, "number"=>1, "section_id"=>24792, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"03d295b0-9582-41ce-996b-7304b837da5a"})
Annotation.create({"id"=>72485, "question_id"=>76423, "org_id"=>8, "text"=>"<p><strong>Data documentation:&nbsp;</strong><span style=\"font-weight: 400;\">It is strongly encouraged to include a ReadMe file with all datasets (or similar) to assist in understanding data collection and processing methods, naming conventions and file structure.</span></p>\r\n<span style=\"font-weight: 400;\">Typically, good data documentation includes information about the study, data-level descriptions, and any other contextual information required to make the data usable by other researchers. Other elements you should document, as applicable, include: research methodology used, variable definitions, vocabularies, classification systems, units of measurement, assumptions made, format and file type of the data, a description of the data capture and collection methods, explanation of data coding and analysis performed (including syntax files). View a useful template from Cornell University&rsquo;s </span><a href=\"https://data.research.cornell.edu/content/readme\"><span style=\"font-weight: 400;\">&ldquo;Guide to writing &lsquo;ReadMe&rsquo; style metadata&rdquo;</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"187f3a43-5898-4c79-8bad-d96b780ac81a"})
Question.create({"id"=>76424, "text"=>"How will you undertake documentation of data collection, processing and analysis, within your workflow to create consistent support material? Who will be responsible for this task?", "default_value"=>nil, "number"=>2, "section_id"=>24792, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4e2a6a99-cd3e-4fc2-b6d0-4954312a7cac"})
Annotation.create({"id"=>72486, "question_id"=>76424, "org_id"=>8, "text"=>"<p><strong>Assign responsibilities for documentation:&nbsp;</strong><span style=\"font-weight: 400;\">Individual roles and workflows should include gathering data documentation as a key element.</span></p>\r\n<p><span style=\"font-weight: 400;\">Establishing responsibilities for data management and documentation is useful if you do it early on,&nbsp; ideally in advance of data collection and analysis, Some researchers use </span><a href=\"https://casrai.org/credit/\"><span style=\"font-weight: 400;\">CRediT taxonomy</span></a><span style=\"font-weight: 400;\"> to determine authorship roles at the beginning of each project. They can also be used to make team members responsible for proper data management and documentation.</span></p>\r\n<p><span style=\"font-weight: 400;\">Consider how you will capture this information and where it will be recorded, to ensure accuracy, consistency, and completeness of the documentation.</span></p>", "type"=>"guidance", "versionable_id"=>"9b51a4f3-1d0e-4099-87e3-d2170827ec09"})
Question.create({"id"=>76425, "text"=>"Do you plan to use a metadata standard? What specific schema might you use?", "default_value"=>nil, "number"=>3, "section_id"=>24792, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"27eb1a30-f4cc-49cc-8034-f1468e8b456d"})
Annotation.create({"id"=>72487, "question_id"=>76425, "org_id"=>8, "text"=>"<p><strong>Metadata for datasets:&nbsp;</strong><span style=\"font-weight: 400;\">DataCite has developed a </span><a href=\"https://schema.datacite.org/meta/kernel-4.3/\"><span style=\"font-weight: 400;\">metadata schema</span></a><span style=\"font-weight: 400;\"> specifically for open datasets. It lists a set of core metadata fields and instructions to make datasets easily identifiable and citable.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">There are many other general and domain-specific metadata standards.&nbsp; Dataset documentation should be provided in one of these standard, machine readable, openly-accessible formats to enable the effective exchange of information between users and systems.&nbsp; These standards are often based on language-independent data formats such as XML, RDF, and JSON. There are many metadata standards based on these formats, including discipline-specific standards. Read more about metadata standards at the </span><a href=\"http://www.dcc.ac.uk/resources/metadata-standards\"><span style=\"font-weight: 400;\">UK Digital Curation Centre's Disciplinary Metadata</span></a><span style=\"font-weight: 400;\"> resource.</span>", "type"=>"guidance", "versionable_id"=>"9d136659-7778-4399-a35e-2060093a21d2"})
Question.create({"id"=>76426, "text"=>"How will you make sure that a) your primary data collection methods are documented with transparency and b) your secondary data sources (i.e., data you did not collect yourself) &mdash; are easily identified and cited?", "default_value"=>nil, "number"=>4, "section_id"=>24792, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"27f81bb9-83f0-4dd7-8892-55a9116411aa"})
Annotation.create({"id"=>72488, "question_id"=>76426, "org_id"=>8, "text"=>"<p><strong>Document your process:&nbsp;</strong><span style=\"font-weight: 400;\">It is useful to consult regularly with members of the research team to capture potential changes in data collection/processing that need to be reflected in the documentation.</span></p>", "type"=>"guidance", "versionable_id"=>"7a05ca96-27ff-47f0-80c9-125b49dc3331"})
Section.create({"id"=>24793, "title"=>"Storage and Backup", "description"=>nil, "number"=>4, "phase_id"=>3931, "modifiable"=>true, "versionable_id"=>"3d0731ee-491c-4b86-aa44-e517a5b4fb5d"})
Question.create({"id"=>76427, "text"=>"List your anticipated storage needs (e.g., hard drives, cloud storage, shared drives). List how long you intend to use each type and what capacities you may require.", "default_value"=>nil, "number"=>1, "section_id"=>24793, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"decb0dcb-e39f-4078-a969-3800219054bb"})
Annotation.create({"id"=>72489, "question_id"=>76427, "org_id"=>8, "text"=>"<p><strong>Estimating data storage needs:&nbsp;</strong><span style=\"font-weight: 400;\">Storage-space estimates should take into account requirements for file versioning, backups, and growth over time.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">If you are collecting data over a long period (e.g. several months or years), your data storage and backup strategy should accommodate data growth. Include your back-up storage media in your estimate. </span></p>", "type"=>"guidance", "versionable_id"=>"af08ba96-f6cb-40cf-9147-48eaf75fafc6"})
Question.create({"id"=>76428, "text"=>"What is your anticipated backup and storage schedule? How often will you save your data, in what formats, and where?", "default_value"=>nil, "number"=>2, "section_id"=>24793, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0f0ae47e-ec8d-45a6-bf7f-ec290f386490"})
Annotation.create({"id"=>72490, "question_id"=>76428, "org_id"=>8, "text"=>"<p><strong>Follow the 3-2-1 rule to prevent data loss: </strong><span>It&rsquo;s important to have a regular backup schedule &mdash; and to document that process &mdash; so that you can review any changes to the data at any point during the project. The risk of losing data due to human error, natural disasters, or other mishaps can be mitigated by following the 3-2-1 backup rule: Have at least three copies of your data; store the copies on two different media; keep one backup copy offsite. Read more about storage and backup practices&nbsp; from the </span><a href=\"https://www.sheffield.ac.uk/library/rdm/storage\"><span>University of Sheffield Library</span></a><span> and the </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\"><span>UK Data Service</span></a><span>.</span></p>", "type"=>"guidance", "versionable_id"=>"4ec04d95-17c8-4b50-908b-f9a9b43cd779"})
Question.create({"id"=>76429, "text"=>"Keeping ethics protocol review requirements in mind, what is your intended storage timeframe for each type of data (raw, processed, clean, final) within your team? Will you also store software code or metadata?", "default_value"=>nil, "number"=>3, "section_id"=>24793, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f8280b19-9bb9-4b57-833f-510956c12708"})
Annotation.create({"id"=>72491, "question_id"=>76429, "org_id"=>8, "text"=>"<p><strong>Ask for help:&nbsp;</strong><span style=\"font-weight: 400;\">Your institution should be able to provide guidance with local storage solutions. Seek out RDM support at your Library or your Advanced Research Computing department.</span><strong>&nbsp;</strong></p>\r\n<p><span style=\"font-weight: 400;\">Third-party commercial file sharing services (such as Google Drive and Dropbox) facilitate file exchange, but they are not necessarily permanent or secure, and servers are often located outside Canada. This may contravene ethics protocol requirements or other institutional policies.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">An ideal solution is one that facilitates cooperation and ensures data security, yet is able to be adopted by users with minimal training. Transmitting data between locations or within research teams can be challenging for data management infrastructure. Relying on email for data transfer is not a robust or secure solution.</span></p>\r\n<ul>\r\n<li><strong>Raw data</strong><span style=\"font-weight: 400;\"> are directly obtained from the instrument, simulation or survey.&nbsp;</span></li>\r\n<li><strong>Processed data</strong><span style=\"font-weight: 400;\"> result from some manipulation of the raw data in order to eliminate errors or outliers, to prepare the data for analysis, to derive new variables, or to de-identify the human participants.&nbsp;</span></li>\r\n<li><strong>Analyzed data</strong><span style=\"font-weight: 400;\"> are the results of qualitative, statistical, or mathematical analysis of the processed data. They can be presented as graphs, charts or statistical tables.&nbsp;</span></li>\r\n<li><strong>Final data</strong><span style=\"font-weight: 400;\"> are processed data that have, if needed, been converted into a preservation-friendly format.&nbsp;</span></li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"8b84516b-8918-4223-be51-7781ed722de6"})
Section.create({"id"=>24794, "title"=>"Sharing, Reuse, and Preservation", "description"=>nil, "number"=>5, "phase_id"=>3931, "modifiable"=>true, "versionable_id"=>"6abbdb64-4d85-4c87-a052-d31966cfc1da"})
Question.create({"id"=>76430, "text"=>"How will your data (both raw and cleaned) be made accessible beyond the scope of the project and by researchers outside your team?", "default_value"=>nil, "number"=>1, "section_id"=>24794, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a67381bd-a9cf-49aa-91db-2e82e7efda39"})
Annotation.create({"id"=>72492, "question_id"=>76430, "org_id"=>8, "text"=>"<p><strong>Help others reuse and cite your data:&nbsp;</strong><span style=\"font-weight: 400;\">Did you know that a dataset is a scholarly output that you can list on your CV, just like a journal article?&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">If you publish your data in a data repository (e.g., Zenodo, Dataverse, Dryad), it can be found and reused by others. Many repositories can issue unique Digital Object Identifiers (DOIs) which make it easier to identify and cite datasets.&nbsp;</span></p>\r\n<a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">re3data.org</span></a><span style=\"font-weight: 400;\"> is a directory of potential open data repositories. Consult with your colleagues to determine what repositories are common for data sharing in your field. You can also enquire about RDM support at your local institution, often in the Library or Advanced Research Computing. In the absence of local support, consult this</span> <a href=\"https://doi.org/10.5281/zenodo.3966349\"><span style=\"font-weight: 400;\">Portage repository options guide.</span></a>", "type"=>"guidance", "versionable_id"=>"4ad27a34-0c8b-4730-a447-3ba337decf31"})
Question.create({"id"=>76431, "text"=>"<span style=\"font-weight: 400;\">Is digital preservation a component of your project and do you need to plan for long-term archiving and preservation?</span>", "default_value"=>nil, "number"=>2, "section_id"=>24794, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"89ad4361-c4c5-48cd-bd57-99db52899d9d"})
Annotation.create({"id"=>72493, "question_id"=>76431, "org_id"=>8, "text"=>"<p><strong>How long should you keep your data? </strong><span style=\"font-weight: 400;\">The length of time that you will keep or share your data beyond the active phase of your research can be determined by external policies (e.g. funding agencies, journal publishers), or by an understanding of the enduring (historical) value of a given set of data. The need to publish data in the short-term (i.e. for peer-verification purposes), for a longer-term access for reuse (to comply with funding requirements), or for preservation through ongoing file conversion and migration (for data of lasting historical value), will influence the choice of data repository or archive.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">If you need long-term archiving for your data set, choose a&nbsp; preservation-capable repository. Digital preservation can be costly and time-consuming, and not all data can or should be preserved. &nbsp; </span></p>", "type"=>"guidance", "versionable_id"=>"007b95f4-b69a-4bf2-92b9-1b612a397ba0"})
Question.create({"id"=>76432, "text"=>"<span style=\"font-weight: 400;\">What data will you be sharing publicly and in what form (e.g. raw, processed, analyzed, final)?</span>", "default_value"=>nil, "number"=>3, "section_id"=>24794, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"2f75c637-1d73-42c3-a6e4-67004e3969e1"})
Annotation.create({"id"=>72494, "question_id"=>76432, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Consider which types of data need to be shared to meet institutional or funding requirements, and which data may be restricted because of confidentiality/privacy/intellectual property considerations.</span></p>", "type"=>"guidance", "versionable_id"=>"6544d7ab-0ace-4193-b027-f8df7230f81f"})
Question.create({"id"=>76433, "text"=>"<span style=\"font-weight: 400;\">Have you considered what type of end-user license to include with your data? </span>", "default_value"=>nil, "number"=>4, "section_id"=>24794, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"8619c8be-e6c3-4840-a476-b1253b2a0bc7"})
Annotation.create({"id"=>72495, "question_id"=>76433, "org_id"=>8, "text"=>"<p><strong>Use open licenses to promote data sharing and reuse:&nbsp;</strong><span style=\"font-weight: 400;\">Licenses determine what uses can be made of your data. Consider including a copy of your end-user license with your DMP.</span><strong>&nbsp;</strong></p>\r\n<p><span style=\"font-weight: 400;\">As the creator of a dataset (or any other academic or creative work) you usually hold its copyright by default. However, copyright prevents other researchers from reusing and building on your work. </span><a href=\"https://opendatacommons.org/licenses/\"><span style=\"font-weight: 400;\">Open Data Commons licenses</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://creativecommons.org/about/cclicenses/\"><span style=\"font-weight: 400;\">Creative Commons licenses</span></a><span style=\"font-weight: 400;\"> are a free, simple and standardized way to grant copyright permissions and ensure proper attribution (i.e., citation). CC-BY is the most open license, and allows others to copy, distribute, remix and build upon your work &mdash;as long as they credit you or cite your work.</span></p>\r\n<p><span style=\"font-weight: 400;\">Even if you choose to make your data part of the public domain (with no restrictions on reuse), it is preferable to make this explicit by using a license such as </span><a href=\"https://creativecommons.org/publicdomain/zero/1.0/\"><span style=\"font-weight: 400;\">Creative Commons' CC0</span></a><span style=\"font-weight: 400;\">. It is strongly recommended to&nbsp; share your data openly using an Open Data or Creative Commons license.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">Learn more about data licensing at the </span><a href=\"http://www.dcc.ac.uk/resources/how-guides/license-research-data\"><span style=\"font-weight: 400;\">Digital Curation Centre</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"9a2e4242-63b6-491f-a3e1-9ebefe008b12"})
Question.create({"id"=>76434, "text"=>"What tools and strategies will you take to promote your research? How will you let the research community and the public know that your data exists and is ready to be reused?", "default_value"=>nil, "number"=>5, "section_id"=>24794, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e48161b9-d263-4e61-a945-600df814d862"})
Annotation.create({"id"=>72496, "question_id"=>76434, "org_id"=>8, "text"=>"<p><strong>Data sharing as knowledge mobilization:&nbsp;</strong><span style=\"font-weight: 400;\">Using social media, e-newsletters, bulletin boards, posters, talks, webinars, discussion boards or discipline-specific forums are good ways to gain visibility, promote transparency and encourage data discovery and reuse.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">One of the best ways to refer other researchers to your deposited datasets is to cite them the same way you cite other types of publications. Publish your data in a repository that will assign a persistent identifier (such as a DOI) to your dataset. This will ensure a stable access to the dataset and make it retrievable by various discovery tools. Some repositories also create links from datasets to their associated papers, increasing the visibility of the publications. </span></p>", "type"=>"guidance", "versionable_id"=>"c7f39a7c-4029-4d82-b80a-06bd074d3e7c"})
Section.create({"id"=>24795, "title"=>"Ethics and Legal Compliance", "description"=>nil, "number"=>6, "phase_id"=>3931, "modifiable"=>true, "versionable_id"=>"278c3695-21ad-434e-b1fb-922da1c5959f"})
Question.create({"id"=>76435, "text"=>"<p>Are there institutional, governmental or legal policies that you need to comply with in regards to your data standards?</p>", "default_value"=>nil, "number"=>1, "section_id"=>24795, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"312c8b7c-0251-4d16-af9b-d0400d78143b"})
Annotation.create({"id"=>72497, "question_id"=>76435, "org_id"=>8, "text"=>"<p><strong>Determine jurisdiction: </strong><span style=\"font-weight: 400;\">If your study is cross-institutional or international, you&rsquo;ll need to determine which laws and policies will apply to your research.</span></p>\r\n<p><span style=\"font-weight: 400;\">Compliance with privacy legislation and laws that may impose content restrictions in the data should be discussed with your institution's privacy officer or research services office.</span></p>\r\n<p><span style=\"font-weight: 400;\">If you collaborate with a partner in the European Union, for example,&nbsp; you might need to follow the </span><a href=\"https://en.wikipedia.org/wiki/General_Data_Protection_Regulation\"><span style=\"font-weight: 400;\">General Data Protection Regulation (GDPR)</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">If you are working with data that has First Nations, M&eacute;tis, or Inuit ownership, for example, you will need to work with protocols that ensure community privacy is respected and community harm is reduced. For further guidance on Indigenous data sovereignty, see </span><a href=\"https://fnigc.ca/ocap-training/\"><span style=\"font-weight: 400;\">OCAP Principles</span></a><span style=\"font-weight: 400;\">, and in a global&nbsp; context, </span><a href=\"https://www.gida-global.org/care\"><span style=\"font-weight: 400;\">CARE Principles of Indigenous Data Governance</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>"cf964f60-e118-45de-bcd8-1d6c5e0848c3"})
Question.create({"id"=>76436, "text"=>"Will you encounter protected or personally-identifiable information in your research? If so, how will you make sure it stays secure and is accessed by approved team members only?", "default_value"=>nil, "number"=>2, "section_id"=>24795, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d853d0f4-fa52-4820-89c0-e98a8af65d69"})
Annotation.create({"id"=>72498, "question_id"=>76436, "org_id"=>8, "text"=>"<p><strong>Get informed consent before you collect data:&nbsp;</strong><span style=\"font-weight: 400;\">Obtaining the appropriate consent from research participants is an important step in assuring Research Ethics Boards that the data may be shared with researchers outside your project. Your informed consent statement may identify certain conditions clarifying the uses of the data by other researchers. For example, your statement may stipulate that the data will either only be shared for non-profit research purposes (you can use CC-by-NC &mdash; the non-commercial Creative Commons licence with attribution) or that the data will not be linked with other personally-identifying data. Note that this aspect is not covered by an open license. You can learn more about data security at the </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">Inform your study participants if you intend to publish an anonymized and de-identified version of collected data, and that by participating, they agree to these terms. For sample language for informed consent: </span><a href=\"https://www.icpsr.umich.edu/web/pages/datamanagement/confidentiality/conf-language.html\"><span style=\"font-weight: 400;\">ICPSR Recommended Informed Consent Language for Data Sharing</span></a>.</p>\r\n<p><span style=\"font-weight: 400;\">You may need to consider strategies to ensure the ethical reuse of your published dataset by new researchers. These strategies may affect your selection of a suitable license, and in some cases you may not be able to use an open license.</span></p>", "type"=>"guidance", "versionable_id"=>"22256257-2b6a-4f7a-8e36-b7ca94259be1"})
Question.create({"id"=>76437, "text"=>"<span style=\"font-weight: 400;\">Before publishing or otherwise sharing a dataset are you required to obscure identifiable data (name, gender, date of birth, etc), in accordance with your jurisdiction's laws, or your ethics protocol? Are there any time restrictions for when data can be publicly accessible?</span>", "default_value"=>nil, "number"=>3, "section_id"=>24795, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"6c519e0c-e338-4edc-bb2c-0363a086e4ff"})
Annotation.create({"id"=>72499, "question_id"=>76437, "org_id"=>8, "text"=>"<p><strong>Privacy protection:&nbsp;</strong><span style=\"font-weight: 400;\">Open science workflows prioritize being &ldquo;as open as possible and as closed as necessary.&rdquo; Think about any privacy concerns you may have in regards to your data, or other restrictions on access outlined in your ethics protocol. If your institution or funder regulates legal or ethical guidelines on what information must be protected, take a moment to verify you have complied with the terms for consent of sharing data. In the absence of local support for anonymization or de-identification of data, you can reach out to the Portage DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a>. </span><span style=\"font-weight: 400;\">&nbsp;</span></p>", "type"=>"guidance", "versionable_id"=>"f0fb40be-45b6-42b6-b2b6-8dd8c63d7c91"})
Template.create!({"id"=>3870, "title"=>"Alliance Template for Advanced Research Computing", "description"=>"<p><span style=\"font-weight: 400;\">ARC provides researchers with digital technology, infrastructure and expertise to help them solve research problems that are either too large or too complex to undertake by other means. It includes access to both computational and storage resources, such as multi-core and many-core high performance computing (HPC or supercomputers) systems, distributed high-throughput computing (HTC) environments, large-scale data analysis frameworks</span> <span style=\"font-weight: 400;\">(e.g., Hadoop, Spark), visualization and data analysis systems, large-memory systems, data storage, and cloud systems. This template is intended for researchers whose research cannot be conducted on a traditional computer but has to rely on one or more of the advanced research computing resources mentioned above. ARC-based research occurs in a wide range of fields including genomics, molecular dynamics, bioinformatics, neuroscience, biochemistry, quantum chemistry, structural mechanics, astrophysics, energy economics, climate change, machine learning, artificial intelligence, and the humanities.</span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>1, "visibility"=>1, "customization_of"=>nil, "family_id"=>272694087, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3924, "title"=>"Phase 1: Data Preparation", "description"=>nil, "number"=>1, "template_id"=>3870, "modifiable"=>true, "versionable_id"=>"05d7f955-8c04-4752-9fae-2293a77b7c88"})
Section.create({"id"=>24762, "title"=>"Data Collection", "description"=>nil, "number"=>1, "phase_id"=>3924, "modifiable"=>true, "versionable_id"=>"7594e254-89ad-4979-9dbd-bf7ec5518071"})
Question.create({"id"=>76330, "text"=>"What types of data, metadata, and scripts will you collect, create, link to, acquire, record, or generate through the proposed research project?", "default_value"=>nil, "number"=>1, "section_id"=>24762, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7f924875-2ec4-446f-ae09-fb22e84fe6ec"})
Annotation.create({"id"=>72379, "question_id"=>76330, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Examples of data types may include text, numeric (ASCII, binary), images, audio, video, tabular data, spatial data, experimental, observational, and simulation/modelling data, instrumentation data, codes, software and algorithms, and any other materials that may be produced in the course of the project.</span>", "type"=>"guidance", "versionable_id"=>"f45abfc0-3ed4-4e31-a50c-b34471711131"})
Section.create({"id"=>24763, "title"=>"Data Organization", "description"=>nil, "number"=>2, "phase_id"=>3924, "modifiable"=>true, "versionable_id"=>"56b7719e-3212-453b-a239-f93d4f87f719"})
Question.create({"id"=>76331, "text"=>"In what file formats will your data be collected and generated? Will these formats allow for data re-use, sharing and long-term access to the data?", "default_value"=>nil, "number"=>1, "section_id"=>24763, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0b6a1acd-9b59-4be9-bd67-21ef3ed75b20"})
Annotation.create({"id"=>72380, "question_id"=>76331, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Proprietary file formats that require specialized software or hardware are not recommended, but may be necessary for certain data collection or analysis methods. Using open file formats or industry-standard formats (e.g. those widely used by a given community) is preferred whenever possible. Read more about recommended file formats at </span><a href=\"https://researchdata.library.ubc.ca/plan/format-your-data/\"><span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"8a82b957-87bd-4578-a455-c21ca626c034"})
Question.create({"id"=>76332, "text"=>"What conventions and procedures will you use to structure, name and version-control your files to help you and others better understand how your data are organized?", "default_value"=>nil, "number"=>2, "section_id"=>24763, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0f7a0bbf-837e-4928-8a0f-0ac53046f702"})
Annotation.create({"id"=>72381, "question_id"=>76332, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">It is important to keep track of different copies and versions of files, files held in different formats or locations, and any information cross-referenced between files.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">Logical file structures, informative naming conventions, and clear indications of file versions all contribute to better use of your data during and after your research project. These practices will help ensure that you and your research team are using the appropriate version of your data, and will minimize confusion regarding copies on different computers, on different media, in different formats, and/or in different locations. Read more about file naming and version control at </span><a href=\"https://researchdata.library.ubc.ca/plan/organize-your-data/\"><span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/organising.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"07440541-24d0-44fb-8290-6a1463f090bc"})
Phase.create({"id"=>3925, "title"=>"Phase 2: Active Research (Data) Management", "description"=>nil, "number"=>2, "template_id"=>3870, "modifiable"=>true, "versionable_id"=>"4b54c857-03ae-486b-884b-1c90a2b4e4bc"})
Section.create({"id"=>24764, "title"=>"Documentation and Metadata", "description"=>nil, "number"=>1, "phase_id"=>3925, "modifiable"=>true, "versionable_id"=>"908fa18f-c99e-4fac-b256-06cfa0f2affe"})
Question.create({"id"=>76333, "text"=>"What information will be needed for the data to be read and interpreted correctly?", "default_value"=>nil, "number"=>1, "section_id"=>24764, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c5e1f309-2af4-4d6e-8fb1-3391580cc6cc"})
Annotation.create({"id"=>72382, "question_id"=>76333, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Some types of documentation typically provided for research data and software include:&nbsp;</span></p>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">README file, codebook, or data dictionary</span></li>\r\n<li><span style=\"font-weight: 400;\">Electronic lab notebooks such as </span><a href=\"https://jupyter.org/\"><span style=\"font-weight: 400;\">Jupyter Notebook</span></a></li>\r\n</ul>", "type"=>"example_answer", "versionable_id"=>"b0466155-dfc1-4eba-b2b6-0e8292404c50"})
Annotation.create({"id"=>72383, "question_id"=>76333, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Typically, good documentation includes high-level information about the study as well as data-level descriptions of the content. It may also include other contextual information required to make the data usable by other researchers, such as: your research methodology, definitions of variables, vocabularies, classification systems, units of measurement, assumptions made, formats and file types of the data, a description of the data capture and collection methods, provenance of various data sources (original source of data, and how the data have been transformed), explanation of data analysis performed (including syntax files), the associated script(s), and annotation of relevant software. </span>", "type"=>"guidance", "versionable_id"=>"69f57e05-3a55-4cf4-8ece-d6776be76a2b"})
Question.create({"id"=>76334, "text"=>"If you are using a metadata standard and/or tools to document and describe your data, please list them here. Explain the rationale for the selection of these standards.", "default_value"=>nil, "number"=>2, "section_id"=>24764, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"26198ef9-51d1-4997-a544-0eee6772d87c"})
Annotation.create({"id"=>72385, "question_id"=>76334, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">There are a wide variety of metadata standards available to choose from, and you can learn more about these options at </span><a href=\"http://www.dcc.ac.uk/resources/metadata-standards\"><span style=\"font-weight: 400;\">UK Digital Curation Centre's Disciplinary Metadata</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://fairsharing.org/standards/\"><span style=\"font-weight: 400;\">FAIRsharing standards</span></a><span style=\"font-weight: 400;\">, </span><a href=\"http://rd-alliance.github.io/metadata-directory/\"><span style=\"font-weight: 400;\">RDA Metadata Standards Directory</span></a><span style=\"font-weight: 400;\">, </span><a href=\"http://jennriley.com/metadatamap/\"><span style=\"font-weight: 400;\">Seeing Standards: A Visualization of the Metadata Universe</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"example_answer", "versionable_id"=>"536f9938-a2ba-46ef-bfb8-89bff810fc19"})
Annotation.create({"id"=>72384, "question_id"=>76334, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">There are many general and domain-specific metadata standards that can be used to manage research data. These machine-readable, openly-accessible standards are often based on language-independent data formats such as XML, RDF, and JSON, which enables the effective exchange of information between users and systems. Existing, accepted community standards should be used wherever possible, including when recording intermediate results.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Where community standards are absent or inadequate, this should be documented along with any proposed solutions or remedies. You may wish to use this DMP Template to propose alternate strategies that will facilitate metadata interoperability in your field. </span></p>", "type"=>"guidance", "versionable_id"=>"c78b846a-d81f-46cf-af87-3904970db920"})
Question.create({"id"=>76335, "text"=>"How will you make sure that documentation is created or captured consistently throughout your project?", "default_value"=>nil, "number"=>3, "section_id"=>24764, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"26ec06e9-b953-4c25-a70e-b5c52acb9b31"})
Annotation.create({"id"=>72386, "question_id"=>76335, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Consider how you will capture information during the project and where it will be recorded to ensure the accuracy, consistency, and completeness of your documentation. Often, resources you've already created can contribute to this (e.g. publications, websites, progress reports, etc.). It is useful to consult regularly with members of the research team to capture potential changes in data collection or processing that need to be reflected in the documentation. Individual roles and workflows should include gathering, creating or maintaining data documentation as a key element.</span>", "type"=>"guidance", "versionable_id"=>"0fbb9f62-e31f-4e66-b12d-230ccbdb250a"})
Section.create({"id"=>24765, "title"=>"Advanced Research Computing (ARC)-Related Facilities and Other Resources", "description"=>nil, "number"=>2, "phase_id"=>3925, "modifiable"=>true, "versionable_id"=>"0c468ef8-3821-4f67-9342-13cc0cd70009"})
Question.create({"id"=>76336, "text"=>"Please identify the facilities to be used (laboratory, computer, office, clinical and other) and/or list the organizational resources available to perform the proposed research. If appropriate, indicate the capacity, pertinent capabilities, relative proximity and extent of availability of the resources to the research project.", "default_value"=>nil, "number"=>1, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"258a0679-f9b8-445a-9c18-d4d6887e5b03"})
Annotation.create({"id"=>72387, "question_id"=>76336, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">ARC resources usually contain both computational resources and data storage resources. Please describe only those ARC resources that are directly applicable to the proposed work. Include existing resources and any external resources that may be made available.</span>", "type"=>"guidance", "versionable_id"=>"bdd3982c-08b8-4828-a627-27409724ba55"})
Question.create({"id"=>76337, "text"=>"What will be the primary production computing platform(s) (e.g., compute clusters, virtual clusters)?", "default_value"=>nil, "number"=>2, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"971c8c4f-e2bb-4eda-bc38-70c7f5240d79"})
Question.create({"id"=>76338, "text"=>"What are the technical details of each of the computational resources?", "default_value"=>nil, "number"=>3, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5e95cec3-07a1-4785-a061-514729e09faf"})
Annotation.create({"id"=>72388, "question_id"=>76338, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">You may wish to provide the following information:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Startup allocation limit</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">System architecture: System component and configuration</span></li>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">CPU nodes</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">GPU nodes</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Large memory nodes</span></li>\r\n</ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Performance: e.g., FLOPs, benchmark</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Associated systems software environment</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Supported application software&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Data transfer</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Storage </span></li>\r\n</ul>", "type"=>"example_answer", "versionable_id"=>"d1d84573-be40-4ee8-9b4b-db3fc72cf1e2"})
Annotation.create({"id"=>72389, "question_id"=>76338, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">It is important to document the</span> <span style=\"font-weight: 400;\">technical details of all the computational and data storage resources, and</span> <span style=\"font-weight: 400;\">associated systems and software environments you plan to use to perform the simulations and analysis proposed in this research project. </span>", "type"=>"guidance", "versionable_id"=>"e1d0b69e-1bc0-4252-a16b-278a3c9508fb"})
Question.create({"id"=>76339, "text"=>"What large-scale data analysis framework (and associated technical specifications) will be used?", "default_value"=>nil, "number"=>4, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"b5e5797c-bcab-4cef-be4a-a42fce921a13"})
Annotation.create({"id"=>72390, "question_id"=>76339, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Examples of data analysis frameworks include:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Hadoop</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Spark</span></li>\r\n</ul>", "type"=>"example_answer", "versionable_id"=>"d16c2362-b42f-4d29-8526-e748978f5b08"})
Question.create({"id"=>76340, "text"=>"What software tools will be utilized and/or developed for the proposed research?", "default_value"=>nil, "number"=>5, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f672c7d4-0697-4db6-8d7e-d6643e3c3e74"})
Annotation.create({"id"=>72391, "question_id"=>76340, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Examples of software tools include:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">High-performance compilers, debuggers, analyzers, editors&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Locally developed custom libraries and application packages for software development</span></li>\r\n</ul>", "type"=>"example_answer", "versionable_id"=>"6d50ebc2-9398-4f94-bb76-5cf836cd4073"})
Question.create({"id"=>76341, "text"=>"What metadata/documentation do you need to provide for others to use your software?", "default_value"=>nil, "number"=>6, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d642820f-cc6b-40c8-a43b-b25f3e856033"})
Annotation.create({"id"=>72392, "question_id"=>76341, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">(Re)using code/software requires, at minimum, information about both the environment and expected input/output. Log all parameter values, including when setting random seeds to predetermined values, and make note of the requirements of the computational environment (software dependencies, etc.) Track your software development with versioning control systems, such as </span><a href=\"https://github.com/\"><span style=\"font-weight: 400;\">GitHub</span></a> <a href=\"https://bitbucket.org/product\"><span style=\"font-weight: 400;\">Bitbucket</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://about.gitlab.com/\"><span style=\"font-weight: 400;\">GitLab</span></a><span style=\"font-weight: 400;\">, etc.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">If your research and/or software are built upon others&rsquo; software code, it is good practice to acknowledge and cite the software you use in the same fashion as you cite papers to both identify the software and to give credit to its developers.</span></p>\r\n<span style=\"font-weight: 400;\">For more information on proper software documentation and citation practices, see: </span><a href=\"https://journals.plos.org/ploscompbiol/article?id=10.1371/journal.pcbi.1006561\"><span style=\"font-weight: 400;\">Ten simple rules for documenting scientific software</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://peerj.com/articles/cs-86/\"><span style=\"font-weight: 400;\">Software Citation Principles</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"00306a03-462d-48f9-b20c-dd659475cbbd"})
Question.create({"id"=>76342, "text"=>"What are the anticipated storage requirements for your project, in terms of storage space (in megabytes, gigabytes, terabytes, etc.) and the length of time you will be storing it?", "default_value"=>nil, "number"=>7, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a31e6028-e95d-4c23-8081-785d2d729fab"})
Annotation.create({"id"=>72393, "question_id"=>76342, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Storage-space estimates should take into account requirements for file versioning, backups, and growth over time, particularly if you are collecting data over a long period (e.g. several months or years). Similarly, a long-term storage plan is necessary if you intend to retain your data after the research project.</span></p>", "type"=>"guidance", "versionable_id"=>"67c3d47e-4e02-431f-9ebf-8ba2898aa952"})
Question.create({"id"=>76343, "text"=>"How and where will your data be stored and backed up during your research project?", "default_value"=>nil, "number"=>8, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"446e5b3c-3d06-4785-90b0-ee59e68ca041"})
Annotation.create({"id"=>72394, "question_id"=>76343, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Data may be stored using optical or magnetic media, which can be removable (e.g. DVD and USB drives), fixed (e.g. desktop or laptop hard drives), or networked (e.g. networked drives or cloud-based servers). Each storage method has benefits and drawbacks that should be considered when determining the most appropriate solution.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">The risk of losing data due to human error, natural disasters, or other mishaps can be mitigated by following the 3-2-1 backup rule: Have at least three copies of your data; store the copies on two different media; keep one backup copy offsite.</span></p>\r\n<span style=\"font-weight: 400;\">Further information on storage and backup practices is available from the </span><a href=\"https://www.sheffield.ac.uk/library/rdm/storage\"><span style=\"font-weight: 400;\">University of Sheffield Library</span></a><span style=\"font-weight: 400;\"> and the </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"1424af2a-e765-40d2-a24d-0b315b9b7bf5"})
Question.create({"id"=>76344, "text"=>"What are the technical details of each of the storage and file systems you will use during the active management of the research project?", "default_value"=>nil, "number"=>9, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"179bd35d-dc94-4d96-835e-c687068094e6"})
Annotation.create({"id"=>72395, "question_id"=>76344, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Technical detail example:</span></p>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Quota&nbsp;</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Examples of systems:</span></p>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">High-performance archival/storage storage&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Database</span></li>\r\n<li><span style=\"font-weight: 400;\">Web server</span></li>\r\n<li><span style=\"font-weight: 400;\">Data transfer</span></li>\r\n<li><span style=\"font-weight: 400;\">Cloud platforms, such as Amazon Web Services, Microsoft Azure, Open Science Framework (OSF), Dropbox, Box, Google Drive, One Drive</span></li>\r\n</ul>", "type"=>"example_answer", "versionable_id"=>"0a86bd51-436f-4527-9cda-9a854a8ace80"})
Question.create({"id"=>76345, "text"=>"How will the research team and other collaborators access, modify, and contribute data throughout the project?", "default_value"=>nil, "number"=>10, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"85fe1899-cef4-4db5-ab53-af78451b539d"})
Annotation.create({"id"=>72396, "question_id"=>76345, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">An ideal solution is one that facilitates cooperation and ensures data security, yet is able to be adopted by users with minimal training. Transmitting data between locations or within research teams can be challenging for data management infrastructure. Relying on email for data transfer is not a robust or secure solution.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Third-party commercial file sharing services (such as Google Drive and Dropbox) facilitate file exchange, but they are not necessarily permanent or secure, and the servers are often located outside Canada.</span></p>", "type"=>"guidance", "versionable_id"=>"4ae0c0f8-5ca3-466d-b6b1-da69fc39686c"})
Question.create({"id"=>76346, "text"=>"What do you estimate the overall cost of managing your data will be?", "default_value"=>nil, "number"=>11, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7d206efc-64af-4d1d-9964-e066f9645370"})
Annotation.create({"id"=>72397, "question_id"=>76346, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">This estimate should incorporate data management costs incurred during the project as well as those required for ongoing support after the project is finished. Consider costs associated with data purchase, data curation, and providing long-term access to the data. For ARC projects, charges for computing time, also called Service Units (SU), and the cost of specialized or proprietary software should also be taken into consideration.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">Some funding agencies state explicitly that they will provide support to meet the cost of preparing data for deposit in a repository. These costs could include: technical aspects of data management, training requirements, file storage &amp; backup, etc. OpenAIRE has a useful tool for </span><a href=\"https://www.openaire.eu/estimating-costs-rdm-tool\"><span style=\"font-weight: 400;\">Estimating costs for RDM</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"8e50335a-e225-4768-9dac-eaff431ef4f7"})
Question.create({"id"=>76347, "text"=>"Identify who will be responsible for managing this project's data during and after the project and the major data management tasks for which they will be responsible.", "default_value"=>nil, "number"=>12, "section_id"=>24765, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"bed1096a-72d7-491c-8808-4f8fae1caa5b"})
Annotation.create({"id"=>72398, "question_id"=>76347, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Your data management plan has identified important data activities in your project. Identify who will be responsible -- individuals or organizations -- for carrying out these parts of your data management plan. This could also include the time frame associated with these staff responsibilities and any training needed to prepare staff for these duties.</span>", "type"=>"guidance", "versionable_id"=>"628f3f90-92bf-4c43-b183-2a5903f35c80"})
Section.create({"id"=>24766, "title"=>"Ensure Portability and Reproducibility of Results", "description"=>nil, "number"=>3, "phase_id"=>3925, "modifiable"=>true, "versionable_id"=>"ecf6fe55-7816-429f-8e05-e27f6a20424f"})
Question.create({"id"=>76348, "text"=>"What will you do to ensure portability and reproducibility of your results?", "default_value"=>nil, "number"=>1, "section_id"=>24766, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"99de61ca-315e-4bd4-818c-a1bd3beaabb4"})
Annotation.create({"id"=>72399, "question_id"=>76348, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Container solutions, such as </span><a href=\"https://www.docker.com/get-started\"><span style=\"font-weight: 400;\">docker</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://sylabs.io/singularity/\"><span style=\"font-weight: 400;\">singularity</span></a><span style=\"font-weight: 400;\">, can replicate the exact computational environment for others to run. For more information, these </span><a href=\"https://osf.io/fsd7t/\"><span style=\"font-weight: 400;\">Ten Simple Rules for Writing Dockerfiles for Reproducible Data Science</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://journals.plos.org/ploscompbiol/article?id=10.1371/journal.pcbi.1003285\"><span style=\"font-weight: 400;\">Ten Simple Rules for Reproducible Computational Research</span></a><span style=\"font-weight: 400;\"> may be helpful.</span>", "type"=>"example_answer", "versionable_id"=>"df82b46f-c99b-46c3-a6cb-7ee03fce97dc"})
Annotation.create({"id"=>72400, "question_id"=>76348, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">A computationally reproducible research package will include:</span></p>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Primary data (and documentation) collected and used in analysis</span></li>\r\n<li><span style=\"font-weight: 400;\">Secondary data (and documentation) collected and used in analysis</span></li>\r\n<li><span style=\"font-weight: 400;\">Primary data output result(s) (and documentation) produced by analysis</span></li>\r\n<li><span style=\"font-weight: 400;\">Secondary data output result(s) (and documentation) produced by analysis</span></li>\r\n<li><span style=\"font-weight: 400;\">Software program(s) (and documentation) for computing published results</span></li>\r\n<li><span style=\"font-weight: 400;\">Dependencies for software program(s) for replicating published results</span></li>\r\n<li><span style=\"font-weight: 400;\">Research Software documentation and implementation details</span></li>\r\n<li><span style=\"font-weight: 400;\">Computational research workflow and provenance information</span></li>\r\n<li><span style=\"font-weight: 400;\">Published article(s)&nbsp;</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">All information above should be accessible to both designated users and reusers.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">(Re)using code/software requires knowledge of two main aspects at minimum: environment and expected input/output. With sufficient information provided, computational results can be reproduced. Sometimes, a minimum working example will be helpful.</span></p>", "type"=>"guidance", "versionable_id"=>"595d0a2c-1922-4d27-ae9d-b20bcb2954de"})
Phase.create({"id"=>3926, "title"=>"Phase 3: Data Protection", "description"=>nil, "number"=>3, "template_id"=>3870, "modifiable"=>true, "versionable_id"=>"3c4e5a7f-a13a-44e4-986d-0e61f4748e07"})
Section.create({"id"=>24767, "title"=>"Ethics and Legal Compliance", "description"=>nil, "number"=>1, "phase_id"=>3926, "modifiable"=>true, "versionable_id"=>"c58f9a84-9387-4afb-9980-51a22e0235f9"})
Question.create({"id"=>76349, "text"=>"Will your proposed research include any sensitive, private, confidential, or other legally protected information or data?", "default_value"=>nil, "number"=>1, "section_id"=>24767, "question_format_id"=>3, "option_comment_display"=>false, "modifiable"=>true, "versionable_id"=>"1e1ec8b9-b18b-4809-bc59-6d9f00fbe1ec"})
QuestionOption.create({"id"=>2881, "question_id"=>76349, "text"=>"Yes", "number"=>1, "is_default"=>false, "versionable_id"=>"5fa14213-7db4-469f-981f-1ca4bdfe11da"})
QuestionOption.create({"id"=>2882, "question_id"=>76349, "text"=>"No", "number"=>2, "is_default"=>false, "versionable_id"=>"8fc9f291-991b-4dcd-8403-27e727cbb773"})
Question.create({"id"=>76350, "text"=>"If your project includes sensitive data, how will you ensure that it is securely managed and accessible only to approved members of the project?", "default_value"=>nil, "number"=>2, "section_id"=>24767, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4ebc2365-0bc7-4adc-a3d7-b9f335bdc52f"})
Annotation.create({"id"=>72401, "question_id"=>76350, "org_id"=>8, "text"=>"Consider where, how, and to whom sensitive data with acknowledged long-term value should be made available, and how long it should be archived. Decisions should align with your institutional Research Ethics Board requirements. <br /><br />Methods used to share data will be dependent on the type, size, complexity and degree of sensitivity of data. For instance, sensitive data should never be shared via email or cloud storage services such as Dropbox. Outline any problems anticipated in sharing data, along with causes and possible measures to mitigate these. Problems may include: confidentiality, lack of consent agreements, or concerns about Intellectual Property Rights, among others.", "type"=>"guidance", "versionable_id"=>"741a81c1-e27b-4967-86f2-bf6206561cd4"})
Question.create({"id"=>76351, "text"=>"If applicable, what strategies will you undertake to address secondary uses of sensitive data?", "default_value"=>nil, "number"=>3, "section_id"=>24767, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"310e841f-51db-4ff7-b012-98bc457a4262"})
Annotation.create({"id"=>72402, "question_id"=>76351, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Obtaining the appropriate consent from research participants is an important step in assuring your Research Ethics Board that data may be shared with researchers outside of your project. The consent statement may identify certain conditions clarifying the uses of the data by other researchers. For example, it may stipulate that the data will only be shared for non-profit research purposes or that the data will not be linked with personally identified data from other sources. Read more about data security: </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<span style=\"font-weight: 400;\">You may need to <a href=\"https://zenodo.org/record/4088946#.Yrnory972-ss\">anonymize or de-identify</a></span><span style=\"font-weight: 400;\">&nbsp;your data before you can share it. Read more about these processes at </span><a href=\"https://researchdata.library.ubc.ca/plan/protect-your-data/\"><span style=\"font-weight: 400;\">UBC Library </span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">, or </span><a href=\"https://doi.org/10.1007/s10278-011-9422-x\"><span style=\"font-weight: 400;\">Image Data Sharing for Biomedical Research&mdash;Meeting HIPAA Requirements for De-identification</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"021e83c5-1b37-4916-88ce-b86803fed149"})
Question.create({"id"=>76352, "text"=>"Under what licence do you plan to release your data?", "default_value"=>nil, "number"=>4, "section_id"=>24767, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7950d965-f90c-40e5-84f8-b453a49918d1"})
Annotation.create({"id"=>72403, "question_id"=>76352, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">There are several types of standard licenses available to researchers, such as the </span><a href=\"https://creativecommons.org/choose/\"><span style=\"font-weight: 400;\">Creative Commons licenses</span></a><span style=\"font-weight: 400;\"> and the </span><a href=\"https://opendatacommons.org/licenses/\"><span style=\"font-weight: 400;\">Open Data Commons licenses</span></a><span style=\"font-weight: 400;\">. For most datasets it is easier to use a standard license rather than to devise a custom-made one. Even if you choose to make your data part of the public domain, it is preferable to make this explicit by using a license such as Creative Commons' CC0. More about data licensing: </span><a href=\"https://www.dcc.ac.uk/guidance/how-guides/license-research-data\"><span style=\"font-weight: 400;\">Digital Curation Centre</span></a><span style=\"font-weight: 400;\">. </span>", "type"=>"example_answer", "versionable_id"=>"e1d81c56-4673-45b3-acbc-4c9edce69960"})
Annotation.create({"id"=>72404, "question_id"=>76352, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Licenses stipulate how your data may be used. Funding agencies and/or data repositories may have end-user license requirements in place; if not, they may still be able to guide you in the selection of a license. Once selected, please include a copy of your end-user license with your Data Management Plan. Note that only the intellectual property rights holder(s) can issue a license, so it is crucial to clarify who owns those rights. </span>", "type"=>"guidance", "versionable_id"=>"eb193e3c-79ad-4b11-ac94-7015949ea145"})
Question.create({"id"=>76353, "text"=>"Under what licence do you plan to release your software?", "default_value"=>nil, "number"=>5, "section_id"=>24767, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"816bd2c3-5c56-49dc-837b-012398fcaf14"})
Annotation.create({"id"=>72405, "question_id"=>76353, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">By providing a licence for your software, you grant others certain freedoms, and define what they are allowed to do with your code. Free and open software licences typically allow someone else to use, study, improve and share your code. You can licence all the software you write, including scripts and macros you develop on proprietary platforms. For more information, see </span><a href=\"https://choosealicense.com/\"><span style=\"font-weight: 400;\">Choose an Open Source License</span></a><span style=\"font-weight: 400;\"> or open source licenses options at the </span><a href=\"https://opensource.org/licenses\"><span style=\"font-weight: 400;\">Open Source Initiative</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">Please be aware that software is typically protected by copyright that is often held by the institution rather than the developer. Ensure you understand what rights you have to share your software before choosing a license.</span></p>", "type"=>"guidance", "versionable_id"=>"35ac909f-7bf6-493b-b0c6-b0b7381d6287"})
Question.create({"id"=>76354, "text"=>"How will you manage legal, ethical, and intellectual property issues?", "default_value"=>nil, "number"=>6, "section_id"=>24767, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"2f45e06f-6ba9-4a4f-9505-f67d714d78cd"})
Annotation.create({"id"=>72406, "question_id"=>76354, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Before you copy, (re-)use, modify, build on, or (re-)distribute others&rsquo; data and code, or engage in the production of derivatives, be sure to check, read, understand and follow any legal licensing agreements. The actions you can take, including whether you can publish or redistribute derivative research products, may depend on terms of the original license.</span></p>\r\n<p><span style=\"font-weight: 400;\">If your research data and/or software are built upon others&rsquo; data and software publications, it is good practice to acknowledge and cite the corresponding data and software you use in the same fashion as you cite papers to both identify the software and to give credit to its developers. Some good resources for developing citations are the </span><a href=\"https://peerj.com/articles/cs-86/\"><span style=\"font-weight: 400;\">Software Citation Principles (Smith et al., 2016)</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://datacite.org/cite-your-data.html\"><span style=\"font-weight: 400;\">DataCite - Cite Your Data</span></a><span style=\"font-weight: 400;\">, and </span><a href=\"https://www.jstage.jst.go.jp/article/dsj/12/0/12_OSOM13-043/_pdf\"><span style=\"font-weight: 400;\">Out of Cite, Out of Mind: The Current State of Practice, Policy, and Technology for the Citation of Data</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">Compliance with privacy legislation and laws that may restrict the sharing of some data should be discussed with your institution's privacy officer or data librarian, if possible. Research Ethics Boards are also central to the research process and a valuable resource. Include in your documentation a description concerning ownership, licensing, and intellectual property rights of the data. Terms of reuse must be clearly stated, in line with the relevant legal and ethical requirements where applicable (e.g., subject consent, permissions, restrictions, etc.).</span></p>", "type"=>"guidance", "versionable_id"=>"63c917bb-345b-4351-b1e2-4d5b6cc6537e"})
Phase.create({"id"=>3927, "title"=>"Phase 4: Sharing and Preserving", "description"=>nil, "number"=>4, "template_id"=>3870, "modifiable"=>true, "versionable_id"=>"d1fd3a69-036b-4779-a768-3b05bc27ff1a"})
Section.create({"id"=>24768, "title"=>"Sharing and Preserving", "description"=>nil, "number"=>1, "phase_id"=>3927, "modifiable"=>true, "versionable_id"=>"a6f30a46-350b-4e96-a9c4-9c56695eac63"})
Question.create({"id"=>76355, "text"=>"What will be the potential impact of the data within the immediate field and in other fields, and any broader societal impact?", "default_value"=>nil, "number"=>1, "section_id"=>24768, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"1e289bf3-8ae3-408f-9be8-27067023ca97"})
Question.create({"id"=>76356, "text"=>"What steps will be taken to help the research community know that your data exists?", "default_value"=>nil, "number"=>2, "section_id"=>24768, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0403467f-a901-48c1-b986-ccba223a81de"})
Annotation.create({"id"=>72407, "question_id"=>76356, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">One of the best ways to refer other researchers to your deposited datasets is to cite them the same way you cite other types of publications. The Digital Curation Centre provides a detailed </span><a href=\"http://www.dcc.ac.uk/resources/how-guides/cite-datasets\"><span style=\"font-weight: 400;\">guide on data citation</span></a><span style=\"font-weight: 400;\">. You may also wish to consult the </span><a href=\"https://datacite.org/cite-your-data.html\"><span style=\"font-weight: 400;\">DataCite citation recommendations</span></a><span style=\"font-weight: 400;\">.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Some repositories also create links from datasets to their associated papers, increasing the visibility of the publications. If possible, cross-reference or link out to all publications, code and data. Choose a repository that will assign a persistent identifier (such as a DOI) to your dataset to ensure stable access to the dataset.</span></p>\r\n<span style=\"font-weight: 400;\">Other sharing possibilities include: data registries, indexes, word-of-mouth, and publications. For more information, see </span><a href=\"https://grants.nih.gov/grants/sharing_key_elements_data_sharing_plan.pdf\"><span style=\"font-weight: 400;\">Key Elements to Consider in Preparing a Data Sharing Plan Under NIH Extramural Support</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"db67d63e-3a0f-4be1-a9b9-3f76fe270c46"})
Question.create({"id"=>76357, "text"=>"What data will you be sharing and in what form? (e.g. raw, processed, analyzed, final).", "default_value"=>nil, "number"=>3, "section_id"=>24768, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"aefe230d-4890-4795-9ba7-3c90480b3f3e"})
Annotation.create({"id"=>72408, "question_id"=>76357, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Consider which data are necessary to </span><a href=\"https://www.energy.gov/datamanagement/doe-policy-digital-research-data-management-glossary#Validate\"><span style=\"font-weight: 400;\">validate</span></a><span style=\"font-weight: 400;\"> (support or verify) your research findings, and which must be shared to meet institutional or funding requirements. This may include data and code used in analyses or to create charts, figures, images, etc. Certain data may need to be restricted because of confidentiality, privacy, or intellectual property considerations and should be described below.</span></p>\r\n<span style=\"font-weight: 400;\">Wherever possible, share your data in preservation-friendly file formats. Some data formats are optimal for the long-term preservation of data. For example, non-proprietary file formats, such as text ('.txt') and comma-separated ('.csv'), are considered preservation-friendly. The </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/recommended-formats\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\"> provides a useful table of file formats for various types of data. Keep in mind that preservation-friendly files converted from one format to another may lose information (e.g. converting from an uncompressed TIFF file to a compressed JPG file), so changes to file formats should be documented. </span>", "type"=>"guidance", "versionable_id"=>"130e6367-1660-461d-897a-55ace3cb40be"})
Question.create({"id"=>76358, "text"=>"Where will you deposit your data and software for preservation and access at the end of your research project?", "default_value"=>nil, "number"=>4, "section_id"=>24768, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"03088318-15b9-4960-ab46-26c8e6c10ed4"})
Annotation.create({"id"=>72410, "question_id"=>76358, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">The general-purpose repositories for data sharing in Canada are the </span><a href=\"https://www.frdr-dfdr.ca/repo/\"><span style=\"font-weight: 400;\">Federated Research Data Repository (FRDR)</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://dataverse.scholarsportal.info/\"><span style=\"font-weight: 400;\">Scholars Portal Dataverse</span></a><span style=\"font-weight: 400;\">. You can search for discipline-specific repositories on </span><a href=\"http://re3data.org\"><span style=\"font-weight: 400;\">re3data.org</span></a><span style=\"font-weight: 400;\"> or by using </span><a href=\"https://repositoryfinder.datacite.org/\"><span style=\"font-weight: 400;\">DataCite's Repository Finder tool</span></a><span style=\"font-weight: 400;\">. </span>", "type"=>"example_answer", "versionable_id"=>"b7ff5b45-cf9a-4437-b847-d9fa73967d40"})
Annotation.create({"id"=>72409, "question_id"=>76358, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Data retention should be considered early in the research lifecycle. Data-retention decisions can be driven by external policies (e.g. funding agencies, journal publishers), or by an understanding of the enduring value of a given set of data. The need to preserve data in the short-term (i.e. for peer-verification purposes) or long-term (for data of lasting value), will influence the choice of data repository or archive. A helpful analogy is to think of creating a 'living will' for the data, that is, a plan describing how future researchers will have continued access to the data.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">It is important to verify whether or not the data repository you have selected will support the terms of use or licenses you wish to apply to your data and code. Consult the repository&rsquo;s own terms of use and preservation policies for more information. For help finding an appropriate repository, contact your institution&rsquo;s library or reach out to the Portage DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a></span><span style=\"font-weight: 400;\">. </span>", "type"=>"guidance", "versionable_id"=>"aa23d61f-b144-4075-8ca2-78f9f46f365a"})
Question.create({"id"=>76359, "text"=>"What software code will you make available, and where?", "default_value"=>nil, "number"=>5, "section_id"=>24768, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4e516f4c-3899-4bd6-afb3-b4be6e03e3a3"})
Annotation.create({"id"=>72411, "question_id"=>76359, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Making the software (or source code) you developed accessible is essential for others to understand your work. It allows others to check for errors in the software, to reproduce your work, and ultimately, to build upon your work. Consider using a code-sharing platform such as </span><a href=\"https://github.com/\"><span style=\"font-weight: 400;\">GitHub</span></a> <a href=\"https://bitbucket.org/product\"><span style=\"font-weight: 400;\">Bitbucket</span></a><span style=\"font-weight: 400;\">, or </span><a href=\"https://about.gitlab.com/\"><span style=\"font-weight: 400;\">GitLab</span></a><span style=\"font-weight: 400;\">. If you would like to archive your code and receive a DOI, </span><a href=\"https://guides.github.com/activities/citable-code/\"><span style=\"font-weight: 400;\">GitHub is integrated with Zenodo</span></a><span style=\"font-weight: 400;\"> as a repository option.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">At a minimum, if using third-party software (proprietary or otherwise), researchers should share and make available the source code (e.g., analysis scripts) used for analysis (even if they do not have the intellectual property rights to share the software platform or application itself).</span></p>", "type"=>"guidance", "versionable_id"=>"6cfa6f30-f945-4dcd-9c7a-8fb7728ded72"})
Question.create({"id"=>76360, "text"=>"Describe your software sustainability plan.", "default_value"=>nil, "number"=>6, "section_id"=>24768, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"119e52f6-19e2-4f03-8a4f-996b61b57c4c"})
Annotation.create({"id"=>72412, "question_id"=>76360, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">After the software has been delivered, used and recognized by a sufficiently large group of users, will you allocate both human and financial resources to support the regular maintenance of the software, for activities such as debugging, continuous improvement, documentation and training?</span>", "type"=>"guidance", "versionable_id"=>"2aa79397-933d-4072-973f-b94cb70b3837"})
