Section.create({"id"=>24796, "title"=>"Data Collection", "description"=>"<p><span style=\"font-weight: 400;\">Outline the processes and procedures you will follow during the data collection process of your study.</span></p>", "number"=>1, "phase_id"=>3932, "modifiable"=>true, "versionable_id"=>"6e5e6d03-d70d-4739-b7d5-d1ab8facd1a9"})
Question.create({"id"=>76438, "text"=>"<span style=\"font-weight: 400;\">What types of data will you be collecting?</span>", "default_value"=>nil, "number"=>1, "section_id"=>24796, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4a43da95-9996-4030-aa0c-de467f51c002"})
Annotation.create({"id"=>72500, "question_id"=>76438, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe all types of data you will collect throughout the research process, with special attention paid to participant-driven data (e.g., written transcripts, video files, audio recordings, journals, art, photographs, etc.).</span>", "type"=>"guidance", "versionable_id"=>"7c3e8ef4-0730-4dbb-a53e-3ba80fbc24e2"})
Question.create({"id"=>76439, "text"=>"<span style=\"font-weight: 400;\">Will you be using any existing data from external sources or previous research?</span>", "default_value"=>nil, "number"=>2, "section_id"=>24796, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e1811bb1-d1ae-453c-ab92-de78d37e4290"})
Annotation.create({"id"=>72501, "question_id"=>76439, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">If you will be combining original research data with existing, or previously used research data, describe those data here. Provide the name, location, URL, and date of the dataset(s) used. Describe any end-user license assigned to the data, or terms of use you must abide by.</span>", "type"=>"guidance", "versionable_id"=>"f9f7b2ac-844c-4554-84bd-72a9449eda3f"})
Question.create({"id"=>76440, "text"=>"<span style=\"font-weight: 400;\">What data collection instrument or scales will you use to collect the data?</span>", "default_value"=>nil, "number"=>3, "section_id"=>24796, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"8ac6962c-4a73-48b9-9154-7eda801495e6"})
Annotation.create({"id"=>72502, "question_id"=>76440, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide a description of any data collection instruments or scales that will be used to collect data. These may include but are not limited to questionnaires, interview guides, or focus group procedures. If using a pre-existing instrument or scale, provide the citation(s) in this section.</span>", "type"=>"guidance", "versionable_id"=>"82353ecb-a845-4a2a-b7b5-6da9b85cab96"})
Question.create({"id"=>76441, "text"=>"<span style=\"font-weight: 400;\">Is your data collected longitudinally or at a single point in time?</span>", "default_value"=>nil, "number"=>4, "section_id"=>24796, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c2d0a9fd-90fa-456f-8d3c-4f09f75acc90"})
Annotation.create({"id"=>72503, "question_id"=>76441, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe the frequency in which you will be collecting data from participants. If you are performing narrative inquiry or longitudinal data collection for example, how often will you gather data from the same participants?</span>", "type"=>"guidance", "versionable_id"=>"14008cfa-ad14-4afb-a218-ec04ae02b410"})
Question.create({"id"=>76442, "text"=>"<span style=\"font-weight: 400;\">What is the time frame over which you are collecting data?</span>", "default_value"=>nil, "number"=>5, "section_id"=>24796, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e371be12-fc64-4fe0-b1ff-9bf8d6d1cdf4"})
Annotation.create({"id"=>72504, "question_id"=>76442, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide an estimate of when you will begin and conclude the data collection process. List this information in the following format: YYYY/MM/DD - YYYY/MM/DD. If you do not know the exact dates, list YYYY/MM - YYYY/MM instead.</span>", "type"=>"guidance", "versionable_id"=>"bd6356db-3665-4eba-8ae6-16753e62b773"})
Question.create({"id"=>76443, "text"=>"<span style=\"font-weight: 400;\">What is the geographic location within the context of the phenomenon/experience where data will be gathered?</span>", "default_value"=>nil, "number"=>6, "section_id"=>24796, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7aaa4be6-82da-4d1d-9335-63e88c416af5"})
Annotation.create({"id"=>72505, "question_id"=>76443, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide a description of the environment and geographic location of where data will be gathered, within the context of the study (e.g., hospital setting, long-term care setting, community). Include national, provincial, or municipal locations if applicable.</span>", "type"=>"guidance", "versionable_id"=>"5b0e7fa5-b8c7-4fcc-8514-0781cc541b0b"})
Question.create({"id"=>76444, "text"=>"<span style=\"font-weight: 400;\">What steps will be involved in the data collection process?</span>", "default_value"=>nil, "number"=>7, "section_id"=>24796, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"026bf9ae-41af-4e3d-9b34-0658820146e5"})
Annotation.create({"id"=>72506, "question_id"=>76444, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Summarize the steps that are involved in the data collection process for your study. This section should include information about screening and recruitment, the informed consent process, information disseminated to participants before data collection, and the methods by which data is gathered.&nbsp;</span></p>\r\n<br />\r\n<p><span style=\"font-weight: 400;\">In this section, consider including documentation such as your study protocol, interview guide, questionnaire, etc.</span></p>", "type"=>"guidance", "versionable_id"=>"354a2417-18dc-48ff-aa02-10a39c78d49a"})
Question.create({"id"=>76445, "text"=>"<span style=\"font-weight: 400;\">What software programs will you use to collect the data?</span>", "default_value"=>nil, "number"=>8, "section_id"=>24796, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"b9212dcf-e14a-4b4b-9a62-9d7203311214"})
Annotation.create({"id"=>72507, "question_id"=>76445, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Include a description of any software that will be used to gather data. Examples may include but are not limited to word processing programs, survey software, and audio/video recording tools. Provide the version of each software program used if applicable.</span>", "type"=>"guidance", "versionable_id"=>"e7679dc5-ebcd-4eb5-a3b1-d0eb32989ac2"})
