Annotation.create({"id"=>72508, "question_id"=>76446, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">List the file formats associated with each software program that will be generated during the data collection phase (e.g., .txt, .csv, .mp4, .wav).</span>", "type"=>"guidance", "versionable_id"=>"1ecc3111-de4d-456b-af9a-757623bd5066"})
Section.create({"id"=>24797, "title"=>"Data Analysis", "description"=>"<p><span style=\"font-weight: 400;\">Outline the steps, materials, and methods that you will use to document how you will analyze the data collected in your study.</span></p>", "number"=>2, "phase_id"=>3932, "modifiable"=>true, "versionable_id"=>"5a6c537f-a4a8-47ea-9b5d-648ef16fd5e4"})
Question.create({"id"=>76447, "text"=>"<span style=\"font-weight: 400;\">How will you document the changes you make to your data on a regular basis?</span>", "default_value"=>nil, "number"=>1, "section_id"=>24797, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"640b37d8-5f24-4f6f-80e2-6299605a1d01"})
