Question.create({"id"=>76448, "text"=>"<span style=\"font-weight: 400;\">What software will you be using to support your data analysis?</span>", "default_value"=>nil, "number"=>2, "section_id"=>24797, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"59c2a56b-01e3-40c3-9246-5761af58fdc5"})
Annotation.create({"id"=>72510, "question_id"=>76448, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Include any software programs you plan to use to perform or supplement data analysis (e.g., NVivo, Atlas.ti, SPSS, SAS, R, etc.). Include the version if applicable.</span>", "type"=>"guidance", "versionable_id"=>"f998358e-c244-45a7-8a5f-66eaf1b61811"})
