Annotation.create({"id"=>72515, "question_id"=>76453, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Metadata standards can provide guidance on how best to document your data. If you do not know of any existing standards in your field, visit this website to search for available standards: </span><a href=\"https://fairsharing.org/\"><span style=\"font-weight: 400;\">https://fairsharing.org/</span></a>.", "type"=>"guidance", "versionable_id"=>"e211cc6f-04db-4452-9795-6d62c6c8e1bb"})
