Annotation.create({"id"=>72516, "question_id"=>76454, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe the participants whose lived experiences/phenomena are being studied in this project.</span>", "type"=>"guidance", "versionable_id"=>"39464e6f-b902-41cd-990d-9798f854f052"})
Question.create({"id"=>76455, "text"=>"<span style=\"font-weight: 400;\">How is the population being sampled?</span>", "default_value"=>nil, "number"=>4, "section_id"=>24798, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"9204d489-fe51-45df-a44b-4d0ad64184f3"})
Annotation.create({"id"=>72517, "question_id"=>76455, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide a brief description of the sampling process undertaken in the study (e.g., purposive sampling, theoretical sampling).</span>", "type"=>"guidance", "versionable_id"=>"43943052-8df5-4ebe-9951-c2110534fdc4"})
Question.create({"id"=>76456, "text"=>"<span style=\"font-weight: 400;\">Is the population being weighted?</span>", "default_value"=>nil, "number"=>5, "section_id"=>24798, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"eb2b338f-6494-4878-a26f-baa83cce91d1"})
