Question.create({"id"=>76459, "text"=>"<span style=\"font-weight: 400;\">Where will your data be stored during the </span><em><span style=\"font-weight: 400;\">data collection</span></em><span style=\"font-weight: 400;\"> phase?</span>", "default_value"=>nil, "number"=>2, "section_id"=>24799, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"eaed6ba4-6e5b-406e-8a7b-9dddb61b2ec1"})
