Question.create({"id"=>76462, "text"=>"<span style=\"font-weight: 400;\">If your data contains confidential information, how will your storage method ensure the protection of this data?</span>", "default_value"=>nil, "number"=>5, "section_id"=>24799, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"30e38154-77c2-4e7f-bc2e-b983bda4c869"})
Annotation.create({"id"=>72524, "question_id"=>76462, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Outline the procedures that will safeguard sensitive data collected during your study. This may include storing identifying data (consent forms) separately from anonymized data (audio files or transcripts), keeping files password protected and secure, and only providing access to investigators analyzing the data.</span>", "type"=>"guidance", "versionable_id"=>"e42a0c91-cde0-444b-8364-8c3fbc92cbb0"})
Question.create({"id"=>76463, "text"=>"<span style=\"font-weight: 400;\">What file naming conventions will be used to save your data?</span>", "default_value"=>nil, "number"=>6, "section_id"=>24799, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c72a4317-fb0a-46f7-bdc1-f3b7c128b598"})
Annotation.create({"id"=>72525, "question_id"=>76463, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide examples of a consistent file naming convention that will be used for this study. Examples of file names might include the type of file, participant number, date of interaction, and/or study phase. Follow </span><a href=\"https://www.ed.ac.uk/records-management/guidance/records/practical-guidance/naming-conventions\"><span style=\"font-weight: 400;\">this guide</span></a><span style=\"font-weight: 400;\"> for more information on file naming.</span>", "type"=>"guidance", "versionable_id"=>"99bc5322-8469-404f-8211-5b88725ae3d4"})
Section.create({"id"=>24800, "title"=>"Preservation", "description"=>"<p><span style=\"font-weight: 400;\">Describe the steps that will ensure that your data will be available and usable for the foreseeable future after your study is complete.</span></p>", "number"=>5, "phase_id"=>3932, "modifiable"=>true, "versionable_id"=>"325204bc-61ad-45a3-bbb6-d691150b8d07"})
Question.create({"id"=>76464, "text"=>"<span style=\"font-weight: 400;\">Where will data be stored </span><em><span style=\"font-weight: 400;\">after </span></em><span style=\"font-weight: 400;\">the project is complete?</span>", "default_value"=>nil, "number"=>1, "section_id"=>24800, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"ae2b90f8-b348-4ed0-a9c3-88a3f30d028a"})
Annotation.create({"id"=>72526, "question_id"=>76464, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe where your data will be stored after project completion (e.g., in an institutional repository, </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">external data repository</span></a><span style=\"font-weight: 400;\">, in secure, institutional computer storage, or external hard drive).</span>", "type"=>"guidance", "versionable_id"=>"f316b26f-a626-4e0f-856c-8e570c7249f5"})
