Annotation.create({"id"=>72527, "question_id"=>76465, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Name the person(s) responsible for managing the data at the completion of the project. List their affiliation(s) and contact information.</span>", "type"=>"guidance", "versionable_id"=>"56ff00ba-8813-4b04-b9b2-62c247288a63"})
Question.create({"id"=>76466, "text"=>"<span style=\"font-weight: 400;\">Will your data be migrated to preservation formats?</span>", "default_value"=>nil, "number"=>3, "section_id"=>24800, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"ff70f74f-a7f1-4bdb-b0dd-0a83b191c94b"})
Annotation.create({"id"=>72528, "question_id"=>76466, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Many proprietary file formats such as those generated from Microsoft software or statistical analysis tools can make the data difficult to access later on. Consider transforming any proprietary files into </span><a href=\"https://www.archives.gov/preservation/products/definitions/filetypes.html\"><span style=\"font-weight: 400;\">preservation-friendly formats</span></a><span style=\"font-weight: 400;\"> to ensure your data can be opened in any program. Describe the process for migrating any data formats here.</span>", "type"=>"guidance", "versionable_id"=>"d6c71dd3-73f4-4a92-9e90-e76ea0c56f2c"})
Question.create({"id"=>76467, "text"=>"<span style=\"font-weight: 400;\">How long do you intend to keep your data after the project is complete?</span>", "default_value"=>nil, "number"=>4, "section_id"=>24800, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d72b31a1-8dc1-4a32-89ea-d50fb75a662f"})
Annotation.create({"id"=>72529, "question_id"=>76467, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide details on how long you plan to keep your data after the project, and list any requirements you must follow based on Research Ethics Board guidelines, data use agreements, or funder requirements. </span>", "type"=>"guidance", "versionable_id"=>"683c7f07-37c6-443a-8ed0-b0616dbdf593"})
Question.create({"id"=>76468, "text"=>"<span style=\"font-weight: 400;\">What procedures are in place to destroy the data after the retention period is complete?</span>", "default_value"=>nil, "number"=>5, "section_id"=>24800, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c35c254f-21c2-460b-b181-7e968c976210"})
Annotation.create({"id"=>72530, "question_id"=>76468, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe what steps will be taken to destroy study data. These steps may include shredding physical documents, making data unretrievable with support from your Information Technology department, or other personal measures to eliminate data files.</span>", "type"=>"guidance", "versionable_id"=>"dbc075f1-c4b4-45bc-a848-031d29d6f359"})
