Question.create({"id"=>76469, "text"=>"<span style=\"font-weight: 400;\">How is the informed consent process carried out in your study? </span>", "default_value"=>nil, "number"=>1, "section_id"=>24801, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"04c365af-79b1-4eea-8409-3695ea7b4374"})
