Question.create({"id"=>76471, "text"=>"<span style=\"font-weight: 400;\">What ethical guidelines or restraints are applicable to your data?</span>", "default_value"=>nil, "number"=>3, "section_id"=>24801, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"03778309-d6c6-4bcc-b2b7-741f775df8cc"})
Annotation.create({"id"=>72533, "question_id"=>76471, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe any ethical concerns that may be associated with the data in this study. For example, if vulnerable and/or Indigenous populations are included as participants, outline specific guidelines that are being followed to protect them (e.g., </span><a href=\"https://www.afn.ca/uploads/files/nihbforum/info_and_privacy_doc-ocap.pdf\"><span style=\"font-weight: 400;\">OCAP</span></a><span style=\"font-weight: 400;\">, community advisory boards, etc.).</span>", "type"=>"guidance", "versionable_id"=>"775e9e85-57c7-45e5-93c8-4278c2e94ee5"})
Question.create({"id"=>76472, "text"=>"<span style=\"font-weight: 400;\">What legal restraints are applicable to your data (e.g., ownership)?</span>", "default_value"=>nil, "number"=>4, "section_id"=>24801, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"47a3188a-a8c0-4979-aca7-20178dff8d24"})
Annotation.create({"id"=>72534, "question_id"=>76472, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide details describing the legal restrictions that apply to your data. These restrictions may include, but are not limited to details about how your research data can be used as outlined by funder, institutional, or community agreements, among others.</span>", "type"=>"guidance", "versionable_id"=>"534128e6-ee88-4a25-a7f0-da58e8808412"})
Question.create({"id"=>76473, "text"=>"<span style=\"font-weight: 400;\">What methods will be used to manage the risk of disclosure of participant information?</span>", "default_value"=>nil, "number"=>5, "section_id"=>24801, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f8bc3892-6a01-431f-94c2-dc3bb071e961"})
Annotation.create({"id"=>72535, "question_id"=>76473, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">List all the steps that will be taken to remove the risk of disclosing personal information from study participants. Include information about keeping data safe and secure, and whether certain information will be removed from the data. If data is being anonymized or de-identified, specify the information type(s) being altered (e.g., names, addresses, dates, location).</span>", "type"=>"guidance", "versionable_id"=>"e3e7662b-8d18-4a76-baf9-a57158076433"})
