Question.create({"id"=>76480, "text"=>"<span style=\"font-weight: 400;\">What restrictions are placed on your data that would prohibit it from being made publicly available?</span>", "default_value"=>nil, "number"=>3, "section_id"=>24803, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"44f18d6c-905c-49ee-af57-4e49d053fbbe"})
Annotation.create({"id"=>72542, "question_id"=>76480, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Restrictions on data may include, but are not limited to, the sensitivity of the data, data being acquired under license, or data being restricted under a data use agreement. Describe what restrictions (if any) apply to your research data. </span>", "type"=>"guidance", "versionable_id"=>"675fb0cb-7e8f-45b7-abe1-2d7cdf888c20"})
Question.create({"id"=>76481, "text"=>"<span style=\"font-weight: 400;\">Where will you share your data?</span>", "default_value"=>nil, "number"=>4, "section_id"=>24803, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0653ed6b-7c6a-443b-9b86-93a665e5461d"})
Annotation.create({"id"=>72543, "question_id"=>76481, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide the location where you intend to share your data. This may be an institutional repository, </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">external data repository</span></a><span style=\"font-weight: 400;\">, or through your Research Ethics Board, among others.</span>", "type"=>"guidance", "versionable_id"=>"bfb60086-a8f2-4225-b408-fc21d136c58e"})
Question.create({"id"=>76482, "text"=>"<span style=\"font-weight: 400;\">If you have collected restricted data, what steps would someone requesting your data need to follow in order to access it?</span>", "default_value"=>nil, "number"=>5, "section_id"=>24803, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c798574d-fcd9-49c9-b303-02216655599a"})
Annotation.create({"id"=>72544, "question_id"=>76482, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">If your data is restricted, describe how a researcher could access that data for secondary analysis. Examples of these procedures may include completing a Research Ethics Board application, signing a data use agreement, submitting a proposal to a community advisory board, among others. Be as specific as possible in this section.</span>", "type"=>"guidance", "versionable_id"=>"89fd85a8-96c5-4f79-bae7-da70b9efdd78"})
Question.create({"id"=>76483, "text"=>"<span style=\"font-weight: 400;\">What license will you apply to your data?</span>", "default_value"=>nil, "number"=>6, "section_id"=>24803, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0629ec4e-34e9-4efb-ad66-34203527b0ca"})
Annotation.create({"id"=>72545, "question_id"=>76483, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Select a license that best suits the parameters of how you would like to share your data, and how you would prefer to be credited. See this resource to help you decide: </span><a href=\"https://creativecommons.org/choose/\"><span style=\"font-weight: 400;\">https://creativecommons.org/choose/</span></a>.", "type"=>"guidance", "versionable_id"=>"5c820c49-5b24-4973-b0de-470ad02ca4a6"})
Template.create!({"id"=>3872, "title"=>"Alliance Template for Neuroimaging in the Neurosciences", "description"=>"<p><span style=\"font-weight: 400;\">This Neuroimaging data management plan (DMP) template is designed to be completed in two phases: Phase 1 questions probe at a high-level, seeking information about the general direction of the study. Normally, researchers will be able to respond to phase 1 questions at the outset of a project.&nbsp;&nbsp;</span></p>\n<p><span style=\"font-weight: 400;\">Phase 2 questions seek greater detail. It is understood that these answers will often depend on the outcome of several steps in the research project, such as: a literature review, imaging protocol design and experimental design, or running multiple pilot subjects and interpreting the outcome. As these details become known, the DMP can and should be revisited. This approach underscores that DMPs are living documents that evolve throughout a research project.&nbsp; </span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>2, "visibility"=>1, "customization_of"=>nil, "family_id"=>1659720835, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3929, "title"=>"Phase 1", "description"=>"<p><span style=\"font-weight: 400;\">Phase 1 questions probe at a high-level, seeking information about the general direction of the study. Normally, researchers will be able to respond to phase 1 questions at the outset of a project.&nbsp;&nbsp;</span></p>", "number"=>1, "template_id"=>3872, "modifiable"=>true, "versionable_id"=>"c5dbdb42-b148-4fb4-bba1-c6b3e435f4e6"})
Section.create({"id"=>24776, "title"=>"Data Collection", "description"=>nil, "number"=>1, "phase_id"=>3929, "modifiable"=>true, "versionable_id"=>"0fe22057-1ce8-4e32-91e0-53ccf9ecd36e"})
Question.create({"id"=>76390, "text"=>"<p>Describe the types of data, and potential data sources, to be acquired during the course of your study.</p>", "default_value"=>nil, "number"=>1, "section_id"=>24776, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c9a94f76-9f35-40bb-8b7a-45fc2ba057f2"})
Annotation.create({"id"=>72456, "question_id"=>76390, "org_id"=>8, "text"=>"<p>Please explain, in particular:</p>\r\n<ul>\r\n<li>What type of neuroimaging modalities will be used to acquire data in this study? Ex: MRI, EEG.</li>\r\n<li>What other types of data will be acquired in this study? Ex: behavioural, biological sample.</li>\r\n<li>Approximately how many participants does the study plan to acquire images from?</li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"f3a0deef-9685-4634-b63c-30371b8ccb41"})
Section.create({"id"=>24777, "title"=>"Documentation and Metadata", "description"=>nil, "number"=>2, "phase_id"=>3929, "modifiable"=>true, "versionable_id"=>"51ad24eb-c30b-48cc-930e-28fee32f4283"})
Question.create({"id"=>76391, "text"=>"<span style=\"font-weight: 400;\">How will you document your methods in order to support reproducibility?</span>", "default_value"=>nil, "number"=>1, "section_id"=>24777, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0f64af3f-c277-49a5-8ce5-5e101a243739"})
Annotation.create({"id"=>72457, "question_id"=>76391, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">For fellow researchers, a write-up of your methods is indispensable for supporting the reproducibility of a study. In preparation for publishing, consider creating an online document or folder (e.g. openneuro, github, zenodo, osf) where your project methods can be gathered/prepared. If appropriate, provide a link to that space here.</span>", "type"=>"guidance", "versionable_id"=>"604d9835-80ab-46d2-9ade-12762553ff6b"})
Section.create({"id"=>24778, "title"=>"Storage and Backup", "description"=>nil, "number"=>3, "phase_id"=>3929, "modifiable"=>true, "versionable_id"=>"3d7536ea-e4c8-4da9-a3ef-51a1b0c3ea2e"})
Question.create({"id"=>76392, "text"=>"<span style=\"font-weight: 400;\">How and where will your data be stored and backed up during your research project? </span>", "default_value"=>nil, "number"=>1, "section_id"=>24778, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"41616a56-5365-4755-b121-70d91ee2aa2a"})
Annotation.create({"id"=>72458, "question_id"=>76392, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Planning how research data will be stored and backed up throughout and beyond a research project is critical in ensuring data security and integrity. Appropriate storage and backup not only helps protect research data from catastrophic losses (due to hardware and software failures, viruses, hackers, natural disasters, human error, etc.), but also facilitates appropriate access by current and future researchers. You may need to encrypt your data to ensure it is not accessible by those outside the project. For more information, see the University of Waterloo&rsquo;s </span><a href=\"https://uwaterloo.ca/research/office-research-ethics/research-human-participants/pre-submission-and-training/human-research-guidelines-policies-and-resources/guideline-researchers-securing-research-participants-data\"><span style=\"font-weight: 400;\">Guideline for researchers on securing research participants' data</span></a><span style=\"font-weight: 400;\">.</span><br /><span style=\"font-weight: 400;\"><br />Please provide URL(s) to any data storage sites. If your data are subject to strict rules governing human subjects and anonymity, then you may need an on-premise solution installed on your institution&rsquo;s server. </span>", "type"=>"guidance", "versionable_id"=>"c1f4afc9-1e68-4f24-8f65-b19f34c533c2"})
Question.create({"id"=>76393, "text"=>"<span style=\"font-weight: 400;\">What are the anticipated storage requirements for your project, in terms of storage space (in megabytes, gigabytes, terabytes, etc.)?</span>", "default_value"=>nil, "number"=>2, "section_id"=>24778, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"480e08b1-7397-4b95-ad3c-1f3d87f7ad17"})
Section.create({"id"=>24779, "title"=>"Preservation", "description"=>nil, "number"=>4, "phase_id"=>3929, "modifiable"=>true, "versionable_id"=>"e0c3137c-a0f7-4c69-a1cb-1ef67e75aaac"})
Question.create({"id"=>76394, "text"=>"<span style=\"font-weight: 400;\">How will you store and retain your data after the active phase of data collection? For how long will you need to keep your data?</span>", "default_value"=>nil, "number"=>1, "section_id"=>24779, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"aa57a10e-ceaf-433f-b851-6502e6a4bf4d"})
Annotation.create({"id"=>72459, "question_id"=>76394, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Choices about data preservation will depend on the potential for reuse and long-term significance of the data, as well as whether you have obligations to funders or collaborators to either retain or destroy data, and what resources will be required to ensure it remains usable in the future. The need to preserve data in the short-term (i.e. for peer-verification purposes) or long-term (for data of lasting value) will influence the choice of data repository or archive. Tools such as </span><a href=\"https://repositoryfinder.datacite.org/\"><span style=\"font-weight: 400;\">DataCite's repository finder tool</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">re3data.org</span></a><span style=\"font-weight: 400;\"> are useful for finding an appropriate repository for your data. </span>", "type"=>"guidance", "versionable_id"=>"838c2bfe-5a87-4ac9-b605-61126c738e85"})
Section.create({"id"=>24780, "title"=>"Sharing and Reuse", "description"=>nil, "number"=>5, "phase_id"=>3929, "modifiable"=>true, "versionable_id"=>"48d1f8c9-c12a-41a8-8572-615b4b295597"})
Question.create({"id"=>76395, "text"=>"<span style=\"font-weight: 400;\">How will you share data from this study with the scientific community? How open can you make it? Describe whether you plan to share your data publicly, make it available in a repository with restricted access, or offer it by request only.</span>", "default_value"=>nil, "number"=>1, "section_id"=>24780, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"aafc0004-5ec3-470f-b021-cf8ad793b7d0"})
Annotation.create({"id"=>72460, "question_id"=>76395, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Most Canadian research funding agencies now have policies recommending or requiring research data to be shared upon publication of the research results or within a reasonable period of time. While data sharing contributes to the visibility and impact of research, it has to be balanced with the legitimate desire of researchers to maximise their research outputs before releasing their data. Equally important is the need to protect the privacy of respondents and to properly handle sensitive data.</span><span style=\"font-weight: 400;\"> What you can share, and with whom, may depend on what type of consent is obtained from study participants. In a case where some (or all) or the data analyzed was previously acquired (by your research team or by others), what you can share for this current study may also be dependent on the terms under which the original data were provided, and any restrictions that were placed on that data originally. Provide a copy of your consent forms and licensing terms for any secondary data, if available.</span>", "type"=>"guidance", "versionable_id"=>"a2d1968d-8db2-4737-892d-330b688d0150"})
Section.create({"id"=>24781, "title"=>"Responsibilities and Resources", "description"=>nil, "number"=>6, "phase_id"=>3929, "modifiable"=>true, "versionable_id"=>"61ac1f71-6a07-4cc9-8ed3-3940a2ba3a35"})
Question.create({"id"=>76396, "text"=>"<span style=\"font-weight: 400;\">Identify who will be responsible for managing this project's data during and after the project and the major data management tasks for which they will be responsible.</span>", "default_value"=>nil, "number"=>1, "section_id"=>24781, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"bdca6b45-0be2-4111-80f2-3d822a4d4b23"})
Annotation.create({"id"=>72461, "question_id"=>76396, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Data management focuses on the 'what' and 'how' of operationally supporting data across the research lifecycle. Data stewardship focuses on 'who' is responsible for ensuring that data management happens. A large project, for example, will involve multiple data stewards. The Principal Investigator should identify at the beginning of a project all of the people who will have responsibilities for data management tasks during and after the project.</span>", "type"=>"guidance", "versionable_id"=>"711d6c62-b4c0-45a4-a2df-921000e69ab3"})
Question.create({"id"=>76397, "text"=>"<span style=\"font-weight: 400;\">What resources will you require to implement your data management plan? What do you estimate the overall cost for data management to be?</span>", "default_value"=>nil, "number"=>2, "section_id"=>24781, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"3d3aaa9d-21d3-4062-a6d5-371d8f1e7f60"})
Annotation.create({"id"=>72462, "question_id"=>76397, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">This estimate should incorporate data management costs expected during the project as well as those required for the longer-term support for the data after the project is finished. Items to consider in the latter category of expenses include the costs of curating and providing long-term access to the data. Some funding agencies state explicitly that they will provide support to meet the cost of preparing data for deposit. This might include technical aspects of data management, training requirements, file storage &amp; backup, and contributions of non-project staff. </span><span style=\"font-weight: 400;\">OpenAIRE has developed a tool to help researchers estimate costs associated with data management. Access this </span><a href=\"https://www.openaire.eu/estimating-costs-rdm-tool\"><span style=\"font-weight: 400;\">tool here</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"abebf105-44b2-4433-a7b9-8c9b307387f1"})
Section.create({"id"=>24782, "title"=>"Ethics and Legal Compliance", "description"=>nil, "number"=>7, "phase_id"=>3929, "modifiable"=>true, "versionable_id"=>"c2a70868-161b-48a0-8567-35814f0dc8da"})
Question.create({"id"=>76398, "text"=>"<p><span style=\"font-weight: 400;\">Please provide the name and a web link for the research ethics board (REB) that is responsible for reviewing and overseeing the legal and ethical compliance of this study. Give the file identifier of the REB application.</span></p>", "default_value"=>nil, "number"=>1, "section_id"=>24782, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0ee0e810-a553-4223-b0a3-9228a3f42bd7"})
Annotation.create({"id"=>72463, "question_id"=>76398, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Researchers must follow the policies and guidance of the research ethics board governing their institutions. There may be important differences across institutions. The Public Health Agency of Canada (PHAC) is responsible for setting standards and coordinating REBs across Canada. They provide </span><a href=\"https://cihr-irsc.gc.ca/e/29072.html\"><span style=\"font-weight: 400;\">10 best practices</span></a><span style=\"font-weight: 400;\"> for ensuring privacy of human participants:</span></p>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Determining the research objectives and justifying the data needed to fulfill these objectives</span></li>\r\n<li><span style=\"font-weight: 400;\">Limiting the collection of personal data</span></li>\r\n<li><span style=\"font-weight: 400;\">Determining if consent from individuals is required</span></li>\r\n<li><span style=\"font-weight: 400;\">Managing and documenting consent</span></li>\r\n<li><span style=\"font-weight: 400;\">Informing prospective research participants about the research</span></li>\r\n<li><span style=\"font-weight: 400;\">Recruiting prospective research participants</span></li>\r\n<li><span style=\"font-weight: 400;\">Safeguarding personal data</span></li>\r\n<li><span style=\"font-weight: 400;\">Controlling access and disclosure of personal data</span></li>\r\n<li><span style=\"font-weight: 400;\">Setting reasonable limits on retention of personal data</span></li>\r\n<li><span style=\"font-weight: 400;\">Ensuring accountability and transparency in the management of personal data</span></li>\r\n</ul>\r\n<p><br /><span style=\"font-weight: 400;\">In the context of neuroimaging research, &ldquo;the potential identifiability of otherwise anonymous image files is of great concern to those in the field who are anxious to encourage electronic data sharing&rdquo; (</span><a href=\"https://doi.org/10.1016/S0278-2626(02)00518-3\"><span style=\"font-weight: 400;\">Kulynych, 2002</span></a><span style=\"font-weight: 400;\">). Please consult your REB for recommendations on how to prepare ethics protocols.</span></p>", "type"=>"guidance", "versionable_id"=>"dec9c270-8cf9-4d1e-8c9e-676371ee2eb0"})
Question.create({"id"=>76399, "text"=>"<span style=\"font-weight: 400;\">If the project includes sensitive data, how will you ensure that it is securely managed and accessible only to approved members of the project?</span>", "default_value"=>nil, "number"=>2, "section_id"=>24782, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"bd5149c8-a0db-441f-98ed-4a740fa1609a"})
Annotation.create({"id"=>72464, "question_id"=>76399, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">State how you will prepare, store, share, and archive the data in a way that ensures participant information is protected, throughout the research lifecycle, from disclosure, harmful use, or inappropriate linkages with other personal data. This may mean avoiding cloud storage services, placing data on computers with no access to the internet, or encrypting data that will be shared during the research project. For more information, see the <a href=\"https://catalyst.harvard.edu/pdf/regulatory/Guide_to_Technologies_Used_in_Research.pdf\">Harvard Catalyst guidance about cloud storage</a>.</span>", "type"=>"guidance", "versionable_id"=>"352abd25-7f3a-4cc9-8177-926787273af9"})
Phase.create({"id"=>3930, "title"=>"Phase 2", "description"=>"<p><span style=\"font-weight: 400;\">Phase 2 questions seek greater detail. It is understood that these answers will often depend on the outcome of several steps in the research project, such as: a literature review, imaging protocol design and experimental design, or running multiple pilot subjects and interpreting the outcome. As these details become known, the DMP can and should be revisited. This approach underscores that DMPs are living documents that evolve throughout a research project.&nbsp; </span></p>", "number"=>2, "template_id"=>3872, "modifiable"=>true, "versionable_id"=>"82eae2ac-d34d-4509-9dc6-e760741d253a"})
Section.create({"id"=>24783, "title"=>"Data Collection", "description"=>nil, "number"=>1, "phase_id"=>3930, "modifiable"=>true, "versionable_id"=>"39bb0d34-876c-482d-948c-871dc3b5705a"})
Question.create({"id"=>76400, "text"=>"<span style=\"font-weight: 400;\">Give details about the sources of data, equipment used, and data formats produced for your project.&nbsp;</span>", "default_value"=>nil, "number"=>1, "section_id"=>24783, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"8b59ec22-4350-4197-aece-977116f0a3de"})
Annotation.create({"id"=>72465, "question_id"=>76400, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Please explain, in particular:<br /></span></span>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">What is the make and model of the neuroimaging system? Ex: Siemens Prisma 3T.&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Can you describe the image acquisition paradigm and parameters being used in the study? Ex. MRI T1w MPRAGE.&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">What is the total duration of the scanning sequence? Ex. 40 minutes.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">What file formats will your neuroimaging data be acquired in?</span></li>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"2\"><span style=\"font-weight: 400;\">Proprietary file formats requiring specialized software or hardware to use are not recommended for preservation, but may be necessary for certain data collection or analysis methods. Use open file formats where possible, or at least industry-standard formats such as dicom, NIFTI, European data format (.edf), or the BrainVision data format (.eeg/.vhdr/.vmrk). Read more about file formats: </span><a href=\"https://researchdata.library.ubc.ca/plan/format-your-data/\"><span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format.aspx\"><span style=\"font-weight: 400;\">UK Data Archive</span></a><span style=\"font-weight: 400;\">.</span></li>\r\n</ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Will the data be converted into other formats? Ex. NIFTI, BIDS, Minc.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Does the study incorporate any data acquired externally?&nbsp;</span></li>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"2\"><span style=\"font-weight: 400;\">No. New data acquisition only.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"2\"><span style=\"font-weight: 400;\">New data plus retrospective data from the same PI.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"2\"><span style=\"font-weight: 400;\">New data plus retrospective data from multiple sources.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"2\"><span style=\"font-weight: 400;\">Only retrospective data used in this study.</span></li>\r\n</ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">If external data are used in this study, please provide details about the source of external data, and identifying coordinates (DOI, URL, citation).</span></li>\r\n</ul>\r\n<span style=\"font-weight: 400;\"><br /></span>", "type"=>"guidance", "versionable_id"=>"0435db33-6f86-4f72-8407-6a2c6349dff1"})
Question.create({"id"=>76401, "text"=>"<span style=\"font-weight: 400;\">What conventions, methods, and standards will be used to structure, name and version-control your files to help you and others better understand how your data are organized? In other words, what types of metadata are being stored alongside the acquisition data? Ex: BIDS, NIDM.</span>", "default_value"=>nil, "number"=>2, "section_id"=>24783, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a67482c5-9f56-4623-b866-5c3c46a14864"})
Annotation.create({"id"=>72466, "question_id"=>76401, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">It is important to keep track of different copies or versions of files, files held in different formats or locations, and information cross-referenced between files. This process is called 'version control'. Logical file structures, informative naming conventions, and clear indications of file versions, all contribute to better use of your data during and after your research project.&nbsp; These practices will help ensure that you and your research team are using the appropriate version of your data, and minimize confusion regarding copies on different computers and/or on different media. Read more about file naming and version control: </span><a href=\"https://researchdata.library.ubc.ca/plan/organize-your-data/\"><span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/organising.aspx\"><span style=\"font-weight: 400;\">UK Data Archive</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"f94cfc78-bf5b-45bd-9e5f-91b33a8135eb"})
Question.create({"id"=>76402, "text"=>"What anonymization measures are taken during data collection and storage?", "default_value"=>nil, "number"=>3, "section_id"=>24783, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a8b1ea4f-a6c9-41d7-83f9-f6bf4b6d0f1d"})
Annotation.create({"id"=>72467, "question_id"=>76402, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">&ldquo;Within the framework of privacy protection, the degree of anonymization of the data is an important consideration and thus is an aspect incorporated in privacy regulations. Different rules apply to data, which are dependent on whether the data is considered personal data, fully anonymized or de‐identified. Fully anonymized data has all personalized data removed, is given a separate identification code, and the key between the fully anonymized dataset and any path back to the original data is deleted such that it would be extremely difficult to trace the data back to an individual&rdquo; (<a href=\"https://doi.org/10.1002/hbm.25120\">White et al., 2020</a>). The technical steps for anonymizing neuroimaging data should be designed to achieve the level of privacy required by ethics protocols governing the study. </span><a href=\"https://open-brain-consent.readthedocs.io/en/stable/anon_tools.html\"><span style=\"font-weight: 400;\">See here</span></a><span style=\"font-weight: 400;\"> for a selection of resources pertaining to anonymization.</span>", "type"=>"guidance", "versionable_id"=>"9636de68-fd5c-4ee3-bbf2-b2548c19fdce"})
Section.create({"id"=>24784, "title"=>"Documentation and Metadata", "description"=>nil, "number"=>2, "phase_id"=>3930, "modifiable"=>true, "versionable_id"=>"80cf683a-52b3-4685-92c2-750cdc024b51"})
Question.create({"id"=>76403, "text"=>"What documentation will be needed for the data to be read and interpreted correctly in the future? Document key details of methods pertaining to data and metadata here.", "default_value"=>nil, "number"=>1, "section_id"=>24784, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d5efa029-9489-400b-9e30-dcc2c8b16e4d"})
Annotation.create({"id"=>72468, "question_id"=>76403, "org_id"=>8, "text"=>"<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Does the study have an identifier (study ID) entered into the imaging console and other software? If so, enter the study ID here.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Does the study use identifiers for participants, e.g. sub-002 ? If so, give an example of the subject ID format here.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><span style=\"font-weight: 400;\">Are there any other codes or identifiers used in the study? If so, please identify and describe them here.</span></li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"a43a2991-777a-497d-8d09-bad9e7bc9329"})
Section.create({"id"=>24785, "title"=>"Storage and Backup", "description"=>nil, "number"=>3, "phase_id"=>3930, "modifiable"=>true, "versionable_id"=>"d10ab0e9-2f2c-40dc-a7e2-c22552d50aa6"})
Question.create({"id"=>76404, "text"=>"<span style=\"font-weight: 400;\">What form of encryption is used, if any, with data transfer and data storage? </span>", "default_value"=>nil, "number"=>1, "section_id"=>24785, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"99e6be21-51d6-4af2-bee6-99392593a254"})
Question.create({"id"=>76405, "text"=>"<p><span style=\"font-weight: 400;\">If you are using a data management application to manage data, please name which system. Describe the features of the application that are important for this project in particular (ex. provenance tracking, versioning, QC, longitudinal design). </span></p>", "default_value"=>nil, "number"=>2, "section_id"=>24785, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"83828d1c-73c6-4e90-aaa8-f63da9f45a17"})
Annotation.create({"id"=>72469, "question_id"=>76405, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">A data management application is a piece of software that stores data and helps to manage some aspects of the data and/or metadata collection, quality control, conversion, processing, reporting, annotation, and other functions. Some applications are designed specifically for the neuroimaging domain, e.g. LORIS, Braincode, while other applications can be used by any research discipline, e.g. XNAT, Redcap. In neurosciences, the term &lsquo;database&rsquo; is sometimes used by convention to refer to data management applications. For the purposes of this question, an application is any software tool used to manage data acquisition or storage.</span></p>", "type"=>"guidance", "versionable_id"=>"e905bc55-f21b-44da-99ac-e1d5ab2c8e20"})
Section.create({"id"=>24786, "title"=>"Preservation", "description"=>nil, "number"=>4, "phase_id"=>3930, "modifiable"=>true, "versionable_id"=>"6f11ab56-de24-4f0a-8ee9-3fdfe1df46e8"})
Question.create({"id"=>76406, "text"=>"<span style=\"font-weight: 400;\">What data will be preserved for the long-term?</span>", "default_value"=>nil, "number"=>1, "section_id"=>24786, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"ecc99b2d-8681-4385-9ac7-ff2802842bb5"})
Annotation.create({"id"=>72470, "question_id"=>76406, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">In some circumstances, it may be desirable to preserve all versions of the data (e.g. raw, processed, analyzed, final), but in others, it may be preferable to keep only selected or final data (e.g. phantom scans and other diagnostic scans may not need to be preserved).</span>", "type"=>"guidance", "versionable_id"=>"f7054d6a-dc3c-4ba8-84c6-3fcd11d21515"})
Question.create({"id"=>76407, "text"=>"Where will you deposit your data for long-term preservation and access at the end of your research project?", "default_value"=>nil, "number"=>2, "section_id"=>24786, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c719c99a-f677-47dc-8a28-cf01319ee782"})
Annotation.create({"id"=>72471, "question_id"=>76407, "org_id"=>8, "text"=>"<a href=\"https://repositoryfinder.datacite.org/\"><span style=\"font-weight: 400;\">DataCite's repository finder tool</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">re3data.org</span></a><span style=\"font-weight: 400;\"> are both useful tools for finding an appropriate repository for your data. Searches on re3data can be easily narrowed by discipline, such as this search for &lsquo;</span><a href=\"https://www.re3data.org/search?subjects[]=206%20Neurosciences\"><span style=\"font-weight: 400;\">neurosciences</span></a><span style=\"font-weight: 400;\">.&rsquo; There are also generalist repository services like Zenodo, OSF, Figshare, and </span><a href=\"https://academictorrents.com/\"><span style=\"font-weight: 400;\">Academictorrents.com</span></a><span style=\"font-weight: 400;\">. If your data is ready to be shared under an open license, then posting to an existing platform like </span><a href=\"https://openneuro.org/\"><span style=\"font-weight: 400;\">openneuro.org</span></a><span style=\"font-weight: 400;\">, </span><a href=\"http://openfmri.org\"><span style=\"font-weight: 400;\">openfmri.org</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://www.nitrc.org/\"><span style=\"font-weight: 400;\">nitrc.org</span></a><span style=\"font-weight: 400;\">, or </span><a href=\"https://portal.conp.ca/\"><span style=\"font-weight: 400;\">portal.conp.ca</span></a><span style=\"font-weight: 400;\"> could be a good solution.</span><br /><span style=\"font-weight: 400;\"><br />Not all repositories offer long-term preservation options, so you may want to consult a repository&rsquo;s posted policies before deciding to deposit. </span>", "type"=>"guidance", "versionable_id"=>"70379a84-67ca-4150-8c02-df3ea42ea671"})
Question.create({"id"=>76408, "text"=>"<span style=\"font-weight: 400;\">Indicate how you will ensure your data, and any accompanying materials (such as software, analysis scripts, or other tools), are preservation ready. </span>", "default_value"=>nil, "number"=>3, "section_id"=>24786, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"60f3624b-fd08-4f81-bd41-9206bb1c64fc"})
Annotation.create({"id"=>72472, "question_id"=>76408, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Consider using preservation-friendly file formats (open, non-proprietary formats), wherever possible. Some data formats are optimal for long-term preservation of data. For example, non-proprietary file formats, such as text ('.txt') and comma-separated ('.csv'), are considered preservation-friendly. The UK Data Archive provides a useful table of file formats for various types of data. Keep in mind that preservation-friendly files converted from one format to another may lose information (e.g. converting from an uncompressed TIFF file to a compressed JPG file), so changes to file formats should be documented. Identify steps required following project completion in order to ensure the data you are choosing to preserve or share is anonymous, error-free, and converted to recommended formats with a minimal risk of data loss. Read more about anonymization: </span><a href=\"https://researchdata.library.ubc.ca/plan/protect-your-data/\"><span style=\"font-weight: 400;\">UBC Library </span></a><span style=\"font-weight: 400;\">or </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical.aspx\"><span style=\"font-weight: 400;\">UK Data Archive</span></a><span style=\"font-weight: 400;\">.</span><br /><span style=\"font-weight: 400;\"><br />Many repositories cannot accept data that has not been anonymized or de-identified, making de-identifying and cleaning the data necessary steps towards long-term preservation. Always include supporting documentation that describes the anonymization and de-identification procedures carried out.</span>", "type"=>"guidance", "versionable_id"=>"df7b5457-d7ca-413a-bdc7-6833bb3838ed"})
Section.create({"id"=>24787, "title"=>"Sharing and Reuse", "description"=>nil, "number"=>5, "phase_id"=>3930, "modifiable"=>true, "versionable_id"=>"f375d44a-e61a-4a1e-9e8e-4083bd927482"})
Question.create({"id"=>76409, "text"=>"<span style=\"font-weight: 400;\">What data will you be sharing and in what form? (e.g. raw, processed, analyzed, final)</span>", "default_value"=>nil, "number"=>1, "section_id"=>24787, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"637fa97e-da27-4f89-8758-44ce31bb4cc0"})
Question.create({"id"=>76410, "text"=>"What type of repository or storage service are you considering as the host of your shared data?", "default_value"=>nil, "number"=>2, "section_id"=>24787, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"6892f96e-2cd6-406a-931d-7f1be3adbc2d"})
Annotation.create({"id"=>72473, "question_id"=>76410, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">You may wish to share your data in the same repository selected for preservation or choose a different one. </span><a href=\"https://repositoryfinder.datacite.org/\"><span style=\"font-weight: 400;\">DataCite's repository finder tool</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">re3data.org</span></a><span style=\"font-weight: 400;\">, recommended in the preservation section, are also useful to consult here. Scientific Data has some specific recommendations for neuroimaging repositories </span><a href=\"https://www.nature.com/sdata/policies/repositories#neurosci\"><span style=\"font-weight: 400;\">here</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"71083540-1036-418b-8936-d3bddc28b158"})
Question.create({"id"=>76411, "text"=>"<span style=\"font-weight: 400;\">Have you considered what type of end-user license to include with your data?</span>", "default_value"=>nil, "number"=>3, "section_id"=>24787, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"877ce894-0065-423f-8681-aef479f72d1a"})
Annotation.create({"id"=>72474, "question_id"=>76411, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">If data will be shared with any collaborators, then it should have a data license that defines the terms of use. If the data will eventually be published to a data hosting platform, then a creative commons open data license would be applicable. Even though it is &ldquo;open&rdquo; the license can place important constraints on what kind of re-use is allowed. For example, you can restrict access to only non-commercial uses of the data, or you can require that credit be given. </span><a href=\"https://creativecommons.org/about/program-areas/open-data/\"><span style=\"font-weight: 400;\">Click here</span></a><span style=\"font-weight: 400;\"> for more about Creative Commons licenses.&nbsp;<br /></span><br /><span style=\"font-weight: 400;\">If data will be shared on a more restricted basis, e.g. with a closed consortium of collaborators, then a custom data license and usage agreement will be needed. Please consult your institution&rsquo;s research librarian or technology transfer office for assistance. </span><a href=\"https://www.openaire.eu/how-do-i-license-my-research-data\"><span style=\"font-weight: 400;\">Click here</span></a><span style=\"font-weight: 400;\"> to access OpenAIRE&rsquo;s guide &ldquo;How do I license my research data?&rdquo;</span>", "type"=>"guidance", "versionable_id"=>"075caae6-cd3b-4609-b733-13934a3c5395"})
Question.create({"id"=>76412, "text"=>"What steps will be taken to help the research community know that your data exists?", "default_value"=>nil, "number"=>4, "section_id"=>24787, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"17108554-4142-4297-9e81-ce0b98fdd066"})
Annotation.create({"id"=>72475, "question_id"=>76412, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Possibilities include: data registries, repositories, indexes, word-of-mouth, publications. How will the data be accessed (Web service, ftp, etc.)? If possible, choose a repository that will assign a persistent identifier (such as a DOI) to your dataset. This will ensure a stable access to the dataset and make it retrievable by various discovery tools.&nbsp;</span><br /><span style=\"font-weight: 400;\"><br />One of the best ways to refer other researchers to your deposited datasets is to cite them the same way you cite other types of publications. The Digital Curation Centre provides a detailed </span><a href=\"http://www.dcc.ac.uk/resources/how-guides/cite-datasets\"><span style=\"font-weight: 400;\">guide on data citation</span></a><span style=\"font-weight: 400;\">. Some repositories also create links from datasets to their associated papers, increasing the visibility of the publications. Contact your Library for assistance in making your dataset visible and easily accessible (reused from National Institutes of Health,<a href=\"https://grants.nih.gov/grants/sharing_key_elements_data_sharing_plan.pdf\"> Key Elements to Consider in Preparing a Data Sharing Plan Under NIH Extramural Support</a> [2009]). </span>", "type"=>"guidance", "versionable_id"=>"ffa1a70c-efcd-4c4d-889c-d11cc5bb3d57"})
Section.create({"id"=>24788, "title"=>"Responsibilities and Resources", "description"=>nil, "number"=>6, "phase_id"=>3930, "modifiable"=>true, "versionable_id"=>"455680e0-88e7-4021-b3c0-14ce62c7a3a3"})
Question.create({"id"=>76413, "text"=>"<span style=\"font-weight: 400;\">Describe your succession plan, indicating the procedures to be followed and the actions to be taken to ensure the continuation of the data management if significant changes in personnel occur. </span>", "default_value"=>nil, "number"=>1, "section_id"=>24788, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"6c892c76-47d2-48e0-8fe3-ca8234a3591d"})
Annotation.create({"id"=>72476, "question_id"=>76413, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Some examples of events to consider: replacement of principal researcher, change of in responsibility for any researchers or data managers, the departure of students who have finished projects associated with the research material described in this DMP.</span>", "type"=>"guidance", "versionable_id"=>"8df8e11a-29ae-4723-997b-c788805c14f0"})
Section.create({"id"=>24789, "title"=>"Ethics and Legal Compliance", "description"=>nil, "number"=>7, "phase_id"=>3930, "modifiable"=>true, "versionable_id"=>"d8f4a209-6c77-4700-b4db-87d8eb714af2"})
Question.create({"id"=>76414, "text"=>"<span style=\"font-weight: 400;\">If human imaging data are acquired, how will the data be anonymized? Will any defacing techniques be used?</span>", "default_value"=>nil, "number"=>1, "section_id"=>24789, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f0e485b6-c49e-424f-aefa-8527d4326439"})
Annotation.create({"id"=>72477, "question_id"=>76414, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Give examples of the tools or software will you use to clean DICOM headers of personally identifiable information. E.g. </span><a href=\"https://github.com/poldracklab/pydeface\"><span style=\"font-weight: 400;\">PyDeface</span></a><span style=\"font-weight: 400;\"> is a tool that can be used to strip facial structures from the brain. For more detailed de-identification guidance and recommended tools for all types of data, see Portage&rsquo;s</span><a href=\"https://doi.org/10.5281/zenodo.4042023\"><span style=\"font-weight: 400;\"> De-identification Guidance</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"f126d268-0593-4fd9-87c8-e00f39916ffa"})
Question.create({"id"=>76415, "text"=>"<span style=\"font-weight: 400;\">If external data are used in this study, please provide the data license &amp; data use agreement. </span>", "default_value"=>nil, "number"=>2, "section_id"=>24789, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"98239d1d-9dfd-4e6b-b7ae-e5f99c7324bc"})
Annotation.create({"id"=>72478, "question_id"=>76415, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">This can be provided as a link, a description, or as a full copy of appropriate documents.</span>", "type"=>"guidance", "versionable_id"=>"eec62d9f-7614-43d5-b58e-868e1b707805"})
Question.create({"id"=>76416, "text"=>"<span style=\"font-weight: 400;\">Do any other legal, ethical, and intellectual property issues require the creation of any special documents that should be shared with the data, e.g., a LICENSE.txt file?</span>", "default_value"=>nil, "number"=>3, "section_id"=>24789, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"6d76a12f-95cc-49f0-94d9-05dadd58e236"})
Template.create!({"id"=>3871, "title"=>"Alliance Template for Arts-Based Research", "description"=>"<p><span style=\"font-weight: 400;\">This template will assist you in creating a data management plan for arts-based research (ABR). It is intended for researchers and artists who use artistic processes as research methods (i.e., arts-based methods). ABR is used across disciplines and encompasses diverse understandings of the arts, research, and how they intersect. In this template, ABR is an umbrella term for all the ways the arts are adapted to answer research questions, including those described as arts research, artistic research, and research-creation. You can use this template on its own, or in combination with others on the </span><a href=\"../../../\"><span style=\"font-weight: 400;\">DMP Assistant</span></a><span style=\"font-weight: 400;\"> when using arts-based methods with other methodological approaches. </span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>1, "visibility"=>1, "customization_of"=>nil, "family_id"=>352166419, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3928, "title"=>"Alliance Template for Arts-Based Research", "description"=>"<p><span style=\"font-weight: 400;\">This template will assist you in creating a data management plan for arts-based research (ABR). It is intended for researchers and artists who use artistic processes as research methods (i.e., arts-based methods). ABR is used across disciplines and encompasses diverse understandings of the arts, research, and how they intersect. In this template, ABR is an umbrella term for all the ways the arts are adapted to answer research questions, including those described as arts research, artistic research, and research-creation. You can use this template on its own, or in combination with others on the </span><a href=\"https://assistant.portagenetwork.ca/\"><span style=\"font-weight: 400;\">DMP Assistant</span></a><span style=\"font-weight: 400;\"> when using arts-based methods with other methodological approaches. </span></p>", "number"=>1, "template_id"=>3871, "modifiable"=>true, "versionable_id"=>"5ba3ad08-b91a-4194-8d20-d904b09fa950"})
Section.create({"id"=>24769, "title"=>"Data Collection", "description"=>nil, "number"=>1, "phase_id"=>3928, "modifiable"=>true, "versionable_id"=>"61d9e90b-adb7-4fd2-94cb-9ffe4d695cdc"})
Question.create({"id"=>76361, "text"=>"What types of data will you create and/or collect? What methods, arts-based and otherwise, will you use?", "default_value"=>nil, "number"=>1, "section_id"=>24769, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"49aa06dc-7a31-4bf5-a5e1-b74c7bd2ce5f"})
Annotation.create({"id"=>72413, "question_id"=>76361, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Drawings, songs, poems, films, short stories, performances, interactive installations, and social experiences facilitated by artists are examples of data.</span> <span style=\"font-weight: 400;\">Data on artistic processes can include documentation of techniques, stages, and contexts of artistic creation, and the physical materials (e.g., paints, textiles, found objects) and tools (e.g., pencils, the body, musical instruments) used to create artwork.</span> <span style=\"font-weight: 400;\">Other types of data are audio recordings of interviews, transcripts, photographs, videos, field notes, historical documents, social media posts, statistical spreadsheets, and computer code.</span>", "type"=>"example_answer", "versionable_id"=>"9dfcce79-872f-4bbc-9dd3-134114763e48"})
Annotation.create({"id"=>72414, "question_id"=>76361, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Artwork is a prominent type of data in ABR that is commonly used as content for analysis and interpretation. Artworks that exist as, or are documented in, image, audio, video, text, and other types of digital files facilitate research data management. The same applies to preparatory, supplemental, and discarded artworks made in the creation of a principal one. Research findings you create in the form of artwork can be treated as data if you will make them available for researchers, artists, and/or the public to use as data. Information about artistic processes can also be data. Read more on artwork and artistic processes as data at </span><a href=\"https://www.vads.ac.uk/customizations/global/pages/kultur2group/projects/datalookgood/bag.html\"><span style=\"font-weight: 400;\">Kultur II Group</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://researchdata.jiscinvolve.org/wp/2016/11/22/research-data-creative-performing-arts/\"><span style=\"font-weight: 400;\">Jisc</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"ac40886b-4ab5-4955-b29f-b2559d4f9122"})
Question.create({"id"=>76362, "text"=>"Do you plan to use datasets published by others? Where will you collect them from?", "default_value"=>nil, "number"=>2, "section_id"=>24769, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"135a4b6f-657b-4417-b51a-526827f9a3c0"})
Annotation.create({"id"=>72415, "question_id"=>76362, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Researchers and artists can publish their data for others to reuse. Research data repositories and government agencies are sources of published data (e.g., </span><a href=\"https://www.frdr-dfdr.ca/repo/\"><span style=\"font-weight: 400;\">Federated Research Data Repository</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://www.statcan.gc.ca/eng/start\"><span style=\"font-weight: 400;\">Statistics Canada</span></a><span style=\"font-weight: 400;\">). Your university may have its own research data repository. Academic journals may host published data as supplementary material connected to their articles. If you need help finding resources for published data, contact your institution&rsquo;s library or reach out to the Portage DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a>.</span>", "type"=>"guidance", "versionable_id"=>"fdca975e-ca6a-4fe0-9bd2-8ba5ae4cc336"})
Question.create({"id"=>76363, "text"=>"How will you digitally document artwork, artistic processes, and other non-digital data? What conditions, hardware, software, and skills will you need?", "default_value"=>nil, "number"=>3, "section_id"=>24769, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5d918a80-b2ee-4f77-9cba-d452ed164f43"})
Annotation.create({"id"=>72416, "question_id"=>76363, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Non-digital data should be digitized when possible. Digitization is needed for many reasons, including returning artwork to participants, creating records of performances, and depositing data in a repository for reuse. When planning your documentation, consider what conditions (e.g., good lighting, sound dampening), hardware (e.g., microphone, smartphone), software (e.g., video editing program), and specialized skills (e.g., filming techniques, image-editing skills) you will need. High quality documentation will make your data more valuable to you and others.</span>", "type"=>"guidance", "versionable_id"=>"347333e4-156f-4042-a4d5-0993577f41ff"})
Question.create({"id"=>76364, "text"=>"What file formats will your data be created and/or collected in?", "default_value"=>nil, "number"=>4, "section_id"=>24769, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"3839408f-1b49-41ad-98ca-cdff46516377"})
Annotation.create({"id"=>72417, "question_id"=>76364, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Open (i.e., non-proprietary) file formats are preferred when possible because they can be used by anyone, which helps ensure others can access and reuse your data in the future. However, proprietary file formats may be necessary for certain arts-based methods because they have special capabilities for creating and editing images, audio, video, and text. If you use proprietary file formats, try to select industry-standard formats (i.e., those widely used by a given community) or those you can convert to open ones. </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/recommended-formats.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\"> provides a table of recommended and acceptable file formats for various types of data.</span></p>\r\n<br /><span style=\"font-weight: 400;\">Original files of artwork and its documentation should be in uncompressed file formats to maximize data quality. Lower quality file formats can be exported from the originals for other purposes (e.g., presentations). Read more on file formats at </span><a href=\"https://researchdata.library.ubc.ca/plan/format-your-data/\"><span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"e0f9609d-5115-497e-9741-54dbb48af80a"})
Question.create({"id"=>76365, "text"=>"What practices will you use to structure, name, and version-control your files?", "default_value"=>nil, "number"=>5, "section_id"=>24769, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"52998176-e4b0-4079-a986-04c172d5a8f5"})
Annotation.create({"id"=>72418, "question_id"=>76365, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">A poem written to analyze a transcript could be named AnalysisPoem_IV05_v03.doc, meaning version 3 of the analysis poem for the interview with participant 05. Revisions to the poem could be marked with _v04, _v05, etc., or a date stamp (e.g., _20200112, _20200315).</span>", "type"=>"example_answer", "versionable_id"=>"51a1eae1-82ae-40f1-822c-d69a01c6e9d0"})
Annotation.create({"id"=>72419, "question_id"=>76365, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Good data organization includes logical folder hierarchies, informative and consistent naming conventions, and clear version markers for files. File names should contain information (e.g., date stamps, participant codes, version numbers, location, etc.) that helps you sort and search for files and identify the content and right versions of files. Version control means tracking and organizing changes to your data by saving new versions of files you modified and retaining the older versions. Good data organization practices minimize confusion when changes to data are made across time, from different locations, and by multiple people. Read more on file naming and version control at </span><a href=\"https://researchdata.library.ubc.ca/plan/organize-your-data/\"><span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://www2.le.ac.uk/services/research-data/old-2019-12-11/organise-data/version-control\"><span style=\"font-weight: 400;\">University of Leicester</span></a><span style=\"font-weight: 400;\">, and </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/organising.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"542c9875-97e2-4b54-bbd7-eb542e2fefcd"})
Section.create({"id"=>24770, "title"=>"Metadata", "description"=>nil, "number"=>2, "phase_id"=>3928, "modifiable"=>true, "versionable_id"=>"238028bd-3940-4e89-82b4-4bc3aeb85614"})
Question.create({"id"=>76366, "text"=>"What metadata will you create to ensure your data can be interpreted and reused in the future?", "default_value"=>nil, "number"=>1, "section_id"=>24770, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"50d88048-2dc2-4662-8dd4-9ed49bf72e36"})
Annotation.create({"id"=>72420, "question_id"=>76366, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Project-level metadata can include basic information about your project (e.g., title, funder, principal investigator, etc.), research design (e.g., background, research questions, aims, artists or artwork informing your project, etc.) and methodology (e.g., description of artistic process and materials, interview guide, transcription process, etc.). Item-level metadata should include basic information about artworks and their documentation (e.g., creator, date, subject, copyright, file format, equipment used for documentation, etc.).</span>", "type"=>"example_answer", "versionable_id"=>"d9ec85bf-7a57-4a2a-b4a1-263201100ea1"})
Annotation.create({"id"=>72421, "question_id"=>76366, "org_id"=>8, "text"=>"<p><a href=\"https://data.research.cornell.edu/content/writing-metadata\"><span style=\"font-weight: 400;\">Cornell University</span></a><span style=\"font-weight: 400;\"> defines metadata as &ldquo;documentation that describes data&rdquo; (see also </span><a href=\"https://library.concordia.ca/research/data/metadata.php\"><span style=\"font-weight: 400;\">Concordia University Library</span></a><span style=\"font-weight: 400;\">). Creating good metadata includes providing information about your project as well as each item in your database, and any other contextual information needed for you and others to interpret and reuse your data in the future. </span><a href=\"https://www.cessda.eu/Training/Training-Resources/Library/Data-Management-Expert-Guide/2.-Organise-Document/Documentation-and-metadata\"><span style=\"font-weight: 400;\">CESSDA</span></a> <span style=\"font-weight: 400;\">and </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/document.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\"> provide examples of project- and item-level metadata. Because arts-based methods tend to be customized and fluid, describing them in your project-level metadata is important.</span></p>", "type"=>"guidance", "versionable_id"=>"07838a20-5080-4530-aae1-2f5b1ecafaa3"})
Question.create({"id"=>76367, "text"=>"What metadata standard will you use?", "default_value"=>nil, "number"=>2, "section_id"=>24770, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c90f656e-86b1-40d4-bc8f-6b95644ab02d"})
Annotation.create({"id"=>72422, "question_id"=>76367, "org_id"=>8, "text"=>"<a href=\"http://dublincore.org/specifications/\"><span style=\"font-weight: 400;\">Dublin Core</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://ddialliance.org/\"><span style=\"font-weight: 400;\">DDI</span></a><span style=\"font-weight: 400;\"> are two widely used general metadata standards. Discipline-specific standards used by museums and galleries (e.g., </span><a href=\"http://vraweb.org/resources/cataloging-cultural-objects/\"><span style=\"font-weight: 400;\">CCO</span></a><span style=\"font-weight: 400;\">, </span><a href=\"http://core.vraweb.org/index.html\"><span style=\"font-weight: 400;\">VRA Core</span></a><span style=\"font-weight: 400;\">) may be useful to describe artworks at the item level. You can also explore arts-specific data repositories at </span><a href=\"https://www.re3data.org/browse/by-subject/\"><span style=\"font-weight: 400;\">re3data.org</span></a><span style=\"font-weight: 400;\"> to see what metadata standards they use.</span>", "type"=>"example_answer", "versionable_id"=>"07f39f5f-2283-4b8f-86a7-a6738dbf8bb6"})
Annotation.create({"id"=>72423, "question_id"=>76367, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">A metadata standard is a set of established categories you can use to describe your data.</span> <span style=\"font-weight: 400;\">Using one helps ensure your metadata is consistent, structured, and machine-readable, which is essential for depositing data in repositories and making them easily discoverable by search engines. While no specific metadata standard exists for ABR, you can adopt existing general or discipline-specific</span> <span style=\"font-weight: 400;\">ones (for more, see </span><a href=\"https://www.queensu.ca/accessandprivacy/guidance/guidelines/recordkeeping-metadata-requirements\"><span style=\"font-weight: 400;\">Queen&rsquo;s University Library</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"http://www.dcc.ac.uk/resources/metadata-standards\"><span style=\"font-weight: 400;\">Digital Curation Centre</span></a><span style=\"font-weight: 400;\">). For more help finding a suitable metadata standard, you may wish to contact your institution&rsquo;s library or reach out to the Portage DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a>.</span>", "type"=>"guidance", "versionable_id"=>"1ca55ef7-e47c-4afc-8451-87dffb9f110d"})
Question.create({"id"=>76368, "text"=>"How will you consistently create metadata during your project?", "default_value"=>nil, "number"=>3, "section_id"=>24770, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"17d24195-35e3-4a38-bbac-ec5d460e40e4"})
Annotation.create({"id"=>72424, "question_id"=>76368, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">One way to record metadata is to place it in a separate text file (i.e., README file) that will accompany your data and to update it throughout your project. </span><a href=\"https://data.research.cornell.edu/content/readme\"><span style=\"font-weight: 400;\">Cornell University</span></a><span style=\"font-weight: 400;\"> provides a README file template you can adapt. You can also embed item-level metadata in certain files, such as placing contextual information and participant details for an interview in a summary page at the beginning of a transcript. Creating a data list, a spreadsheet that collects all your item-level metadata under key categories, will help you and others easily identify items, their details, and patterns across them. </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/document/data-level/qualitative.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\"> has a data list template you can adapt.</span>", "type"=>"example_answer", "versionable_id"=>"321e496f-be88-4c25-86f9-f43b11a874bd"})
Annotation.create({"id"=>72425, "question_id"=>76368, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Creating metadata should not be left to the end of your project. A plan that lays out how, when, where, and by whom metadata will be captured during your project will help ensure your metadata is accurate, consistent, and complete. You can draw metadata from files you have already created or will create for your project (e.g., proposals, notebooks, interview guides, file properties of digital images). If your arts-based methods shift during your project, make sure to record these changes in your metadata. The same practices for organizing data can be used to organize metadata (e.g., </span><span style=\"font-weight: 400;\">consistent naming conventions, file version markers).</span>", "type"=>"guidance", "versionable_id"=>"5715da0a-d3b1-4e50-ae94-408a2f94e71c"})
Section.create({"id"=>24771, "title"=>"Storage, Backup, and Access", "description"=>nil, "number"=>3, "phase_id"=>3928, "modifiable"=>true, "versionable_id"=>"246bba52-bf9d-4d5a-8e38-b02aa34bc68e"})
Question.create({"id"=>76369, "text"=>"How much storage space will you need for digital data during your project? How long will you store them?", "default_value"=>nil, "number"=>1, "section_id"=>24771, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a4e6c71b-2d6d-45a1-bcc6-2f0e481ce4ca"})
Annotation.create({"id"=>72426, "question_id"=>76369, "org_id"=>8, "text"=>"Estimate the storage space you will need in megabytes, gigabytes, terabytes, etc., and for how long this storage will need to be active. Take into account file size, file versions, backups, and the growth of your data, if you will create and/or collect data over several months or years.", "type"=>"guidance", "versionable_id"=>"84853632-07c0-49f4-9b1e-39c3d35ba1a0"})
Question.create({"id"=>76370, "text"=>"How and where will you store and back up digital data during your project?", "default_value"=>nil, "number"=>2, "section_id"=>24771, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"363804ec-3338-4015-a369-1a2206b15dbe"})
Annotation.create({"id"=>72427, "question_id"=>76370, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Digital data can be stored on optical or magnetic media, which can be removable (e.g., DVDs, USB drives), fixed (e.g., computer hard drives), or networked (e.g., networked drives, cloud-based servers). Each storage method has pros and cons you should consider. Having multiple copies of your data and not storing them all in the same physical location reduces the risk of losing your data. Follow the 3-2-1 backup rule: have at least three copies of your data; store the copies on two different media; keep one backup copy offsite. A regular backup schedule reduces the risk of losing recent versions of your data.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">Securely accessible servers or cloud-based environments with regular backup processes are recommended for your offsite backup copy; however, you should know about the consequences of storing your data outside of Canada, especially in relation to privacy. Data stored in different countries is subject to their laws, which may differ from those in Canada. Ensure your data storage and backup methods align with any requirements of your funder, institution, and research ethics office. Read more on storage and backup practices at the <a href=\"https://www.sheffield.ac.uk/library/rdm/storage\">University of Sheffield Library</a> and <a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\">UK Data Service</a>.&nbsp;</span>", "type"=>"guidance", "versionable_id"=>"355177d3-c7d6-400a-b47b-f9ad68d43993"})
Annotation.create({"id"=>72428, "question_id"=>76370, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Many universities offer networked file storage with automatic backup. </span><a href=\"https://www.computecanada.ca/research-portal/accessing-resources/rapid-access-service/\"><span style=\"font-weight: 400;\">Compute Canada&rsquo;s Rapid Access Service</span></a><span style=\"font-weight: 400;\"> provides principal investigators at Canadian postsecondary institutions a modest amount of storage and other cloud resources for free. Contact your institution&rsquo;s IT services to find out what secure data storage services are available to you.</span>", "type"=>"example_answer", "versionable_id"=>"cb4d0466-fa4a-4382-aa24-2be161882775"})
Question.create({"id"=>76371, "text"=>"How will you store non-digital data during your project?", "default_value"=>nil, "number"=>3, "section_id"=>24771, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"cbee4afb-f351-4df0-8293-3426cf024e3c"})
Annotation.create({"id"=>72429, "question_id"=>76371, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe how you will store your non-digital data and what you will need to do so (e.g., physical space, equipment, special conditions). Include where you will store these data and for how long. Ensure your storage methods for non-digital data align with any requirements of your funder, institution, and research ethics office.</span>", "type"=>"guidance", "versionable_id"=>"c8ae0608-25d4-4f59-b8bb-b8bda32a7253"})
Question.create({"id"=>76372, "text"=>"How will your research team and others transfer, access, and/or modify data during your project?", "default_value"=>nil, "number"=>4, "section_id"=>24771, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"016ab377-9296-433f-80e0-ce8e1ce28946"})
Annotation.create({"id"=>72430, "question_id"=>76372, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Research team members, other collaborators, participants, and independent contractors (e.g., transcriptionists, videographers) are examples of individuals who can transfer, access, and modify data in your project, often from different locations. Ideally, a strategy for these activities facilitates cooperation, ensures data security, and can be adopted with minimal instructions or training. If applicable, your strategy should address how raw data from portable recording devices will be transferred to your project database (e.g., uploading raw video data within 48 hours, then erasing the camera).</span></p>\r\n<p><span style=\"font-weight: 400;\">Relying on email to transfer data is not a robust or secure solution, especially for exchanging large files or artwork, transcripts, and other data with sensitive information. Third-party commercial file sharing services (e.g., Google Drive, Dropbox) are easy file exchange tools, but may not be permanent or secure, and are often located outside Canada. Contact your librarian and IT services to develop a solution for your project.</span></p>", "type"=>"guidance", "versionable_id"=>"14c72d4e-cc5e-4e5b-806c-f6243a9fa5e6"})
Section.create({"id"=>24772, "title"=>"Preservation", "description"=>nil, "number"=>4, "phase_id"=>3928, "modifiable"=>true, "versionable_id"=>"8760a9b2-bfa4-4019-82f8-b142cf5c2663"})
Question.create({"id"=>76373, "text"=>"What are your preservation needs for your digital data?", "default_value"=>nil, "number"=>1, "section_id"=>24772, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"b86359bf-4e3c-4c81-a81f-eb0ce1cd8067"})
Annotation.create({"id"=>72431, "question_id"=>76373, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Preservation means storing data in ways that make them accessible and reuseable to you and others long after your project ends (for more, see </span><a href=\"https://www.ugent.be/en/research/datamanagement/after-research/preservation.htm\"><span style=\"font-weight: 400;\">Ghent University</span></a><span style=\"font-weight: 400;\">). Many factors inform preservation, including policies of funding agencies and academic publishers, an understanding of the enduring value of a dataset, and ethical frameworks informing a project (e.g., making artwork co-created with community members accessible to their community).&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">Creating a &ldquo;living will&rdquo; for your data can help you decide what your preservation needs</span> <span style=\"font-weight: 400;\">are in relation to these or other factors. It is a plan describing how future researchers, artists, and others will be able to access and reuse your data. If applicable, consider the needs of participants and collaborators who will co-create and/or co-own artwork and other data. Your &ldquo;living will&rdquo; can address where you will store your data, how they will be accessed, how long they will be accessible for, and how much digital storage space you will need.</span>", "type"=>"guidance", "versionable_id"=>"dbb3bbe4-6c2e-4c76-97a2-2e825b51b91d"})
Question.create({"id"=>76374, "text"=>"Where will you preserve your research data for the long-term, if needed?", "default_value"=>nil, "number"=>2, "section_id"=>24772, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a05eff74-8429-457b-b8cd-b2ada451dbf9"})
Annotation.create({"id"=>72432, "question_id"=>76374, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Deposit in a data repository is one way to preserve your data, but keep in mind that not all repositories have a preservation mandate. Many repositories focus on sharing data, not preserving them, meaning they will store and make your data accessible for a few years, but not long term. It can be difficult to distinguish repositories with preservation services from those without, so carefully read the policies of repositories you are considering for preservation and, if possible, before your project begins. If you need or want to place special conditions on your data, check if the repository will accommodate them and, if so, get written confirmation. Read more on choosing a repository at </span><a href=\"https://www.openaire.eu/opendatapilot-repository-guide\"><span style=\"font-weight: 400;\">OpenAIRE</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"e6f35970-2cac-41b5-b5ed-7ef391572227"})
Annotation.create({"id"=>72433, "question_id"=>76374, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Data repositories labelled as &ldquo;trusted&rdquo; or &ldquo;trustworthy&rdquo; indicate they have met high standards for receiving, storing, accessing, and preserving data through an external certification process. Two certifications are </span><a href=\"https://www.crl.edu/archiving-preservation/digital-archives/metrics\"><span style=\"font-weight: 400;\">Trustworthy Digital Repository</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.coretrustseal.org/\"><span style=\"font-weight: 400;\">CoreTrustSeal</span></a><span style=\"font-weight: 400;\">.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">A repository that lacks certification may still be a valid preservation option. Many established repositories in Canada have not gone through a certification process yet. For repositories without certification, you can evaluate their quality by comparing their policies to the standards of a certification. Read more on trusted data repositories at the </span><a href=\"https://www.ed.ac.uk/information-services/research-support/research-data-service/after/data-repository/trustworthy-digital-repository\">University of Edinburgh</a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.openaire.eu/find-trustworthy-data-repository\"><span style=\"font-weight: 400;\">OpenAIRE</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"example_answer", "versionable_id"=>"62bcfe39-5c6a-4547-a74b-fbb009bd5ded"})
Question.create({"id"=>76375, "text"=>"How will you ensure your digital data is preservation ready?", "default_value"=>nil, "number"=>3, "section_id"=>24772, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"8b976a44-307a-4770-85b8-1edd0b66b82e"})
Annotation.create({"id"=>72434, "question_id"=>76375, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Open file formats are considered preservation-friendly because of their accessibility. Proprietary file formats are not optimal for preservation because they can have accessibility barriers (e.g., needing specialized licensed software to open). Keep in mind that preservation-friendly files converted from one format to another may lose information (e.g., converting from an uncompressed TIFF file to a compressed JPEG file), so any changes to file formats should be documented and double checked. See </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format/recommended-formats.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\"> for a list of preservation-friendly file formats.</span>", "type"=>"example_answer", "versionable_id"=>"9ecfc004-9743-4f9b-a163-1a75930dbe65"})
Annotation.create({"id"=>72435, "question_id"=>76375, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Converting to preservation-friendly file formats, checking for unintended changes to files, confirming metadata is complete, and gathering supporting documents are practices, among others, that will help ensure your data are ready for preservation.</span>", "type"=>"guidance", "versionable_id"=>"95cf81a3-e6e6-4f61-9ebc-54cde0ab5f0c"})
Question.create({"id"=>76376, "text"=>"What are your preservation needs for your non-digital data?", "default_value"=>nil, "number"=>4, "section_id"=>24772, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"730ca1e5-18a4-4227-8912-f685f77ed244"})
Annotation.create({"id"=>72436, "question_id"=>76376, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Sometimes non-digital data cannot be digitized or practical limitations (e.g., cost) prevent them from being digitized. If you want others to access and reuse your non-digital data, consider where they will be stored, how they will be accessed, and how long they will be accessible for. Sometimes, you can deposit your data in an archive, which will take responsibility for preservation and access. If non-archivists (e.g., you, a partner community centre) take responsibility for preservation, describe how your non-digital data will be protected from physical deterioration over time. Make sure to incorporate non-digital data into the &ldquo;living will&rdquo; for your data. Contact the archives at your institution for help developing a preservation strategy for non-digital data. Read more on preserving non-digital data at </span><a href=\"https://www.ru.nl/rdm/archiving-data/archiving-non-digital-data/\"><span style=\"font-weight: 400;\">Radboud University</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"b856d87b-25f0-4146-a0e2-d26b1cc888b0"})
Question.create({"id"=>76377, "text"=>"Are there data you will need or choose to destroy? If so, how will you destroy them securely?", "default_value"=>nil, "number"=>5, "section_id"=>24772, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0a169a59-ba1b-46b8-b784-a1a7526461c0"})
Annotation.create({"id"=>72437, "question_id"=>76377, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Certain data may not have long-term value, may be too sensitive for preservation, or must be destroyed due to data agreements. Deleting files from your computer is not a secure method of data disposal. Contact your IT services, research ethics office, and/or privacy office to find out how you can securely destroy your data. Read more on secure data disposal at </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store/disposal.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"8ff55717-6e07-4cff-a677-f9bb55175721"})
Section.create({"id"=>24773, "title"=>"Sharing and Reuse", "description"=>nil, "number"=>5, "phase_id"=>3928, "modifiable"=>true, "versionable_id"=>"d5f5f383-b15f-4912-8b57-9b9bef463a61"})
Question.create({"id"=>76378, "text"=>"What types of data will you share and in what form?", "default_value"=>nil, "number"=>1, "section_id"=>24773, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0f9989f8-e862-4b46-8fff-f06f742d2664"})
Annotation.create({"id"=>72438, "question_id"=>76378, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Your shared data can be in different forms:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><strong>Raw data</strong><span style=\"font-weight: 400;\"> are the original, unaltered data obtained directly from data collection methods (e.g., image files from cameras, audio files from digital recorders). In the context of your project, published data you reuse count as raw data.</span></li>\r\n<li style=\"font-weight: 400;\"><strong>Processed data</strong><span style=\"font-weight: 400;\"> are raw data that have been modified to, for example, prepare for analysis (e.g., removing video that will not be analyzed) or de-identify participants (e.g., blurring faces, cropping, changing voices).</span><span style=\"font-weight: 400;\">&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\"><strong>Analyzed data</strong><span style=\"font-weight: 400;\"> are the results of arts-based, qualitative, or quantitative analyses of processed data, and include artworks, codebooks, themes, texts, diagrams, graphs, charts, and statistical tables.</span></li>\r\n<li style=\"font-weight: 400;\"><strong>Final data</strong><span> are copies of raw, processed, or analyzed data you are no longer working with. These copies may have been migrated or transformed from their original file formats into preservation-friendly formats.</span></li>\r\n</ul>", "type"=>"example_answer", "versionable_id"=>"54d8c57a-ee62-43c9-9675-a84f565633a7"})
Annotation.create({"id"=>72439, "question_id"=>76378, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Sharing means making your data available to people outside your project (for more, see </span><a href=\"https://www.ugent.be/en/research/datamanagement/after-research/sharing.htm\"><span style=\"font-weight: 400;\">Ghent University</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://instr.iastate.libguides.com/dmp/step6\"><span style=\"font-weight: 400;\">Iowa State University</span></a><span style=\"font-weight: 400;\">). Of all the types of data you will create and/or collect (e.g., artwork, field notes), consider which ones you need to share to fulfill institutional or funding policies, the ethical framework of your project, and other requirements and considerations. You generally need participant consent to share data, and your consent form should state how your data will be shared, accessed, and reused.</span>", "type"=>"guidance", "versionable_id"=>"c64198af-dd08-417d-b92e-77b4a9e895df"})
Question.create({"id"=>76379, "text"=>"Will you need to share some data with restricted access? What restrictions will you apply?", "default_value"=>nil, "number"=>2, "section_id"=>24773, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"263b3a05-17fa-4d96-b6e4-629fa834c748"})
Annotation.create({"id"=>72440, "question_id"=>76379, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe which forms of data (e.g., raw, processed) you will share with restricted access due to confidentiality, privacy, intellectual property, and other legal or ethical considerations and requirements. Remember to inform participants of any restrictions you will implement to protect their privacy and to state them on your consent form. Read more on restricted access at </span><a href=\"https://www.york.ac.uk/library/research-creativity/rdm/\"><span style=\"font-weight: 400;\">University of York</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"88b400f4-ceb6-48ef-b60a-ba384413ded3"})
Question.create({"id"=>76380, "text"=>"Who owns the data you will use in your project? Will the ownership of these data affect their sharing and reuse?", "default_value"=>nil, "number"=>3, "section_id"=>24773, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"23d0be2b-b4dd-49ef-a063-1c4132812686"})
Annotation.create({"id"=>72441, "question_id"=>76380, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">List the owners of the data in your project (i.e., those who hold the intellectual property rights), such as you, collaborators, participants, and the owners of published data you will reuse. Consider how ownership will affect the sharing and reuse of data in your project. For example, existing licenses attached to copyrighted materials that you, collaborators, or participants incorporate into new artwork may prevent its sharing or allow it with conditions, like creator attribution, non-commercial use, and restricted access.</span></p>", "type"=>"guidance", "versionable_id"=>"aa6d38e5-471d-4ae7-b33d-97fb63f3b6af"})
Question.create({"id"=>76381, "text"=>"What type of end-user license will you include with your data?", "default_value"=>nil, "number"=>4, "section_id"=>24773, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a3a43915-3130-4c28-8378-210b5691167a"})
Annotation.create({"id"=>72442, "question_id"=>76381, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Several types of standard licenses are available to researchers, such as </span><a href=\"https://creativecommons.org/choose/\"><span style=\"font-weight: 400;\">Creative Commons licenses</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://opendatacommons.org/licenses/\"><span style=\"font-weight: 400;\">Open Data Commons licenses</span></a><span style=\"font-weight: 400;\">. In most circumstances, it is easier to use a standard license rather than a custom-made one. If you make your data part of the public domain, you should make this explicit by using a license, such as </span><a href=\"https://creativecommons.org/publicdomain/zero/1.0/\"><span style=\"font-weight: 400;\">Creative Commons CC0</span></a><span style=\"font-weight: 400;\">. Read more on data licenses at </span><a href=\"https://www.dcc.ac.uk/guidance/how-guides/license-research-data\"><span style=\"font-weight: 400;\">Digital Curation Centre</span></a><span style=\"font-weight: 400;\">. </span>", "type"=>"example_answer", "versionable_id"=>"75edfde8-29ca-47b3-8c2d-97eb6e3a0663"})
Annotation.create({"id"=>72443, "question_id"=>76381, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Include a copy of your end-user license here. Licenses set out how others can use your data. Funding agencies and/or data repositories may have end-user license requirements in place; if not, they may be able to guide you in developing a license. Only the intellectual property rights holder(s) of the data you want to share can issue a license, so it is crucial to clarify who holds those rights. Make sure the terms of use of your end-user license fulfill any legal and ethical obligations you have (e.g., consent forms, copyright, data sharing agreements, etc.).</span>", "type"=>"guidance", "versionable_id"=>"ca664c91-5ac5-4126-a998-8e41c703edf3"})
Question.create({"id"=>76382, "text"=>"How will researchers, artists, and/or the public find your data?", "default_value"=>nil, "number"=>5, "section_id"=>24773, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"ebc83e7c-0e43-447e-9b83-c07ff8df7670"})
Annotation.create({"id"=>72444, "question_id"=>76382, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Many Canadian postsecondary institutions use Dataverse, a popular data repository platform for survey data and qualitative text data (for more, see </span><a href=\"https://dataverse.scholarsportal.info/\"><span style=\"font-weight: 400;\">Scholars Portal)</span></a><span style=\"font-weight: 400;\">. It has many capabilities, including open and restricted access, built-in data citations, file versioning, customized terms of use, and assignment of a </span><a href=\"https://en.wikipedia.org/wiki/Digital_object_identifier\"><span style=\"font-weight: 400;\">digital object identifier</span></a><span style=\"font-weight: 400;\"> (DOI) to datasets. A DOI is a unique, persistent identifier that provides a stable link to your data. Try to choose repositories that assign persistent identifiers. Contact your institution&rsquo;s library or the Portage DMP Coordinator at <a href=\"mailto:support@portagenetwork.ca\">support@portagenetwork.ca</a>&nbsp;to find out if a local Dataverse is available to you, or for help locating another repository that meets your needs. You can also check out <a href=\"https://www.re3data.org/\">re3data.org</a>, a directory of data repositories that includes arts-specific ones.</span>", "type"=>"example_answer", "versionable_id"=>"2f9bedb3-4ac5-49fc-b692-fcb9f9fdd7d7"})
Annotation.create({"id"=>72445, "question_id"=>76382, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Researchers can find data through data repositories, word-of-mouth, project websites, academic journals, etc. Sharing your data through a data repository is recommended because it enhances the discoverability of your data in the research community. You can also cite your deposited data the same way you would cite a publication, by including a link in the citation. Read more on data citation at </span><a href=\"https://www.ukdataservice.ac.uk/citethedata.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.dcc.ac.uk/guidance/how-guides/cite-datasets\"><span style=\"font-weight: 400;\">Digital Curation Centre</span></a><span style=\"font-weight: 400;\">.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">The best ways to let artists and the public know about your data may not mirror those of researchers. Social media, artistic organizations, and community partners may be options. For more help making your data findable, contact your institution&rsquo;s library or the Portage DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a>.&nbsp;&nbsp;</span></p>", "type"=>"guidance", "versionable_id"=>"36d0a222-c39b-4f05-9a1b-ec162adf3707"})
Section.create({"id"=>24774, "title"=>"Responsibilities and Resources", "description"=>nil, "number"=>6, "phase_id"=>3928, "modifiable"=>true, "versionable_id"=>"242249ed-d805-4ef8-a1d9-df8fb24c40e7"})
Question.create({"id"=>76383, "text"=>"Who will be responsible for research data management during and after your project? What will their tasks be?", "default_value"=>nil, "number"=>1, "section_id"=>24774, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5cc4fd8f-5548-4cd1-b317-4587e75521da"})
Annotation.create({"id"=>72446, "question_id"=>76383, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Research data management is often a shared responsibility, which can involve principal investigators, co-investigators, collaborators, graduate students, data repositories, etc. Describe the roles and responsibilities of those who will carry out the activities of your data management plan, whether they are individuals or organizations, and</span> <span style=\"font-weight: 400;\">the timeframe of their responsibilities. Consider who can conduct these activities in relation to data management expertise, time commitment, training needed to carry out tasks, and other factors.</span></p>", "type"=>"guidance", "versionable_id"=>"3933cd31-1fd2-40c0-909d-fd1b859a002e"})
Question.create({"id"=>76384, "text"=>"If responsibility for research data management needs to be transferred to other individuals or organizations, who will assume responsibility and how?", "default_value"=>nil, "number"=>2, "section_id"=>24774, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f3ba4d05-7375-4be4-85b5-af103c367172"})
Annotation.create({"id"=>72447, "question_id"=>76384, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Expected and unexpected changes to who manages data during your project (e.g., a student graduates, research staff turnover) and after (e.g., retirement, death, agreement with data repository ends) can happen. A succession plan details how research data management responsibilities will transfer to other individuals or organizations. Consider what will happen if the principal investigator, whether you or someone else, leaves the project. In some instances, a co-investigator or the department or division overseeing your project can assume responsibility. Your post-project succession plan can be part of the &ldquo;living will&rdquo; for your data.</span>", "type"=>"guidance", "versionable_id"=>"81329dc8-50a9-4471-86bd-7833fe92d66d"})
Question.create({"id"=>76385, "text"=>"What resources will you need to implement your data management plan? How much will they cost?", "default_value"=>nil, "number"=>3, "section_id"=>24774, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4e9cff16-21e6-4eb7-8f22-4ecb2edf0a89"})
Annotation.create({"id"=>72448, "question_id"=>76385, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Know what resources you will need for research data management during and after your project and their estimated cost as early as possible. For example, transcription, training for research team members, digitizing artwork, cloud storage, and depositing your data in a repository can all incur costs. Many funding agencies provide financial support for data management, so check what costs they will cover. Read more on costing data management at </span><a href=\"https://www.dcc.ac.uk/blog/infographic-what-will-it-cost-manage-and-share-my-data\"><span style=\"font-weight: 400;\">Digital Curation Centre</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.openaire.eu/how-to-comply-to-h2020-mandates-rdm-costs\"><span style=\"font-weight: 400;\">OpenAIRE</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"33c37ba5-5bfb-4be3-9cda-42336926d2c1"})
Section.create({"id"=>24775, "title"=>"Ethics and Legal Compliance", "description"=>nil, "number"=>7, "phase_id"=>3928, "modifiable"=>true, "versionable_id"=>"23e1af42-0008-47ff-94ae-8f9f53983583"})
Question.create({"id"=>76386, "text"=>"Are there policies that outline requirements and/or best practices pertaining to your research data management?", "default_value"=>nil, "number"=>1, "section_id"=>24775, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"27b42dbf-c1a5-46a2-be89-c05a6c0cf81f"})
Annotation.create({"id"=>72449, "question_id"=>76386, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Research data management policies can be set by funders, postsecondary institutions, legislation, communities of researchers, and research data management specialists. List policies relevant to managing your data, including those of your institution and the Tri-Agency Research Data Management Policy, if you have SSHRC, CIHR, or NSERC funding. Include URL links to these policies. </span>", "type"=>"guidance", "versionable_id"=>"3687ffa9-0dc5-44f6-b1c5-c80d5539fc3f"})
Question.create({"id"=>76387, "text"=>"What ethical and legal issues will affect your data? How will you address them?", "default_value"=>nil, "number"=>2, "section_id"=>24775, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0941c12d-0a14-446e-bc59-082fa7f9d1bd"})
Annotation.create({"id"=>72450, "question_id"=>76387, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Compliance with privacy and copyright law is a common issue in ABR and may restrict what data you can create, collect, preserve, and share. Familiarity with Canadian copyright law is especially important in ABR (see </span><a href=\"https://laws-lois.justice.gc.ca/eng/acts/c-42/\"><span style=\"font-weight: 400;\">Copyright Act of Canada</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://www.ic.gc.ca/eic/site/cipointernet-internetopic.nsf/eng/h_wr02281.html\"><span style=\"font-weight: 400;\">Canadian Intellectual Property Office</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://educaloi.qc.ca/en/capsules/copyright-protecting-creative-works/\"><span style=\"font-weight: 400;\">&Eacute;ducaloi</span></a><span style=\"font-weight: 400;\">, and </span><a href=\"https://artistslegaloutreach.com/copyright-toolkits/\"><span style=\"font-weight: 400;\">Artists&rsquo; Legal Outreach</span></a><span style=\"font-weight: 400;\">). Obtaining permissions is key to managing privacy and copyright compliance and will help you select or develop an end-user license.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">It is also important to know about ethical and legal issues pertaining to the cultural context(s) in which you do ABR. For example, Indigenous data sovereignty and governance are essential to address in all aspects of research data management in projects with and affecting First Nations, Inuit, and M&eacute;tis communities and lands (see </span><a href=\"https://fnigc.ca/\"><span style=\"font-weight: 400;\">FNIGC</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://www.itk.ca/\"><span style=\"font-weight: 400;\">ITK</span></a><span style=\"font-weight: 400;\">, and </span><a href=\"https://www.gida-global.org/\"><span style=\"font-weight: 400;\">GIDA</span></a><span style=\"font-weight: 400;\">), including collective ownership of traditional knowledge and cultural expressions (see </span><a href=\"https://guides.library.ubc.ca/c.php?g=383361&amp;p=2597611%23s-lg-box-8105430\"><span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.ic.gc.ca/eic/site/108.nsf/eng/00007.html\"><span style=\"font-weight: 400;\">ISED Canada</span></a><span style=\"font-weight: 400;\">). Experts at your institution can help you address ethical and legal issues, such as those at your library, privacy office, research ethics office, or copyright office.</span>", "type"=>"guidance", "versionable_id"=>"15c1fd54-030b-4e04-a9dd-1671ea16c370"})
Annotation.create({"id"=>72451, "question_id"=>76387, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Obtaining permissions to create, document, and use artwork in ABR can be complex when, for example, non-participants are depicted in artwork or artwork is co-created or co-owned, made by minors, or derived from other copyrighted work (e.g., collages made of photographs, remixed songs).</span> <span style=\"font-weight: 400;\">Consider creating a plan describing how you will obtain permissions for your project. It should include what you want to do (e.g., create derivative artwork, deposit data); who to ask when permission is needed for what you want to do; and, if granted, what the conditions are. </span>", "type"=>"example_answer", "versionable_id"=>"8b56eb85-d3e6-4c87-ba6e-e829e797ad31"})
Question.create({"id"=>76388, "text"=>"If your project includes sensitive data, how will you ensure they are securely managed and accessible only to approved individuals during your project?", "default_value"=>nil, "number"=>3, "section_id"=>24775, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d9bbc535-e385-41c8-802d-6da2aff0d992"})
Annotation.create({"id"=>72452, "question_id"=>76388, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Security measures for sensitive data include password protection, encryption, and limiting physical access to storage devices. Sensitive data should never be shared via email or cloud storage services not approved by your research ethics office. Security measures for sensitive non-digital data include storage under lock and key, and logging removal and return of artwork from storage.</span>", "type"=>"example_answer", "versionable_id"=>"c50a8a39-054c-4bd8-b92e-3c218f0cfb0f"})
Annotation.create({"id"=>72453, "question_id"=>76388, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Sensitive data is any data that may negatively impact individuals, organizations, communities, institutions, and businesses if publicly disclosed. Copyrighted artwork, Indigenous cultural expressions, and personal identifiers in artwork or its documentation can be examples of sensitive data in ABR. Your data security measures should be proportional to the sensitivity of your data: the more sensitive your data, the more data security you need.</span> <span style=\"font-weight: 400;\">Read more on sensitive data and data security at </span><a href=\"https://research.mcmaster.ca/home/support-for-researchers/ethics/mcmaster-research-ethics-board-mreb/mreb-data-storage-and-security-tools/\"><span style=\"font-weight: 400;\">Data Storage and Security Tools (PDF) by McMaster Research Ethics Board</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://www.openaire.eu/sensitive-data-guide\"><span style=\"font-weight: 400;\">OpenAIRE</span></a><span style=\"font-weight: 400;\">, and </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store/security.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>"72f0d1a7-d993-48c2-8a94-7dfb20dd1cd7"})
Question.create({"id"=>76389, "text"=>"If you will share sensitive data, what issues do you need to address? How will you address them?", "default_value"=>nil, "number"=>4, "section_id"=>24775, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"47394078-ffc7-4cb5-87da-dc1d26238682"})
Annotation.create({"id"=>72454, "question_id"=>76389, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Removing direct and indirect identifiers from data is a common strategy to manage sensitive data. However, some strategies to remove identifiers in images, audio, and video also remove information of value to others (e.g., facial expressions, context, tone of voice). Consult your research ethics office to find out if solutions exist to retain such information. Read more on de-identifying data at </span><a href=\"https://researchdata.library.ubc.ca/share/anonymize-and-de-identify/\"><span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical/anonymisation/qualitative.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"example_answer", "versionable_id"=>"f4009153-a74a-41a0-8f7e-6e4513d86c5e"})
Annotation.create({"id"=>72455, "question_id"=>76389, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Sensitive data can still be shared and reused if strategies are in place to protect against unauthorized disclosure and the problems that can rise from it. Obtain the consent of participants to share and reuse sensitive data beyond your project. Your consent form should state how sensitive data will be protected when shared, accessed, and reused. Strategies to reduce the risk of public disclosure are de-identifying data and implementing access restrictions on deposited data. Make sure to address types of sensitive data beyond personal identifiers of participants. Your strategies should align with requirements of your research ethics office, institution, and, if applicable, legal agreements for sharing data. Consult your research ethics office if you need help identifying problems and strategies.</span></p>", "type"=>"guidance", "versionable_id"=>"2fa619b7-41c0-4d14-b2de-4c95d3121444"})
Template.create!({"id"=>3875, "title"=>"Alliance Template for Studying Molecular Interactions", "description"=>"<p><span style=\"font-weight: 400;\">The following template is intended for research projects combining experimental (scientific) methods with computer modeling/simulation to study molecular interactions. </span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>1, "visibility"=>1, "customization_of"=>nil, "family_id"=>674550998, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3933, "title"=>"Alliance Template for Studying Molecular Interactions", "description"=>"<p><span style=\"font-weight: 400;\">The following template is intended for research projects combining experimental (scientific) methods with computer modeling/simulation to study molecular interactions. </span></p>", "number"=>1, "template_id"=>3875, "modifiable"=>true, "versionable_id"=>"6ab2d2c7-c1d4-4379-b478-c8edfab0e98e"})
Section.create({"id"=>24804, "title"=>"Data Production", "description"=>nil, "number"=>1, "phase_id"=>3933, "modifiable"=>true, "versionable_id"=>"30ab6347-9286-4236-b292-c12f3471765a"})
Question.create({"id"=>76484, "text"=>"What type(s) of data will be produced and in what format(s)?", "default_value"=>nil, "number"=>1, "section_id"=>24804, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"ab67b7f4-714b-4da2-af3c-60411169fa9f"})
Annotation.create({"id"=>72546, "question_id"=>76484, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Examples of experimental image data may include: Magnetic Resonance (MR), X-ray, Fluorescent Resonance Energy Transfer (FRET), Fluorescent Lifetime Imaging (FLIM), Atomic-Force Microscopy (AFM), Electron Paramagnetic Resonance (EPR), Laser Scanning Microscope (LSM), Extended X-ray Absorption Fine Structure (EXAFS), Femtosecond X-ray, Raman spectroscopy, or other digital imaging methods. </span>", "type"=>"example_answer", "versionable_id"=>"80386c7d-6d15-4c8c-b70a-9782970c3820"})
Annotation.create({"id"=>72547, "question_id"=>76484, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Describe the type(s) of data that will be collected, such as: text, numeric (ASCII, binary), images, and animations.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">List the file formats you expect to use. Keep in mind that some file formats are optimal for the long-term preservation of data, for example, non-proprietary formats such as text ('.txt'), comma-separated ('.csv'), TIFF (&lsquo;.tiff&rsquo;), JPEG (&lsquo;.jpg&rsquo;), and MPEG-4 (&lsquo;.m4v&rsquo;, &lsquo;mp4&rsquo;). Files converted from one format to another for archiving and preservation may lose information (e.g. converting from an uncompressed TIFF file to a compressed JPG file), so changes to file formats should be documented. Guidance on file formats recommended for sharing and preservation are available from the </span><a href=\"https://ukdataservice.ac.uk/learning-hub/research-data-management/\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://guides.library.cornell.edu/ecommons/formats\"><span style=\"font-weight: 400;\">Cornell&rsquo;s Digital Repository</span></a><span style=\"font-weight: 400;\">, the </span><a href=\"https://www.ed.ac.uk/information-services/research-support/research-data-service/after/data-repository/choosing-file-formats\"><span style=\"font-weight: 400;\">University of Edinburgh</span></a><span style=\"font-weight: 400;\">, and the </span><a href=\"https://researchdata.library.ubc.ca/plan/format-your-data/\"><span style=\"font-weight: 400;\">University of British Columbia</span></a><span style=\"font-weight: 400;\">. </span>", "type"=>"guidance", "versionable_id"=>"4c249ccd-12cf-4049-b06c-207bb7892b50"})
Question.create({"id"=>76485, "text"=>"Does this project involve the use or analysis of secondary data? What is the data-sharing arrangement for these data?", "default_value"=>nil, "number"=>2, "section_id"=>24804, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"3c4a84ea-35ab-4e3c-9481-6658e44c47b8"})
Annotation.create({"id"=>72548, "question_id"=>76485, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Describe any secondary data you expect to reuse. List any available documentation, licenses, or terms of use assigned. If the data have a DOI or unique accession number, include that information and the name of the repository or database that holds the data. This will allow you to easily navigate back to the data, and properly cite and acknowledge the data creators in any publication or research output.&nbsp;&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">For data that are not publicly available, you may have entered into a data-sharing arrangement with the data owner, which should be noted here.&nbsp; A data-sharing arrangement describes what data are being shared and how the data can be used. It can be a license agreement or any other formal agreement, for example, an agreement to use copyright-protected data. </span></p>", "type"=>"guidance", "versionable_id"=>"dcc9b366-e2cb-4c4a-bca1-1f04b0cd0d9f"})
Annotation.create({"id"=>72549, "question_id"=>76485, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">An example of experimental data from a secondary data source may be structures or parameters obtained from </span><a href=\"https://www.rcsb.org/pages/about-us/index\"><span style=\"font-weight: 400;\">Protein Data Bank</span></a><span style=\"font-weight: 400;\"> (PDB).&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Examples of computational data and data sources may include: log files, parameters, structures, or trajectory files from previous modeling/simulations or tests. </span></p>", "type"=>"example_answer", "versionable_id"=>"fd6a7d30-85b2-4b7f-ba9a-96866b5721bb"})
Question.create({"id"=>76486, "text"=>"What tools, devices, platforms, and/or software packages will be used to generate and manipulate data during the project?", "default_value"=>nil, "number"=>3, "section_id"=>24804, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7f80ec41-591c-4737-8408-1a97ce128e49"})
Annotation.create({"id"=>72550, "question_id"=>76486, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">List all devices and/or instruments and describe the experimental setup (if applicable) that will be utilized to collect empirical data. For commercial instruments or devices, indicate the brand, type, and other necessary characteristics for identification. For a home-built experimental setup, list the components, and describe the functional connectivity. Use diagrams when essential for clarity.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Indicate the program and software package with the version you will use to prepare a structure or a parameter file for modeling or simulation. If web-based services such as </span><a href=\"http://falcon.ictbda.cn:89/\"><span style=\"font-weight: 400;\">FALCON@home</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://www.vlifesciences.com/products/VLifeMDS/Protein_Modeller.php\"><span style=\"font-weight: 400;\">ProModel</span></a><span style=\"font-weight: 400;\">, </span><a href=\"http://www.charmm-gui.org/\"><span style=\"font-weight: 400;\">CHARMM-GUI</span></a><span style=\"font-weight: 400;\">, etc. will be used to prepare or generate data, provide details such as the name of the service, URL, version (if applicable), and description of how you plan to use it.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">If you plan to use your own software or code, specify where and how it can be obtained to independently verify computational outputs and reproduce figures by providing the DOI, link to GitHub, or another source. Specify if research collaboration platforms such as </span><a href=\"https://codeocean.com/\"><span style=\"font-weight: 400;\">CodeOcean</span></a><span style=\"font-weight: 400;\">, or </span><a href=\"https://wholetale.org/\"><span style=\"font-weight: 400;\">WholeTale</span></a><span style=\"font-weight: 400;\"> will be used to create, execute, and publish computational findings. </span>", "type"=>"guidance", "versionable_id"=>"f084e269-7304-4fac-b32b-ac62b0acf88e"})
Question.create({"id"=>76487, "text"=>"Describe the data flow through the entire project. What steps will you take to increase the likelihood that your results will be reproducible?", "default_value"=>nil, "number"=>4, "section_id"=>24804, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"37dd29f3-612e-466f-80d6-4a386d2cf598"})
Annotation.create({"id"=>72551, "question_id"=>76487, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Reproducible computational practices are critical to continuing progress within the discipline. At a high level, describe the steps you will take to ensure computational reproducibility in your project, including the operations you expect to perform on the data, and the path taken by the data through systems, devices, and/or procedures. Describe how an instrument response function will be obtained, and operations and/or procedures through which data (research and computational outputs) can be replicated. Indicate what documentation will be provided to ensure the reproducibility of your research and computational outputs.</span>", "type"=>"guidance", "versionable_id"=>"f688b884-f96e-4757-ab52-c5af219f3bf5"})
Annotation.create({"id"=>72552, "question_id"=>76487, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Some examples of data procedures include: data normalization, data fitting, data convolution, or Fourier transformation.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Examples of documentation may include: syntax, code, algorithm(s), parameters, device log files, or manuals.&nbsp; </span></p>", "type"=>"example_answer", "versionable_id"=>"994ee138-55e1-4404-82b3-57e2878e029c"})
Section.create({"id"=>24805, "title"=>"Documentation and Metadata", "description"=>nil, "number"=>2, "phase_id"=>3933, "modifiable"=>true, "versionable_id"=>"04d3a032-fbc9-440d-89e5-5bf25780efac"})
Question.create({"id"=>76488, "text"=>"What documentation will be needed for the data to be read and interpreted correctly in the future?", "default_value"=>nil, "number"=>1, "section_id"=>24805, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f0604451-12b1-47f9-8e12-c73cd389af5e"})
Annotation.create({"id"=>72553, "question_id"=>76488, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Documentation can be provided in the form of a README file with information to ensure the data can be correctly interpreted by you or by others when you share or publish your data. Typically, a README file includes a description (or abstract) of the study, and any other contextual information required to make data usable by other researchers. Other information could include: research methodology used, variable definitions, vocabularies, units of measurement, assumptions made, format and file type of the data, a description of the data origin and production, an explanation of data file formats that were converted, a description of data analysis performed, a description of the computational environment, references to external data sources, details of who worked on the project and performed each task. Further guidance on writing README files is available from the University of British Columbia (</span><a href=\"https://osf.io/sczv5\"><span style=\"font-weight: 400;\">UBC</span></a><span style=\"font-weight: 400;\">) and </span><a href=\"https://data.research.cornell.edu/content/readme\"><span style=\"font-weight: 400;\">Cornell</span></a><span style=\"font-weight: 400;\"> University.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Consider also saving detailed information during the course of the project in a log file. A log file will help to manage and resolve issues that arise during a project and prioritize the response to them. It may include events that occur in an operating system, messages between users, run time and error messages for troubleshooting. The level of detail in a log file depends on the complexity of your project. </span></p>", "type"=>"guidance", "versionable_id"=>"a961d0b7-d516-4014-b774-8174d3336c95"})
Question.create({"id"=>76489, "text"=>"How will you make sure that documentation is created or captured consistently throughout your project? What approaches will be employed by the research team to access, modify, and contribute data throughout the project?", "default_value"=>nil, "number"=>2, "section_id"=>24805, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a5d6a7d4-9ebd-441c-abc3-9d3fb01babd7"})
Annotation.create({"id"=>72554, "question_id"=>76489, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Consider how you will capture this information in advance of data production and analysis, to ensure accuracy, consistency, and completeness of the documentation.&nbsp; Often, resources you've already created can contribute to this (e.g. publications, websites, progress reports, etc.).&nbsp; It is useful to consult regularly with members of the research team to capture potential changes in data collection/processing that need to be reflected in the documentation. Individual roles and workflows should include gathering data documentation as a key element.</span></p>\r\n<span style=\"font-weight: 400;\">Describe how data will be shared and accessed by the members of the research group during the project. Provide details of the data management service or tool (name, URL) that will be utilized to share data with the research group (e.g. Open Science Framework [</span><a href=\"https://osf.io/\"><span style=\"font-weight: 400;\">OSF]</span></a><span style=\"font-weight: 400;\">&nbsp;or </span><a href=\"https://www.radiam.ca/\"><span style=\"font-weight: 400;\">Radiam</span></a><span style=\"font-weight: 400;\">).</span>", "type"=>"guidance", "versionable_id"=>"8c3497f9-7a59-4df4-acf3-3dead8eeaac3"})
Question.create({"id"=>76490, "text"=>"<p>If you are using a metadata standard and/or online tools to document and describe your data, please list them here.</p>", "default_value"=>nil, "number"=>3, "section_id"=>24805, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"705e04e3-8143-4627-a71e-ca8b163ce2d5"})
Annotation.create({"id"=>72555, "question_id"=>76490, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">There are many general and domain-specific metadata standards. Dataset documentation should be provided in a standard, machine-readable, openly-accessible format to enable the effective exchange of information between users and systems. These standards are often based on language-independent data formats such as XML, RDF, and JSON. Read more about metadata standards here: </span><a href=\"http://dcc.ac.uk/resources/metadata-standards\"><span style=\"font-weight: 400;\">UK Digital Curation Centre's Disciplinary Metadata</span></a><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>"9214a907-2d2b-4529-82e0-6b4430bd1ff8"})
Section.create({"id"=>24806, "title"=>"Storage and Backup", "description"=>nil, "number"=>3, "phase_id"=>3933, "modifiable"=>true, "versionable_id"=>"756c8000-9858-4708-a8a1-87bef623f457"})
Question.create({"id"=>76491, "text"=>"What are the anticipated storage requirements for your project, in terms of storage space (in megabytes, gigabytes, terabytes, etc.) and the length of time you will be storing it?", "default_value"=>nil, "number"=>1, "section_id"=>24806, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"6f893e83-b902-4936-91a1-54ac849a0278"})
Annotation.create({"id"=>72556, "question_id"=>76491, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Storage-space estimates should consider requirements for file versioning, backups, and growth over time.&nbsp; If you are collecting data over a long period (e.g. several months or years), your data storage and backup strategy should accommodate data growth. Similarly, a long-term storage plan is necessary if you intend to retain your data after the research project. </span>", "type"=>"guidance", "versionable_id"=>"9a9335a3-8b84-486f-b40e-1ff7c00acee5"})
Question.create({"id"=>76492, "text"=>"How and where will your data be stored and backed up during your research project?", "default_value"=>nil, "number"=>2, "section_id"=>24806, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5b99e052-4eb8-4388-8ec2-a2937c6f88f2"})
Annotation.create({"id"=>72557, "question_id"=>76492, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Data may be stored using optical or magnetic media, which can be removable (e.g. DVD and USB drives), fixed (e.g. desktop or laptop hard drives), or networked (e.g. networked drives or cloud-based servers). Each storage method has benefits and drawbacks that should be considered when determining the most appropriate solution.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">The risk of losing data due to human error, natural disasters, or other mishaps can be mitigated by following the </span><a href=\"http://dataabinitio.com/?p=501\"><span style=\"font-weight: 400;\">3-2-1 backup rule</span></a>:\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Have at least three copies of your data.<br /></span></li>\r\n<li><span style=\"font-weight: 400;\">Store the copies on two different media.</span></li>\r\n<li><span style=\"font-weight: 400;\">Keep one backup copy offsite.</span></li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"fa83b113-8821-42d7-bd6f-8e31496046f6"})
Section.create({"id"=>24807, "title"=>"Sharing and Archiving", "description"=>nil, "number"=>4, "phase_id"=>3933, "modifiable"=>true, "versionable_id"=>"845adc68-1a26-4f68-83f7-87ac28b43d06"})
Question.create({"id"=>76493, "text"=>"What data will you be sharing and in what form?", "default_value"=>nil, "number"=>1, "section_id"=>24807, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"9037505d-00ae-425c-b43b-3e5a9932beaf"})
Annotation.create({"id"=>72558, "question_id"=>76493, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Consider which data need to be shared to meet institutional, funding, or industry requirements. Consider which data will need to be restricted because of data-sharing arrangements with third parties, or other intellectual property considerations.&nbsp;<br /></span></p>\r\n<p><span style=\"font-weight: 400;\">In this context, data might include research and computational findings, software, code, algorithms, or any other outputs (research or computational) that may be generated during the project. Research outputs might be in the form of:<br /></span></p>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\"><strong>raw data</strong> are the data directly obtained from the simulation or modeling;</span></li>\r\n<li><span style=\"font-weight: 400;\"><strong>processed data</strong> result from some manipulation of the raw data in order to eliminate errors or outliers, to prepare the data for analysis, or to derive new variables; or </span></li>\r\n<li><span style=\"font-weight: 400;\"><strong>analyzed data</strong> are the results of quantitative, statistical, or mathematical analysis of the processed data. </span></li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"ed4acabe-10df-49d9-b014-45732c3c6d5e"})
Question.create({"id"=>76494, "text"=>"What steps will be taken to help the research community know that your research data exist?", "default_value"=>nil, "number"=>2, "section_id"=>24807, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"aebf9124-cdea-43e8-b0f4-4ea87618c728"})
Annotation.create({"id"=>72559, "question_id"=>76494, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Possibilities include: data registries, data repositories, indexes, word-of-mouth, and publications. If possible, choose to archive your data in a repository that will assign a persistent identifier (such as a DOI) to your dataset. This will ensure stable access to the dataset and make it retrievable by various discovery tools.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">One of the best ways to refer other researchers to your deposited datasets is to cite them the same way you cite other types of publications (articles, books, proceedings). The Digital Curation Centre provides a detailed </span><a href=\"http://www.dcc.ac.uk/resources/how-guides/cite-datasets\"><span style=\"font-weight: 400;\">guide</span></a><span style=\"font-weight: 400;\"> on data citation. Note that some data repositories also create links from datasets to their associated papers, thus increasing the visibility of the publications.&nbsp;</span><strong>&nbsp;</strong>", "type"=>"guidance", "versionable_id"=>"7bb7b378-5516-472f-bf7e-0b582154dd96"})
Question.create({"id"=>76495, "text"=>"If you will use your own code or software in this project, describe your strategies for sharing it with other researchers.", "default_value"=>nil, "number"=>3, "section_id"=>24807, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"03939b11-2489-45ee-9f9f-cdc6c7b039bf"})
Annotation.create({"id"=>72560, "question_id"=>76495, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Some strategies for sharing include:<br /></span></p>\r\n<ol>\r\n<li><span style=\"font-weight: 400;\">Research collaboration platforms such as <a href=\"https://codeocean.com/\">Code Ocean</a>, <a href=\"https://wholetale.org/\">Whole Tale,</a> or other, will be used to create, execute, share, and publish computational code and data;</span></li>\r\n<li><span style=\"font-weight: 400;\"><a href=\"https://github.com/\">GitHub</a>, <a href=\"https://about.gitlab.com/\">GitLab</a> or <a href=\"https://bitbucket.org/product?&amp;aceid=&amp;adposition=&amp;adgroup=92542387895&amp;campaign=9128560521&amp;creative=414608948607&amp;device=c&amp;keyword=bitbucket&amp;matchtype=e&amp;network=g&amp;placement=&amp;ds_kids=p51241296780&amp;ds_e=GOOGLE&amp;ds_eid=700000001551985&amp;ds_e1=GOOGLE&amp;gclid=EAIaIQobChMI9qOg0P_-6QIV2uKGCh2tmQDZEAAYASAAEgKJyfD_BwE&amp;gclsrc=aw.ds\">Bitbucket</a> will be utilized to allow for version control; </span></li>\r\n<li><span style=\"font-weight: 400;\">A general public license (e.g., <a href=\"https://www.gnu.org/licenses/gpl-3.0.en.html\">GNU/GPL</a> or <a href=\"https://opensource.org/licenses/MIT\">MIT</a>) will be applied to allow others to run, study, share, and modify the code or software. For further information about licenses see, for example, the <a href=\"https://opensource.org/licenses\">Open Source Initiative</a>; </span></li>\r\n<li><span style=\"font-weight: 400;\">The code or software will be archived in a repository, and a DOI will be assigned to track use through citations. Provide the name of the repository;</span></li>\r\n<li><span style=\"font-weight: 400;\">A software patent will be submitted. </span></li>\r\n</ol>", "type"=>"guidance", "versionable_id"=>"2de5ee93-1ff5-47db-a980-4ebaf2f503ea"})
Question.create({"id"=>76496, "text"=>"<p>Which data (research and computational outputs) will be retained after the completion of the project? Where will your research data be archived for the long-term? Describe your strategies for long-term data archiving.</p>", "default_value"=>nil, "number"=>4, "section_id"=>24807, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"be3e6cf4-6936-402c-b78a-7331217c329a"})
Annotation.create({"id"=>72561, "question_id"=>76496, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">In cases where only selected data will be retained, indicate the reason(s) for this decision. These might include legal, physical preservation issues or other requirements to keep or destroy data.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">There are general-purpose data repositories available in Canada, such as </span><a href=\"https://dataverse.scholarsportal.info/\"><span style=\"font-weight: 400;\">Scholars Portal Dataverse</span></a><span style=\"font-weight: 400;\">, and the Federated Research Data Repository (</span><a href=\"https://www.frdr-dfdr.ca/repo/\"><span style=\"font-weight: 400;\">FRDR</span></a><span style=\"font-weight: 400;\">), which have preservation policies in place. Many research disciplines also have dedicated repositories. </span><a href=\"https://www.nature.com/sdata/policies/repositories#general\"><span style=\"font-weight: 400;\">Scientific Data</span></a><span style=\"font-weight: 400;\">, for example, provides a list of repositories for scientific research outputs.&nbsp; Some of these repositories may request or require data to be submitted in a specific file format. You may wish to consult with a repository early in your project, to ensure your data are generated in, or can be transformed into, an appropriate standard format for your field. </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">Re3data.org</span></a><span style=\"font-weight: 400;\"> is an international registry of research data repositories that may help you identify a suitable repository for your data. The </span><a href=\"https://repositoryfinder.datacite.org/\"><span style=\"font-weight: 400;\">Repository Finder</span></a><span style=\"font-weight: 400;\"> tool hosted by </span><a href=\"https://datacite.org/\"><span style=\"font-weight: 400;\">DataCite</span></a><span style=\"font-weight: 400;\"> can help you find a repository listed in re3data.org. For assistance in making your dataset visible and easily accessible, contact your institution&rsquo;s library or reach out to the Portage DMP Coordinator at </span><a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a><span style=\"font-weight: 400;\">.&nbsp;</span></p>", "type"=>"guidance", "versionable_id"=>"ecde3cfd-0916-42f4-bd56-f78027907fa1"})
Section.create({"id"=>24808, "title"=>"Ethics and Intellectual Property", "description"=>nil, "number"=>5, "phase_id"=>3933, "modifiable"=>true, "versionable_id"=>"6030c2d9-510a-4a63-9d40-9a56be11b3d3"})
Question.create({"id"=>76497, "text"=>"Are there any ethical or legal concerns related to your data that you will need to address? Are there any ownership or intellectual property concerns that could limit if/how you can share your research outputs?", "default_value"=>nil, "number"=>1, "section_id"=>24808, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"436857f9-9ca4-4d5f-9dba-4a3fcfd75cce"})
Annotation.create({"id"=>72562, "question_id"=>76497, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Consider the end-user license, and ownership or intellectual property rights of any secondary data or code you will use. Consider any data-sharing agreements you have signed, and repository &lsquo;terms of use&rsquo; you have agreed to. These may determine what end-user license you can apply to your own research outputs, and may limit if and how you can redistribute your research outputs. If you are working with an industry partner, will you have a process in place to manage that partnership, and an understanding of how the research outputs may be shared? Describe any foreseeable concerns or constraints here, if applicable.</span>", "type"=>"guidance", "versionable_id"=>"78e41338-2260-43d5-8f77-b4ceab751e6b"})
Section.create({"id"=>24809, "title"=>"Roles and Responsibilities", "description"=>nil, "number"=>6, "phase_id"=>3933, "modifiable"=>true, "versionable_id"=>"8266d425-9967-49b2-96dd-789b44af2ce7"})
Question.create({"id"=>76498, "text"=>"Identify who will be responsible for managing data during and after the project. Indicate the major data management tasks for which they will be responsible.", "default_value"=>nil, "number"=>1, "section_id"=>24809, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"b0d408b7-5f77-494b-8bf1-d3a1a21f4ab6"})
Annotation.create({"id"=>72563, "question_id"=>76498, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Identify who will be responsible -- individuals or organizations -- for carrying out these parts of your project. Consider including the time frame associated with these staff responsibilities, and document any training needed to prepare staff for data management duties.</span>", "type"=>"guidance", "versionable_id"=>"b1d340cb-6a7c-4184-acb8-ae00ee0d72e3"})
Question.create({"id"=>76499, "text"=>"How will responsibilities for managing data activities be handled if substantive changes happen in the personnel overseeing the project's data, including a change of Principal Investigator?", "default_value"=>nil, "number"=>2, "section_id"=>24809, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"63641555-6eab-43a0-8bad-d23e046af190"})
Annotation.create({"id"=>72564, "question_id"=>76499, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Indicate a succession strategy for management of these data if one or more people responsible for the data leaves (e.g. a graduate student leaving after graduation). Describe the process to follow if the Principal Investigator leaves the project. In some instances, a co-investigator or the department or division overseeing this research will assume responsibility.</span>", "type"=>"guidance", "versionable_id"=>"39b4484c-74c2-4e81-9380-83265c0f17c7"})
Question.create({"id"=>76500, "text"=>"What resources will you require to implement your data management plan? What do you estimate the overall cost for data management to be?", "default_value"=>nil, "number"=>3, "section_id"=>24809, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f569c924-a28c-4850-be99-8023b7245a7b"})
Annotation.create({"id"=>72565, "question_id"=>76500, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">This estimate should incorporate data management costs incurred during the project as well as those required for the longer-term support for the data after the project has completed. Items to consider in the latter category of expenses include the costs of curating and providing long-term access to the data. It might include technical aspects of data management, training requirements, file storage &amp; backup, the computational environment or software needed to manage, analyze or visualize research data, and contributions of non-project staff. Read more about the costs of RDM and how these can be addressed in advance: &ldquo;</span><a href=\"https://zenodo.org/record/3837717#.XxHRAC0ZPUK\"><span style=\"font-weight: 400;\">What will it cost to manage and share my data?</span></a><span style=\"font-weight: 400;\">&rdquo; by OpenAIRE. There is also an online </span><a href=\"https://dam.ukdataservice.ac.uk/media/622368/costingtool.pdf\"><span style=\"font-weight: 400;\">data management costing</span></a><span style=\"font-weight: 400;\"> tool available to help determine the costs and staffing requirements in your project proposal. </span>", "type"=>"guidance", "versionable_id"=>"c2c74cb7-7f7a-4011-84fc-9ef478f55426"})
Template.create!({"id"=>3847, "title"=>"Alliance Template for Research in History and the Humanities", "description"=>"<p><span style=\"font-weight: 400;\">This model was developed for researchers in history and in the larger field of humanities. It was designed to take into account the fact that research projects in these disciplines still primarily use analog research data during the active phases of a project.&nbsp;</span></p>\n<p><span style=\"font-weight: 400;\">Two versions of the model are proposed: guidance labelled &ldquo;Phase 1&rdquo; is for the documentation of DMP sections joined with a funding application. The headings documented in Phase&nbsp;1 are primarily aimed at producing a DMP to support research data management (RDM) budgeting for the research project. Headings or guidance labelled &ldquo;Phase 2&rdquo; may be considered once funding has been secured. The entire DMP is an evolving management document since the content of certain headings will only become clearer once the project is well underway.</span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>1, "visibility"=>1, "customization_of"=>nil, "family_id"=>657828489, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3894, "title"=>"Phase 1: Data Management Plan for Grant Application", "description"=>"<p><span style=\"font-weight: 400;\">&ldquo;Phase 1&rdquo; is for the documentation of DMP sections joined with a funding application. The headings documented in Phase&nbsp;1 are primarily aimed at producing a DMP to support research data management (RDM) budgeting for the research project.</span></p>", "number"=>1, "template_id"=>3847, "modifiable"=>true, "versionable_id"=>"05204d86-fc3a-4e00-a791-4701dd5042db"})
Section.create({"id"=>24597, "title"=>"Data Collection", "description"=>nil, "number"=>1, "phase_id"=>3894, "modifiable"=>true, "versionable_id"=>"2179662f-5a12-4f78-902d-aa655282061c"})
Question.create({"id"=>75798, "text"=>"Describe each set of research materials using the table provided. Repeat as many times as necessary for each new set.<br />\r\n<table style=\"border-collapse: collapse; width: 100%; height: 486px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 32.0366%; height: 18px;\"><em><strong>Data Source</strong></em></td>\r\n<td style=\"width: 67.9634%; height: 18px;\">(e.g. the Archives of Ontario)<br />If the data will be produced as part of the project, indicate this.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 32.0366%; height: 36px;\"><em><strong>Data Type</strong></em></td>\r\n<td style=\"width: 67.9634%; height: 36px;\">(e.g. images, recordings, manuscripts, word processing files)</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 32.0366%; height: 18px;\"><em><strong>Data Granularity</strong></em></td>\r\n<td style=\"width: 67.9634%; height: 18px;\">(e.g. individual item; dataset, collection, corpus)</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 32.0366%; height: 36px;\"><strong><em>Data Creation Methodology</em></strong><strong><em><br /></em></strong></td>\r\n<td style=\"width: 67.9634%; height: 36px;\"><span style=\"font-weight: 400;\">(if the data are produced as part of the project)<br />(e.g., surveys and qualitative interviews or focus groups)<br /></span></td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 32.0366%; height: 54px;\"><strong><em>Data Producer</em></strong><strong><em><br /></em></strong></td>\r\n<td style=\"width: 67.9634%; height: 54px;\">Explain 1) who created the research data if it is not collected data, or 2) who created an additional analytical layer to existing research data.<br />Example: In the second case, one could use a finding aid prepared by the archive or a catalog raisonn&eacute; of another researcher.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 32.0366%; height: 36px;\"><strong><em>Is it sensitive data?</em></strong></td>\r\n<td style=\"width: 67.9634%; height: 36px;\"><span style=\"font-weight: 400;\">Archival records are generally reviewed by an archivist for privacy concerns before being made available to researchers. In cases where the information will be collected directly by the principal researcher, you should avoid disclosing any information that could identify a living person such as ethnic origin, personal beliefs, personal orientation, health status, etc. without permission. For further guidance, see the </span><a href=\"https://doi.org/10.5281/zenodo.4088954\"><span style=\"font-weight: 400;\">Human Research Data Risk Matrix</span></a><span style=\"font-weight: 400;\">.</span></td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 32.0366%; height: 54px;\"><strong><em>Analog or digital format of research data/material during the project</em></strong></td>\r\n<td style=\"width: 67.9634%; height: 54px;\">(e.g. print, magnetic tape, artefact, .txt, .csv, .jpeg, .nvpx, etc.)<br /><span style=\"font-weight: 400;\">Find more information on file formats:</span><a href=\"https://researchdata.library.ubc.ca/plan/format-your-data/\"> <span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\"> or</span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format.aspx\"> <span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span></td>\r\n</tr>\r\n<tr style=\"height: 108px;\">\r\n<td style=\"width: 32.0366%; height: 108px;\"><strong><em>Does the research data require long-term preservation?</em></strong></td>\r\n<td style=\"width: 67.9634%; height: 108px;\">Research material that has heritage value or value to one or more research communities or to the public interest should provide for specific actions to ensure its long-term access. If so, explain here how long-term value is characterized.<br />(The <em>Preservation</em> section provides an opportunity to reflect on all of the elements to be considered for this dataset, including in particular the preservation format).</td>\r\n</tr>\r\n<tr style=\"height: 108px;\">\r\n<td style=\"width: 32.0366%; height: 108px;\"><strong><em>Will the research data be shared?</em></strong></td>\r\n<td style=\"width: 67.9634%; height: 108px;\">If not, please justify why no form of sharing is possible or desirable. Sharing research materials promotes knowledge development, collaborations and reduces duplication of research efforts. <br />(The <em>Sharing and Reuse</em> section provides an opportunity to consider all of the considerations for this dataset, particularly the dissemination format).</td>\r\n</tr>\r\n</tbody>\r\n</table>", "default_value"=>nil, "number"=>1, "section_id"=>24597, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"cd65abaa-79f1-405d-9fa8-e68c3444eb49"})
Question.create({"id"=>75799, "text"=>"Explain how the research data will be organized to facilitate understanding of its organization.", "default_value"=>nil, "number"=>2, "section_id"=>24597, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"90b02cf3-2f78-419c-94b5-bc9af4be61c1"})
Annotation.create({"id"=>71795, "question_id"=>75799, "org_id"=>8, "text"=>"A <a href=\"https://www.canada.ca/en/heritage-information-network/services/collections-documentation-standards/adopting-classification-system-collections.html\">classification system</a> is a useful tool, especially if you work with original manuscripts or non-digital objects (for example, manuscripts in binders). Provide the description of your classification system in this plan or provide reference to the documents containing it.", "type"=>"guidance", "versionable_id"=>"50a8c1d7-f600-4533-ac5e-41229794b54c"})
Question.create({"id"=>75800, "text"=>"Describe how digital files will be named and how their version(s) will be controlled to facilitate understanding of this organization.", "default_value"=>nil, "number"=>3, "section_id"=>24597, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"bc650225-0edc-4ef8-ba9b-e896533ce760"})
Annotation.create({"id"=>71796, "question_id"=>75800, "org_id"=>8, "text"=>"Naming conventions should be developed. Provide the description of your naming and versioning procedure in this plan or provide reference to documents containing it. Read more about file naming and version control at <a href=\"https://www.ukdataservice.ac.uk/manage-data/format/organising.aspx\">UK Data Service</a>.", "type"=>"guidance", "versionable_id"=>"450e27c9-0da9-4230-94c3-68449653385b"})
Section.create({"id"=>24598, "title"=>"Documentation and Metadata", "description"=>nil, "number"=>2, "phase_id"=>3894, "modifiable"=>true, "versionable_id"=>"ab594d86-94c9-4a24-89fd-36e99f776ec9"})
Question.create({"id"=>75801, "text"=>"What documentation is required to correctly read and interpret the research data?", "default_value"=>nil, "number"=>1, "section_id"=>24598, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"93e7165d-ec60-464e-92f6-b6fd389f5538"})
Annotation.create({"id"=>71797, "question_id"=>75801, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Elements to consider in contextualizing research data: methodologies, definitions of variables or analysis categories, specific classification systems, assumptions, code tree, analyses performed, terminological evolution of a concept, staff members who worked on the data and tasks performed, etc.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">To ensure a verifiable historical interpretation and the lowest possible bias in the possible reuse of the data, try to identify elements of implicit knowledge or that involve direct communication with the principal investigator.</span></p>", "type"=>"guidance", "versionable_id"=>"b6d5882d-e945-4022-b666-da4e4ae96a36"})
Section.create({"id"=>24599, "title"=>"Storage and Backup", "description"=>nil, "number"=>3, "phase_id"=>3894, "modifiable"=>true, "versionable_id"=>"df7aa976-ac08-454b-861c-108d4cccf96e"})
Question.create({"id"=>75802, "text"=>"<p>Describe the storage conditions for your research data taking into account the following aspects:</p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 352px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 155px;\">\r\n<td style=\"width: 34.8971%; height: 155px;\"><strong><em>Master file and backup copies</em></strong></td>\r\n<td style=\"width: 65.1029%; height: 155px;\"><span style=\"font-weight: 400;\">Follow the 3-2-1 backup rule: keep 3 copies of files (master file + 2 copies), stored on 2 types of media (e.g. institutional server + external drive), and 1 copy kept in an off-site location. <br /><br />Each storage medium has advantages and disadvantages. If needed, consult a <a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\">resource person</a> or contact the DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a>. Find more information on storage and backup practices at <a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\">UK Data Service</a>. </span></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 34.8971%; height: 18px;\"><strong><em>Anticipated storage space</em></strong></td>\r\n<td style=\"width: 65.1029%; height: 18px;\"><span style=\"font-weight: 400;\">(e.g. 2 tablets; 15 files of ~70 MB =~ 1 GB multiplied in 3 copies)</span></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 34.8971%; height: 36px;\"><strong><em>Anticipated storage duration</em></strong></td>\r\n<td style=\"width: 65.1029%; height: 36px;\"><span style=\"font-weight: 400;\">(e.g. for the duration of the project; 5 years after the end of the project; long term = well beyond the end of the project)</span></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 34.8971%; height: 36px;\"><strong><em>Is the access to this research data restricted? </em></strong></td>\r\n<td style=\"width: 65.1029%; height: 36px;\"><span style=\"font-weight: 400;\">If applicable, indicate what measures are being taken to manage this access (e.g. password protection, file encryption).</span></td>\r\n</tr>\r\n<tr style=\"height: 118px;\">\r\n<td style=\"width: 34.8971%; height: 107px;\"><strong><em>Who can access the data?</em></strong></td>\r\n<td style=\"width: 65.1029%; height: 107px;\"><span style=\"font-weight: 400;\">Describe functional roles.<br /></span><br /><span style=\"font-weight: 400;\">To make sure your research data is transmitted in a secure manner or through servers governed by Canadian or provincial legislation, either contact your </span><a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\"><span style=\"font-weight: 400;\">institution&rsquo;s library</span></a><span style=\"font-weight: 400;\"> or the DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a></span><span style=\"font-weight: 400;\">.</span></td>\r\n</tr>\r\n</tbody>\r\n</table>", "default_value"=>nil, "number"=>1, "section_id"=>24599, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4b8b32c0-28f1-460f-924d-bcfb354ae247"})
Question.create({"id"=>75803, "text"=>"What is the total cost for storage space in the active and semi-active phase of the project?", "default_value"=>nil, "number"=>2, "section_id"=>24599, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d9ba5aad-0ff9-45e4-aad0-33436d498bfc"})
Annotation.create({"id"=>71798, "question_id"=>75803, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Consider the total volume of storage space expected for each media containing these files. If applicable, include hardware costs in the funding request. Include this information in the </span><em><span style=\"font-weight: 400;\">Responsibilities and Resources</span></em><span style=\"font-weight: 400;\"> section as well.</span>", "type"=>"guidance", "versionable_id"=>"7b670f2a-b164-4cff-abb8-e72637153cb0"})
Section.create({"id"=>24600, "title"=>"Preservation", "description"=>nil, "number"=>4, "phase_id"=>3894, "modifiable"=>true, "versionable_id"=>"019e2ce7-e963-4675-b33e-ac0d0608a8fd"})
Question.create({"id"=>75804, "text"=>"Describe the research data that requires long-term preservation by considering the following aspects:<br /><br />\r\n<table style=\"border-collapse: collapse; width: 100%; height: 18px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 50%; height: 18px;\"><strong><em>Preservation reason</em></strong></td>\r\n<td style=\"width: 50%; height: 18px;\">(e.g. heritage value; value for one or multiple research communities; public interest; policy requirement)</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 50%;\"><strong><em>Preservation format</em></strong></td>\r\n<td style=\"width: 50%;\"><span style=\"font-weight: 400;\">See recommendations of the </span><a href=\"https://www.loc.gov/preservation/resources/rfs/index.html\"><span style=\"font-weight: 400;\">Library of Congress</span></a><span style=\"font-weight: 400;\">. Note that converting from one file format to another for preservation purposes may result in loss of information. This type of operation must be mentioned in the </span><em><span style=\"font-weight: 400;\">Documentation and Metadata</span></em><span style=\"font-weight: 400;\"> section.</span></td>\r\n</tr>\r\n</tbody>\r\n</table>", "default_value"=>nil, "number"=>1, "section_id"=>24600, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"3b5342bf-175e-47ee-9746-90dc8125636c"})
Question.create({"id"=>75805, "text"=>"<p>Where will the research data be stored at the end of the research project?</p>", "default_value"=>nil, "number"=>2, "section_id"=>24600, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"89624f5d-deda-460e-8d03-4e1d1c610b29"})
Annotation.create({"id"=>71799, "question_id"=>75805, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">For long-term preservation, you may wish to consider CoreTrustSeal certified repositories found in this </span><a href=\"https://www.coretrustseal.org/why-certification/certified-repositories/\"><span style=\"font-weight: 400;\">directory</span></a><span style=\"font-weight: 400;\">. However, as many repositories may be in the process of being certified and are not yet listed in this directory, reviewing the retention policy of a repository of interest will increase your options. For repositories without certification, you can evaluate their quality by comparing their policies to the standards of a certification. Read more on trusted data repositories at <a href=\"https://www.ed.ac.uk/information-services/research-support/research-data-service/after/data-repository/trustworthy-digital-repository\">The University of Edinburgh</a> and <a href=\"https://www.openaire.eu/find-trustworthy-data-repository\">OpenAIRE</a>.</span></p>\r\n<p><span style=\"font-weight: 400;\">To increase the visibility of research data, opt for disciplinary repositories: search by discipline in </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">re3data.org</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">For solutions governed by Canadian legislation, it is possible to browse by country of origin in re3data.org. In addition, Canada&rsquo;s digital research infrastructure offers the Federated Research Data Repository (</span><a href=\"https://www.frdr-dfdr.ca/repo/\"><span style=\"font-weight: 400;\">FRDR</span></a><span style=\"font-weight: 400;\">). Finally, it is quite possible that your institution has its own research data repository.</span></p>\r\n<p><span style=\"font-weight: 400;\">To make sure the selected repository meets the requirements of your DMP, feel free to seek advice from a </span><a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\"><span style=\"font-weight: 400;\">resource person</span></a><span style=\"font-weight: 400;\"> or contact the DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a></span><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>"a4e2efd8-5d7e-4ca0-95d3-a2d4edc73756"})
Question.create({"id"=>75806, "text"=>"What are the costs related to the choice of deposit location and data preparation?", "default_value"=>nil, "number"=>3, "section_id"=>24600, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"644d166a-6219-4016-a699-1e3b81b8f8ab"})
Annotation.create({"id"=>71800, "question_id"=>75806, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Preparing research data for eventual preservation involves different tasks that may have costs that are budgeted for preferably in the funding application. This could require a cost model or simply the basic sections of the </span><a href=\"https://ukdataservice.ac.uk/media/622368/costingtool.pdf\"><span style=\"font-weight: 400;\">UK Data Service Costing Tool</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">Include this cost estimate in the </span><em><span style=\"font-weight: 400;\">Responsibilities and Resources</span></em><span style=\"font-weight: 400;\"> section.</span></p>\r\n<p><span style=\"font-weight: 400;\">If necessary, contact a </span><a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\"><span style=\"font-weight: 400;\">resource person</span></a> <span style=\"font-weight: 400;\">or the DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a></span><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>"51b4072d-6a2e-45b5-a9c3-7f0d23b26d43"})
Section.create({"id"=>24601, "title"=>"Sharing and Reuse", "description"=>nil, "number"=>5, "phase_id"=>3894, "modifiable"=>true, "versionable_id"=>"26ba986d-5058-4cc1-846a-39550504497f"})
Question.create({"id"=>75807, "text"=>"<p>Describe each research dataset that will be shared with other researchers or a broader audience while taking into account the following considerations:</p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 160px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 50%; height: 36px;\"><strong><em>Is it sensitive data?</em></strong></td>\r\n<td style=\"width: 50%; height: 36px;\"><span style=\"font-weight: 400;\">If so, explain if this limits access. Refer to the </span><em><span style=\"font-weight: 400;\">Ethics and Legal Compliance</span></em><span style=\"font-weight: 400;\"> section if necessary.</span></td>\r\n</tr>\r\n<tr style=\"height: 34px;\">\r\n<td style=\"width: 50%; height: 34px;\"><strong><em>Is the research data subject to intellectual property?</em></strong></td>\r\n<td style=\"width: 50%; height: 34px;\"><span style=\"font-weight: 400;\">If so, explain if this limits access. Refer to the </span><em><span style=\"font-weight: 400;\">Ethics and Legal Compliance</span></em><span style=\"font-weight: 400;\"> section if necessary.</span></td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 50%; height: 54px;\"><strong><em>Sharing requirement</em></strong></td>\r\n<td style=\"width: 50%; height: 54px;\"><span style=\"font-weight: 400;\">It depends on whether an institutional policy or the granting agency requires some form of sharing of research materials.</span></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 50%; height: 36px;\"><strong><em>Target audience </em></strong></td>\r\n<td style=\"width: 50%; height: 36px;\"><span style=\"font-weight: 400;\">(e.g. history researchers, researchers from various disciplines, general public)</span></td>\r\n</tr>\r\n</tbody>\r\n</table>", "default_value"=>nil, "number"=>1, "section_id"=>24601, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e3f69fea-0603-4ac9-8feb-ceca508cd30e"})
Question.create({"id"=>75808, "text"=>"D&eacute;crire la strat&eacute;gie de diffusion envisag&eacute;e pour faire conna&icirc;tre l&rsquo;existence du mat&eacute;riel de recherche aupr&egrave;s de ses publics.", "default_value"=>nil, "number"=>2, "section_id"=>24601, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"8846fb23-13f0-4587-ab85-c572b61ab4b8"})
Annotation.create({"id"=>71801, "question_id"=>75808, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\"><strong>Exemple : </strong>Signalement dans un d&eacute;p&ocirc;t de donn&eacute;es de reconnu, attribution d&rsquo;un identifiant p&eacute;renne comme DOI - voir le </span><a href=\"https://zenodo.org/record/3862656/files/Dataset%20Identifiers%20Guide.pdf?download=1\"><span style=\"font-weight: 400;\">guide du projet FREYA</span></a><span style=\"font-weight: 400;\"> (</span><em><span style=\"font-weight: 400;\">lien en anglais</span></em><span style=\"font-weight: 400;\">), signalement dans les listes de diffusion et r&eacute;seaux sociaux.</span>", "type"=>"example_answer", "versionable_id"=>"0e2c548b-e22c-4123-b7a1-07ccd3ed8830"})
Annotation.create({"id"=>71802, "question_id"=>75808, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Pour optimiser la diffusion du mat&eacute;riel de recherche, suivre le plus possible les principes FAIR. L&rsquo;</span><a href=\"https://ardc.edu.au/resources/working-with-data/fair-data/fair-self-assessment-tool/\"><span style=\"font-weight: 400;\">Australian Research Data Commons</span></a><span style=\"font-weight: 400;\"> offre un outil d&rsquo;&eacute;valuation du respect de ces principes qui est tr&egrave;s facile d'utilisation (</span><em><span style=\"font-weight: 400;\">lien en anglais</span></em><span style=\"font-weight: 400;\">). Le Digital Curation Centre fournit un </span><a href=\"http://www.dcc.ac.uk/resources/how-guides/cite-datasets\"><span style=\"font-weight: 400;\">guide d&eacute;taill&eacute; sur la citation des donn&eacute;es</span></a><span style=\"font-weight: 400;\"> (tant num&eacute;riques que physiques; </span><em><span style=\"font-weight: 400;\">lien en anglais</span></em><span style=\"font-weight: 400;\">).<br /><br />Pour rendre le mat&eacute;riel r&eacute;cup&eacute;rable par d&rsquo;autres outils et le citer dans les publications savantes, publication d&rsquo;un article de donn&eacute;es dans une revue en libre acc&egrave;s comme <a href=\"https://brill.com/rdj\">Research Data Journal for the Humanities and Social Sciences</a> (<em>lien en anglais</em>).</span></p>\r\n<p><span style=\"font-weight: 400;\">Consulter au besoin une </span><a href=\"https://portagenetwork.ca/fr/outils-et-ressources/personnes-ressources-pour-la-gdr-dans-les-etablissements/\"><span style=\"font-weight: 400;\">personne ressource</span></a> <span style=\"font-weight: 400;\">ou contactez le Coordonnateur du PGD &agrave; <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a></span>.</p>", "type"=>"guidance", "versionable_id"=>"8efb8326-d1ad-4018-9a9e-9649d9278599"})
Section.create({"id"=>24602, "title"=>"Responsibilities and Resources", "description"=>nil, "number"=>6, "phase_id"=>3894, "modifiable"=>true, "versionable_id"=>"03023cd6-579c-43d6-a687-afc172e1ba76"})
Question.create({"id"=>75809, "text"=>"For all research data management activities, consider who is responsible (individual or organization), based on what timeframe, whether staff training is required, and whether there are costs associated with these tasks.", "default_value"=>nil, "number"=>1, "section_id"=>24602, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7166332d-39f3-424e-9871-8f135c9be104"})
Annotation.create({"id"=>71803, "question_id"=>75809, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">If the DMP is at the funding application stage, focus on cost-incurring activities in order to budget as accurately as possible research data management in the funding application.</span></p>\r\n<p><span style=\"font-weight: 400;\">Activities that should be documented: drafting and updating the DMP; drafting document management procedures (naming rules, backup copies, etc.); monitoring document management procedure implementation; conducting the quality assurance process; designing and updating the succession plan; drafting the documentation; assessing the retention period; assessing data management costs; managing sensitive data; managing licences and intellectual property; choosing the final data repository location; and preparing research data for the final repository.</span></p>", "type"=>"guidance", "versionable_id"=>"45bef002-dbcb-4629-8492-7cbf55e153aa"})
Question.create({"id"=>75810, "text"=>"What is an overall cost estimate for the management of research materials?", "default_value"=>nil, "number"=>2, "section_id"=>24602, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e000d526-7a1c-4af1-8926-0b207454eea6"})
Annotation.create({"id"=>71804, "question_id"=>75810, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Taking into account all the aspects in the previous sections, estimate the overall cost of implementing the data management plan. Consider both the management activities required during the active phase of the project and the preservation phase. Some of these costs may be covered by funding agencies.</span>", "type"=>"guidance", "versionable_id"=>"dc82a326-c36f-412e-8094-cfdc36d5c68d"})
Section.create({"id"=>24603, "title"=>"Ethics and Legal Compliance", "description"=>nil, "number"=>7, "phase_id"=>3894, "modifiable"=>true, "versionable_id"=>"42ea8d29-70f6-423e-a0bf-49b2d00657f2"})
Question.create({"id"=>75811, "text"=>"<p>For each research dataset reported as containing sensitive data, identify the security issues that need to be considered to protect the privacy and confidentiality within your team.</p>", "default_value"=>nil, "number"=>1, "section_id"=>24603, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"48d0cd6c-61ef-4232-8243-d82a737bd6c3"})
Annotation.create({"id"=>71805, "question_id"=>75811, "org_id"=>8, "text"=>"<p>If applicable, retrieve written consent from an institution's ethics approval process. If the research involves human participants, verify that the content of the various sections of this DMP is consistent with the consent form signed by the participants.</p>\r\n<p><span style=\"font-weight: 400;\">Describes anticipated data sharing issues within the team, their causes, and possible measures to mitigate them. </span><span style=\"font-weight: 400;\">Read more about data security at </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>"dd04067b-b5fd-4365-a257-15a093e87c0b"})
Question.create({"id"=>75812, "text"=>"If research data sharing is desired and possible, what difficulties do you anticipate in dealing with the secondary use of sensitive data?", "default_value"=>nil, "number"=>2, "section_id"=>24603, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"982a01ea-78d1-4cf2-8f75-5a4ea9088a7d"})
Annotation.create({"id"=>71806, "question_id"=>75812, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">If applicable, pay close attention to the appropriateness of the content in the <em>Sharing and Reuse</em> section with the consent forms signed by participants. Anonymizing data can reassure participants while supporting the development of a data sharing culture. Learn more about anonymization: <a href=\"https://researchdata.library.ubc.ca/plan/protect-your-data/\">UBC Library</a>, <a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical.aspx\">UK Data Service</a>, or&nbsp;</span><a href=\"https://doi.org/10.5281/zenodo.4452825\"><span style=\"font-weight: 400;\">R&eacute;seau Portage</span></a><span style=\"font-weight: 400;\">. </span></p>\r\n<p><span style=\"font-weight: 400;\">Also make sure that metadata does not disclose sensitive data.</span></p>\r\n<p><span style=\"font-weight: 400;\">Explain how access requests to research data containing sensitive data will be managed. What are the access conditions? Who will monitor these requests? What explanations should be provided to applicants?</span></p>", "type"=>"guidance", "versionable_id"=>"a2c63667-170e-4578-a6ac-3c1dfa503601"})
Question.create({"id"=>75813, "text"=>"Are there legal and intellectual property issues that will limit the opening of data?", "default_value"=>nil, "number"=>3, "section_id"=>24603, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"34e3d2fc-47c8-494b-ae44-8b6566db6411"})
Annotation.create({"id"=>71807, "question_id"=>75813, "org_id"=>8, "text"=>"<p>Describe the allocation of copyrights between members of the research team and external copyright holders (include libraries, archives and museums). Verify that the licenses to use the research materials identified in the <em>Sharing and Reuse</em> section are consistent with the description in this section.</p>\r\n<p><span style=\"font-weight: 400;\">If commercial activities are involved in your research project, there are legal aspects to consider regarding the protection of private information. Compliance with </span><a href=\"https://www.priv.gc.ca/en/privacy-topics/privacy-laws-in-canada/02_05_d_15/\"><span style=\"font-weight: 400;\">privacy laws</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://www.ic.gc.ca/eic/site/cipointernet-internetopic.nsf/eng/h_wr02301.html\"><span style=\"font-weight: 400;\">intellectual property legislation</span></a><span style=\"font-weight: 400;\"> may impose data access restrictions. This issue can be discussed with a </span><a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\"><span style=\"font-weight: 400;\">resource person</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>"d44d3454-0269-4e3d-a71d-6db2f7dcffbd"})
Phase.create({"id"=>3895, "title"=>"Phase 2: Data Management Plan for Project Development", "description"=>"<p><span style=\"font-weight: 400;\">&ldquo;Phase 2&rdquo; may be considered once funding has been secured. The entire DMP is an evolving management document since the content of certain headings will only become clearer once the project is well underway.</span></p>", "number"=>2, "template_id"=>3847, "modifiable"=>true, "versionable_id"=>"fce2cc8c-03bb-42b7-8e0e-471fb3d71a8e"})
Section.create({"id"=>24604, "title"=>"Data Collection", "description"=>nil, "number"=>1, "phase_id"=>3895, "modifiable"=>true, "versionable_id"=>"32bb0bb8-9d29-451c-b5e9-b3c072321bea"})
Question.create({"id"=>75814, "text"=>"Describe each set of research materials using the table provided. Repeat as many times as necessary for each new set.<br />\r\n<table style=\"border-collapse: collapse; width: 100%; height: 486px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 32.0366%; height: 18px;\"><em><strong>Data Source</strong></em></td>\r\n<td style=\"width: 67.9634%; height: 18px;\">(e.g. the Archives of Ontario)<br />If the data will be produced as part of the project, indicate this.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 32.0366%; height: 36px;\"><em><strong>Data Type</strong></em></td>\r\n<td style=\"width: 67.9634%; height: 36px;\">(e.g. images, recordings, manuscripts, word processing files)</td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 32.0366%; height: 18px;\"><em><strong>Data Granularity</strong></em></td>\r\n<td style=\"width: 67.9634%; height: 18px;\">(e.g. individual item; dataset, collection, corpus)</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 32.0366%; height: 36px;\"><strong><em>Data Creation Methodology</em></strong><strong><em><br /></em></strong></td>\r\n<td style=\"width: 67.9634%; height: 36px;\"><span style=\"font-weight: 400;\">(if the data are produced as part of the project)<br />(e.g., surveys and qualitative interviews or focus groups)<br /></span></td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 32.0366%; height: 54px;\"><strong><em>Data Producer</em></strong><strong><em><br /></em></strong></td>\r\n<td style=\"width: 67.9634%; height: 54px;\">Explain 1) who created the research data if it is not collected data, or 2) who created an additional analytical layer to existing research data.<br />Example: In the second case, one could use a finding aid prepared by the archive or a catalog raisonn&eacute; of another researcher.</td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 32.0366%; height: 36px;\"><strong><em>Is it sensitive data?</em></strong></td>\r\n<td style=\"width: 67.9634%; height: 36px;\"><span style=\"font-weight: 400;\">Archival records are generally reviewed by an archivist for privacy reasons before being made available to researchers. In cases where the information will be collected directly by the principal researcher, you should avoid disclosing any information that could identify a living person such as ethnic origin, personal beliefs, personal orientation, health status, etc. without permission. For further guidance, see the </span><a href=\"https://doi.org/10.5281/zenodo.4088954\"><span style=\"font-weight: 400;\">Human Research Data Risk Matrix</span></a><span style=\"font-weight: 400;\">.</span></td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 32.0366%; height: 54px;\"><strong><em>Analog or digital format of research data/material during the project</em></strong></td>\r\n<td style=\"width: 67.9634%; height: 54px;\">(e.g. print, magnetic tape, artefact, .txt, .csv, .jpeg, .nvpx, etc.)<br /><span style=\"font-weight: 400;\">Find more information on file formats:</span><a href=\"https://researchdata.library.ubc.ca/plan/format-your-data/\"> <span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\"> or</span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format.aspx\"> <span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span></td>\r\n</tr>\r\n<tr style=\"height: 108px;\">\r\n<td style=\"width: 32.0366%; height: 108px;\"><strong><em>Does the research data require long-term preservation?</em></strong></td>\r\n<td style=\"width: 67.9634%; height: 108px;\">Research material that has heritage value or value to one or more research communities or to the public interest should provide for specific actions to ensure its long-term access. If so, explain here how long-term value is characterized.<br />(The <em>Preservation</em> section provides an opportunity to reflect on all of the elements to be considered for this dataset, including in particular the preservation format).</td>\r\n</tr>\r\n<tr style=\"height: 108px;\">\r\n<td style=\"width: 32.0366%; height: 108px;\"><strong><em>Will the research data be shared?</em></strong></td>\r\n<td style=\"width: 67.9634%; height: 108px;\">If not, please justify why no form of sharing is possible or desirable. Sharing research materials promotes knowledge development, collaborations and reduces duplication of research efforts. <br />(The <em>Sharing and Reuse</em> section provides an opportunity to consider all of the considerations for this dataset, particularly the dissemination format).</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 32.0366%;\"><strong><em>Will the dataset require updates?</em></strong><strong><em><br /></em></strong></td>\r\n<td style=\"width: 67.9634%;\">If so, make sure to properly and timely document this process in the Documentation and Metadata section.</td>\r\n</tr>\r\n</tbody>\r\n</table>", "default_value"=>nil, "number"=>1, "section_id"=>24604, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a4327b25-64d9-4e80-b740-2480ec110de2"})
Question.create({"id"=>75815, "text"=>"Explain how the research data will be organized to facilitate understanding of its organization.", "default_value"=>nil, "number"=>2, "section_id"=>24604, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"ac327207-4aed-4be7-bd0f-66b3aeaf3b60"})
Annotation.create({"id"=>71808, "question_id"=>75815, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">A</span> <a href=\"https://www.canada.ca/en/heritage-information-network/services/collections-documentation-standards/adopting-classification-system-collections.html\"><span style=\"font-weight: 400;\">classification system</span></a><span style=\"font-weight: 400;\"> is a useful tool, especially if you work with original manuscripts or non-digital objects (for example, manuscripts in binders). Provide the description of your classification system in this plan or provide reference to the documents containing it. </span>", "type"=>"guidance", "versionable_id"=>"e174fbd7-d7c0-4a02-9ca5-8d59595df06f"})
Question.create({"id"=>75816, "text"=>"Describe how digital files will be named and how their version(s) will be controlled to facilitate understanding of this organization.", "default_value"=>nil, "number"=>3, "section_id"=>24604, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"9093d97f-e74d-46ef-be16-bfc8c3ab7b80"})
Annotation.create({"id"=>71809, "question_id"=>75816, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Naming conventions should be developed. Provide the description of your naming and versioning procedure in this plan or provide reference to documents containing it. Read more about file naming and version control at</span> <a href=\"https://www.ukdataservice.ac.uk/manage-data/format/organising.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>"87da019f-ed1d-4f12-9dfb-1f07e1c56fb6"})
Question.create({"id"=>75817, "text"=>"Describe the quality assurance process in place to ensure data quality and completeness during data operations (observation, recording, processing, analysis).", "default_value"=>nil, "number"=>4, "section_id"=>24604, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"44ec04e5-8503-4ebd-9aad-797cadfa1d52"})
Annotation.create({"id"=>71810, "question_id"=>75817, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">e.g. </span><span style=\"font-weight: 400;\">field notebook, information log, committee implementation, tools such as </span><a href=\"https://openrefine.org/\"><span style=\"font-weight: 400;\">OpenRefine</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://www.ukdataservice.ac.uk/about-us/our-rd/qamydata.aspx\"><span style=\"font-weight: 400;\">QAMyData</span></a><span style=\"font-weight: 400;\">; consistency with standards. </span>", "type"=>"example_answer", "versionable_id"=>"1d4f00dc-4219-4fd8-a312-2b3b67e9d04c"})
Section.create({"id"=>24605, "title"=>"Documentation and Metadata", "description"=>nil, "number"=>2, "phase_id"=>3895, "modifiable"=>true, "versionable_id"=>"9cf3c43d-1af5-4d67-905c-946387159a59"})
Question.create({"id"=>75818, "text"=>"What documentation is required to correctly read and interpret the research data?", "default_value"=>nil, "number"=>1, "section_id"=>24605, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5019ca1f-7cad-4b2c-ab5c-b6f35fcfe2e3"})
Annotation.create({"id"=>71811, "question_id"=>75818, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Elements to consider in contextualizing research data: methodologies, definitions of variables or analysis categories, specific classification systems, assumptions, code tree, analyses performed, terminological evolution of a concept, staff members who worked on the data and tasks performed, etc.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">To ensure a verifiable historical interpretation and the lowest possible bias in the possible reuse of the data, try to identify elements of implicit knowledge or that involve direct communication with the principal investigator.</span></p>", "type"=>"guidance", "versionable_id"=>"e2576a0a-c4b5-4eae-82a2-bf1f30184bec"})
Question.create({"id"=>75819, "text"=>"What documentation strategy will enable you to regularly document the research data throughout the project?", "default_value"=>nil, "number"=>2, "section_id"=>24605, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"18ec00e9-9675-4e91-9ae8-10d2267b4416"})
Annotation.create({"id"=>71812, "question_id"=>75819, "org_id"=>8, "text"=>"You may want to systematically include a documentation section in project progress reports or link quality assurance activities to the documentation. It is good practice to ensure that data management is included in the tasks of designated individuals.", "type"=>"guidance", "versionable_id"=>"d9b2fc06-4f11-4643-b422-c683c24d9aae"})
Question.create({"id"=>75820, "text"=>"If applicable, indicate the metadata schema and tools used to document research data.", "default_value"=>nil, "number"=>3, "section_id"=>24605, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"28ab8e97-cbab-4ade-842a-829ba0b4b2c5"})
Annotation.create({"id"=>71813, "question_id"=>75820, "org_id"=>8, "text"=>"<p>A <a href=\"https://www.getty.edu/publications/intrometadata/setting-the-stage/\">metadata schema</a> is very useful to systematize the description of research material while making it readable by computers, thus contributing to a better dissemination of this material (e.g.: see <a href=\"https://www.musees.qc.ca/fr/professionnel/guidesel/doccoll/fr/introduction/societemuseesqc.htm\">R&eacute;seau Info-Mus&eacute;e</a> [<em>link in</em> <em>French</em>] or <a href=\"https://vraweb.org/resources/cataloging-cultural-objects/\">Cataloging Cultural Objects</a>). However, their use may result in a loss of information on provenance or contextualization, so ensure that this documentation is present elsewhere.</p>\r\n<p><span style=\"font-weight: 400;\">Resource for exploring and identifying metadata schemas that may be helpful: </span><span style=\"font-weight: 400;\"><a href=\"http://rd-alliance.github.io/metadata-directory/\">RDA Metadata Directory</a>.</span></p>\r\n<p><span style=\"font-weight: 400;\">Resources for exploring controlled vocabularies: <a href=\"http://www.cidoc-crm.org/\">CIDOC/ICOM Conceptual Reference Model</a>, <a href=\"https://lov.linkeddata.es/dataset/lov/\">Linked Open Vocabularies</a>. If needed, contact a DMP <a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\">resource person</a> at your institution.</span></p>", "type"=>"guidance", "versionable_id"=>"722ffbcf-2d67-4e51-a217-3e7ff3d39661"})
Section.create({"id"=>24606, "title"=>"Storage and Backup", "description"=>nil, "number"=>3, "phase_id"=>3895, "modifiable"=>true, "versionable_id"=>"b4af9111-eb1c-4225-ab47-f847a78e96b9"})
Question.create({"id"=>75821, "text"=>"<p>Describe the storage conditions for your research data taking into account the following aspects:</p>\r\n<table style=\"border-collapse: collapse; width: 100%; height: 352px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 155px;\">\r\n<td style=\"width: 34.8971%; height: 155px;\"><strong><em>Master file and backup copies</em></strong></td>\r\n<td style=\"width: 65.1029%; height: 155px;\"><span style=\"font-weight: 400;\">Follow the 3-2-1 backup rule: keep 3 copies of files (master file + 2 copies), stored on 2 types of media (e.g. institutional server + external drive), and 1 copy kept in an off-site location. <br /><br />Each storage medium has advantages and disadvantages. If needed, consult a <a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\">resource person</a> or contact the DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a>. Find more information on storage and backup practices at <a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\">UK Data Service</a>. </span></td>\r\n</tr>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 34.8971%; height: 18px;\"><strong><em>Anticipated storage space</em></strong></td>\r\n<td style=\"width: 65.1029%; height: 18px;\"><span style=\"font-weight: 400;\">(e.g. 2 tablets; 15 files of ~70 MB =~ 1 GB multiplied in 3 copies)</span></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 34.8971%; height: 36px;\"><strong><em>Anticipated storage duration</em></strong></td>\r\n<td style=\"width: 65.1029%; height: 36px;\"><span style=\"font-weight: 400;\">(e.g. for the duration of the project; 5 years after the end of the project; long term = well beyond the end of the project)</span></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 34.8971%; height: 36px;\"><strong><em>Is the access to this research data restricted? </em></strong></td>\r\n<td style=\"width: 65.1029%; height: 36px;\"><span style=\"font-weight: 400;\">If applicable, indicate what measures are being taken to manage this access (e.g. password protection, file encryption).</span></td>\r\n</tr>\r\n<tr style=\"height: 118px;\">\r\n<td style=\"width: 34.8971%; height: 107px;\"><strong><em>Who can access the data?</em></strong></td>\r\n<td style=\"width: 65.1029%; height: 107px;\"><span style=\"font-weight: 400;\">Describe functional roles.<br /></span><br /><span style=\"font-weight: 400;\">To make sure your research data is transmitted in a secure manner or through servers governed by Canadian or provincial legislation, either contact your </span><a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\"><span style=\"font-weight: 400;\">institution&rsquo;s library</span></a><span style=\"font-weight: 400;\"> or the DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a></span><span style=\"font-weight: 400;\">.</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><br /><br /></p>", "default_value"=>nil, "number"=>1, "section_id"=>24606, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c6977177-8d98-46de-a1eb-6b4c387f70bc"})
Question.create({"id"=>75822, "text"=>"What is the total cost for storage space in the active and semi-active phase of the project?", "default_value"=>nil, "number"=>2, "section_id"=>24606, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a4cd20d8-1690-46dd-be3e-edf88f61f553"})
Annotation.create({"id"=>71814, "question_id"=>75822, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Consider the total volume of storage space expected for each media containing these files. If applicable, include hardware costs in the funding request. Include this information in the </span><em><span style=\"font-weight: 400;\">Responsibilities and Resources</span></em><span style=\"font-weight: 400;\"> section as well.</span>", "type"=>"guidance", "versionable_id"=>"6dcd441f-5a74-4c61-b948-fd22caf1b465"})
Section.create({"id"=>24607, "title"=>"Preservation", "description"=>nil, "number"=>4, "phase_id"=>3895, "modifiable"=>true, "versionable_id"=>"233ab0b2-52a6-4c67-9006-3f8676ef058b"})
Question.create({"id"=>75823, "text"=>"Describe the research data that requires long-term preservation by considering the following aspects:<br /><br />\r\n<table style=\"border-collapse: collapse; width: 100%; height: 18px;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 18px;\">\r\n<td style=\"width: 50%; height: 18px;\"><strong><em>Preservation reason</em></strong></td>\r\n<td style=\"width: 50%; height: 18px;\">(e.g. heritage value; value for one or multiple research communities; public interest; policy requirement)</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 50%;\"><strong><em>Preservation format</em></strong></td>\r\n<td style=\"width: 50%;\"><span style=\"font-weight: 400;\">See recommendations of the </span><a href=\"https://www.loc.gov/preservation/resources/rfs/index.html\"><span style=\"font-weight: 400;\">Library of Congress</span></a><span style=\"font-weight: 400;\">. Note that converting from one file format to another for preservation purposes may result in loss of information. This type of operation must be mentioned in the </span><em><span style=\"font-weight: 400;\">Documentation and Metadata</span></em><span style=\"font-weight: 400;\"> section.</span></td>\r\n</tr>\r\n</tbody>\r\n</table>", "default_value"=>nil, "number"=>1, "section_id"=>24607, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5305c254-0f59-408a-a311-1f6631bcb7bd"})
Question.create({"id"=>75824, "text"=>"<p>Where will the research data be stored at the end of the research project?</p>", "default_value"=>nil, "number"=>2, "section_id"=>24607, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5761caf8-33c5-48cc-9ea2-183a9b144265"})
Annotation.create({"id"=>71815, "question_id"=>75824, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">For long-term preservation, you may wish to consider CoreTrustSeal certified repositories found in this </span><a href=\"https://www.coretrustseal.org/why-certification/certified-repositories/\"><span style=\"font-weight: 400;\">directory</span></a><span style=\"font-weight: 400;\">. However, as many repositories may be in the process of being certified and are not yet listed in this directory, reviewing the retention policy of a repository of interest will increase your options. For repositories without certification, you can evaluate their quality by comparing their policies to the standards of a certification. Read more on trusted data repositories at <a href=\"https://www.ed.ac.uk/information-services/research-support/research-data-service/after/data-repository/trustworthy-digital-repository\">The University of Edinburgh</a> and <a href=\"https://www.openaire.eu/find-trustworthy-data-repository\">OpenAIRE</a>.</span></p>\r\n<p><span style=\"font-weight: 400;\">To increase the visibility of research data, opt for disciplinary repositories: search by discipline in </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">re3data.org</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">For solutions governed by Canadian legislation, it is possible to browse by country of origin in re3data.org. In addition, Canada&rsquo;s digital research infrastructure offers the Federated Research Data Repository (</span><a href=\"https://www.frdr-dfdr.ca/repo/\"><span style=\"font-weight: 400;\">FRDR</span></a><span style=\"font-weight: 400;\">). Finally, it is quite possible that your institution has its own research data repository.</span></p>\r\n<p><span style=\"font-weight: 400;\">To make sure the selected repository meets the requirements of your DMP, feel free to seek advice from a </span><a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\"><span style=\"font-weight: 400;\">resource person</span></a><span style=\"font-weight: 400;\"> or contact the DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a></span><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>"61b3c8ed-3479-4195-bef6-26b06f9ba0d3"})
Question.create({"id"=>75825, "text"=>"Des co&ucirc;ts sont-ils associ&eacute;s au choix du lieu de d&eacute;p&ocirc;t et &agrave; la pr&eacute;paration des donn&eacute;es?", "default_value"=>nil, "number"=>3, "section_id"=>24607, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"ad8ea15c-7cca-4b6a-b696-4e7ac6539b84"})
Annotation.create({"id"=>71816, "question_id"=>75825, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">La pr&eacute;paration du mat&eacute;riel de recherche pour son &eacute;ventuelle conservation implique une vari&eacute;t&eacute; de t&acirc;ches pouvant pr&eacute;senter des co&ucirc;ts qu&rsquo;il est pr&eacute;f&eacute;rable de budg&eacute;tiser dans la demande de financement. &Agrave; cette fin, un </span><a href=\"https://www.curationexchange.org/understand-your-costs/19-summary-of-cost-models\"><span style=\"font-weight: 400;\">mod&egrave;le de co&ucirc;ts</span></a><span style=\"font-weight: 400;\"> peut-&ecirc;tre utile ou simplement les rubriques de base du </span><a href=\"https://ukdataservice.ac.uk/media/622368/costingtool.pdf\"><span style=\"font-weight: 400;\">UK Data Service Costing Tool</span></a><span style=\"font-weight: 400;\"> (</span><em><span style=\"font-weight: 400;\">liens en anglais</span></em><span style=\"font-weight: 400;\">).</span></p>\r\n<p><span style=\"font-weight: 400;\">Int&eacute;grer cette estimation de co&ucirc;t dans la section </span><em><span style=\"font-weight: 400;\">Responsabilit&eacute;s et ressources</span></em><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">Consulter au besoin une </span><a href=\"https://portagenetwork.ca/fr/outils-et-ressources/personnes-ressources-pour-la-gdr-dans-les-etablissements/\"><span style=\"font-weight: 400;\">personne ressource</span></a><span style=\"font-weight: 400;\"> ou contactez le Coordonnateur du PGD &agrave; <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a></span><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>"ebee1e4e-5742-45e8-86bf-4b52341a9963"})
Section.create({"id"=>24608, "title"=>"Sharing and Reuse", "description"=>nil, "number"=>5, "phase_id"=>3895, "modifiable"=>true, "versionable_id"=>"e6e87ef9-bcb3-48a3-a6d2-a3790d48be78"})
Question.create({"id"=>75826, "text"=>"<p>Describe each research dataset that will be shared with other researchers or a broader audience while taking into account the following considerations:</p>\r\n<table style=\"border-collapse: collapse; width: 100%;\" border=\"1\">\r\n<tbody>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 50%; height: 36px;\"><strong><em>Is it sensitive data?</em></strong></td>\r\n<td style=\"width: 50%; height: 36px;\"><span style=\"font-weight: 400;\">If so, explain if this limits access. Refer to the </span><em><span style=\"font-weight: 400;\">Ethics and Legal Compliance</span></em><span style=\"font-weight: 400;\"> section if necessary.</span></td>\r\n</tr>\r\n<tr style=\"height: 34px;\">\r\n<td style=\"width: 50%; height: 34px;\"><strong><em>Is the research data subject to intellectual property?</em></strong></td>\r\n<td style=\"width: 50%; height: 34px;\"><span style=\"font-weight: 400;\">If so, explain if this limits access. Refer to the </span><em><span style=\"font-weight: 400;\">Ethics and Legal Compliance</span></em><span style=\"font-weight: 400;\"> section if necessary.</span></td>\r\n</tr>\r\n<tr style=\"height: 54px;\">\r\n<td style=\"width: 50%; height: 54px;\"><strong><em>Sharing requirement</em></strong></td>\r\n<td style=\"width: 50%; height: 54px;\"><span style=\"font-weight: 400;\">It depends on whether an institutional policy or the granting agency requires some form of sharing of research materials.</span></td>\r\n</tr>\r\n<tr style=\"height: 36px;\">\r\n<td style=\"width: 50%; height: 36px;\"><strong><em>Target audience </em></strong></td>\r\n<td style=\"width: 50%; height: 36px;\"><span style=\"font-weight: 400;\">(e.g. history researchers, researchers from various disciplines, general public)</span></td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 50%;\"><strong><em>Data processing level </em></strong></td>\r\n<td style=\"width: 50%;\"><span style=\"font-weight: 400;\">Describe in what format the data is shared, i.e. raw, processed, analyzed, or final, or whether only metadata can be shared. </span><span style=\"font-weight: 400;\">These processing level options are not mutually exclusive.</span><br />\r\n<ul>\r\n<li><em><span style=\"font-weight: 400;\">Raw</span></em><span style=\"font-weight: 400;\">: data obtained directly from the field or an interview.</span></li>\r\n<li><em><span style=\"font-weight: 400;\">Processed</span></em><span style=\"font-weight: 400;\">: operations performed to make data ready for analysis or to de-identify individuals.</span></li>\r\n<li><em><span style=\"font-weight: 400;\">Analyzed</span></em><span style=\"font-weight: 400;\">: data resulting from a qualitative or quantitative analysis following a methodology and a conceptual framework.</span></li>\r\n<li><em><span style=\"font-weight: 400;\">Final</span></em><span style=\"font-weight: 400;\">: research data prepared for its preservation.</span></li>\r\n<li><em><span style=\"font-weight: 400;\">Metadata</span></em><span style=\"font-weight: 400;\">: information describing research data.</span></li>\r\n</ul>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 50%;\"><strong><em>User licence</em></strong></td>\r\n<td style=\"width: 50%;\"><span style=\"font-weight: 400;\">The holder of the research data intellectual property should grant a licence that clarifies how the research data may be used. The most commonly used licences are </span><a href=\"https://creativecommons.org/choose/\"><span style=\"font-weight: 400;\">Creative Commons licences</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://opendatacommons.org/licenses/\"><span style=\"font-weight: 400;\">Open Data Commons licences</span></a><span style=\"font-weight: 400;\">. Please note that once a licence is granted, even if it is subsequently changed, the use of data obtained under the former licence cannot be prevented.</span></td>\r\n</tr>\r\n<tr>\r\n<td style=\"width: 50%;\"><strong><em>Required software</em></strong></td>\r\n<td style=\"width: 50%;\"><span style=\"font-weight: 400;\">If applicable, indicate the name and version of the software required to access research data.</span></td>\r\n</tr>\r\n</tbody>\r\n</table>", "default_value"=>nil, "number"=>1, "section_id"=>24608, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"51fe7def-a468-4e8b-8cb3-ffbdb877bc14"})
Question.create({"id"=>75827, "text"=>"Describe the proposed dissemination strategy to communicate the existence of the research data to its target audiences.", "default_value"=>nil, "number"=>2, "section_id"=>24608, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"056ba9f1-b7de-48bc-8cf3-363e07660554"})
Annotation.create({"id"=>71817, "question_id"=>75827, "org_id"=>8, "text"=>"<strong>Example: </strong>Reporting in a recognized data repository, attribution of a perennial identifier such as DOI (see the <a href=\"https://zenodo.org/record/3862656/files/Dataset%20Identifiers%20Guide.pdf?download=1\">FREYA project guide</a>), reporting in mailing lists and social networks.", "type"=>"example_answer", "versionable_id"=>"9023c3ed-e569-4083-997c-c2463eddaf45"})
Annotation.create({"id"=>71818, "question_id"=>75827, "org_id"=>8, "text"=>"<p>To optimize the dissemination of research material, follow the FAIR principles as much as possible. The <a href=\"https://ardc.edu.au/resources/working-with-data/fair-data/fair-self-assessment-tool/\">Australian Research Data Commons</a> offers an easy-to-use tool for assessing compliance with these principles. The <a href=\"http://www.dcc.ac.uk/resources/how-guides/cite-datasets\">Digital Curation Centre</a> provides a detailed guide to data citation (both digital and physical).</p>\r\n<p>To make the material retrievable by other tools and to cite it in scholarly publications, publish a data article in an open access journal such as the <a href=\"https://brill.com/rdj\">Research Data Journal for the Humanities and Social Sciences</a>.</p>\r\n<p><span style=\"font-weight: 400;\">If necessary, contact a </span><a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\"><span style=\"font-weight: 400;\">resource person</span></a> <span style=\"font-weight: 400;\">or the DMP Coordinator at <a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a></span><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>"4ce570ef-7b88-4f06-a61b-c716e6851bc0"})
Section.create({"id"=>24609, "title"=>"Responsibilities and Resources", "description"=>nil, "number"=>6, "phase_id"=>3895, "modifiable"=>true, "versionable_id"=>"72d30063-58ba-4d95-b6c6-edcccabe1c79"})
Question.create({"id"=>75828, "text"=>"For all research data management activities, consider who is responsible (individual or organization), based on what timeframe, whether staff training is required, and whether there are costs associated with these tasks.", "default_value"=>nil, "number"=>1, "section_id"=>24609, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"8926cd4f-47ce-459d-921d-7c996e8040c3"})
Annotation.create({"id"=>71819, "question_id"=>75828, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Activities that should be documented: drafting and updating the DMP; drafting document management procedures (naming rules, backup copies, etc.); monitoring document management procedure implementation; conducting the quality assurance process; designing and updating the succession plan; drafting the documentation; assessing the retention period; assessing data management costs; managing sensitive data; managing licences and intellectual property; choosing the final data repository location; and preparing research data for the final repository.</span></p>", "type"=>"guidance", "versionable_id"=>"00db0119-d41d-4692-8140-ce91b83a44b8"})
Question.create({"id"=>75829, "text"=>"Describe your succession plan to deal with significant disruptions.", "default_value"=>nil, "number"=>2, "section_id"=>24609, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"38397470-8029-47e5-8db2-ebed561ee8f1"})
Annotation.create({"id"=>71820, "question_id"=>75829, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe the process to be followed, the actions to be taken, and the avenues to be considered to ensure ongoing data management if significant changes occur. Here are possible events to consider: a principal investigator is replaced, a person designated in the assignment table changes, a student who has finished their project related to research data in this DMP leaves.</span>", "type"=>"guidance", "versionable_id"=>"5f421626-03d8-427e-82f2-c22273e0eecf"})
Question.create({"id"=>75830, "text"=>"What is an overall cost estimate for the management of research materials?", "default_value"=>nil, "number"=>3, "section_id"=>24609, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"b3126d9a-6fba-4db3-92d0-12789b7d23f0"})
Annotation.create({"id"=>71821, "question_id"=>75830, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Taking into account all the aspects in the previous sections, estimate the overall cost of implementing the data management plan. Consider both the management activities required during the active phase of the project and the preservation phase. Some of these costs may be covered by funding agencies.</span>", "type"=>"guidance", "versionable_id"=>"7bb68fa7-7b1f-4110-b6e5-f9d4dcce6a99"})
Section.create({"id"=>24610, "title"=>"Ethics and Legal Compliance", "description"=>nil, "number"=>7, "phase_id"=>3895, "modifiable"=>true, "versionable_id"=>"626bb916-6ad3-485b-a94c-dc985540c10d"})
Question.create({"id"=>75831, "text"=>"<p>For each research dataset reported as containing sensitive data (see Research Data Collection section), <strong>explain how this data will be safely managed</strong> to protect the privacy and confidentiality within your team.</p>", "default_value"=>nil, "number"=>1, "section_id"=>24610, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"71ca01b9-1c77-4edc-839c-8956f0c3f16d"})
Annotation.create({"id"=>71822, "question_id"=>75831, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">If applicable, retrieve written consent from an institution's ethics approval process. If the research involves human participants, verify that the content of the various sections of this DMP is consistent with the consent form signed by the participants.</span></p>\r\n<p><span style=\"font-weight: 400;\">Describes anticipated data sharing issues within the team, their causes, and possible measures to mitigate them. Read more about data security at</span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\"> <span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>"d9c12fa1-61e0-4c63-b930-abb1ae28d579"})
Question.create({"id"=>75832, "text"=>"If research data sharing is desired and possible, <strong>what strategies will you implement to address</strong> the secondary use of sensitive data?", "default_value"=>nil, "number"=>2, "section_id"=>24610, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e3d606e8-113f-4e84-ab93-64411b82415a"})
Annotation.create({"id"=>71823, "question_id"=>75832, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">If applicable, pay close attention to the appropriateness of the content in the <em>Sharing and Reuse</em> section with the consent forms signed by participants. Anonymizing data can reassure participants while supporting the development of a data sharing culture. Learn more about anonymization: <a href=\"https://researchdata.library.ubc.ca/plan/protect-your-data/\">UBC Library</a>, <a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical.aspx\">UK Data Service</a>, or the </span><a href=\"https://doi.org/10.5281/zenodo.4270551\">Portage Network</a><span style=\"font-weight: 400;\">. </span></p>\r\n<p><span style=\"font-weight: 400;\">Also make sure that metadata does not disclose sensitive data.</span></p>\r\n<p><span style=\"font-weight: 400;\">Explain how access requests to research data containing sensitive data will be managed. What are the access conditions? Who will monitor these requests? What explanations should be provided to applicants?</span></p>", "type"=>"guidance", "versionable_id"=>"56d5978b-98ca-4f16-8b42-2f2569e8dc59"})
Question.create({"id"=>75833, "text"=>"Are there legal and intellectual property issues that will limit the opening of data?", "default_value"=>nil, "number"=>3, "section_id"=>24610, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"3d1ba59a-37ed-4dfb-b5cc-5750f3d0583b"})
Annotation.create({"id"=>71824, "question_id"=>75833, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Describe the allocation of copyrights between members of the research team and external copyright holders (include libraries, archives and museums). Verify that the licenses to use the research materials identified in the </span><em><span style=\"font-weight: 400;\">Sharing and Reuse</span></em><span style=\"font-weight: 400;\"> section are consistent with the description in this section.</span></p>\r\n<p><span style=\"font-weight: 400;\">If commercial activities are involved in your research project, there are legal aspects to consider regarding the protection of private information. Compliance with</span> <a href=\"https://www.priv.gc.ca/en/privacy-topics/privacy-laws-in-canada/02_05_d_15/\"><span style=\"font-weight: 400;\">privacy laws</span></a><span style=\"font-weight: 400;\"> and</span> <a href=\"https://www.ic.gc.ca/eic/site/cipointernet-internetopic.nsf/eng/h_wr02301.html\"><span style=\"font-weight: 400;\">intellectual property legislation</span></a><span style=\"font-weight: 400;\"> may impose data access restrictions. This issue can be discussed with a</span>&nbsp;<a href=\"https://portagenetwork.ca/tools-and-resources/institutional-rdm-contacts/\"><span style=\"font-weight: 400;\">resource person</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>"ff1c47e5-ec6e-413c-bd9c-b4ef92b64ad0"})
Template.create!({"id"=>3957, "title"=>"Alliance Template for Water Quality Research", "description"=>"<p><span style=\"font-weight: 400;\">This template provides guidance to researchers who are collecting or generating water quality data. Highly Qualified Personnel (HQP) and students are encouraged to consult with their advisors or principal investigators while completing this template. </span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>2, "visibility"=>1, "customization_of"=>nil, "family_id"=>749158652, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>4024, "title"=>"Alliance Template for Water Quality Research", "description"=>"<p><span style=\"font-weight: 400;\">This template provides guidance to researchers who are collecting or generating water quality data. Highly Qualified Personnel (HQP) and students are encouraged to consult with their advisors or principal investigators while completing this template. </span></p>", "number"=>1, "template_id"=>3957, "modifiable"=>true, "versionable_id"=>"cfd0d847-711a-44cf-8ee8-ac444142777d"})
Section.create({"id"=>25276, "title"=>"Data Collection", "description"=>nil, "number"=>1, "phase_id"=>4024, "modifiable"=>true, "versionable_id"=>"15e93d45-fc9f-4e85-a2c9-da7751a9781d"})
Question.create({"id"=>77728, "text"=>"Why are you collecting or generating your data?", "default_value"=>nil, "number"=>1, "section_id"=>25276, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"67eed90a-668b-4bca-ab18-58f957cee32c"})
Annotation.create({"id"=>73915, "question_id"=>77728, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe the purpose or goal of this project. Is the data collection for a specific study or part of a long-term collection effort? What is the relationship between the data you are collecting and any existing data? Note existing data structure and procedures if building on previous work.</span>", "type"=>"guidance", "versionable_id"=>"be721245-2846-4178-b766-861e5c850b5b"})
Question.create({"id"=>77729, "text"=>"What types of data will you collect, create, link to, acquire and/or record? Please be specific, including:", "default_value"=>nil, "number"=>2, "section_id"=>25276, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"3202cea2-c97b-486b-83a2-4e0d6333e3dc"})
Annotation.create({"id"=>73916, "question_id"=>77729, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Types of data you may create or capture could include: geospatial layers (shapefiles; may include observations, models, remote sensing, etc.); tabular observational data; field, laboratory, or experimental data; numerical model input data and outputs from numerical models; images; photographs; video.</span>", "type"=>"example_answer", "versionable_id"=>"33df6e31-d265-407e-abd3-eee758360891"})
Annotation.create({"id"=>73917, "question_id"=>77729, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Please also describe the tools and methods that you will use to collect or generate the data. Outline the procedures that must be followed when using these tools to ensure consistent data collection or generation. If possible, include any sampling procedures or modelling techniques you will use to collect or generate your data. </span></p>", "type"=>"guidance", "versionable_id"=>"63e9565a-f7f5-4744-92be-bcb6fd752ef9"})
Question.create({"id"=>77730, "text"=>"<p>Where are you collecting or generating your data (i.e., study area)? Include as appropriate the spatial boundaries, water source type and watershed name.</p>", "default_value"=>nil, "number"=>3, "section_id"=>25276, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0ae45d15-9459-482c-bdb5-3fcc91bd5efc"})
Annotation.create({"id"=>73918, "question_id"=>77730, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Try to use pre-existing collection standards, such as the </span><a href=\"http://beta-static.fishersci.com/content/dam/fishersci/en_CA/documents/brochures-and-catalogs/catalogs/ccme-protocols-manual-water-quality-sampling.pdf\"><span style=\"font-weight: 400;\">CCME&rsquo;s Protocols for Water Quality Sampling in Canada</span></a><span style=\"font-weight: 400;\">, whenever possible.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">If you will set up monitoring station(s) to continuously collect or sample water quality data, please review resources such as the </span><a href=\"https://library.wmo.int/doc_num.php?explnum_id=7821\"><span style=\"font-weight: 400;\">World Meteorological Organization&rsquo;s technical report on Water Quality Monitoring</span></a><span style=\"font-weight: 400;\"> and</span> <a href=\"https://ccme.ca/en/current-activities/canadian-environmental-quality-guidelines\"><span style=\"font-weight: 400;\">CCME&rsquo;s Protocols for Water Quality Guidelines in Canada</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>"2272baa6-458f-469e-886c-b9b785d0f0d4"})
Question.create({"id"=>77731, "text"=>"Are you using third party data? If so, describe the source of the data including the owner, database or repository DOIs or accession numbers.", "default_value"=>nil, "number"=>4, "section_id"=>25276, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"fb845b73-ae02-4d18-9c92-df383dde46bd"})
Annotation.create({"id"=>73919, "question_id"=>77731, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Include full references or links to the data when possible. Identify any license or use restrictions and ensure that you understand the policies for permitted use, redistribution and derived products.</span>", "type"=>"guidance", "versionable_id"=>"a5495f08-461c-4af9-998d-f95ec2fbf281"})
Section.create({"id"=>25277, "title"=>"Ethics and Legal Compliance", "description"=>nil, "number"=>2, "phase_id"=>4024, "modifiable"=>true, "versionable_id"=>"0c571421-5307-4fa9-bb80-eabb35d343f4"})
Question.create({"id"=>77732, "text"=>"Does your project include sensitive data?", "default_value"=>nil, "number"=>1, "section_id"=>25277, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a2a9fa25-176b-4d44-a3c8-152e18b3ccf6"})
Annotation.create({"id"=>73920, "question_id"=>77732, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Sensitive data is data that carries some risk with its collection. Examples of sensitive data include:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Data governed by third party agreements, contracts or legislation.</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Personal information, health related data, biological samples, etc.</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Indigenous knowledge, and data collected from Indigenous peoples, or Indigenous lands, water and ice.</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Data collected with an industry partner.</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Location information of species at risk.&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Data collected on private property, for example where identification of contaminated wells could impact property values or stigmatize residents or land owners.</span></li>\r\n</ul>\r\n<span style=\"font-weight: 400;\">Additional sensitivity assessment can be made using data classification matrices such as the </span><a href=\"https://policies.usask.ca/documents/data-classifications.pdf\"><span style=\"font-weight: 400;\">University of Saskatchewan Data Classification</span></a><span style=\"font-weight: 400;\"> guidance.</span>", "type"=>"guidance", "versionable_id"=>"8118e66e-1b55-4912-88d2-8640096bbdc4"})
Question.create({"id"=>77733, "text"=>"If your project includes sensitive data, how will you ensure that it is securely managed and accessible only to approved members of the project?", "default_value"=>nil, "number"=>2, "section_id"=>25277, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0544c37f-2051-41dd-9b81-5c22f2665382"})
Annotation.create({"id"=>73921, "question_id"=>77733, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Methods used to share data will be dependent on the type, size, complexity and degree of sensitivity of data. Outline any problems anticipated in sharing data, along with causes and possible measures to mitigate these. Problems may include confidentiality, lack of consent agreements, or concerns about Intellectual Property Rights, among others.</span></p>\r\n<p><span style=\"font-weight: 400;\">Decisions should align with Research Ethics Board requirements. If you are collecting water quality data from Indigenous communities, please also review resources such as the Tri-Council Policy Statement (TCPS2) - Chapter 9:</span> <a href=\"https://ethics.gc.ca/eng/tcps2-eptc2_2018_chapter9-chapitre9.html\"><span style=\"font-weight: 400;\">Research Involving the First Nations, Inuit and M&eacute;tis Peoples of Canada</span></a><span style=\"font-weight: 400;\">, the <a href=\"https://www.afn.ca/uploads/files/nihbforum/info_and_privacy_doc-ocap.pdf\">First Nations </a></span><a href=\"https://www.afn.ca/uploads/files/nihbforum/info_and_privacy_doc-ocap.pdf\"><span style=\"font-weight: 400;\">Principles of OCAP</span></a><span style=\"font-weight: 400;\">, the </span><a href=\"https://www.gida-global.org/care\"><span style=\"font-weight: 400;\">CARE Principles of Indigenous Data Governance</span></a><span style=\"font-weight: 400;\">, the </span><a href=\"https://www.itk.ca/wp-content/uploads/2020/10/ITK-National-Inuit-Strategy-on-Research.pdf\"><span style=\"font-weight: 400;\">National Inuit Strategy on Researc</span><span style=\"font-weight: 400;\">h</span></a><span style=\"font-weight: 400;\">, and </span><a href=\"https://www.nri.nu.ca/sites/default/files/public/files/06-068%20ITK%20NRR%20booklet.pdf\"><span style=\"font-weight: 400;\">Negotiating Research Relationships with Inuit Communities</span></a><span style=\"font-weight: 400;\"> as appropriate.&nbsp;</span></p>\r\n<span style=\"font-weight: 400;\">Restrictions can be imposed by limiting physical access to storage devices, placing data on computers with no access to the Internet, through password protection, and by encrypting files. Sensitive data should never be shared via email or cloud storage services such as Dropbox. Read more about data security here: </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">. </span>", "type"=>"guidance", "versionable_id"=>"8bd94c7f-21de-4184-b266-af91563a45aa"})
Question.create({"id"=>77734, "text"=>"If applicable, what strategies will you undertake to address secondary uses of sensitive data?", "default_value"=>nil, "number"=>3, "section_id"=>25277, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c9369fc0-bbee-4892-a1c2-e6a82db29cf8"})
Annotation.create({"id"=>73922, "question_id"=>77734, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Consider where, how, and to whom sensitive data with acknowledged long-term value should be made available, and for how long it should be archived. If you must restrict some data from sharing, consider making the metadata (information about the dataset) available in a public metadata catalogue.</span></p>\r\n<p><span style=\"font-weight: 400;\">Obtaining the appropriate consent from research participants is an important step in assuring Research Ethics Boards that the data may be shared with researchers outside your project. The consent statement may identify certain conditions clarifying the uses of your data by other researchers. For example, it may stipulate that the data will only be shared for non-profit research purposes or that the data will not be linked with personally identified data from other sources. It is important to consider how the data you are collecting may contribute to future research prior to obtaining research ethics approval since consent will dictate how the data can be used in the immediate study and in perpetuity.</span></p>", "type"=>"guidance", "versionable_id"=>"ab0ed679-5fff-472a-af52-324a8d76fac1"})
Question.create({"id"=>77735, "text"=>"How will you manage other legal, ethical, and intellectual property issues?", "default_value"=>nil, "number"=>4, "section_id"=>25277, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"82596e39-4cc6-46aa-8dcc-a075f224ca1f"})
Annotation.create({"id"=>73923, "question_id"=>77735, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Compliance with privacy legislation and laws that may impose content restrictions in the data should be discussed with your institution's privacy officer or research services office. Research Ethics Boards are also central to the research process.</span></p>\r\n<p><span style=\"font-weight: 400;\">Describe ownership, licensing, and any intellectual property rights associated with the data. Check your institution's policies for additional guidance in these areas. The University of Waterloo has a good example of an institutional policy on </span><a href=\"https://uwaterloo.ca/secretariat/policies-procedures-guidelines/policies/policy-73-intellectual-property-rights\"><span style=\"font-weight: 400;\">Intellectual Property Rights</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">Terms of reuse must be clearly stated, in line with the relevant legal and ethical requirements where applicable (e.g., subject consent, permissions, restrictions, etc.). </span></p>", "type"=>"guidance", "versionable_id"=>"262b3f56-cfb7-4f90-af00-5d573d10b655"})
Section.create({"id"=>25278, "title"=>"File Management", "description"=>nil, "number"=>3, "phase_id"=>4024, "modifiable"=>true, "versionable_id"=>"2c30a63a-1c2f-4272-aa1d-11847a4c9739"})
Question.create({"id"=>77736, "text"=>"What file formats will your data be in? Will these formats allow for data re-use, sharing and long-term access to the data? If not, how will you convert these into interoperable formats?", "default_value"=>nil, "number"=>1, "section_id"=>25278, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"af28a425-2068-4230-8af6-d6014601928e"})
Annotation.create({"id"=>73924, "question_id"=>77736, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Data should be collected and stored using machine readable, non-proprietary formats, such as .csv, .json, or .tiff. Proprietary file formats requiring specialized software or hardware to use are not recommended, but may be necessary for certain data collection or instrument analysis methods. If a proprietary format </span><em><span style=\"font-weight: 400;\">must</span></em><span style=\"font-weight: 400;\"> be used, can it be converted to an open format or accessed using free and open source tools?<br /></span><br />Using open file formats or industry-standard formats (e.g. those widely used by a given community) is preferred whenever possible. Read more about file formats: <a href=\"https://researchdata.library.ubc.ca/plan/format-your-data/\"><span style=\"font-weight: 400;\">UBC Library</span></a><span style=\"font-weight: 400;\">,</span> <a href=\"https://www.usgs.gov/products/data-and-tools/data-management/file-formats\"><span style=\"font-weight: 400;\">USGS</span></a><span style=\"font-weight: 400;\">, </span><a href=\"https://dataoneorg.github.io/Education/\"><span style=\"font-weight: 400;\">DataONE</span></a><span style=\"font-weight: 400;\">, or </span><a href=\"https://www.ukdataservice.ac.uk/manage-data/format.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"33219c57-1ce1-4382-b315-3a1d189521a4"})
Question.create({"id"=>77737, "text"=>"<p>What conventions and procedures will you use to structure, name and version-control your files to help you and others better understand how your data are organized?</p>", "default_value"=>nil, "number"=>2, "section_id"=>25278, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"60c43eee-c012-45f0-9193-065bba52330a"})
Annotation.create({"id"=>73925, "question_id"=>77737, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">File names should:</span></p>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">Clearly identify the name of the project (Unique identifier, Project Abbreviation), timeline (use the </span><a href=\"https://www.iso.org/iso-8601-date-and-time-format.html\">ISO date standard</a>) and type of data in the file;</li>\r\n<li>Avoid use of special characters, such as&nbsp; $ % ^ &amp; # | :, to prevent errors and use an underscore ( _)&nbsp; or dash (-) rather than spaces;</li>\r\n<li><span style=\"font-weight: 400;\">Be as concise as possible. Some instruments may limit you to specific characters. Check with your labs for any naming Standard Operating Procedures (SOPs) or requirements.&nbsp;</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Data Structure:</span></p>\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">It is important to keep track of different copies or versions of files, files held in different formats or locations, and information cross-referenced between files. This process is called 'version control'. For versioning, the format of vMajor.Minor.Patch should be used (i.e. v1.1.0);</span></li>\r\n<li>Logical file structures, informative naming conventions and clear indications of file versions all contribute to better use of your data during and after your research project.&nbsp; These practices will help ensure that you and your research team are using the appropriate version of your data and minimize confusion regarding copies on different computers and/or on different media.&nbsp;</li>\r\n</ul>\r\n<p><span>Read more about file naming and version control:</span> <a href=\"https://researchdata.library.ubc.ca/plan/organize-your-data/\"><span>UBC Library</span></a> <span>or</span> <a href=\"https://www.ukdataservice.ac.uk/manage-data/format/organising.aspx\"><span>UK Data Service</span></a><span>.</span></p>", "type"=>"guidance", "versionable_id"=>"724d59ab-d887-406f-9491-d4028d3a645f"})
Section.create({"id"=>25279, "title"=>"Documentation and Metadata", "description"=>nil, "number"=>4, "phase_id"=>4024, "modifiable"=>true, "versionable_id"=>"840ef947-99d8-42f7-bd29-2d36886cdd81"})
Question.create({"id"=>77738, "text"=>"What documentation will be needed for the data to be read and interpreted correctly in the future?", "default_value"=>nil, "number"=>1, "section_id"=>25279, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e1d28f9a-2909-45c8-8e61-aa512f9dc073"})
Annotation.create({"id"=>73926, "question_id"=>77738, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Typically, good documentation includes information about the study, data-level descriptions and any other contextual information required to make the data usable by other researchers. Elements to document, as applicable, include: research methodology, variable definitions, vocabularies, classification systems, units of measurement, assumptions made, format and file type of the data, and details of who has worked on the project and performed each task, etc.&nbsp;&nbsp;</span><br /><span style=\"font-weight: 400;\"><br />A readme file describing your formatting, naming conventions and procedures can be used to promote use and facilitate adherence to data policies. For instance, describe the names or naming process used for your study sites.</span><br /><span style=\"font-weight: 400;\"><br />Verify the spelling of study site names using the</span> <a href=\"https://www.nrcan.gc.ca/earth-sciences/geography/querying-canadian-geographical-names-database/9170\"><span style=\"font-weight: 400;\">Canadian Geographical Names Database</span></a><span style=\"font-weight: 400;\">.&nbsp;</span><br /><span style=\"font-weight: 400;\"><br />If your data will be collected on Indigenous lands, ensure your naming scheme follows the naming conventions determined by the community.</span>", "type"=>"guidance", "versionable_id"=>"d7d92cb2-d7dd-480d-93b6-b98ce41c1e40"})
Question.create({"id"=>77739, "text"=>"<p>How will you describe samples collected?</p>", "default_value"=>nil, "number"=>2, "section_id"=>25279, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7d973add-2f5f-4869-a46d-91b0bd7506cd"})
Annotation.create({"id"=>73927, "question_id"=>77739, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Include descriptions of sampling procedures and hardware or software used for data collection, including make, model and version where applicable. </span><strong>Sample and replicate labels</strong><span style=\"font-weight: 400;\"> should have a consistent format (sample number, name, field site, date of collection, analysis requested and preservatives added, if applicable) and a corresponding document with descriptions of any codes or short forms used.&nbsp;</span><br /><span style=\"font-weight: 400;\"><br />For examples and guidelines, see the </span><a href=\"http://beta-static.fishersci.com/content/dam/fishersci/en_CA/documents/brochures-and-catalogs/catalogs/ccme-protocols-manual-water-quality-sampling.pdf\"><span style=\"font-weight: 400;\">CCME Protocols Manual for Water Quality Sampling in Canada</span></a> <span style=\"font-weight: 400;\">(taxonomy example p. 11, general guidelines p. 32-33).&nbsp;<br /></span><br /><span style=\"font-weight: 400;\">Consistency, relevance and cost-efficiency are key factors of sample collection and depend on the scope of the project. For practical considerations, see &ldquo;4.3 Step 3. Optimizing Data Collection and Data Quality&rdquo; in the </span><a href=\"https://ccme.ca/en/res/guidancemanualforoptimizingwaterqualitymonitoringprogramdesign_1.0_e.pdf\"><span style=\"font-weight: 400;\">CCME Guidance Manual for Optimizing Water Quality Monitoring Program Design</span></a><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>"aa17caa0-e78b-44ed-8521-6419a256992c"})
Question.create({"id"=>77740, "text"=>"<p>How will you analyze and interpret the water quality data?</p>", "default_value"=>nil, "number"=>3, "section_id"=>25279, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f2239dc5-45e2-4b8e-8eac-f4007daeff46"})
Annotation.create({"id"=>73928, "question_id"=>77740, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">It is important to have a standardized data analysis procedure and metadata detailing both the collection and analysis of the data. For guidance see &ldquo;4.4 Step 4. Data Analysis, Interpretation and Evaluation&rdquo; in the </span><a href=\"https://ccme.ca/en/res/guidancemanualforoptimizingwaterqualitymonitoringprogramdesign_1.0_e.pdf\"><span style=\"font-weight: 400;\">CCME Guidance Manual for Optimizing Water Quality Monitoring Program Design</span></a><span style=\"font-weight: 400;\">.</span><span style=\"font-weight: 400;\">&nbsp;<br /></span><br /><span style=\"font-weight: 400;\">If you will collect or analyze data as part of a wider program, such as the </span><a href=\"https://www.canada.ca/en/environment-climate-change/services/canadian-aquatic-biomonitoring-network/database.html\"><span style=\"font-weight: 400;\">Canadian Aquatic Biomonitoring Network</span></a><span style=\"font-weight: 400;\">, include links to the appropriate guidance documents.</span></p>", "type"=>"guidance", "versionable_id"=>"f4c447b1-3eec-41c5-9531-6564599b5bf1"})
Question.create({"id"=>77741, "text"=>"<p>What kind of Quality Assurance/Quality Control procedures are you planning to do?</p>", "default_value"=>nil, "number"=>4, "section_id"=>25279, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"6fb37f0d-2728-446f-bb7b-8265dc43ea4a"})
Annotation.create({"id"=>73929, "question_id"=>77741, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Include documentation about what QA/QC procedures will be performed. For guidance see &ldquo;1.3 QUALITY ASSURANCE/CONTROL IN SAMPLING&rdquo; in the </span><a href=\"https://ccme.ca/en/res/protocolsdocument_e_-final1.0correctedisbn-secure.pdf\"><span style=\"font-weight: 400;\">CCME </span><span style=\"font-weight: 400;\">Integrated guidance manual of sampling protocols for water quality monitoring in Canada</span></a> <span style=\"font-weight: 400;\">or the </span><a href=\"https://pubs.usgs.gov/of/2018/1018/ofr20181018.pdf\"><span style=\"font-weight: 400;\">Quality-Control Design for Surface-Water Sampling in the National Water-Quality Network</span></a><span style=\"font-weight: 400;\"> from the USGS.</span></p>", "type"=>"guidance", "versionable_id"=>"e884ea5b-f3b7-4037-943a-bb922a3b035f"})
Question.create({"id"=>77742, "text"=>"How will you make sure that documentation is created or captured consistently throughout your project?", "default_value"=>nil, "number"=>5, "section_id"=>25279, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7b00c0b5-cb80-4df1-b2ed-70f98d79db2f"})
Annotation.create({"id"=>73930, "question_id"=>77742, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Consider how you will capture this information and where it will be recorded, ideally in advance of data collection and analysis, to ensure accuracy, consistency, and completeness of the documentation. Writing guidelines or instructions for the documentation process will enhance adoption and consistency among contributors. </span><span style=\"font-weight: 400;\">Often, resources you have already created can contribute to this (e.g., laboratory Standard Operating Procedures (SOPs), recommended textbooks,&nbsp; publications, websites, progress reports, etc.).&nbsp;&nbsp;</span><br /><span style=\"font-weight: 400;\"><br />It is useful to consult regularly with the members of the research team to capture potential changes in data collection or processing that need to be reflected in the documentation. Individual roles and workflows should include gathering data documentation as a key element. </span><span style=\"font-weight: 400;\">Researchers should audit their documentation at a specific time interval (e.g., bi-weekly) to ensure documentation is created properly and information is captured consistently throughout the project. </span>", "type"=>"guidance", "versionable_id"=>"bb152fb9-7b27-498e-a53b-924870710526"})
Question.create({"id"=>77743, "text"=>"<p>List any metadata standard(s) and/or tools you will use to document and describe your data:</p>", "default_value"=>nil, "number"=>6, "section_id"=>25279, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d01d2655-31d5-49a1-88a0-64caf9dd6529"})
Annotation.create({"id"=>73931, "question_id"=>77743, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Metadata describes a dataset and provides vital information such as owner, description, keywords, etc. that allow data to be shared and discovered effectively. Researchers are encouraged to adopt commonly used and interoperable metadata schemas (general or domain-specific), which focus on the exchange of data via open spatial standards. Dataset documentation should be provided in a standard, machine readable, openly-accessible format to enable the effective exchange of information between users and systems.&nbsp; </span></p>", "type"=>"guidance", "versionable_id"=>"6740bdb4-ef76-4f1d-98fe-f37786af661e"})
Annotation.create({"id"=>73932, "question_id"=>77743, "org_id"=>8, "text"=>"<p><strong>Water Quality metadata standards</strong>:</p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://github.com/gordonfn/schema\"><span style=\"font-weight: 400;\">DS-WQX</span></a><span style=\"font-weight: 400;\">: A schema designed for data entered into the DataStream repository based off of the US EPA&rsquo;s WQX standard.</span></li>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://www.epa.gov/waterdata/water-quality-data-wqx\"><span style=\"font-weight: 400;\">WQX</span></a><span style=\"font-weight: 400;\">: Data model designed by the US EPA and USGS for upload to their water quality exchange portal.</span></li>\r\n</ul>\r\n<p><strong>Ecological metadata standards</strong>:</p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://eml.ecoinformatics.org\"><span style=\"font-weight: 400;\">Ecological Metadata Language (EML)</span></a><span style=\"font-weight: 400;\">: A comprehensive vocabulary and a readable XML markup syntax for documenting research data.</span></li>\r\n</ul>\r\n<p><strong>Geographic metadata standards</strong>:</p>\r\n<ul>\r\n<li style=\"font-weight: 400;\" aria-level=\"1\"><a href=\"https://www.dcc.ac.uk/resources/metadata-standards/iso-19115\"><span style=\"font-weight: 400;\">ISO 19115</span></a><span style=\"font-weight: 400;\">: International Standards Organisation&rsquo;s schema for describing geographic information and services.</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Read more about metadata standards:</span> <a href=\"http://www.dcc.ac.uk/resources/metadata-standards\"><span style=\"font-weight: 400;\">UK Digital Curation Centre's Disciplinary Metadata</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"example_answer", "versionable_id"=>"d2a93ca3-2303-49ec-842e-baf6d577e5a5"})
Question.create({"id"=>77744, "text"=>"If the metadata standard will be modified, please explain how you will modify the standard to meet your needs.", "default_value"=>nil, "number"=>7, "section_id"=>25279, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e85efaa9-5617-4edd-8c6d-85de20c2d03d"})
Annotation.create({"id"=>73933, "question_id"=>77744, "org_id"=>8, "text"=>"Deviation from existing metadata standards should only occur when necessary. If this is the case, please document these deviations so that others can recreate your process.", "type"=>"guidance", "versionable_id"=>"884d4577-d7a3-40c4-9bab-e9d47c1eca1b"})
Question.create({"id"=>77745, "text"=>"How will you make sure that metadata is created or captured consistently throughout your project?", "default_value"=>nil, "number"=>8, "section_id"=>25279, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"b828b1b7-c349-4a2b-a550-beea4bc788e2"})
Annotation.create({"id"=>73934, "question_id"=>77745, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Once a standard has been chosen, it is important that data collectors have the necessary tools to properly create or capture the metadata. </span><span style=\"font-weight: 400;\">Audits of collected metadata should occur at specific time intervals (e.g., bi-weekly) to ensure metadata is created properly and captured consistently throughout the project. <br /><br /></span><span style=\"font-weight: 400;\">Some tips for ensuring good metadata collection are:<br /></span>\r\n<ul>\r\n<li>Provide support documentation and routine metadata training to data collectors.</li>\r\n<li><span style=\"font-weight: 400;\">Provide data collectors with thorough data collection tools (e.g., field or lab sheets) so they are able to capture the necessary information.</span></li>\r\n<li><span style=\"font-weight: 400;\">Samples or notes recorded in a field or lab book should be scanned or photographed daily to prevent lost data.</span></li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"7488ee2f-b1c7-440e-8901-4cc5507377ae"})
Section.create({"id"=>25280, "title"=>"Storage and Backup", "description"=>nil, "number"=>5, "phase_id"=>4024, "modifiable"=>true, "versionable_id"=>"581c58fe-5830-49e6-afcb-9560ae0b7a85"})
Question.create({"id"=>77746, "text"=>"What are the anticipated storage requirements for your project, in terms of storage space (in megabytes, gigabytes, terabytes, etc.) and the length of time you will be storing it?", "default_value"=>nil, "number"=>1, "section_id"=>25280, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"35e7a540-e037-4b95-9dcd-5e85638040c0"})
Annotation.create({"id"=>73935, "question_id"=>77746, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Storage-space estimates should take into account requirements for file versioning, backups and growth over time. </span><span style=\"font-weight: 400;\">A long-term storage plan is necessary if you intend to retain your data after the research project.</span>", "type"=>"guidance", "versionable_id"=>"3b5b4276-7470-4889-a001-bdd952db5933"})
Question.create({"id"=>77747, "text"=>"<p>How and where will your data be stored and backed up during your research project?</p>", "default_value"=>nil, "number"=>2, "section_id"=>25280, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"bd303b55-27c4-4f2c-9cb6-d91e96708b79"})
Annotation.create({"id"=>73936, "question_id"=>77747, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">The risk of losing data due to human error, natural disasters, or other mishaps can be mitigated by following the 3-2-1 backup rule: Have at least three copies of your data; store the copies on two different media; keep one backup copy offsite. </span><span style=\"font-weight: 400;\">Data may be stored using optical or magnetic media, which can be removable (e.g., DVD and USB drives), fixed (e.g., desktop or laptop hard drives), or networked (e.g., networked drives or cloud-based servers such as </span><a href=\"https://alliancecan.ca/en/services/advanced-research-computing\"><span style=\"font-weight: 400;\">Compute Canada</span></a><span style=\"font-weight: 400;\">)</span><span style=\"font-weight: 400;\">. </span><span style=\"font-weight: 400;\">Each storage method has benefits and drawbacks that should be considered when determining the most appropriate solution.</span><br /><span style=\"font-weight: 400;\"><br />Raw data should be preserved and never altered. Some options for preserving raw data are storing on a read-only drive or archiving the raw, unprocessed data. The preservation of raw data should be included in the data collection process and backup procedures.<br /></span><br /><span style=\"font-weight: 400;\">Examples of further information on storage and backup practices are available from the</span> <a href=\"https://onesearch.library.utoronto.ca/researchdata/data-storage\"><span style=\"font-weight: 400;\">University of Toronto</span></a><span style=\"font-weight: 400;\">&nbsp;and the</span><a href=\"https://www.ukdataservice.ac.uk/manage-data/store.aspx\"> <span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span></p>", "type"=>"guidance", "versionable_id"=>"2efd47a8-a3fa-4800-9af8-7efa5bc3dafc"})
Question.create({"id"=>77748, "text"=>"How will the research team and other collaborators access, modify and contribute data throughout the project? How will data be shared?", "default_value"=>nil, "number"=>3, "section_id"=>25280, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4d5c273d-bae6-4266-82ba-f0122a25f0ce"})
Annotation.create({"id"=>73937, "question_id"=>77748, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">An ideal shared data management solution facilitates collaboration, ensures data security and is easily adopted by users with minimal training. Tools such as the </span><a href=\"https://www.globus.org/\"><span style=\"font-weight: 400;\">Globus</span></a><span style=\"font-weight: 400;\"> file transfer system, currently in use by many academic institutions, allows data to be securely transmitted between researchers or to centralized project data storage. Relying on email for data transfer is not a robust or secure solution.&nbsp;<br /></span><br /><span style=\"font-weight: 400;\">Third-party commercial file sharing services (such as Google Drive and Dropbox) facilitate file exchange, but they are not necessarily permanent or secure, and are often located outside Canada. </span><span style=\"font-weight: 400;\">Additional resources such as </span><a href=\"https://osf.io/\"><span style=\"font-weight: 400;\">Open Science Framework</span></a><span style=\"font-weight: 400;\"> and </span><a href=\"https://alliancecan.ca/en/services/advanced-research-computing\"><span style=\"font-weight: 400;\">Compute Canada</span></a><span style=\"font-weight: 400;\"> are also recommended options for collaborations.&nbsp;</span><br /><span style=\"font-weight: 400;\"><br />If your data will be collected on Indigenous lands, how will you share data with community members throughout the project?&nbsp;</span><br /><span style=\"font-weight: 400;\"><br />Please contact librarians at your institution to determine if there is support available to develop the best solution for your research project.</span>", "type"=>"guidance", "versionable_id"=>"d833984c-8bb8-4bd9-ba0f-50d5da7799b5"})
Section.create({"id"=>25281, "title"=>"Responsibilities and Resources", "description"=>nil, "number"=>6, "phase_id"=>4024, "modifiable"=>true, "versionable_id"=>"e7d0a07c-95ad-4f6a-97eb-0df9a0f798ab"})
Question.create({"id"=>77749, "text"=>"Who will be responsible for managing this project's data during and after the project, and for what major data management tasks will they be responsible?", "default_value"=>nil, "number"=>1, "section_id"=>25281, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"8955020a-c029-4de1-b1be-72ec94f8e5fa"})
Annotation.create({"id"=>73938, "question_id"=>77749, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe the roles and responsibilities of all parties with respect to the management of the data. Consider the following:</span><br />\r\n<ul>\r\n<li><span style=\"font-weight: 400;\">If there are multiple investigators involved, what are the data management responsibilities of each investigator?&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">If data will be collected by students, clarify the student role versus the principal investigator role, and identify who will hold theIntellectual Property rights.&nbsp;&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Will training be required to perform the data collection or data management tasks? If so, how will this training be administered and recorded?&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Who will be the primary person responsible for ensuring compliance with the Data Management Plan during all stages of the data lifecycle?</span></li>\r\n<li><span style=\"font-weight: 400;\">Include the time frame associated with these staff responsibilities and any training needed to prepare staff for these duties. </span></li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"b9b42e92-5671-43ae-8552-ae98d6a04ac7"})
Question.create({"id"=>77750, "text"=>"How will responsibilities for managing data activities be handled if substantive changes happen in the personnel overseeing the project's data, including a change of Principal Investigator?", "default_value"=>nil, "number"=>2, "section_id"=>25281, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"fb4c9c46-7d0d-460c-aa56-660f5da91edd"})
Annotation.create({"id"=>73939, "question_id"=>77750, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Indicate a succession strategy for these data in the event that one or more people responsible for the data leaves (e.g., a student leaving after graduation). </span><span style=\"font-weight: 400;\">Describe the process to be followed in the event that the Principal Investigator leaves the project. In some instances, a co-investigator or the department or division overseeing this research will assume responsibility.</span>", "type"=>"guidance", "versionable_id"=>"241b9006-d901-4e4d-b128-ae9252d580d4"})
Question.create({"id"=>77751, "text"=>"What resources will you require to implement your data management plan? What do you estimate the overall cost for data management to be?", "default_value"=>nil, "number"=>3, "section_id"=>25281, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a29447ae-d72c-4361-aef7-72cc4e75a5af"})
Annotation.create({"id"=>73940, "question_id"=>77751, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">This estimate should incorporate data management costs incurred during the project and those required for longer-term support for the data when the project is finished, such as the cost of preparing&nbsp; your data for deposit and repository fees. </span><span style=\"font-weight: 400;\">Some funding agencies state explicitly the support that they will provide to meet the cost of preparing data for deposit. This might include technical aspects of data management, training requirements, file storage &amp; backup and contributions of non-project staff. </span><span style=\"font-weight: 400;\">Can you leverage existing resources, such as Compute Canada Resources, University Library Data Services, etc. to support implementation of your DMP?<br /></span><br /><span style=\"font-weight: 400;\">To help assess costs, OpenAIRE&rsquo;s &lsquo;</span><a href=\"https://www.openaire.eu/how-to-comply-to-h2020-mandates-rdm-costs\"><span style=\"font-weight: 400;\">estimating costs RDM tool</span></a><span style=\"font-weight: 400;\">&rsquo; may be useful. </span>", "type"=>"guidance", "versionable_id"=>"95311d59-098e-40af-a45c-9f6ae938f0c1"})
Section.create({"id"=>25282, "title"=>"Sharing, Reuse and Preservation", "description"=>"<p><span style=\"font-weight: 400;\">In general, data collected using public funds should be preserved for future discovery and reuse. </span><span style=\"font-weight: 400;\">As you develop your data sharing strategy you will want to consider the following:</span></p>", "number"=>7, "phase_id"=>4024, "modifiable"=>true, "versionable_id"=>"63b58dbe-0928-409d-973f-e865180ca465"})
Question.create({"id"=>77752, "text"=>"Do you, your institution or collaborators have an existing data sharing strategy?", "default_value"=>nil, "number"=>1, "section_id"=>25282, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0f48263a-dd45-4c97-a1ad-a5a341bc9a99"})
Annotation.create({"id"=>73941, "question_id"=>77752, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Use all or parts of existing strategies to meet your requirements.</span>", "type"=>"guidance", "versionable_id"=>"cff070f3-8808-4cfe-94b0-2cefc7118354"})
Question.create({"id"=>77753, "text"=>"Are there restrictions on sharing due to ethics or legal constraints?", "default_value"=>nil, "number"=>2, "section_id"=>25282, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"51d57e5a-f9a7-483d-854b-5e51c128d704"})
Annotation.create({"id"=>73942, "question_id"=>77753, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">In these instances, it is critical to assess whether data can or should be shared. It is necessary to comply with:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Data treatment protocols established by the Research Ethics Board (REB) process, including data collection consent, privacy considerations, and potential expectations of data destruction;</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Data-sharing agreements or contracts.&nbsp; Data that you source or derive from a third party may only be shared in accordance with the original data sharing agreements or licenses;</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Any relevant legislation.</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\"><strong>Note:</strong>&nbsp; </span>If raw or identifiable data cannot be shared, is it possible to share aggregated data, or to de-identify your data, or coarsen location information for sharing? If data cannot be shared, consider publishing descriptive metadata (data about the data), documentation and contact information that will allow others to discover your work.</p>", "type"=>"guidance", "versionable_id"=>"0555c6e1-8182-4a14-8312-4d2420f991c8"})
Question.create({"id"=>77754, "text"=>"What data will you be sharing and in what form? (e.g., raw, processed, analyzed, final).", "default_value"=>nil, "number"=>3, "section_id"=>25282, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"0a33b3d9-f0fe-4a9a-8448-622cc4737eb0"})
Annotation.create({"id"=>73943, "question_id"=>77754, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Think about what data needs to be shared to meet institutional or funding requirements, and what data may be restricted because of confidentiality, privacy, or intellectual property considerations.</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><strong>Raw data</strong><span style=\"font-weight: 400;\"> are unprocessed data directly obtained from sampling, field instruments, laboratory instruments,&nbsp; modelling,&nbsp; simulation, or survey.&nbsp; Sharing raw data is valuable because it enables researchers to evaluate new processing techniques and analyse disparate datasets in the same way.&nbsp;</span></li>\r\n<li style=\"font-weight: 400;\"><strong>Processed data</strong><span style=\"font-weight: 400;\"> results from some manipulation of the raw data in order to eliminate errors or outliers, to prepare the data for analysis or preservation, to derive new variables, or to de-identify the sampling locations. Processing steps need to be well described.</span></li>\r\n<li style=\"font-weight: 400;\"><strong>Analyzed data</strong><span style=\"font-weight: 400;\"> are the results of qualitative, statistical, or mathematical analysis of the processed data. They may&nbsp; be presented as graphs, charts or statistical tables.</span></li>\r\n<li style=\"font-weight: 400;\"><strong>Final data</strong><span> are processed data that have undergone a review process to ensure data quality and, if needed, have been converted into a preservation-friendly format.</span></li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"dd290184-dbe6-41fd-bba9-a94127e93d43"})
Question.create({"id"=>77755, "text"=>"Will you deposit your data for long-term preservation and access at the end of your research project? Please indicate any repositories that you will use.", "default_value"=>nil, "number"=>4, "section_id"=>25282, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"74ddaf0c-0a70-420e-b14c-734c1c857351"})
Annotation.create({"id"=>73944, "question_id"=>77755, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Data repositories help maintain scientific data over time and support data discovery, reuse, citation, and quality. Researchers are encouraged to deposit data in leading &ldquo;domain-specific&rdquo; repositories, especially those that are FAIR-aligned, whenever possible.<br /></span></span>\r\n<p><strong>Domain-specific repositories for water quality data include:</strong></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><a href=\"http://www.datastream.org\"><span style=\"font-weight: 400;\">DataStream</span></a><span style=\"font-weight: 400;\">: A free, open-access platform for storing, visualizing, and sharing water quality data in Canada.</span></li>\r\n<li style=\"font-weight: 400;\"><a href=\"https://www.canada.ca/en/environment-climate-change/services/canadian-aquatic-biomonitoring-network.html\"><span style=\"font-weight: 400;\">Canadian Aquatic Biomonitoring Network (CABIN)</span></a><span style=\"font-weight: 400;\">: A national biomonitoring program developed by Environment and Climate Change Canada that provides a standardized sampling protocol and a recommended assessment approach for assessing aquatic ecosystem condition.</span></li>\r\n</ul>\r\n<p><strong>General Repositories:</strong></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><a href=\"https://www.frdr-dfdr.ca/repo/\"><span style=\"font-weight: 400;\">Federated Research Data Repository</span></a><span style=\"font-weight: 400;\">: A scalable federated platform for digital research data management (RDM) and discovery.</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Institution-specific Dataverse: Please contact your institution&rsquo;s library to see if this is a possibility.</span></li>\r\n</ul>\r\n<p><strong>Other resources:</strong></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">The </span><a href=\"https://repositoryfinder.datacite.org\"><span style=\"font-weight: 400;\">Repository Finder Tool</span></a><span style=\"font-weight: 400;\"> developed by DataCite. This tool queries the </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">re3data registry</span></a><span style=\"font-weight: 400;\"> of research data repositories.</span></li>\r\n<li style=\"font-weight: 400;\">Coalition for Publishing Data in the Earth and Space Sciences: <a href=\"https://copdess.org/enabling-fair-data-project/enabling-fair-data-faqs/#:~:text=This%20FAQ%20is%20a%20companion,in%20the%20FAIR%20Guiding%20Principles\">Enabling FAIR Data &ndash; FAQs</a>.</li>\r\n</ul>", "type"=>"guidance", "versionable_id"=>"bc6a8349-5047-4d54-89ca-e85cae503ab7"})
Question.create({"id"=>77756, "text"=>"What steps will you take to ensure your data is prepared for preservation?", "default_value"=>nil, "number"=>5, "section_id"=>25282, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"8a094adb-7390-4592-ac4c-f845aa2eb9dd"})
Annotation.create({"id"=>73945, "question_id"=>77756, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Consider using preservation-friendly file formats. For example, non-proprietary formats, such as text (.txt) and comma-separated (.csv), are considered preservation-friendly. For guidance, please see <a href=\"https://researchdata.library.ubc.ca/plan/format-your-data/\">UBC Library</a>, <a href=\"https://www.usgs.gov/products/data-and-tools/data-management/file-formats\">USGS</a>, <a href=\"https://dataoneorg.github.io/Education/\">DataONE</a>, or <a href=\"https://www.ukdataservice.ac.uk/manage-data/format.aspx\">UK Data Service</a></span><span style=\"font-weight: 400;\">. Keep in mind that files converted from one format to another may lose information (e.g., converting from an uncompressed TIFF file to a compressed JPG file degrades image quality), so changes to file formats should be documented.&nbsp;<br /><br /></span><span style=\"font-weight: 400;\">Some data you collect may be deemed sensitive and require unique preservation techniques, including anonymization. Be sure to note what this data is and how you will preserve it to ensure it is used appropriately. Read more about anonymization:</span> <a href=\"https://researchdata.library.ubc.ca/plan/protect-your-data/\"><span style=\"font-weight: 400;\">UBC Library</span></a> <span style=\"font-weight: 400;\">or</span> <a href=\"https://www.ukdataservice.ac.uk/manage-data/legal-ethical.aspx\"><span style=\"font-weight: 400;\">UK Data Service</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"d4d33b32-796e-46cc-a92a-f967009b44b2"})
Question.create({"id"=>77757, "text"=>"What type of end-user license will you use for your data?", "default_value"=>nil, "number"=>6, "section_id"=>25282, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"48ddc6c6-5c87-4252-9d8c-7cccbe1f6061"})
Annotation.create({"id"=>73946, "question_id"=>77757, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Licenses dictate how your data can be used. Funding agencies and data repositories may have end-user license requirements in place; if not, they may still be able to guide you in choosing or developing an appropriate license. Once determined, please consider including a copy of your end-user license with your Data Management Plan. Note that only the intellectual property rights holder(s) can issue a license, so it is crucial to clarify who owns those rights.&nbsp;<br /></span><br /><span style=\"font-weight: 400;\">There are several types of standard licenses available to researchers, such as the</span> <a href=\"https://creativecommons.org/choose/\"><span style=\"font-weight: 400;\">Creative Commons licenses</span></a><span style=\"font-weight: 400;\"> and the</span> <a href=\"https://opendatacommons.org/licenses/\"><span style=\"font-weight: 400;\">Open Data Commons licenses</span></a><span style=\"font-weight: 400;\">. For most datasets it is easier to use a standard license rather than to devise a custom-made one. Even if you choose to make your data part of the public domain, it is preferable to make this explicit by using a license such as Creative Commons' CC0. More about data licensing:</span> <a href=\"http://www.dcc.ac.uk/resources/how-guides/license-research-data\"><span style=\"font-weight: 400;\">UK DCC</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"43e9c1da-2f84-4d88-87c5-226b47a18071"})
Question.create({"id"=>77758, "text"=>"What steps will be taken to help the research community know that your data exists?", "default_value"=>nil, "number"=>7, "section_id"=>25282, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"58474196-62d5-48c8-aa03-bd7eef908ba5"})
Annotation.create({"id"=>73947, "question_id"=>77758, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Possibilities include: data registries, repositories, indexes, word-of-mouth, publications. How will the data be accessed (Web service, ftp, etc.)? One of the best ways to refer other researchers to your deposited datasets is to cite them the same way you cite other types of publications. The Digital Curation Centre provides a detailed </span><a href=\"http://www.dcc.ac.uk/resources/how-guides/cite-datasets\"><span style=\"font-weight: 400;\">guide on data citation</span></a><span style=\"font-weight: 400;\">. Some repositories also create links from datasets to their associated papers, increasing the visibility of the publications. Read more at the National Institutes of Health&rsquo;s </span><a href=\"https://grants.nih.gov/grants/sharing_key_elements_data_sharing_plan.pdf\"><span style=\"font-weight: 400;\">Key Elements to Consider in Preparing a Data Sharing Plan Under NIH Extramural Support</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<span style=\"font-weight: 400;\">Contact librarians at your institution for assistance in making your dataset visible and easily accessible, or reach out to the Portage DMP Coordinator at </span><a href=\"mailto:dmp-assistant@tech.alliancecan.ca\">dmp-assistant@tech.alliancecan.ca</a><span style=\"font-weight: 400;\">.&nbsp; </span>", "type"=>"guidance", "versionable_id"=>"19ff75d4-cec0-4862-885c-4d0e7025584b"})
Template.create!({"id"=>3508, "title"=>"Alliance CRDCN Template for Accessing Data from Research Data Centres", "description"=>"<p><span style=\"font-weight: 400;\">The </span><a href=\"https://crdcn.org/\"><span style=\"font-weight: 400;\">Canadian Research Data Centre Network</span></a><span style=\"font-weight: 400;\"> (CRDCN) template summarizes the data management that is conducted by Statistics Canada and the CRDCN on behalf of researchers. While there are some advantages to working inside the RDC for data management, there is also a substantial drawback: RDC data can never be deposited in a repository in accordance with the recommended best practices for research data management. Because of this, researchers should be mindful of other options to engage in best practices. In addition to ensuring that the RDC project folder is well documented, and consistent with the research output, researchers should curate a supporting data deposit at a recognized repository in their discipline or within the </span><a href=\"https://www.frdr-dfdr.ca/repo/\"><span style=\"font-weight: 400;\">Federated Research Data Repository</span></a><span style=\"font-weight: 400;\"> (FRDR) containing metadata, syntax (code that produces a statistical output), and any other supporting material for the research project.</span></p>\n<p><span style=\"font-weight: 400;\">This template is for researchers who are doing RDC work using Statistics Canada data available in the RDC </span><em><span style=\"font-weight: 400;\">only</span></em><span style=\"font-weight: 400;\"> (i.e. there is no supplemental data, public use statistics, or any other information that complements the RDC work). If your work is being conducted in the RDC in concert with other data that you either intend to bring into the RDC or work on outside the RDC in parallel to your RDC work, then the RDC and External Analysis template should be completed.&nbsp; </span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>1, "visibility"=>1, "customization_of"=>nil, "family_id"=>1315485956, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3486, "title"=>"CRDCN Template for Accessing Data from Research Data Centres", "description"=>"<p><span style=\"font-weight: 400;\">This template is for researchers who are doing RDC work using Statistics Canada data available in the RDC </span><em><span style=\"font-weight: 400;\">only</span></em><span style=\"font-weight: 400;\"> (i.e. there is no supplemental data, public use statistics, or any other information that complements the RDC work). If your work is being conducted in the RDC in concert with other data that you either intend to bring into the RDC or work on outside the RDC in parallel to your RDC work, then the RDC and External Analysis template should be completed.&nbsp;</span></p>", "number"=>1, "template_id"=>3508, "modifiable"=>true, "versionable_id"=>"3d9e83e3-cfa8-463b-84a1-78bb0d7ba287"})
Section.create({"id"=>22401, "title"=>"Data Collection", "description"=>"<p><span style=\"font-weight: 400;\">All research conducted in the Research Data Centres (hereafter RDC), using Statistics Canada data exclusively, is secondary in nature. There is no data collection involved in this project. These data are owned and maintained by Statistics Canada with storage and access provided by the Canadian Research Data Centres Network.</span></p>\r\n<p><span style=\"font-weight: 400;\">Raw data in the RDC are stored in multiple formats including but not limited to .SAS (SAS), .dta (STATA), and .shp (shapefiles) as appropriate. The availability of StatTransfer&trade; software within the RDCs and continued management by Statistics Canada will ensure that the data will be accessible indefinitely should the file formats currently in use become obsolete.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">The data provided by Statistics Canada are assigned unique identifiers which can be used to identify the data in any research output.&nbsp;</span></p>", "number"=>1, "phase_id"=>3486, "modifiable"=>true, "versionable_id"=>"30afda1c-6465-43c7-b6d2-5ce2614dd57e"})
Question.create({"id"=>68954, "text"=>"<span style=\"font-weight: 400;\">Which RDC datasets will be used in the research?</span>", "default_value"=>nil, "number"=>1, "section_id"=>22401, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"b6a61020-d71f-4dc5-804f-69b399c731ae"})
Annotation.create({"id"=>64798, "question_id"=>68954, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">The data source(s) for this project is/are the &lt;&lt;INSERT NAME OF SURVEYS/ADMINISTRATIVE RECORDS APPROVED&gt;&gt;. The current version(s) is/are: &lt;&lt;Record number&gt;&gt;.</span>", "type"=>"example_answer", "versionable_id"=>"f91d8b3a-5396-450c-97c2-98d89d7ecec9"})
Annotation.create({"id"=>64799, "question_id"=>68954, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">The record number is available on Statistics Canada's website which can be accessed directly, or through our website: </span><a href=\"http://crdcn.org/data\"><span style=\"font-weight: 400;\">crdcn.org/data</span></a><span style=\"font-weight: 400;\">. E.g. Aboriginal People's Survey 2017 Record number:3250 </span><a href=\"https://www23.statcan.gc.ca/imdb/p2SV.pl?Function=getSurvey&amp;SDDS=3250\"><span style=\"font-weight: 400;\">https://www23.statcan.gc.ca/imdb/p2SV.pl?Function=getSurvey&amp;SDDS=3250</span></a>", "type"=>"guidance", "versionable_id"=>"ae0eaf61-4172-408a-916a-f893e10b89f4"})
Section.create({"id"=>22402, "title"=>"Documentation and Metadata", "description"=>"<p>Documentation provided by Statistics Canada in the RDC is available to any data-users. This documentation is freely available to those with approved projects, and contains information about the sample selection process, a copy of the questionnaire, and a codebook.</p>", "number"=>2, "phase_id"=>3486, "modifiable"=>true, "versionable_id"=>"0e450924-d1b2-4518-9d48-391c9b1bed71"})
Question.create({"id"=>68955, "text"=>"What will you do to ensure that your research data contributions (syntax, output etc&hellip;) in your RDC project folder and (if applicable) your external analysis are properly documented, organized and accessible?", "default_value"=>nil, "number"=>1, "section_id"=>22402, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7a6c4601-6c9b-4d9f-a77a-d7b9246c687c"})
Annotation.create({"id"=>64800, "question_id"=>68955, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">Syntax: Any code used by the researcher to transform the raw data into the research results. This most commonly includes, but is not limited to, .do (Stata) files, .sas (SAS) files, and .r (R) R code.</span></p>", "type"=>"guidance", "versionable_id"=>"786ea364-31bd-4160-a794-e81c1a02e14a"})
Question.create({"id"=>68956, "text"=>"<span style=\"font-weight: 400;\">How will you make sure that the syntax archived in your project folder is created consistently throughout your project?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22402, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e39530d5-9ad5-4d35-87d3-6f7b7a003f85"})
Question.create({"id"=>68957, "text"=>"<span style=\"font-weight: 400;\">Some metadata is available by contacting the RDC analyst. Is the metadata for the data to be used in your analysis available outside of the RDC? Please provide the information about the availability of the metadata for your project here.</span>", "default_value"=>nil, "number"=>3, "section_id"=>22402, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"cb453d78-0b94-4008-9ed7-e80f7af374b2"})
Annotation.create({"id"=>64801, "question_id"=>68957, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">You can consult your analyst to learn more about the availability of metadata for your proposed dataset. In some cases, the codebooks contain confidential information (quantiles with small numbers of individuals identified etc.). and cannot be made available.</span>", "type"=>"guidance", "versionable_id"=>"337cc82e-bc7f-4fe0-92ef-44cc61a0975c"})
Section.create({"id"=>22403, "title"=>"Storage and Backup", "description"=>"<p><span style=\"font-weight: 400;\">Data storage is managed by the CRDCN in partnership with Statistics Canada&nbsp;on Servers located across the network. The current policy of the CRDCN is to store project data (syntax, releases, and anything else stored in the project folder) for ten years. Data are backed up on site and accessible through a highly secured network from any of the other RDC locations.</span></p>", "number"=>3, "phase_id"=>3486, "modifiable"=>true, "versionable_id"=>"5561e7cb-3805-45d5-a8a4-b29c4e82c03a"})
Question.create({"id"=>68958, "text"=>"<p>Please confirm you are <span style=\"font-weight: 400;\">using Statistics Canada data available in the RDC.</span></p>", "default_value"=>nil, "number"=>1, "section_id"=>22403, "question_format_id"=>3, "option_comment_display"=>false, "modifiable"=>true, "versionable_id"=>"14e94737-c708-4318-8c63-754e36e0b91c"})
QuestionOption.create({"id"=>212, "question_id"=>68958, "text"=>"Yes", "number"=>1, "is_default"=>true, "versionable_id"=>"81734366-3316-4982-a9c2-1b040b1aceb0"})
QuestionOption.create({"id"=>213, "question_id"=>68958, "text"=>"No", "number"=>2, "is_default"=>false, "versionable_id"=>"6bae1db5-30d4-40b2-b451-fcaccb011ae1"})
Section.create({"id"=>22404, "title"=>"Preservation", "description"=>"<p><span style=\"font-weight: 400;\">The work conducted in the RDC for this project is kept based on the Contract ID provided by the RDC program which can be used by anyone on the project team to retrieve the code and supporting documents for a period of 10 years as described above in &ldquo;Storage and Backup&rdquo;. Raw data that is the property of Statistics Canada, i.e. RDC data are permanently stored by Statistics Canada, but can never be released to the researcher. Researchers can also preserve all user-generated RDC research data that meets the criteria for release through a vetting request via a repository such as FRDR (though it is again emphasized that the raw RDC data cannot be shared). Best practices for reproducible work require indefinite preservation of research data (so in the case of RDC research, this means metadata, syntax, methodology).</span></p>", "number"=>4, "phase_id"=>3486, "modifiable"=>true, "versionable_id"=>"75ff3601-8f80-4d0f-857c-fc25687f6764"})
Question.create({"id"=>68959, "text"=>"<span style=\"font-weight: 400;\">Will you deposit your syntax and other research data in a repository to host your syntax files publicly? If so, please describe here:</span>", "default_value"=>nil, "number"=>1, "section_id"=>22404, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"44d66491-10f1-490b-aafb-817e51f11762"})
Question.create({"id"=>68960, "text"=>"<p><span style=\"font-weight: 400;\">Is there any other preservation that will be done as part of this research project? If so, please describe here.</span></p>", "default_value"=>nil, "number"=>2, "section_id"=>22404, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"9c3b255c-f24a-47b1-b440-ae2472dc7874"})
Section.create({"id"=>22405, "title"=>"Sharing and Reuse", "description"=>"<p><span style=\"font-weight: 400;\">Because the Statistics Canada Microdata files are collected under assurances of confidentiality and are owned and controlled by Statistics Canada, they cannot be shared by any member of the research team.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">Access to the data in the RDCs is governed by the CRDCN's Access and Fee-for-service policy in </span><a href=\"https://crdcn.org/sites/default/files/uploads/crdcn_affs_policy.pdf\"><span style=\"font-weight: 400;\">English</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://crdcn.org/sites/default/files/uploads/crdcn_affs_policy_fr.pdf\"><span style=\"font-weight: 400;\">French</span></a><span style=\"font-weight: 400;\">. The policy provides free access to university-based researchers who are network members and provides access to others on a cost-recovery basis.</span></p>\r\n<p><span style=\"font-weight: 400;\">The CRDCN and Statistics Canada promote their data holdings through social media and their respective websites. In addition, CRDCN data are required to be cited in any and all publications with the Statistics Canada Record Number so that readers are able to find the data. In addition, all publications using RDC data should include the RDC contract ID so that potential users can find information on the original contract. This information is available on the CRDCN website (</span><a href=\"https://crdcn.org/publications\"><span style=\"font-weight: 400;\">crdcn.org/publications</span></a><span style=\"font-weight: 400;\">). </span></p>", "number"=>5, "phase_id"=>3486, "modifiable"=>true, "versionable_id"=>"d016456a-5106-4f0d-ad94-dee7b42f8017"})
Question.create({"id"=>68961, "text"=>"<span style=\"font-weight: 400;\">If you feel there are any additional sharing and reuse concerns related to your project please describe them here:</span>", "default_value"=>nil, "number"=>1, "section_id"=>22405, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"216a2127-db44-45cc-b457-47de04cf4c8b"})
Section.create({"id"=>22406, "title"=>"Responsibilities and Resources", "description"=>"<p><span style=\"font-weight: 400;\">The CRDCN and Statistics Canada will maintain the research data even if the researcher leaves their organization.</span></p>\r\n<p><span style=\"font-weight: 400;\">CRDCN enjoys the support of CIHR, SSHRC and CFI as well as receiving funds from the partner universities. There is no charge to the users of the RDCs for the data management conducted under the auspices of CRDCN and Statistics Canada as described within this DMP.&nbsp;</span></p>\r\n<p><span style=\"font-weight: 400;\">CRDCN does not employ consistency checking to ensure that the code provided alongside requests for research results to be released from the secure facility truly creates the output as requested. The responsibility for ensuring that the code and documents describing their use work as intended and are clear to other users who might access them lies with the researchers in the RDC. The CRDCN has a mechanism to ensure that the code is saved alongside all of the research output used to support the conclusions of any published works.</span></p>", "number"=>6, "phase_id"=>3486, "modifiable"=>true, "versionable_id"=>"094e7e5a-5a17-4cd4-9ee3-a83410cf9615"})
Question.create({"id"=>68962, "text"=>"<p><span style=\"font-weight: 400;\">In addition to the data management employed by Statistics Canada, it is possible for researchers to have research output that does not contain confidential data, including tables, syntax and other information, released from the RDC where it could be curated in a repository of the researcher&rsquo;s choosing as described in question 5. If you plan to do any supplemental storage or curation of your research data, please comment on where the responsibility for curation and maintenance of the archive resides.</span></p>\r\n<p>Will any resources be required for this curation and maintenance? If so, please estimate the overall data management costs.</p>", "default_value"=>nil, "number"=>1, "section_id"=>22406, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"fcc2bc79-e43d-4ee8-a5a9-2399fd452186"})
Annotation.create({"id"=>64802, "question_id"=>68962, "org_id"=>8, "text"=>"<p><span style=\"font-weight: 400;\">A tool provided by OpenAIRE can help researchers estimate the cost of research data management: </span><a href=\"https://www.openaire.eu/how-to-comply-to-h2020-mandates-rdm-costs\"><span style=\"font-weight: 400;\">https://www.openaire.eu/how-to-comply-to-h2020-mandates-rdm-costs</span></a><span style=\"font-weight: 400;\">. </span></p>", "type"=>"guidance", "versionable_id"=>"f480ab21-743f-443d-8ba9-41e8f313f3a0"})
Section.create({"id"=>22407, "title"=>"Ethics and Legal Compliance", "description"=>"<p><span style=\"font-weight: 400;\">Any users of the RDC must be 'deemed employees' of Statistics Canada. To become a deemed employee, the Treasury Board mandates a security clearance process including a criminal background check, credit check and fingerprinting. Approval for access to data requires a peer-review process of a research proposal and an institutional review at Statistics Canada. In cases where a researcher&rsquo;s scholarly work has been assessed through the tenure review process, they are considered peer-review pre-approved and only the institutional review is required.</span></p>\r\n<p><span style=\"font-weight: 400;\">Once a researcher is granted access to the RDC they must take an Oath of Secrecy &ndash; promising never to disclose confidential data. Criminal penalties can apply under the Statistics Act for violations of this oath.</span></p>\r\n<p><span style=\"font-weight: 400;\">Intellectual property for work done within the RDC becomes property of Statistics Canada including code used to manipulate data. The collection and dissemination of, and access to, confidential microdata is conducted under the Statistics Act and complies with all legal requirements. The confidential microdata for this project cannot be shared, posted, or copied. Access to the data is available through the RDC program. More information on how to access data is available here in </span><a href=\"https://crdcn.org/research\"><span style=\"font-weight: 400;\">English</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://crdcn.org/fr/recherche\"><span style=\"font-weight: 400;\">French</span></a><span style=\"font-weight: 400;\">.</span></p>\r\n<p><span style=\"font-weight: 400;\">In general, research ethics clearance is not required for research conducted in the RDC. A statement from the CRDCN on the topic is available here in </span><a href=\"https://crdcn.org/sites/default/files/uploads/ethics_review_recommendations_en.pdf\"><span style=\"font-weight: 400;\">English</span></a><span style=\"font-weight: 400;\"> or </span><a href=\"https://crdcn.org/sites/default/files/uploads/ethics_review_recommendations_fr.pdf\"><span style=\"font-weight: 400;\">French</span></a><span style=\"font-weight: 400;\">.</span></p>", "number"=>7, "phase_id"=>3486, "modifiable"=>true, "versionable_id"=>"517137f4-c725-4c4b-8213-6bd3dc009364"})
Question.create({"id"=>68963, "text"=>"<span style=\"font-weight: 400;\">If you feel there are any additional legal or ethical requirements for your project please describe them here.</span>", "default_value"=>nil, "number"=>1, "section_id"=>22407, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e8c3fcf7-621d-4889-a5d0-235553023f4f"})
Template.create!({"id"=>3462, "title"=>"Alliance Template for Interdisciplinary Health Software/Technology Development", "description"=>"<p><span style=\"font-weight: 400;\">This template is designed for research projects where software or technology is being developed in an interdisciplinary health context. This template was created to represent the many stakeholders (e.g., patients, practitioners, developers, industry) involved in software or technology development, either as advisors or as participants being studied as a product of the research process. As a result, this template is separated into two sections; the first is focused solely on a management plan for the creation of software or technology, and the second on a data management plan designed to describe the methods in which data are gathered, analyzed, and shared from participants based on interventions or testing of the corresponding software or technology. In these studies, research participants can include either patients or practitioners, or both, depending on the software or technology&rsquo;s intended use.</span></p>", "published"=>true, "org_id"=>8, "locale"=>"en-CA", "is_default"=>false, "version"=>0, "visibility"=>1, "customization_of"=>nil, "family_id"=>694012005, "archived"=>false, "links"=>{"funder"=>[], "sample_plan"=>[]}})
Phase.create({"id"=>3436, "title"=>"Software/Technology Management Plan", "description"=>"<p>This section <span style=\"font-weight: 400;\">is focused solely on a management plan for the creation of software or technology.</span></p>", "number"=>1, "template_id"=>3462, "modifiable"=>true, "versionable_id"=>"0ef47415-b642-46c5-98c3-e4530c541b63"})
