Annotation.create({"id"=>63786, "question_id"=>68049, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide the location of where you intend to share your software/technology (e.g., app store, lab website, an industry partner). If planning to share underlying code, please indicate where that may be available as well. Consider using a tool like </span><a href=\"https://github.com/\"><span style=\"font-weight: 400;\">GitHub</span></a><span style=\"font-weight: 400;\"> to make your code accessible and retrievable.</span>", "type"=>"guidance", "versionable_id"=>"fb2927d6-5ab7-40e3-b412-e4dc50a68a13"})
Phase.create({"id"=>3437, "title"=>"Data Management Plan", "description"=>"<p>This section is focused <span style=\"font-weight: 400;\">on a data management plan designed to describe the methods in which data are gathered, analyzed, and shared from participants based on interventions or testing of the corresponding software or technology</span></p>", "number"=>2, "template_id"=>3462, "modifiable"=>true, "versionable_id"=>"4e00645f-49e4-4c08-a074-1d06bab51dd2"})
Section.create({"id"=>22105, "title"=>"Data Collection", "description"=>"<p><span style=\"font-weight: 400;\">Outline the processes and procedures you will follow during the data collection process of your study.</span></p>", "number"=>1, "phase_id"=>3437, "modifiable"=>true, "versionable_id"=>"df0bdaa0-3452-4367-aa57-1123fb0e37ce"})
Question.create({"id"=>68050, "text"=>"<span style=\"font-weight: 400;\">What types of data will you be collecting?</span>", "default_value"=>nil, "number"=>1, "section_id"=>22105, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"ce39f836-3fd6-4d73-a522-c07610e18d8d"})
Annotation.create({"id"=>63787, "question_id"=>68050, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Please describe the types of data you will gather across all phases of your study. Examples may include, but are not limited to data collected from surveys, interviews, personas or user stories, images, user testing, usage data, audio/video recordings, etc.</span>", "type"=>"guidance", "versionable_id"=>"372bf344-fdbc-4a43-9383-656134ca926c"})
Question.create({"id"=>68051, "text"=>"<span style=\"font-weight: 400;\">Will you be using any existing data from external sources or previous research?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22105, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d1651ce5-7808-40fc-8678-e644bfd42d18"})
Annotation.create({"id"=>63788, "question_id"=>68051, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">If you will be combining original research data with existing licensed, restricted, or previously used research data, describe those data here. Provide the name, location, and date</span> <span style=\"font-weight: 400;\">of the dataset(s)</span> <span style=\"font-weight: 400;\">used. </span>", "type"=>"guidance", "versionable_id"=>"f6a71ea4-d24d-46e3-9775-2c9b8cc4bb41"})
Question.create({"id"=>68052, "text"=>"<span style=\"font-weight: 400;\">What data collection instrument or scales will you use to collect the data?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22105, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a111bfdd-8d93-4144-be70-583eae689d7b"})
Annotation.create({"id"=>63789, "question_id"=>68052, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide a description of any data collection instruments or scales that will be used to collect data. These may include but are not limited to questionnaires, assessment scales, or persona guides. If using a pre-existing instrument or scale from another study, provide the citation(s) in this section.</span>", "type"=>"guidance", "versionable_id"=>"faab5f23-0ddf-4159-8634-c4b6977e6e65"})
Question.create({"id"=>68053, "text"=>"<span style=\"font-weight: 400;\">Is your data collected longitudinally or at a single point in time?</span>", "default_value"=>nil, "number"=>4, "section_id"=>22105, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"e61e53ac-d122-44ec-a8ee-ceacfec1a7d4"})
Annotation.create({"id"=>63790, "question_id"=>68053, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Indicate how frequently you will be collecting data from participants. For example, if you are conducting a series of user tests with the same participants each time, indicate the frequency here.</span>", "type"=>"guidance", "versionable_id"=>"54321f51-40b7-474b-a8a7-e4cab22af9bb"})
Question.create({"id"=>68054, "text"=>"<span style=\"font-weight: 400;\">What is the time frame over which you are collecting data?</span>", "default_value"=>nil, "number"=>5, "section_id"=>22105, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a5927d13-7681-4887-8d0d-8d5c439bd32e"})
Annotation.create({"id"=>63791, "question_id"=>68054, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide an estimate of when you will begin and conclude the data collection process. List this information in the following format: YYYY/MM/DD - YYYY/MM/DD. If you do not know the exact dates, list YYYY/MM - YYYY/MM instead.</span>", "type"=>"guidance", "versionable_id"=>"f41fa5e1-25e0-4122-9744-502d0ddabcc3"})
Question.create({"id"=>68055, "text"=>"<span style=\"font-weight: 400;\">What is the setting and geographic location of where the data is being gathered?</span>", "default_value"=>nil, "number"=>6, "section_id"=>22105, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"60120ef7-3d4e-451b-82a9-8623ff037f72"})
Annotation.create({"id"=>63792, "question_id"=>68055, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Indicate the broader geographic location and setting where data will be gathered.</span>", "type"=>"guidance", "versionable_id"=>"b2abfc32-8577-472c-bc1b-e4cc532a4eb2"})
Question.create({"id"=>68056, "text"=>"<span style=\"font-weight: 400;\">What are the steps involved in the data collection process?</span>", "default_value"=>nil, "number"=>7, "section_id"=>22105, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"aeebc389-8b6f-49d9-97fc-6f2c354bba7d"})
Annotation.create({"id"=>63793, "question_id"=>68056, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Utilize this section to include a descriptive overview of the procedures involved in the data collection process. This may include but not be limited to recruitment, screening, information dissemination, and the phases of data collection (e.g., participant surveys, user acceptance testing, etc.). </span>", "type"=>"guidance", "versionable_id"=>"7f336af8-20a9-4447-84cd-7e5c192e911b"})
Question.create({"id"=>68057, "text"=>"<span style=\"font-weight: 400;\">What software programs will you use to collect the data?</span>", "default_value"=>nil, "number"=>8, "section_id"=>22105, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"1f525774-4cc8-4fb0-af22-4c571b0b8100"})
Annotation.create({"id"=>63794, "question_id"=>68057, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Include the name and version of any software programs used to collect data in the study. If homegrown software/technology is being used, describe it and list any dependencies associated with running that program.</span>", "type"=>"guidance", "versionable_id"=>"db2921c9-9c72-42db-a475-c3bd4be9f850"})
Question.create({"id"=>68058, "text"=>"<span style=\"font-weight: 400;\">What file formats will you be generating during the data collection phase?</span>", "default_value"=>nil, "number"=>9, "section_id"=>22105, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"09b33c61-518d-4751-b1f9-f7628f15a05c"})
Annotation.create({"id"=>63795, "question_id"=>68058, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">List any of the output files formats from the software programs listed above.</span>", "type"=>"guidance", "versionable_id"=>"f9c0d3f7-a304-4fbd-8152-d28434de9628"})
Section.create({"id"=>22106, "title"=>"Data Analysis", "description"=>"<p><span style=\"font-weight: 400;\">Outline the steps, materials, and methods that you will use during the data analysis phase of your study.</span></p>", "number"=>2, "phase_id"=>3437, "modifiable"=>true, "versionable_id"=>"807de6c7-fbb5-4d7a-9f0f-e578ccbdee1e"})
Question.create({"id"=>68059, "text"=>"<span style=\"font-weight: 400;\">How will you document the changes you make to your data on a regular basis during the data analysis phase?</span>", "default_value"=>nil, "number"=>1, "section_id"=>22106, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"824ee04d-21da-4e19-90ec-856da0fd322a"})
Annotation.create({"id"=>63796, "question_id"=>68059, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide a description of how you will track changes made to any data analysis files. An example of this might include your audit trails or versioning systems that you will follow iterations of the data during the analysis process.</span>", "type"=>"guidance", "versionable_id"=>"1ab23a43-99df-45ce-83a9-e2cc7e6e0182"})
Question.create({"id"=>68060, "text"=>"<span style=\"font-weight: 400;\">What software will you be using to support your data analysis?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22106, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7649fc69-8fea-49d9-af35-8b136d585bfa"})
Annotation.create({"id"=>63797, "question_id"=>68060, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe the software you will use to perform any data analysis tasks associated with your study, along with the version of that software (e.g., SPSS, Atlas.ti, Excel, R, etc.).</span>", "type"=>"guidance", "versionable_id"=>"7e4237cd-032b-47df-aa70-72bc3c6dccdb"})
Question.create({"id"=>68061, "text"=>"<span style=\"font-weight: 400;\">What file formats will your data analysis files be saved in?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22106, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4e470a43-d705-4f33-8367-bcc2c0884951"})
Annotation.create({"id"=>63798, "question_id"=>68061, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">List the file formats associated with each analysis software program that will be generated in your study (e.g., .txt, .csv, .xsls, .docx).</span>", "type"=>"guidance", "versionable_id"=>"b84b67c8-92ab-4c13-9196-953da1e860b7"})
Question.create({"id"=>68062, "text"=>"<span style=\"font-weight: 400;\">What code you will be generating that should accompany the data analysis file(s)?</span>", "default_value"=>nil, "number"=>4, "section_id"=>22106, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"595fef18-8ade-447f-873e-9c941b5b5ce3"})
Annotation.create({"id"=>63799, "question_id"=>68062, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Include any code or coding schemes used to perform data analysis. Examples in this section could include codebooks for analyzing interview transcripts from user testing, code associated with the functional/non-functional requirements of the software/technology program, or analytical frameworks used for evaluation.</span>", "type"=>"guidance", "versionable_id"=>"ea7e645d-fe08-4aba-8b30-fdacfe7f2846"})
Question.create({"id"=>68063, "text"=>"<span style=\"font-weight: 400;\">What quality assurance measures will be implemented over the course of the study?</span>", "default_value"=>nil, "number"=>5, "section_id"=>22106, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c8d54028-bb90-452a-9f8e-2dc6e5d9b95a"})
Annotation.create({"id"=>63800, "question_id"=>68063, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Use this section to describe any quality review schedules, double coding measures, inter-rater reliability, quality review schedules, etc. that you intend to implement in your study.</span>", "type"=>"guidance", "versionable_id"=>"17d367b9-da26-41c4-81fd-e2dda28e943d"})
Section.create({"id"=>22107, "title"=>"Documentation and Metadata", "description"=>"<p><span style=\"font-weight: 400;\">This section will focus on including information that would be required for someone else to interpret and re-use your data.</span></p>", "number"=>3, "phase_id"=>3437, "modifiable"=>true, "versionable_id"=>"2faa27ae-5642-4d03-a3e3-91f85e2aa975"})
Question.create({"id"=>68064, "text"=>"<span style=\"font-weight: 400;\">What information would be required for someone else to understand and reuse your data?</span>", "default_value"=>nil, "number"=>1, "section_id"=>22107, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"7b178dbb-8489-4d79-a29b-ba5878245868"})
Annotation.create({"id"=>63801, "question_id"=>68064, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Consider what information might be useful to accompany your data if you were to share it with someone else (e.g., the study protocol, interview guide, personas, user testing procedures, data collection instruments, or software dependencies, etc.).</span>", "type"=>"guidance", "versionable_id"=>"522adfc3-082c-4469-a458-b1bd27468f1d"})
Question.create({"id"=>68065, "text"=>"<span style=\"font-weight: 400;\">Are there metadata standards which you could use to describe your data?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22107, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"2b599d29-5ea0-4e6b-ba80-0ff1dc3e26a2"})
Annotation.create({"id"=>63802, "question_id"=>68065, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Metadata standards can provide guidance on how best to document your data. If you do not know of any existing standards in your field, visit this website to search for available standards: </span><a href=\"https://fairsharing.org/\"><span style=\"font-weight: 400;\">https://fairsharing.org/</span></a>.", "type"=>"guidance", "versionable_id"=>"73273305-16dd-4e59-9b2f-fc216ccd0b43"})
Question.create({"id"=>68066, "text"=>"<span style=\"font-weight: 400;\">Who is the target population being investigated?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22107, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"656099b0-b5e6-482e-9672-462a9af9b962"})
Annotation.create({"id"=>63803, "question_id"=>68066, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe the target population for which the software/technology is being developed (i.e., end users).</span>", "type"=>"guidance", "versionable_id"=>"de20f90d-fb03-4cbc-addc-638d67ffd761"})
Question.create({"id"=>68067, "text"=>"<span style=\"font-weight: 400;\">How is the population being sampled?</span>", "default_value"=>nil, "number"=>4, "section_id"=>22107, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"6a89bd1e-5925-4610-9455-4d3b7e735f0b"})
Annotation.create({"id"=>63804, "question_id"=>68067, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe the processes used to sample the population (e.g., convenience, snowball, purposeful, etc.).</span>", "type"=>"guidance", "versionable_id"=>"b6eb6945-0ec8-4868-aa69-9efc8562a8a0"})
Question.create({"id"=>68068, "text"=>"<span style=\"font-weight: 400;\">What are the variables being studied? </span>", "default_value"=>nil, "number"=>5, "section_id"=>22107, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"25795f81-fabe-49ac-a7e1-05a3830a99f3"})
Annotation.create({"id"=>63805, "question_id"=>68068, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">For any data gathered, list the variables being studied. For each variable, include the variable name, explanatory information, variable type, and values associated with each variable. Examples may include demographic characteristics of stakeholders, components of the software/technology program&rsquo;s functional and nonfunctional requirements, etc. See guidance on </span><a href=\"https://help.osf.io/hc/en-us/articles/360019739054-How-to-Make-a-Data-Dictionary\"><span style=\"font-weight: 400;\">how to create a data dictionary</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"07002e40-ae9f-4ed6-bda9-9a585fe511d6"})
Question.create({"id"=>68069, "text"=>"<span style=\"font-weight: 400;\">Are there any acronyms or abbreviations that will be used within your study that may be unclear to others?</span>", "default_value"=>nil, "number"=>6, "section_id"=>22107, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"f59ad952-5238-4127-a9b3-22013fc8f20e"})
Annotation.create({"id"=>63806, "question_id"=>68069, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Create a glossary of all acronyms or abbreviations used within your study. </span>", "type"=>"guidance", "versionable_id"=>"638ed9c9-0f67-485d-bcab-3c1e6f41cc60"})
Section.create({"id"=>22108, "title"=>"Storage and Backup", "description"=>"<p><span style=\"font-weight: 400;\">Describe and outline how and where your data will be stored throughout the research project.</span></p>", "number"=>4, "phase_id"=>3437, "modifiable"=>true, "versionable_id"=>"3c5c8138-2f19-4e51-965a-4070829d7c66"})
Question.create({"id"=>68070, "text"=>"<span style=\"font-weight: 400;\">What are the storage requirements needed for your data?</span>", "default_value"=>nil, "number"=>1, "section_id"=>22108, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a6e70518-a7f8-46ee-b875-75315083a245"})
Annotation.create({"id"=>63807, "question_id"=>68070, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide an estimate of how much data you will collect for all data in the form of terabytes, gigabytes, or megabytes as needed. Breaking down the size requirements by data types is advised (e.g., 2 GB required for video files, 500 MB for survey data). </span>", "type"=>"guidance", "versionable_id"=>"bebd0395-19da-436f-b18c-e7e0e73f6f50"})
Question.create({"id"=>68071, "text"=>"<span style=\"font-weight: 400;\">Where will your data be stored during the </span><em><span style=\"font-weight: 400;\">data collection</span></em><span style=\"font-weight: 400;\"> phase?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22108, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"37646e16-c485-4325-b2f9-5aea824c6ef7"})
Annotation.create({"id"=>63808, "question_id"=>68071, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Indicate where and how data will be stored during data collection. Examples may include storing data in secure, password protected computer files, encrypted cloud storage, software programs (e.g., REDCap), hard copies stored in locked filing cabinets, external hard drives, etc.</span>", "type"=>"guidance", "versionable_id"=>"62cefb51-7fea-4ded-bafb-d1d7200dceaa"})
Question.create({"id"=>68072, "text"=>"<span style=\"font-weight: 400;\">Where will your data be stored during the </span><em><span style=\"font-weight: 400;\">data analysis</span></em><span style=\"font-weight: 400;\"> phase?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22108, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a315fbae-62f8-4cb1-9fd9-0f4e7bf22778"})
Annotation.create({"id"=>63809, "question_id"=>68072, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">If different from above, indicate where data is stored during the data analysis process. If data is being sent to external locations for analysis by a statistician, describe that process here.</span>", "type"=>"guidance", "versionable_id"=>"f290e30f-1e54-437c-99a1-aa9c0e75862c"})
Question.create({"id"=>68073, "text"=>"<span style=\"font-weight: 400;\">If your data contains confidential information, how will your storage method ensure the protection of this data?</span>", "default_value"=>nil, "number"=>4, "section_id"=>22108, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"45f38bfa-e8c4-43bb-b864-4a34a82aed32"})
Annotation.create({"id"=>63810, "question_id"=>68073, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Indicate the security measures used to protect participant identifying data. Examples may include storing informed consent forms separately from anonymized data, password protecting files, locking unused computers, and restricting access to data that may contain identifying information. </span>", "type"=>"guidance", "versionable_id"=>"b2413179-3e9a-4666-9aa9-98284196508f"})
Question.create({"id"=>68074, "text"=>"<span style=\"font-weight: 400;\">What file naming conventions will you use in your study?</span>", "default_value"=>nil, "number"=>5, "section_id"=>22108, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"d7573e51-7f2c-4e6c-a786-bb400ede02ee"})
Annotation.create({"id"=>63811, "question_id"=>68074, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">List any specific file naming conventions used throughout the study. Provide examples of this file naming convention in the text indicating the context for each part of the file name. See file naming guidance </span><a href=\"https://www.ed.ac.uk/records-management/guidance/records/practical-guidance/naming-conventions\"><span style=\"font-weight: 400;\">here</span></a><span style=\"font-weight: 400;\">.</span>", "type"=>"guidance", "versionable_id"=>"e9585f61-7cde-4356-8a25-0d391eada68d"})
Question.create({"id"=>68075, "text"=>"<span style=\"font-weight: 400;\">What backup measures will be implemented to ensure the safety of your data?</span>", "default_value"=>nil, "number"=>6, "section_id"=>22108, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"39a3ba3b-b1ba-4755-b5a5-875aeca6127d"})
Annotation.create({"id"=>63812, "question_id"=>68075, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe how your study data will be regularly saved, backed up, and updated. If using institutional servers, consult with your Information Technology department to find out how frequently data is backed up.</span>", "type"=>"guidance", "versionable_id"=>"4990eea3-5c26-4ca3-92c9-04078ee357a6"})
Section.create({"id"=>22112, "title"=>"Preservation", "description"=>"<p><span style=\"font-weight: 400;\">Describe the steps that will ensure that your data will be available and usable for the foreseeable future after your study is complete. </span></p>", "number"=>5, "phase_id"=>3437, "modifiable"=>true, "versionable_id"=>"bcb0ab3a-497f-409c-878c-b09623a9cca2"})
Question.create({"id"=>68091, "text"=>"<span style=\"font-weight: 400;\">Where will data be stored </span><em><span style=\"font-weight: 400;\">after </span></em><span style=\"font-weight: 400;\">the project is complete?</span>", "default_value"=>nil, "number"=>1, "section_id"=>22112, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"53c2268c-b3b1-4917-9906-ddd04d7127f4"})
Annotation.create({"id"=>63828, "question_id"=>68091, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe where your data will be stored after project completion (e.g., in an institutional repository, an </span><a href=\"https://www.re3data.org/\"><span style=\"font-weight: 400;\">external data repository</span></a><span style=\"font-weight: 400;\">, a secure institutional computer storage, or an external hard drive).</span>", "type"=>"guidance", "versionable_id"=>"54926748-74c5-4863-b49a-8ccb26cee1bc"})
Question.create({"id"=>68092, "text"=>"<span style=\"font-weight: 400;\">Who is responsible for managing the data after the study is complete?</span>", "default_value"=>nil, "number"=>2, "section_id"=>22112, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"efb0cf68-3752-47f6-a725-c48ed9840dc3"})
Annotation.create({"id"=>63829, "question_id"=>68092, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Name the person(s) responsible for managing the data at the completion of the project. List their affiliation and contact information.</span>", "type"=>"guidance", "versionable_id"=>"12e94ee0-9806-41bd-adce-78134147f913"})
Question.create({"id"=>68093, "text"=>"<span style=\"font-weight: 400;\">Will your data be migrated to preservation formats?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22112, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"b6c5be29-c300-410e-9055-11dca3648437"})
Annotation.create({"id"=>63830, "question_id"=>68093, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Many proprietary file formats such as those generated from Microsoft software or statistical analysis tools can make the data difficult to access later on. Consider transforming any proprietary files into </span><a href=\"https://www.archives.gov/preservation/products/definitions/filetypes.html\"><span style=\"font-weight: 400;\">preservation-friendly formats</span></a><span style=\"font-weight: 400;\"> to ensure your data can be opened. Describe the process for migrating your data formats here.</span>", "type"=>"guidance", "versionable_id"=>"7ad982d0-fce6-4d18-8a3f-624f7280ae45"})
Question.create({"id"=>68094, "text"=>"<span style=\"font-weight: 400;\">How long do you intend to keep your data after the project is complete?</span>", "default_value"=>nil, "number"=>4, "section_id"=>22112, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"5d8f3683-eb48-4dc6-a8e0-d60e36ae3249"})
Annotation.create({"id"=>63831, "question_id"=>68094, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide details on how long you plan to keep your data after the project, and list any requirements you must follow based on Research Ethics Board guidelines, data use agreements, or funder requirements. </span>", "type"=>"guidance", "versionable_id"=>"f412cb33-084d-48bb-9c8b-16e35ae13fec"})
Question.create({"id"=>68095, "text"=>"<span style=\"font-weight: 400;\">What steps will you take to destroy the data after the retention period is complete?</span>", "default_value"=>nil, "number"=>5, "section_id"=>22112, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"a5f2b97a-d0b8-410b-90e6-a7cc14e411dd"})
Annotation.create({"id"=>63832, "question_id"=>68095, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe what steps will be taken to destroy study data. These steps may include but are not limited to shredding physical documents, making data unretrievable with support from your Information Technology department, or personal measures to eliminate data files.</span>", "type"=>"guidance", "versionable_id"=>"8bff066e-20f3-4dc5-a347-09b2b6397309"})
Section.create({"id"=>22109, "title"=>"Ethics and Legal Compliance", "description"=>"<p><span style=\"font-weight: 400;\">Outline the ethical and legal implications placed on your research data.</span></p>", "number"=>6, "phase_id"=>3437, "modifiable"=>true, "versionable_id"=>"0269648e-fb33-48ac-b10e-b31baaa7300e"})
Question.create({"id"=>68076, "text"=>"<span style=\"font-weight: 400;\">How will the informed consent process be carried out within your study?</span>", "default_value"=>nil, "number"=>1, "section_id"=>22109, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"4870ea39-c813-48a2-b4d7-6ed45b538880"})
Annotation.create({"id"=>63813, "question_id"=>68076, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Outline the information provided in your Research Ethics Board protocol, and describe how informed consent is collected, and at which phases of the data collection process. Examples include steps to gain written or verbal consent, re-establishing consent at subsequent points of contact, etc. </span>", "type"=>"guidance", "versionable_id"=>"b4edbd85-afa5-4106-ba23-d35ae0787c72"})
