Annotation.create({"id"=>63814, "question_id"=>68077, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide the name, institutional affiliation, and contact information of the person(s) who hold intellectual property rights to the data.</span>", "type"=>"guidance", "versionable_id"=>"c2d679ff-202f-468b-9f0c-eca57cf12ac5"})
Question.create({"id"=>68078, "text"=>"<span style=\"font-weight: 400;\">What ethical guidelines or constraints are applicable to your data?</span>", "default_value"=>nil, "number"=>3, "section_id"=>22109, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"19acf131-2562-469b-8793-6374a70e8e3b"})
Annotation.create({"id"=>63815, "question_id"=>68078, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Describe any ethical concerns that may be associated with the data in this study. For example, if vulnerable and/or Indigenous populations were studied, outline specific guidelines that are being followed to protect participants (e.g., </span><a href=\"https://www.afn.ca/uploads/files/nihbforum/info_and_privacy_doc-ocap.pdf\"><span style=\"font-weight: 400;\">OCAP</span></a><span style=\"font-weight: 400;\">, community advisory boards, etc.).</span>", "type"=>"guidance", "versionable_id"=>"6d26482f-fe6f-455e-b73d-f15907d832f5"})
Question.create({"id"=>68079, "text"=>"<span style=\"font-weight: 400;\">What legal restraints are applicable to your data (e.g., ownership)?</span>", "default_value"=>nil, "number"=>4, "section_id"=>22109, "question_format_id"=>1, "option_comment_display"=>true, "modifiable"=>true, "versionable_id"=>"c896663a-7235-4271-a1a7-727ed744fdc1"})
Annotation.create({"id"=>63816, "question_id"=>68079, "org_id"=>8, "text"=>"<span style=\"font-weight: 400;\">Provide details describing the legal restrictions that apply to your data. These restrictions may include, but are not limited to details about how your research data can be used as outlined by a funder, institution, collaboration or commercial agreement. </span>", "type"=>"guidance", "versionable_id"=>"edbfb3db-1603-41a2-bce1-61a05440b7bf"})
